        // Set by beforeAssemblyReload so any in-flight EditorApplication.update tickers
        // (local lambdas we can't reach from outside their scope) can early-exit before
        // their closure's captured handles get released by Unity post-reload. Without this,
        // mid-animation reloads produce "Release of invalid GC handle. The handle is from
        // a previous domain." warnings — the captured closure tries to fire in the new
        // domain and Unity refuses to release its old-domain handles cleanly.
        private static bool _reloadingDomain;
        // Anonymous (closure-scoped) EditorApplication.update tickers register themselves here
        // so the before-reload cleanup can unsubscribe them even though it can't name them.
        // This prevents "invalid GC handle" warnings from tickers that are still active when a
        // domain reload happens (e.g. the Synty Pass auto-on timer right after the tool opens).
        private static readonly List<EditorApplication.CallbackFunction> _activeAnonTickers = new List<EditorApplication.CallbackFunction>();
        private static void RegisterAnonTicker(EditorApplication.CallbackFunction fn)
        {
            if (fn == null) return;
            if (!_activeAnonTickers.Contains(fn)) _activeAnonTickers.Add(fn);
            EditorApplication.update += fn;
        }
        private static void UnregisterAnonTicker(EditorApplication.CallbackFunction fn)
        {
            if (fn == null) return;
            try { EditorApplication.update -= fn; } catch { }
            _activeAnonTickers.Remove(fn);
        }
        
        // Recurring VisualElement scheduled items (spinners etc.) tracked so the before-reload
        // cleanup can pause them all. A recurring schedule item whose tick straddles a domain
        // reload can leave a handle from the previous domain ("invalid GC handle" warning).
        private static readonly List<IVisualElementScheduledItem> _activeScheduledItems = new List<IVisualElementScheduledItem>();
        private static void TrackScheduledItem(IVisualElementScheduledItem item)
        {
            if (item == null) return;
            _activeScheduledItems.Add(item);
        }

        // Pause a scheduled item without throwing. Unity 6.3+ throws ArgumentException ("Cannot
        // unschedule unknown scheduled function") if the item is already unscheduled/torn down —
        // which happens routinely on domain reload / package import.
        private static void SafePause(IVisualElementScheduledItem item)
        {
            if (item == null) return;
            try { item.Pause(); } catch { }
        }

