        }
        
        [System.Serializable]
        public class ExclusiveDeal
        {
            public string id;
            public string title;
            public string line1;
            public string line2;
            public string product_handle;
            public string product_name;
            public string discount_type;
            public float discount_amount;
            public string discount_code;
            public string icon_url;
            public string start_time;
            public long duration_seconds;
            public string end_time;
            // Deal type: "single" (default), "multi", "all", "theme", or "asset_type"
            //   single     — one product_handle, classic behaviour
            //   multi      — product_handles[] hand-picked by admin
            //   all        — applies to every pack the customer doesn't already own
            //   theme      — applies to every pack in `theme` the customer doesn't already own
            //   asset_type — applies to every pack of one brand/series (POLYGON, Sidekick, etc.) the customer doesn't already own
            public string type;
            public string[] product_handles;  // multi
            public string theme;              // theme
            public string asset_type;         // asset_type
            public string type_bg_color;      // hex (e.g. "#FEDE0D") — recolors the deal's type-background image; empty falls back to _dealTypeBgColor
            public DealTier[] discount_tiers; // optional multi-tier codes — picked at click time based on customer's eligible item count
        }
        
        // One tier of a multi-tier exclusive deal. Each tier has its own Shopify discount
        // code with a different cart-minimum-quantity requirement, so the tool can pick a
        // code whose minimum is close to (but below) the customer's eligible-item count —
        // forcing them to actually buy most of what's in the cart instead of trimming it
        // down to just one or two items for an unfair discount. The discount_amount can
        // vary across tiers (a "ramp") so customers eligible for more packs get a bigger
        // percentage off than customers eligible for few packs.
        [System.Serializable]
        public class DealTier
        {
            public int min_quantity;
            public string code;
            public float discount_amount;  // baked-in % or $ for this tier — overrides the deal's flat discount_amount when set
        }
