        // When true, we've locked Unity's assembly reloading for the duration of a multi-install
        // so scripted assets don't trigger a domain reload mid-batch (which was interrupting the
        // queue and the UI). Unlocked when the whole batch finishes — the recompile then happens
        // once, cleanly, at the end.
        private bool _assemblyReloadLocked = false;
        
        private void LockAssemblyReloadForBatch()
        {
            if (_assemblyReloadLocked) return;
            try { EditorApplication.LockReloadAssemblies(); _assemblyReloadLocked = true; SyntyDownloadManager.AssembliesLockedForBatch = true; }
            catch { _assemblyReloadLocked = false; }
        }
        
        private void UnlockAssemblyReloadAfterBatch()
        {
            if (!_assemblyReloadLocked) return;
            _assemblyReloadLocked = false;
            SyntyDownloadManager.AssembliesLockedForBatch = false;
            try
            {
                EditorApplication.UnlockReloadAssemblies();
                // Now that the batch is done, let the queued recompile happen once.
                AssetDatabase.Refresh();
                UnityEditor.Compilation.CompilationPipeline.RequestScriptCompilation();
            }
            catch { }
        }

        // Releases the reload lock WITHOUT forcing a Refresh/recompile. Used when the lock was held
        // only to protect an async section (e.g. the pre-install download-size fetch) where nothing
        // was imported, so triggering a recompile on unlock would be pointless churn.
        private void UnlockAssemblyReloadPlain()
        {
            if (!_assemblyReloadLocked) return;
            _assemblyReloadLocked = false;
            SyntyDownloadManager.AssembliesLockedForBatch = false;
            try { EditorApplication.UnlockReloadAssemblies(); } catch { }
        }

