        // Opens the tool window. The "Synty/Internal/Open Synty Importer Window" menu entry is
        // registered dev-only in RegisterInternalMenu() below — only when the SyntyDebugUnlock marker
        // is present — using Menu.AddMenuItem, so the whole Internal submenu is HIDDEN (not just greyed)
        // in customer projects.
        public static void ShowWindow()
        {
            var window = GetWindow<SyntyAssetDownloaderV2>();
            window.titleContent = new GUIContent("Synty Importer");

            // Always open with options panel closed.
            // Use delayCall so our resize runs AFTER Unity restores its saved layout.
            EditorApplication.delayCall += () =>
            {
                if (window == null) return;

                window._optionsPanelVisible = false;
                if (window._optionsPanel != null)
                {
                    window._optionsPanel.style.display = DisplayStyle.None;
                    window._verticalDivider.style.display = DisplayStyle.None;
                }

                // Min height depends on state — the login screen is compact, the main UI a bit taller.
                float minH = SyntyLoginManager.IsLoggedIn ? window._minHeight : window._loginMinHeight;
                window.minSize = new Vector2(window._minWidthNoOptions, minH);
                var pos = window.position;
                pos.width = WIDTH_NO_OPTIONS;
                window.position = pos;
                window.RightSizeWindowOnce();
            };
        }
        
        // Registers the dev-only "Synty/Internal/Open Synty Importer Window" item ONLY when the
        // SyntyDebugUnlock marker is present, via Menu.AddMenuItem — so it (and the Internal submenu)
        // don't exist at all in customer projects. A [MenuItem] validate can only grey out, not hide.
        [InitializeOnLoadMethod]
        private static void RegisterInternalMenu()
        {
            if (!IsDebugUnlocked()) return;
            EditorApplication.delayCall += () =>
                AddMenuItemReflective("Synty/Internal/Open Synty Importer Window", false, 1000, ShowWindow);
        }

        // UnityEditor.Menu.AddMenuItem is internal (binds to native MenuController::AddMenuItem), so
        // it isn't callable directly — invoke it via reflection. This lets us register the dev menu
        // item at runtime ONLY when the marker is present, so it's HIDDEN (not greyed) otherwise.
        private static void AddMenuItemReflective(string path, bool isChecked, int priority, System.Action execute)
        {
            try
            {
                var m = typeof(UnityEditor.Menu).GetMethod("AddMenuItem",
                    System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.NonPublic,
                    null,
                    new[] { typeof(string), typeof(string), typeof(bool), typeof(int), typeof(System.Action), typeof(System.Func<bool>) },
                    null);
                if (m != null) m.Invoke(null, new object[] { path, "", isChecked, priority, execute, null });
            }
            catch { }
        }
        
        public static void ResetLogin()
        {
            SyntyLoginManager.Logout();
            EditorPrefs.SetBool(PREFS_PREFIX + "SyntyPass", false);
            
            var window = GetWindow<SyntyAssetDownloaderV2>(false, null, false);
            if (window != null)
            {
                window._licenseSyntyPass = false;
                window.StopSaleBadgePulse();
                var r = window.rootVisualElement;
                r.Clear();
                if (window._styleSheet != null) r.styleSheets.Add(window._styleSheet);
                window.ShowLoginScreen(r);
            }
            
        }
        
        public static void ClearQueue()
        {
            SyntyDownloadManager.Instance.CancelAll();
            SyntyDownloadManager.Instance.ClearCompleted();
            SessionState.EraseString("SyntyDownloadManager_SessionQueue");
            SessionState.EraseBool("SyntyDownloadManager_WasProcessing");
        }
        
        public static void ResetInstalledAssets()
        {
            if (!EditorUtility.DisplayDialog("Reset Installed Assets",
                "This will clear all install tracking data. The tool will no longer know which assets are installed.\n\nNo files will be deleted -- this only resets the tracking.\n\nYou will need to reopen the tool for changes to take effect.",
                "Reset", "Cancel"))
                return;
            
            SyntyImportTracker.ClearAll(); // legacy cleanup
            SyntyInstallManifest.ClearAll();
            SyntyDownloadManager.Instance.CancelAll();
            SyntyDownloadManager.Instance.ClearCompleted();
            SessionState.EraseString("SyntyDownloadManager_SessionQueue");
            SessionState.EraseBool("SyntyDownloadManager_WasProcessing");
        }
        
        private void OnEnable()
        {
            // Always set the window title here so it's correct however the window opened or was
            // restored by Unity's saved layout (was showing the old "Synty - Passport").
            titleContent = new GUIContent("Synty Importer");
            // The domain reload (if any) is over by the time a fresh window initializes, so
            // clear the static reload flag. Otherwise a value left true from a prior reload
            // makes guarded update-tickers (e.g. the Synty Pass auto-on) bail immediately,
            // which is why the pass filter sometimes failed to turn on after opening.
            _reloadingDomain = false;
            
            // Warm the currency cache so any prices shown before login completes are already
            // in the user's selected currency (rates load from EditorPrefs instantly).
            _ = SyntyCurrency.EnsureRatesAsync();
            // Auto-pick the currency from the user's location (Cloudflare geo-IP) on open, unless
            // they've chosen one manually. Falls back to USD when detection fails or is unmapped.
            _ = SyntyCurrency.DetectFromLocationAsync();
            
            FindImagesPath();
            
            // Clear cached asset icons so updated icons from server are picked up
            var iconKeys = new List<string>();
            foreach (var key in _imageCache.Keys)
                if (key.Contains("AssetIcons")) iconKeys.Add(key);
            foreach (var key in iconKeys)
                _imageCache.Remove(key);
            
            // Load filter states from EditorPrefs (before CreateGUI is called by Unity)
            LoadFilterStates();
            
            // Subscribe to download manager events for real-time progress
            SyntyDownloadManager.Instance.OnItemProgressChanged += OnDownloadProgress;
            SyntyDownloadManager.Instance.OnItemStatusChanged += OnManagerItemStatusChanged;
            SyntyDownloadManager.Instance.OnItemCompleted += OnDownloadComplete;
            SyntyDownloadManager.Instance.OnItemFailed += OnDownloadFailed;
            
            // Safety watchdog: if the UI still thinks a download is active but the download
            // manager reports no active work (an event was missed, or an install stalled out),
            // force the UI back to its normal state so the dim overlay and bottom bars return.
            EditorApplication.update += DownloadStuckWatchdog;
            
            // Subscribe to announcement updates
            SyntyNotificationService.OnAnnouncementsUpdated += OnAnnouncementsUpdated;
            
            // Belt-and-braces: abort in-flight UnityWebRequests AND unsubscribe known
            // EditorApplication.update handlers before any domain reload, regardless of
            // whether OnDisable fires first. Stops "Release of invalid GC handle. The
            // handle is from a previous domain." warnings from anything whose native
            // handles would otherwise survive into the new domain.
            _beforeReloadCleanup = () =>
            {
                _reloadingDomain = true;
                if (_dealsRequest != null)    { try { _dealsRequest.Abort();    _dealsRequest.Dispose();    } catch { } _dealsRequest = null; }
                if (_dealIconRequest != null) { try { _dealIconRequest.Abort(); _dealIconRequest.Dispose(); } catch { } _dealIconRequest = null; }
                if (_bannerImageRequest != null) { try { _bannerImageRequest.Abort(); _bannerImageRequest.Dispose(); } catch { } _bannerImageRequest = null; }
                // Unsubscribe every named EditorApplication.update handler we know about.
                // Local-lambda tickers can't be reached from here (they're closure-scoped)
                // but they self-check _reloadingDomain at the top and bail before touching
                // any captured handles.
                try { EditorApplication.update -= RunStaggerQueue; } catch { }
                try { EditorApplication.update -= DownloadStuckWatchdog; } catch { }
                try { EditorApplication.update -= SaleBadgePulseTick; } catch { }
                try { EditorApplication.update -= PassButtonPulseTick; } catch { }
                try { EditorApplication.update -= UpdateNotifDotPulse; } catch { }
                // Unsubscribe every tracked anonymous ticker so none survive into the new
                // domain with a dangling handle.
                foreach (var fn in _activeAnonTickers.ToArray())
                {
                    try { EditorApplication.update -= fn; } catch { }
                }
                _activeAnonTickers.Clear();
                // Pause + drop every tracked recurring scheduled item (spinners) so their
                // handles don't survive the domain reload.
                foreach (var si in _activeScheduledItems.ToArray())
                {
                    try { SafePause(si); } catch { }
                }
                _activeScheduledItems.Clear();
                // Clear the static icon cache — Texture2Ds with HideAndDontSave survive the
                // reload but the native side gets reclaimed, leaving dangling references.
                _dealIconCache.Clear();
            };
            AssemblyReloadEvents.beforeAssemblyReload += _beforeReloadCleanup;
            
            // Check for a tool update on open (covers forward updates and rollbacks).
            MaybeCheckToolUpdate(force: true);
        }
        
        // How often (minutes) to re-check for a tool-package update while the window is in use.
        private const double ToolUpdateCheckIntervalMinutes = 30.0;
        private const string ToolUpdateLastCheckKey = "SyntyPassport_LastToolUpdateCheck";
        
        // Called on window focus: if enough time has passed since the last check, look for a tool
        // update (any version mismatch vs the live channel, so rollbacks are picked up too) and
        // install it silently. "force" bypasses the interval (used on first open).
        private void MaybeCheckToolUpdate(bool force = false)
        {
            double now = EditorApplication.timeSinceStartup;
            // Persist across domain reloads using a wall-clock timestamp.
            double lastUtc = 0;
            double.TryParse(EditorPrefs.GetString(ToolUpdateLastCheckKey, "0"), out lastUtc);
            double nowUtc = (System.DateTime.UtcNow - new System.DateTime(1970, 1, 1)).TotalMinutes;
            if (!force && (nowUtc - lastUtc) < ToolUpdateCheckIntervalMinutes) return;
            // Respect the per-project auto-update toggle (Synty/Internal/Auto-Update Passport) and
            // never auto-update a dev project (presence of the debug-unlock marker). The key must
            // match SyntyImporter_Installer.ProjectKey() so the menu toggle affects this path too.
            int h = 17; foreach (char c in Application.dataPath) h = h * 31 + c;
            string autoKey = "SyntyPassport_AutoUpdate_" + (h & 0x7fffffff).ToString();
            // Customers respect the per-project auto-update toggle. A dev project (debug-unlock marker
            // present) always runs the check so it gets the dev/live prompt when a new version exists.
            bool isDevProject = SyntyCatalogBridge.HasDebugUnlockMarker();
            if (!isDevProject && !EditorPrefs.GetBool(autoKey, true)) return;
            EditorPrefs.SetString(ToolUpdateLastCheckKey, nowUtc.ToString());
            
            SyntyCatalogBridge.CheckAndAutoUpdate((updated, info) =>
            {
                if (updated) Synty.Tools.SyntyLog.Info("Synty Importer updated, reloading...");
            });
        }
        
        private void OnFocus()
        {
            // Throttled tool-update check when the user clicks back into the window.
            MaybeCheckToolUpdate(force: false);
            // Also run the throttled order-count check, so a purchase made while the user was away in
            // the browser is picked up as soon as they return to Unity — no click needed. Combined
            // with the worker now honouring the force flag, the new pack shows without waiting for the
            // ownership cache to expire.
            OnWindowInteractionCheckOrders();
        }
        
        private void OnDisable()
        {
            StopSaleBadgePulse();
            StopPassButtonPulse();
            EditorApplication.update -= CartPulseTick;
            EditorApplication.update -= CartBarPulseTick;
            EnsureInstallKeepAlive(false);
            EditorUtility.ClearProgressBar();
            
            // Never leave assembly reloading locked if the window closes mid-batch — that would
            // freeze recompilation until the editor restarts.
            UnlockAssemblyReloadAfterBatch();
            
            // Unsubscribe from download manager events
            SyntyDownloadManager.Instance.OnItemProgressChanged -= OnDownloadProgress;
            SyntyDownloadManager.Instance.OnItemStatusChanged -= OnManagerItemStatusChanged;
            SyntyDownloadManager.Instance.OnItemCompleted -= OnDownloadComplete;
            SyntyDownloadManager.Instance.OnItemFailed -= OnDownloadFailed;
            EditorApplication.update -= DownloadStuckWatchdog;
            SyntyNotificationService.OnAnnouncementsUpdated -= OnAnnouncementsUpdated;
            EditorApplication.update -= UpdateNotifDotPulse;
            
            // Abort any in-flight deals request so its native handle isn't released across a domain reload
            if (_dealsRequest != null) { try { _dealsRequest.Abort(); _dealsRequest.Dispose(); } catch { } _dealsRequest = null; }
            if (_dealIconRequest != null) { try { _dealIconRequest.Abort(); _dealIconRequest.Dispose(); } catch { } _dealIconRequest = null; }
            if (_bannerImageRequest != null) { try { _bannerImageRequest.Abort(); _bannerImageRequest.Dispose(); } catch { } _bannerImageRequest = null; }
            if (_beforeReloadCleanup != null) { AssemblyReloadEvents.beforeAssemblyReload -= _beforeReloadCleanup; _beforeReloadCleanup = null; }
        }
        
        // Fired by the download manager whenever an item's status changes. We use it to drive the
        // spotlight + "INSTALLING X of N" badge from the REAL install, since the manager runs its
        // own queue independently of the tool's UI queue (which can stall). When an item begins
        // downloading or importing, make its card the current (bright, badged) one.
        private string _lastVisualizedHandle = null;
        // Scrolls the asset grid so the given card is visible (used when a pack starts
        // downloading/installing, so the user always sees the active card).
        // ── Drag-select (marquee) ──────────────────────────────────────────────────────────────
        // Lets the user click in empty grid space and drag a rectangle; every asset card the box
        // touches is selected (added to the current selection). Auto-scrolls when dragging past the
        // top/bottom edge. A tiny drag is treated as a click (handled by the card itself).
        private void SetupMarqueeSelect(ScrollView scroll)
        {
            if (scroll == null) return;
            var viewport = scroll.contentViewport;
            if (viewport == null) return;

            // The marquee rectangle overlay (hidden until dragging).
            _marqueeRect = new VisualElement();
            _marqueeRect.name = "marquee-rect";
            _marqueeRect.pickingMode = PickingMode.Ignore;
            _marqueeRect.style.position = Position.Absolute;
            _marqueeRect.style.display = DisplayStyle.None;
            _marqueeRect.style.backgroundColor = new Color(_accentColor.r, _accentColor.g, _accentColor.b, 0.15f);
            _marqueeRect.style.borderTopWidth = 1;
            _marqueeRect.style.borderBottomWidth = 1;
            _marqueeRect.style.borderLeftWidth = 1;
            _marqueeRect.style.borderRightWidth = 1;
            _marqueeRect.style.borderTopColor = _accentColor;
            _marqueeRect.style.borderBottomColor = _accentColor;
            _marqueeRect.style.borderLeftColor = _accentColor;
            _marqueeRect.style.borderRightColor = _accentColor;
            viewport.Add(_marqueeRect);

            // Transparent, pickable overlay shown over the grid while dragging. Being the topmost
            // pickable element under the pointer, cards beneath it never enter the :hover state, so
            // their USS hover styles (round button turning blue, download tint, etc.) don't fire.
            _marqueeHoverShield = new VisualElement();
            _marqueeHoverShield.name = "marquee-hover-shield";
            _marqueeHoverShield.pickingMode = PickingMode.Position;
            _marqueeHoverShield.style.position = Position.Absolute;
            _marqueeHoverShield.style.top = 0;
            _marqueeHoverShield.style.left = 0;
            _marqueeHoverShield.style.right = 0;
            _marqueeHoverShield.style.bottom = 0;
            _marqueeHoverShield.style.display = DisplayStyle.None;
            viewport.Add(_marqueeHoverShield);

            viewport.RegisterCallback<PointerDownEvent>(OnMarqueePointerDown, TrickleDown.TrickleDown);
            viewport.RegisterCallback<PointerMoveEvent>(OnMarqueePointerMove, TrickleDown.TrickleDown);
            viewport.RegisterCallback<PointerUpEvent>(OnMarqueePointerUp, TrickleDown.TrickleDown);
        }

        // Forcibly cancels any in-progress or pending marquee drag and hides the rectangle. Called
        // whenever the grid is rebuilt/filtered, since a pointer-up can be lost when the viewport's
        // contents change under an active drag (e.g. clicking "Clear Filters" from the empty state).
        private void ResetMarqueeState()
        {
            _marqueePending = false;
            _marqueeActive = false;
            _marqueeDidDrag = false;
            _marqueeSuppressHover = false;
            EditorApplication.update -= MarqueeEdgeScrollTick;
            if (_marqueeRect != null) _marqueeRect.style.display = DisplayStyle.None;
            if (_marqueeHoverShield != null) _marqueeHoverShield.style.display = DisplayStyle.None;
            var viewport = _assetScrollView?.contentViewport;
            if (viewport != null && _marqueePointerId >= 0) { try { viewport.ReleasePointer(_marqueePointerId); } catch { } }
            _marqueePointerId = -1;
        }

        private void OnMarqueePointerDown(PointerDownEvent evt)
        {
            if (evt.button != 0) return; // left button only
            var viewport = _assetScrollView?.contentViewport;
            if (viewport == null) return;
            // Don't begin a marquee when the press is on a Button (e.g. the "Clear Filters" button in
            // the empty-state overlay) — let the button handle its click.
            var tgt = evt.target as VisualElement;
            int g = 0;
            while (tgt != null && tgt != viewport && g++ < 40)
            {
                if (tgt is Button) return;
                tgt = tgt.parent;
            }
            // Record a potential drag start whether the press is on a card or empty space. The
            // marquee only actually starts once the mouse moves past a small threshold (so a plain
            // click on a card still behaves as click-select).
            _marqueePending = true;
            _marqueeDidDrag = false;
            _marqueeSuppressHover = false;
            _marqueePressOnCard = IsInsideAssetCard(evt.target as VisualElement);
            _marqueeRemove = evt.ctrlKey || evt.commandKey;
            _marqueeAdd = evt.shiftKey;
            _marqueePendingStartWorld = evt.position;
            _marqueePointerId = evt.pointerId;
            _marqueeStartViewport = viewport.WorldToLocal(evt.position);
            _marqueeCurrentViewport = _marqueeStartViewport;
            _marqueeStartContent = _assetContent != null ? _assetContent.WorldToLocal(evt.position) : _marqueeStartViewport;
            _marqueeScrollLastTick = EditorApplication.timeSinceStartup;
            // Don't capture or stop propagation yet — let the card receive its press too.
        }

        private void OnMarqueePointerMove(PointerMoveEvent evt)
        {
            var viewport = _assetScrollView?.contentViewport;
            if (viewport == null) return;

            // Promote a pending press to an active drag once it moves past the threshold.
            if (_marqueePending && !_marqueeActive)
            {
                float moved = (((Vector2)evt.position) - _marqueePendingStartWorld).magnitude;
                // Kill the hover the instant there's any real movement — well before the drag
                // threshold — so cards don't flicker their hover pop as a drag begins.
                if (moved > 2f && !_marqueeSuppressHover)
                {
                    _marqueeSuppressHover = true;
                    ResetAllCardHovers();
                    if (_marqueeHoverShield != null) { _marqueeHoverShield.style.display = DisplayStyle.Flex; _marqueeHoverShield.BringToFront(); }
                }
                if (moved < 6f) return; // still a click, not a drag
                _marqueeActive = true;
                _marqueeDidDrag = true;
                ResetAllCardHovers(); // clear any hover applied just before the drag began
                // Snapshot the selection at drag start so the marquee can restore cards to their
                // pre-drag state when the box shrinks back off them (fixes cards staying selected
                // after the rectangle no longer covers them).
                _marqueeBaseSelected = new System.Collections.Generic.HashSet<int>();
                for (int i = 0; i < _assetItems.Count; i++)
                    if (_assetItems[i].button != null && _assetItems[i].getSelected())
                        _marqueeBaseSelected.Add(i);
                _marqueeRect.style.display = DisplayStyle.Flex;
                _marqueeRect.BringToFront(); // keep the selection rectangle above the hover shield
                EditorApplication.update += MarqueeEdgeScrollTick;
                try { viewport.CapturePointer(_marqueePointerId); } catch { }
            }

            if (!_marqueeActive) return;
            _marqueeRemove = evt.ctrlKey || evt.commandKey; // Ctrl (or Cmd on Mac) → remove
            _marqueeAdd = evt.shiftKey;                      // Shift → add to the pre-drag selection
            _marqueeCurrentViewport = viewport.WorldToLocal(evt.position);
            UpdateMarqueeRectVisual();
            ApplyMarqueeSelection();
            evt.StopPropagation();
        }

        private void OnMarqueePointerUp(PointerUpEvent evt)
        {
            var viewport = _assetScrollView?.contentViewport;
            bool wasActive = _marqueeActive;
            _marqueePending = false;
            _marqueeActive = false;
            _marqueeSuppressHover = false;
            EditorApplication.update -= MarqueeEdgeScrollTick;
            if (_marqueeRect != null) _marqueeRect.style.display = DisplayStyle.None;
            if (_marqueeHoverShield != null) _marqueeHoverShield.style.display = DisplayStyle.None;
            if (viewport != null && _marqueePointerId >= 0) { try { viewport.ReleasePointer(_marqueePointerId); } catch { } }
            _marqueePointerId = -1;

            if (wasActive)
            {
                // A real drag happened — apply the final selection, refresh bars, and swallow the
                // event so the card's click-select toggle doesn't also fire.
                ApplyMarqueeSelection();
                UpdateDownloadBar();
                evt.StopPropagation();
                // Clear the drag flag on the next frame so the card's MouseUp (which fires around
                // now) sees it and skips its toggle.
                _assetScrollView.schedule.Execute(() => _marqueeDidDrag = false).StartingIn(50);
            }
            else if (!_marqueePressOnCard)
            {
                // Plain click on empty grid space (not on a card) — clear the whole selection.
                bool any = false;
                for (int i = 0; i < _assetItems.Count; i++)
                {
                    if (_assetItems[i].button != null && _assetItems[i].getSelected())
                    {
                        _assetItems[i].setSelected(false);
                        RemoveFromSessionSelection(_assetItems[i].name);
                        any = true;
                    }
                }
                if (any)
                {
                    UpdateSelectButtonStates();
                    UpdateDownloadBar();
                }
            }
            // If no drag and the press was on a card, do nothing — the card handles its own click-select.
        }

        private bool IsInsideAssetCard(VisualElement el)
        {
            // Walk up from the click target; if we hit an asset card button before the viewport,
            // the click was on a card (let the card handle click-select instead of the marquee).
            var viewport = _assetScrollView?.contentViewport;
            int guard = 0;
            while (el != null && el != viewport && guard++ < 50)
            {
                foreach (var it in _assetItems)
                    if (it.button == el) return true;
                el = el.parent;
            }
            return false;
        }

        // Positions the marquee rectangle in viewport-local space from the drag start to the current
        // mouse. Start is kept in content space so it stays anchored to the grid as it scrolls.
        private void UpdateMarqueeRectVisual()
        {
            if (_marqueeRect == null) return;
            var viewport = _assetScrollView?.contentViewport;
            if (viewport == null || _assetContent == null) return;
            // Convert the content-anchored start point back into current viewport space.
            Vector2 startWorld = _assetContent.LocalToWorld(_marqueeStartContent);
            Vector2 startVp = viewport.WorldToLocal(startWorld);
            Vector2 cur = _marqueeCurrentViewport;
            float x = Mathf.Min(startVp.x, cur.x);
            float y = Mathf.Min(startVp.y, cur.y);
            float w = Mathf.Abs(cur.x - startVp.x);
            float h = Mathf.Abs(cur.y - startVp.y);
            _marqueeRect.style.left = x;
            _marqueeRect.style.top = y;
            _marqueeRect.style.width = w;
            _marqueeRect.style.height = h;
        }

        // Clears any hover pop on every card — used when a drag begins so a card the mouse was
        // already over (hover applied before the drag started) doesn't stay hovered through the drag.
        private void ResetAllCardHovers()
        {
            float pbs = GetProductBtnBaseScale();
            float bs = GetBtnBaseScale();
            foreach (var it in _assetItems)
            {
                var card = it.button;
                if (card == null) continue;
                var pBtn = card.Q<VisualElement>("product-btn");
                if (pBtn != null) pBtn.style.scale = new Scale(new Vector3(pbs, pbs, 1f));
                var pOvr = card.Q<VisualElement>("product-pressed-overlay");
                if (pOvr != null) pOvr.style.display = DisplayStyle.None;
                // Reset the INNER visual's scale (btnVisual), not the outer container. The outer
                // (it.button) is sized to the column width and kept at scale 1 by UpdateThumbnailSize;
                // only btnVisual carries the icon-size base scale. Scaling the outer here too was
                // double-shrinking every card when a drag began at a smaller icon size.
                if (!it.getSelected() && it.btnVisual != null)
                    it.btnVisual.style.scale = new Scale(new Vector3(bs, bs, 1f));
            }
        }

        // Sets each visible card's selection from the CURRENT marquee rectangle, recomputed every
        // move against a snapshot of the pre-drag selection. Plain (and Shift) drag ADD the box to
        // the pre-drag selection; Ctrl removes it. Cards inside the box that were already selected
        // stay selected; the box shrinking off a card that was in the pre-drag selection keeps it.
        // Hidden/filtered cards keep their pre-drag state.
        private void ApplyMarqueeSelection()
        {
            var viewport = _assetScrollView?.contentViewport;
            if (viewport == null || _assetContent == null) return;
            // Build the marquee rect in WORLD space (works regardless of scroll).
            Vector2 startWorld = _assetContent.LocalToWorld(_marqueeStartContent);
            Vector2 curWorld = viewport.LocalToWorld(_marqueeCurrentViewport);
            float x = Mathf.Min(startWorld.x, curWorld.x);
            float y = Mathf.Min(startWorld.y, curWorld.y);
            var marquee = new Rect(x, y, Mathf.Abs(curWorld.x - startWorld.x), Mathf.Abs(curWorld.y - startWorld.y));

            float pbsScale = GetProductBtnBaseScale();
            for (int i = 0; i < _assetItems.Count; i++)
            {
                var it = _assetItems[i];
                if (it.button == null) continue;
                // Keep hover visuals cleared on every card while dragging (a card the pointer passes
                // over mid-drag can still get a hover pop; clear it here every move).
                if (it.button.style.display != DisplayStyle.None)
                {
                    var pBtn = it.button.Q<VisualElement>("product-btn");
                    if (pBtn != null) pBtn.style.scale = new Scale(new Vector3(pbsScale, pbsScale, 1f));
                    var pOvr = it.button.Q<VisualElement>("product-pressed-overlay");
                    if (pOvr != null && pOvr.style.display == DisplayStyle.Flex) pOvr.style.display = DisplayStyle.None;
                }
                bool hidden = it.button.style.display == DisplayStyle.None;
                bool inBase = _marqueeBaseSelected != null && _marqueeBaseSelected.Contains(i);
                // Hidden (filtered-out) cards are never touched by the box — keep their pre-drag state.
                bool inRect = !hidden && marquee.Overlaps(it.button.worldBound, true);

                bool shouldSelect;
                if (hidden)              shouldSelect = inBase;             // untouched by the drag
                else if (_marqueeRemove) shouldSelect = inBase && !inRect; // Ctrl: remove the box from the pre-drag selection
                else                     shouldSelect = inBase || inRect;   // plain/Shift: ADD the box to the pre-drag selection

                // Recomputing every move is what makes cards deselect when the box shrinks back off them.
                if (it.getSelected() != shouldSelect) it.setSelected(shouldSelect);
            }
            UpdateSelectButtonStates();
        }

        // While dragging near the top/bottom edge of the viewport, scroll the grid so the user can
        // extend the selection past what's currently visible.
        private void MarqueeEdgeScrollTick()
        {
            if (!_marqueeActive || _assetScrollView == null) return;
            var viewport = _assetScrollView.contentViewport;
            if (viewport == null) return;
            double now = EditorApplication.timeSinceStartup;
            float dt = (float)(now - _marqueeScrollLastTick);
            _marqueeScrollLastTick = now;

            float vpHeight = viewport.resolvedStyle.height;
            float edge = 40f;             // px band near top/bottom that triggers scrolling
            float speed = 600f;           // px per second at full push
            float y = _marqueeCurrentViewport.y;
            float delta = 0f;
            if (y < edge)
            {
                float mult = y < 0f ? 3f : 1f; // 3x faster when dragged past the top edge
                delta = -speed * mult * dt * Mathf.Clamp01((edge - y) / edge);
            }
            else if (y > vpHeight - edge)
            {
                float mult = y > vpHeight ? 3f : 1f; // 3x faster when dragged past the bottom edge
                delta = speed * mult * dt * Mathf.Clamp01((y - (vpHeight - edge)) / edge);
            }

            if (Mathf.Abs(delta) > 0.01f)
            {
                var off = _assetScrollView.scrollOffset;
                off.y = Mathf.Max(0f, off.y + delta);
                _assetScrollView.scrollOffset = off;
                UpdateMarqueeRectVisual();
                ApplyMarqueeSelection();
            }
        }

        private void ScrollCardIntoView(VisualElement card)
        {
            if (card == null || _assetScrollView == null) return;
            // Defer two frames so any layout changes settle before we read positions.
            _assetScrollView.schedule.Execute(() =>
            {
                if (_assetScrollView == null || card == null || card.panel == null) return;
                var viewport = _assetScrollView.contentViewport;
                if (viewport == null) return;
                try
                {
                    const float margin = 12f;
                    // Card top/bottom relative to the CONTENT container (independent of scroll).
                    // Walk up from the card to the content container, summing layout.y offsets.
                    var content = _assetScrollView.contentContainer;
                    float cardTopInContent = 0f;
                    VisualElement e = card;
                    int guard = 0;
                    while (e != null && e != content && guard++ < 100)
                    {
                        cardTopInContent += e.layout.y;
                        e = e.hierarchy.parent;
                    }
                    float cardHeight = card.layout.height;
                    float cardBottomInContent = cardTopInContent + cardHeight;

                    float viewTop = _assetScrollView.scrollOffset.y;
                    float vpHeight = viewport.resolvedStyle.height;
                    float viewBottom = viewTop + vpHeight;

                    float newY = viewTop;
                    if (cardTopInContent < viewTop + margin)
                        newY = Mathf.Max(0f, cardTopInContent - margin);
                    else if (cardBottomInContent > viewBottom - margin)
                        newY = cardBottomInContent - vpHeight + margin;
                    else
                        return; // fully visible already

                    var off = _assetScrollView.scrollOffset;
                    off.y = Mathf.Max(0f, newY);
                    _assetScrollView.scrollOffset = off;
                }
                catch { }
            }).ExecuteLater(1);
        }

        private void OnManagerItemStatusChanged(SyntyDownloadManager.DownloadItem item)
        {
            if (item == null || _multiInstallTotal < 1) return;
            // During the download-only phase we skip the per-asset spotlight/visual jumping (reserved
            // for install), BUT this is the responsive phase (network I/O, main thread free), so it's
            // the only time scrolling actually takes visual effect. Scroll the downloading card into
            // view here. (During install, Unity blocks the main thread with ImportPackage, so a
            // scroll wouldn't repaint until the whole batch finishes.)
            if (SyntyDownloadManager.Instance.DownloadOnlyMode)
            {
                if (item.status == SyntyDownloadManager.DownloadStatus.Downloading)
                {
                    VisualElement dlCard = null;
                    foreach (var kv in _assetPackMapping)
                    {
                        if (kv.Key < 0 || kv.Key >= _assetItems.Count) continue;
                        if (SyntyStoreService.ExtractHandleFromUrl(kv.Value.storeUrl) == item.productHandle)
                        {
                            dlCard = _assetItems[kv.Key].button;
                            break;
                        }
                    }
                    if (dlCard != null) ScrollCardIntoView(dlCard);
                }
                return;
            }
            if (item.status != SyntyDownloadManager.DownloadStatus.Downloading &&
                item.status != SyntyDownloadManager.DownloadStatus.Importing)
                return;
            // Only kick off the visual once per asset.
            if (_lastVisualizedHandle == item.productHandle) return;
            
            // Find the card for this item's handle.
            VisualElement card = null;
            foreach (var kvp in _assetPackMapping)
            {
                if (kvp.Key < 0 || kvp.Key >= _assetItems.Count) continue;
                if (SyntyStoreService.ExtractHandleFromUrl(kvp.Value.storeUrl) == item.productHandle)
                {
                    card = _assetItems[kvp.Key].button;
                    break;
                }
            }
            if (card == null) return;
            // Don't re-run the install visual on an already-installed card.
            var bv = card.Q<VisualElement>("asset-btn-visual");
            if (bv != null && bv.ClassListContains("asset-installed")) return;
            
            _lastVisualizedHandle = item.productHandle;
            // Customer-facing progress line for multi-installs.
            {
                int idx = (_multiInstallDone < _multiInstallTotal) ? _multiInstallDone + 1 : _multiInstallTotal;
                Synty.Tools.SyntyLog.Info($"Installing {item.productTitle} ({idx} of {_multiInstallTotal})");
                // During import, Unity shows its own "Preparing Package" progress bar which takes
                // over the screen, so we don't set our own here (it would just be clobbered). The
                // on-card spotlight/badge below shows which pack and the count behind Unity's bar.
            }
            
            var rRing   = card.Q<VisualElement>("radial-ring");
            var rRingBg = card.Q<VisualElement>("radial-ring-bg");
            var dlBtn   = card.Q<VisualElement>("download-btn");
            var dlIcon  = dlBtn?.Q<VisualElement>("download-icon");
            var selOvr  = card.Q<VisualElement>("asset-btn-selected");
            if (rRing == null || dlBtn == null) return;
            
            SpotlightCard(card);
            ScrollCardIntoView(card);
            MoveInstallBadgeToCard(card, item.productHandle);
            RunSingleDownload(rRing, rRingBg, dlBtn, dlIcon, selOvr, card, null, null, null, item.productHandle);
            // Make sure the ring sits on top of the product art / dim and the current card is not
            // darkened (the batch dimmed everything; this is the installing card so it stays lit).
            UndimCard(card);
            // The installing card stays bright (undimmed), but its sale "% OFF" badge overflows
            // the card and would paint over the install overlay, so hide it for the duration of
            // the install. RestoreUiAfterDownloads puts it back per the user's _showSaleAmount pref.
            var saleEl = card.Q<VisualElement>("sale-amount");
            if (saleEl != null) saleEl.style.display = DisplayStyle.None;
            if (rRingBg != null) rRingBg.BringToFront();
            rRing.BringToFront();
            var badgeEl = card.Q<Label>("download-status-badge");
            if (badgeEl != null) badgeEl.BringToFront();
            ForceRepaintNow();
            var badgeChk = card.Q<Label>("download-status-badge");
        }
        
        
        private void OnDownloadProgress(SyntyDownloadManager.DownloadItem item)
        {
            // TODO: Update the radial ring progress for the matching asset button
            // Find the button by product handle and update its visual progress
            Repaint();
        }
        
        // ─── Exclusive Deals ─────────────────────────────────────────────
        
        private void FetchExclusiveDeals()
        {
            string email = SyntyStoreHelper.LoggedInEmail;
            if (string.IsNullOrEmpty(email)) return;
            
            // Send the session token; the worker resolves the email from it (a body-supplied email
            // could be used to fetch anyone's deals/discount codes).
            string sessionToken = EditorPrefs.GetString("SyntyStore_SessionToken", "");
            if (string.IsNullOrEmpty(sessionToken)) return;
            string json = "{\"session_token\":\"" + sessionToken.Replace("\"", "") + "\"}";
            
            // Dispose any in-flight request before starting a new one
            if (_dealsRequest != null) { try { _dealsRequest.Abort(); _dealsRequest.Dispose(); } catch { } _dealsRequest = null; }
            
            var request = new UnityEngine.Networking.UnityWebRequest(
                "https://synty-downloads.syntystore.workers.dev/my-deals", "POST");
            request.uploadHandler = new UnityEngine.Networking.UploadHandlerRaw(
                System.Text.Encoding.UTF8.GetBytes(json));
            request.downloadHandler = new UnityEngine.Networking.DownloadHandlerBuffer();
            request.SetRequestHeader("Content-Type", "application/json");
            _dealsRequest = request;
            
            var op = request.SendWebRequest();
            op.completed += _ =>
            {
                if (!this) { try { request.Dispose(); } catch { } if (_dealsRequest == request) _dealsRequest = null; return; }
                if (request.result == UnityEngine.Networking.UnityWebRequest.Result.Success)
                {
                    try
                    {
                        var resp = JsonUtility.FromJson<DealsResponse>(request.downloadHandler.text);
                        _activeDeals = resp?.deals != null 
                            ? new System.Collections.Generic.List<ExclusiveDeal>(resp.deals) 
                            : new System.Collections.Generic.List<ExclusiveDeal>();
                        RenderExclusiveDeals();
                    }
                    catch { }
                }
                request.Dispose();
                if (_dealsRequest == request) _dealsRequest = null;
            };
        }
        
        [System.Serializable]
        private class DealsResponse
        {
            public bool success;
            public ExclusiveDeal[] deals;
        }
        
        private void RenderExclusiveDeals()
        {
            if (_dealsContainer == null) return;
            _dealsContainer.Clear();
            
            if (_activeDeals == null || _activeDeals.Count == 0)
            {
                _dealsContainer.style.display = DisplayStyle.None;
                return;
            }
            
            int rendered = 0;
            foreach (var deal in _activeDeals)
            {
                // For multi/all/theme deals: if the customer already owns every eligible pack,
                // there's nothing left to buy — hide the deal entirely instead of showing a
                // dead "you own everything" card. Single deals always render (the customer may
                // want to gift a pack they already own, etc).
                if (GetDealType(deal) != "single")
                {
                    var items = ResolveDealEligibleItems(deal);
                    if (items.Count == 0) continue;
                }
                var dealBtn = CreateDealButton(deal);
                _dealsContainer.Add(dealBtn);
                rendered++;
            }
            
            if (rendered == 0)
            {
                _dealsContainer.style.display = DisplayStyle.None;
                return;
            }
            UpdateDealsVisibility();
        }
        
        // Deals are hidden whenever the Synty Pass filter is active.
        private void UpdateDealsVisibility()
        {
            if (_dealsContainer == null) return;
            bool hasDeals = _activeDeals != null && _activeDeals.Count > 0;
            _dealsContainer.style.display = (hasDeals && !_licenseSyntyPass) ? DisplayStyle.Flex : DisplayStyle.None;
            UpdateEmptyStateTop();
        }
        
        // True when an exclusive deal button is currently shown at the top of the list.
        private bool DealsAreVisible()
        {
            return _activeDeals != null && _activeDeals.Count > 0 && !_licenseSyntyPass;
        }
        
        // Download the deal image uploaded via the sales portal (cached per URL) and apply it.
        private void LoadDealIconImage(string url, VisualElement target)
        {
            if (_dealIconCache.TryGetValue(url, out var cached) && cached != null)
            {
                target.style.backgroundImage = new StyleBackground(cached);
                return;
            }
            
            // Abort any previous in-flight icon fetch
            if (_dealIconRequest != null) { try { _dealIconRequest.Abort(); _dealIconRequest.Dispose(); } catch { } _dealIconRequest = null; }
            
            var req = UnityEngine.Networking.UnityWebRequestTexture.GetTexture(url);
            _dealIconRequest = req;
            var op = req.SendWebRequest();
            op.completed += _ =>
            {
                try
                {
                    if (req.result == UnityEngine.Networking.UnityWebRequest.Result.Success)
                    {
                        var tex = UnityEngine.Networking.DownloadHandlerTexture.GetContent(req);
                        if (tex != null)
                        {
                            tex.hideFlags = HideFlags.HideAndDontSave;
                            _dealIconCache[url] = tex;
                            if (target != null && target.panel != null)
                                target.style.backgroundImage = new StyleBackground(tex);
                        }
                    }
                }
                catch { }
                finally
                {
                    try { req.Dispose(); } catch { }
                    if (_dealIconRequest == req) _dealIconRequest = null;
                }
            };
        }
        
        // Start the empty-state overlay below the deal button so its centered message/button
        // doesn't draw on top of the exclusive deal.
        private void UpdateEmptyStateTop()
        {
            if (_emptyStateContainer == null) return;
            _emptyStateContainer.style.top = DealsAreVisible() ? (_assetButtonSize3Across + _assetBtnMargin * 2f) : 0f;
        }
        
        private VisualElement CreateDealButton(ExclusiveDeal deal)
        {
            // Placeholder rectangle button — 3 asset-buttons wide.
            // Real UI art will be swapped in later.
            var btn = new VisualElement();
            btn.name = "deal-button";
            btn.AddToClassList("deal-button");
            btn.userData = deal.id; // lets per-deal updaters (e.g. UpdateDealTypeBg) match overlays back to their deal data
            // Height matches the largest asset button (3-across size); left-aligned, sized to the banner
            float dealHeight = _assetButtonSize3Across;
            btn.style.height = dealHeight;
            btn.style.flexShrink = 0; // don't stretch/shrink with the row — leave empty space on the right
            btn.style.overflow = Overflow.Visible; // children (e.g. sale amount) may spill past the edges
            btn.style.marginTop = _assetBtnMargin;
            btn.style.marginBottom = _assetBtnMargin;
            btn.style.marginLeft = _assetBtnMargin;
            btn.style.marginRight = _assetBtnMargin;
            // Inner clip layer: holds the bleeding art/overlays and clips them to the button edges,
            // while the button itself stays overflow-visible so badges can spill outside.
            var dealClip = new VisualElement();
            dealClip.name = "deal-clip";
            dealClip.pickingMode = PickingMode.Ignore;
            dealClip.style.position = Position.Absolute;
            dealClip.style.top = 0;
            dealClip.style.left = 0;
            dealClip.style.right = 0;
            dealClip.style.bottom = 0;
            dealClip.style.overflow = Overflow.Hidden;
            dealClip.style.borderTopLeftRadius = 8;
            dealClip.style.borderTopRightRadius = 8;
            dealClip.style.borderBottomLeftRadius = 8;
            dealClip.style.borderBottomRightRadius = 8;
            btn.Add(dealClip);
            // Background art — Asset_Button_Background_ExclusiveDeal, tinted black.
            // Rendered as a centered child kept at the texture's true ratio and scaled to the
            // button height, so a wide texture flows out past the left and right edges.
            float dealArtAspect = 0f; // texture aspect — shared so the hover overlay matches the art exactly
            var dealBg = LoadImage("Assets", "Asset_Button_Background_ExclusiveDeal");
            if (dealBg != null && dealBg.height > 0)
            {
                dealArtAspect = (float)dealBg.width / dealBg.height;
                var dealArt = new VisualElement();
                dealArt.name = "deal-button-art";
                dealArt.pickingMode = PickingMode.Ignore; // let clicks fall through to the button
                dealArt.style.position = Position.Absolute;
                dealArt.style.top = 0;
                dealArt.style.height = dealHeight;
                dealArt.style.width = dealHeight * dealArtAspect; // true texture ratio, no distortion
                dealArt.style.left = Length.Percent(50);
                dealArt.style.translate = new Translate(Length.Percent(-50), 0); // center horizontally
                dealArt.style.backgroundImage = new StyleBackground(dealBg);
                dealArt.style.unityBackgroundImageTintColor = Color.black;
                dealArt.style.SetBackgroundStretchToFill();
                dealClip.Add(dealArt);
                btn.style.backgroundColor = Color.clear;
                btn.style.width = _dealButtonWidth; // fixed, left-aligned; art is centered within (left:50% + translate)
            }
            else
            {
                // Fallback until Asset_Button_Background_ExclusiveDeal.png is added to the project
                btn.style.backgroundColor = Color.black;
                btn.style.flexGrow = 1;
                btn.style.flexBasis = Length.Percent(100);
            }
            
            // Deal image uploaded via the sales portal — occupies the same space as the
            // background art, layered above it but below the selected overlays
            var dealIconImg = new VisualElement();
            dealIconImg.name = "deal-icon-img";
            dealIconImg.pickingMode = PickingMode.Ignore;
            dealIconImg.style.position = Position.Absolute;
            if (dealArtAspect > 0f)
            {
                dealIconImg.style.top = 0;
                dealIconImg.style.height = dealHeight;
                dealIconImg.style.width = dealHeight * dealArtAspect;
                dealIconImg.style.left = Length.Percent(50);
                dealIconImg.style.translate = new Translate(Length.Percent(-50), 0);
            }
            else
            {
                dealIconImg.style.top = 0;
                dealIconImg.style.left = 0;
                dealIconImg.style.right = 0;
                dealIconImg.style.bottom = 0;
            }
            dealIconImg.style.SetBackgroundStretchToFill();
            dealClip.Add(dealIconImg);
            if (!string.IsNullOrEmpty(deal.icon_url))
                LoadDealIconImage(deal.icon_url, dealIconImg);
            btn.style.borderTopLeftRadius = 8;
            btn.style.borderTopRightRadius = 8;
            btn.style.borderBottomLeftRadius = 8;
            btn.style.borderBottomRightRadius = 8;
            btn.style.justifyContent = Justify.Center;
            btn.style.alignItems = Align.Center;
            
            // Local builder: an absolute overlay matching the background art's geometry (or filling the button if no art)
            VisualElement MakeArtOverlay(string ovName, Texture2D ovTex, Color ovTint)
            {
                var ov = new VisualElement();
                ov.name = ovName;
                ov.pickingMode = PickingMode.Ignore;
                ov.style.position = Position.Absolute;
                if (dealArtAspect > 0f)
                {
                    ov.style.top = 0;
                    ov.style.height = dealHeight;
                    ov.style.width = dealHeight * dealArtAspect;
                    ov.style.left = Length.Percent(50);
                    ov.style.translate = new Translate(Length.Percent(-50), 0);
                }
                else
                {
                    ov.style.top = 0; ov.style.left = 0; ov.style.right = 0; ov.style.bottom = 0;
                }
                if (ovTex != null)
                {
                    ov.style.backgroundImage = new StyleBackground(ovTex);
                    ov.style.SetBackgroundStretchToFill();
                    ov.style.unityBackgroundImageTintColor = ovTint;
                }
                return ov;
            }
            
            var dealSelTex = LoadImage("Assets", "Asset_Button_Selected_ExclusiveDeal");
            
            // Always-on selected frame — same texture, permanently visible, tintable in the options
            dealClip.Add(MakeArtOverlay("deal-selected-always", dealSelTex, _dealSelectedAlwaysColor));
            
            // Hover highlight overlay — fades in on mouse over
            var dealSelected = MakeArtOverlay("deal-selected", dealSelTex, Color.white);
            dealSelected.style.opacity = 0;
            dealSelected.style.transitionProperty = new List<StylePropertyName> { new StylePropertyName("opacity") };
            dealSelected.style.transitionDuration = new List<TimeValue> { new TimeValue(150, TimeUnit.Millisecond) };
            dealSelected.style.transitionTimingFunction = new List<EasingFunction> { new EasingFunction(EasingMode.EaseOut) };
            dealClip.Add(dealSelected);
            // Price popup — created lazily on first hover so it can look up pack pricing AFTER
            // asset packs finish loading (deals may arrive before the catalog is ready).
            VisualElement dealPriceTooltip = null;
            VisualElement dealBadgeRef = null;
            VisualElement dealSaleAmtRef = null;
            
            // Hover state helpers — let child buttons (Product Link, Get Offer) release the hover
            // state when they're the active target, so the parent deal button returns to its
            // resting visual just like asset buttons do with the cart/download buttons.
            System.Action applyHover = null;
            System.Action releaseHover = null;
            applyHover = () =>
            {
                dealSelected.style.opacity = 1f;
                btn.style.transitionDuration = new List<TimeValue> { new TimeValue(0, TimeUnit.Millisecond) };
                btn.style.scale = new Scale(new Vector3(_dealPressedScale, _dealPressedScale, 1f));
                if (dealSaleAmtRef != null)
                {
                    float hovered = _dealSaleAmountScale * _dealSaleAmountHoverScale;
                    dealSaleAmtRef.style.scale = new Scale(new Vector3(hovered, hovered, 1f));
                }
                if (!_showDealPriceTooltip) return;
                if (dealPriceTooltip == null)
                {
                    dealPriceTooltip = CreateDealPriceTooltip(deal);
                    if (dealPriceTooltip != null)
                    {
                        dealPriceTooltip.name = "deal-price-tooltip";
                        btn.Add(dealPriceTooltip);
                    }
                }
                if (dealPriceTooltip != null)
                {
                    dealPriceTooltip.BringToFront();
                    dealPriceTooltip.style.display = DisplayStyle.Flex;
                    if (dealBadgeRef != null) dealBadgeRef.style.display = DisplayStyle.None;
                }
            };
            releaseHover = () =>
            {
                dealSelected.style.opacity = 0f;
                btn.style.transitionDuration = new List<TimeValue> { new TimeValue(_dealAnimDuration, TimeUnit.Millisecond) };
                btn.style.scale = new Scale(Vector3.one);
                if (dealSaleAmtRef != null)
                    dealSaleAmtRef.style.scale = new Scale(new Vector3(_dealSaleAmountScale, _dealSaleAmountScale, 1f));
                if (dealPriceTooltip != null) dealPriceTooltip.style.display = DisplayStyle.None;
                if (dealBadgeRef != null) dealBadgeRef.style.display = _showDealBadge ? DisplayStyle.Flex : DisplayStyle.None;
            };
            
            // Press-in hover animation, same as the asset buttons (instant press, eased release)
            btn.style.transitionProperty = new List<StylePropertyName> { new StylePropertyName("scale") };
            btn.style.transitionTimingFunction = new List<EasingFunction> { new EasingFunction(EasingMode.EaseOut) };
            btn.RegisterCallback<MouseEnterEvent>(_ => applyHover());
            btn.RegisterCallback<MouseLeaveEvent>(_ => releaseHover());
            
            // Product page link (top-left), like the asset buttons — opens the deal's product.
            // Only meaningful for "single" deals (one product to link to); for multi/all/theme
            // we hide it since there's no single canonical product to point the customer at.
            var dealProductBtn = CreateDealProductButton(deal);
            if (GetDealType(deal) != "single")
                dealProductBtn.style.display = DisplayStyle.None;
            btn.Add(dealProductBtn);
            // Treat hover on the product link as "off the main body" — release hover state
            dealProductBtn.RegisterCallback<MouseEnterEvent>(_ => releaseHover());
            dealProductBtn.RegisterCallback<MouseLeaveEvent>(_ => applyHover());
            
            // Exclusive deal badge (top-right), a copy of the On Sale badge
            dealBadgeRef = CreateDealBadge();
            btn.Add(dealBadgeRef);
            
            // Type background — drawn in the same space as the art but layered above everything
            // Per-deal type-bg colour overrides the global default — admin sets this in the
            // sales portal so each deal can have its own brand accent.
            Color dealTypeBgColor = ParseHexColorOrDefault(deal.type_bg_color, _dealTypeBgColor);
            var dealTypeBg = MakeArtOverlay("deal-type-bg", LoadImage("Assets", "Asset_Button_TypeBackground_ExclusiveDeal"), dealTypeBgColor);
            dealClip.Add(dealTypeBg);
            
            // Asset Type + Asset Name text — same positions/fonts as the asset buttons. For
            // multi/all/theme deals, fall back to type-aware defaults (BUNDLE/COMPLETE + a count)
            // so the admin doesn't have to type a label for every deal. If they DID set line1/
            // line2, those win — admin override always beats the auto-default.
            string defaultLine1, defaultLine2;
            ComputeDealTypeLabels(deal, out defaultLine1, out defaultLine2);
            var dealTypeLabel = new Label(!string.IsNullOrEmpty(deal.line1) ? deal.line1 : defaultLine1);
            dealTypeLabel.name = "deal-type-label";
            dealTypeLabel.style.position = Position.Absolute;
            dealTypeLabel.style.left = _dealTypeLabelX;
            dealTypeLabel.style.bottom = _typeLabelY;
            dealTypeLabel.style.fontSize = _typeFontSize;
            dealTypeLabel.style.color = _dealTypeTextColor;
            if (_titleFont != null)
                dealTypeLabel.style.unityFontDefinition = FontDefinition.FromFont(_titleFont);
            dealTypeLabel.style.unityFontStyleAndWeight = _typeLabelBold ? FontStyle.Bold : FontStyle.Normal;
            dealTypeLabel.style.unityTextAlign = TextAnchor.LowerLeft;
            dealTypeLabel.pickingMode = PickingMode.Ignore;
            btn.Add(dealTypeLabel);
            
            var dealNameLabel = new Label(!string.IsNullOrEmpty(deal.line2) ? deal.line2 : defaultLine2);
            dealNameLabel.name = "deal-name-label";
            dealNameLabel.style.position = Position.Absolute;
            dealNameLabel.style.left = _dealNameLabelX;
            dealNameLabel.style.bottom = _nameLabelY;
            dealNameLabel.style.fontSize = _nameFontSize;
            dealNameLabel.style.color = _dealNameTextColor;
            dealNameLabel.style.unityFontStyleAndWeight = _nameLabelBold ? FontStyle.Bold : FontStyle.Normal;
            dealNameLabel.style.unityTextAlign = TextAnchor.LowerLeft;
            dealNameLabel.style.overflow = Overflow.Hidden;
            dealNameLabel.style.textOverflow = TextOverflow.Ellipsis;
            dealNameLabel.pickingMode = PickingMode.Ignore;
            btn.Add(dealNameLabel);
            
            // Deal sale amount image (Sales_Amount_XX_Deal) from the discount percentage
            VisualElement dealSaleAmt = null;
            if (string.IsNullOrEmpty(deal.discount_type) || deal.discount_type == "percentage")
            {
                int dealSaleBucket = ComputeDealSaleBucket(GetEffectiveDealDiscountAmount(deal));
                dealSaleAmt = new VisualElement();
                dealSaleAmt.name = "deal-sale-amount";
                dealSaleAmt.pickingMode = PickingMode.Ignore;
                dealSaleAmt.style.position = Position.Absolute;
                dealSaleAmt.style.right = _dealSaleAmountX;
                dealSaleAmt.style.bottom = _dealSaleAmountY;
                dealSaleAmt.style.width = _dealSaleAmountWidth;
                dealSaleAmt.style.height = _dealSaleAmountHeight;
                dealSaleAmt.style.scale = new Scale(new Vector3(_dealSaleAmountScale, _dealSaleAmountScale, 1f));
                dealSaleAmt.style.transformOrigin = new TransformOrigin(
                    Length.Percent(_dealSaleAmountHoverPivotX),
                    Length.Percent(_dealSaleAmountHoverPivotY), 0);
                dealSaleAmt.style.transitionProperty = new List<StylePropertyName> { new StylePropertyName("scale") };
                dealSaleAmt.style.transitionDuration = new List<TimeValue> { new TimeValue(_dealSaleAmountHoverDurationMs, TimeUnit.Millisecond) };
                dealSaleAmt.style.transitionTimingFunction = new List<EasingFunction> { new EasingFunction(EasingMode.EaseOut) };
                var dealSaleTex = LoadImage("Sales", $"Sales_Amount_{dealSaleBucket}_Deal");
                if (dealSaleTex != null)
                {
                    dealSaleAmt.style.backgroundImage = new StyleBackground(dealSaleTex);
                    dealSaleAmt.style.SetBackgroundScaleToFit();
                }
                dealSaleAmt.style.display = _showDealSaleAmount ? DisplayStyle.Flex : DisplayStyle.None;
                btn.Add(dealSaleAmt);
                dealSaleAmtRef = dealSaleAmt;
            }
            
            // Live countdown timer — DAYS / HOURS / MINUTES / SECONDS in rounded coloured boxes
            var dealTimer = new VisualElement();
            dealTimer.name = "deal-timer";
            dealTimer.pickingMode = PickingMode.Ignore;
            dealTimer.style.position = Position.Absolute;
            dealTimer.style.right = _dealTimerX;
            dealTimer.style.bottom = _dealTimerY;
            dealTimer.style.flexDirection = FlexDirection.Row;
            dealTimer.style.alignItems = Align.FlexStart;
            dealTimer.style.scale = new Scale(new Vector3(_dealTimerScale, _dealTimerScale, 1f));
            dealTimer.style.display = _showDealTimer ? DisplayStyle.Flex : DisplayStyle.None;
            
            Label MakeTimerBox(string boxName)
            {
                var box = new Label("00");
                box.name = boxName;
                box.pickingMode = PickingMode.Ignore;
                box.style.width = _dealTimerBoxWidth;
                box.style.height = _dealTimerBoxHeight;
                box.style.backgroundColor = _dealTimerBoxColor;
                box.style.borderTopLeftRadius = _dealTimerBoxRadius;
                box.style.borderTopRightRadius = _dealTimerBoxRadius;
                box.style.borderBottomLeftRadius = _dealTimerBoxRadius;
                box.style.borderBottomRightRadius = _dealTimerBoxRadius;
                box.style.color = _dealTimerBoxTextColor;
                box.style.fontSize = _dealTimerBoxFontSize;
                box.style.unityFontStyleAndWeight = FontStyle.Bold;
                box.style.unityTextAlign = TextAnchor.MiddleCenter;
                if (_newakeFont != null) box.style.unityFontDefinition = FontDefinition.FromFont(_newakeFont);
                return box;
            }
            Label MakeTimerUnitLabel(string text)
            {
                var lbl = new Label(text);
                lbl.pickingMode = PickingMode.Ignore;
                lbl.style.color = _dealTimerLabelColor;
                lbl.style.fontSize = _dealTimerLabelFontSize;
                lbl.style.unityFontStyleAndWeight = FontStyle.Bold;
                lbl.style.unityTextAlign = TextAnchor.MiddleCenter;
                lbl.style.marginTop = _dealTimerLabelMarginTop;
                lbl.style.translate = new Translate(_dealTimerLabelX, _dealTimerLabelY);
                lbl.style.minWidth = _dealTimerBoxWidth;
                if (_newakeFont != null) lbl.style.unityFontDefinition = FontDefinition.FromFont(_newakeFont);
                lbl.AddToClassList("deal-timer-unit-label");
                return lbl;
            }
            Label MakeTimerColon()
            {
                var c = new Label(":");
                c.pickingMode = PickingMode.Ignore;
                c.style.color = _dealTimerColonColor;
                c.style.fontSize = _dealTimerColonFontSize;
                c.style.height = _dealTimerBoxHeight;
                c.style.unityFontStyleAndWeight = FontStyle.Bold;
                c.style.unityTextAlign = TextAnchor.MiddleCenter;
                c.style.marginLeft = _dealTimerGap;
                c.style.marginRight = _dealTimerGap;
                c.style.translate = new Translate(0, _dealTimerColonY);
                if (_newakeFont != null) c.style.unityFontDefinition = FontDefinition.FromFont(_newakeFont);
                c.AddToClassList("deal-timer-colon");
                return c;
            }
            VisualElement MakeTimerUnit(Label box, string labelText)
            {
                var col = new VisualElement();
                col.pickingMode = PickingMode.Ignore;
                col.style.flexDirection = FlexDirection.Column;
                col.style.alignItems = Align.Center;
                col.Add(box);
                col.Add(MakeTimerUnitLabel(labelText));
                return col;
            }
            
            var daysBox  = MakeTimerBox("deal-timer-days");
            var hoursBox = MakeTimerBox("deal-timer-hours");
            var minsBox  = MakeTimerBox("deal-timer-mins");
            var secsBox  = MakeTimerBox("deal-timer-secs");
            dealTimer.Add(MakeTimerUnit(daysBox,  "DAYS"));
            dealTimer.Add(MakeTimerColon());
            dealTimer.Add(MakeTimerUnit(hoursBox, "HOURS"));
            dealTimer.Add(MakeTimerColon());
            dealTimer.Add(MakeTimerUnit(minsBox,  "MINUTES"));
            dealTimer.Add(MakeTimerColon());
            dealTimer.Add(MakeTimerUnit(secsBox,  "SECONDS"));
            btn.Add(dealTimer);
            
            // Tick the countdown
            var endTime = ParseDealEndTime(deal);
            ScheduleDealCountdown(dealTimer, daysBox, hoursBox, minsBox, secsBox, endTime, deal);
            
            // Click → same behaviour as the GET OFFER button: build the cart URL with the
            // deal's eligible variants and the per-customer discount code applied. Falls
            // back to the discount landing page if no variants resolve.
            btn.RegisterCallback<MouseDownEvent>(evt =>
            {
                SyntyAnalytics.Track("exclusive_deal_click", new System.Collections.Generic.Dictionary<string, object>
                {
                    { "deal_id", deal.id },
                    { "product_handle", deal.product_handle ?? "" }
                });
                Application.OpenURL(BuildDealCartUrl(deal));
            });
            
            // Keep the type background above the badge/product/timer, then the text on top of it
            dealTypeBg.BringToFront();
            dealTypeLabel.BringToFront();
            dealNameLabel.BringToFront();
            dealSaleAmt?.BringToFront();
            
            // "GET OFFER" button (bottom-right, filter-button styled)
            var dealOfferBtn = CreateDealOfferButton(deal);
            btn.Add(dealOfferBtn);
            dealOfferBtn.BringToFront();
            
            // While hovering the offer button, treat it as "off the main body" — release the
            // deal button's full hover state (scale, popup, badge). Leaving the offer button
            // back onto the deal body re-applies it; leaving the whole button still ends with
            // it released because the button's own MouseLeave fires last.
            dealOfferBtn.RegisterCallback<MouseEnterEvent>(_ => releaseHover());
            dealOfferBtn.RegisterCallback<MouseLeaveEvent>(_ => applyHover());
            
            // Sale-amount percentage image renders on top of the offer button
            dealSaleAmt?.BringToFront();
            
            return btn;
        }
        // Opens the product the discount applies to; stops the click from also firing checkout.
        private VisualElement CreateDealProductButton(ExclusiveDeal deal)
        {
            var productBtn = new VisualElement();
            productBtn.name = "deal-product-btn";
            productBtn.style.position = Position.Absolute;
            productBtn.style.width = 28;
            productBtn.style.height = 28;
            productBtn.style.backgroundColor = Color.clear;
            ApplyDealProductOffsets(productBtn); // same offset + scale the asset buttons use for the current grid
            
            var roundTex = LoadImage("Buttons", "Button_Round");
            if (roundTex != null)
                productBtn.style.backgroundImage = new StyleBackground(roundTex);
            productBtn.style.unityBackgroundImageTintColor = Color.black; // button background black
            
            // Product-page icon inside the button (white)
            var productIcon = new VisualElement();
            productIcon.name = "deal-product-icon";
            productIcon.style.position = Position.Absolute;
            productIcon.style.top = _productIconPadding;
            productIcon.style.left = _productIconPadding;
            productIcon.style.right = _productIconPadding;
            productIcon.style.bottom = _productIconPadding;
            productIcon.pickingMode = PickingMode.Ignore;
            var prodTex = LoadImage("Assets", "Icon_ProductPage");
            if (prodTex != null)
            {
                productIcon.style.backgroundImage = new StyleBackground(prodTex);
                productIcon.style.SetBackgroundScaleToFit();
            }
            productIcon.style.unityBackgroundImageTintColor = Color.white;
            productBtn.Add(productIcon);
            
            // Hover scale (matches the asset product button)
            productBtn.style.transitionProperty = new List<StylePropertyName> { new StylePropertyName("scale") };
            productBtn.style.transitionDuration = new List<TimeValue> { new TimeValue(100, TimeUnit.Millisecond) };
            productBtn.style.transitionTimingFunction = new List<EasingFunction> { new EasingFunction(EasingMode.EaseOut) };
            productBtn.RegisterCallback<MouseEnterEvent>(_ =>
                productBtn.style.scale = new Scale(new Vector3(_productBtnHoverScale, _productBtnHoverScale, 1f)));
            productBtn.RegisterCallback<MouseLeaveEvent>(_ =>
                productBtn.style.scale = new Scale(Vector3.one));
            
            // Click → open the discounted product's page; stop the deal-button checkout from firing too
            productBtn.RegisterCallback<MouseDownEvent>(evt =>
            {
                evt.StopPropagation();
                SyntyAnalytics.Track("exclusive_deal_product_click", new System.Collections.Generic.Dictionary<string, object>
                {
                    { "deal_id", deal.id },
                    { "product_handle", deal.product_handle ?? "" }
                });
                string purl = !string.IsNullOrEmpty(deal.product_handle)
                    ? AppendUtm($"https://syntystore.com/products/{deal.product_handle}", "exclusive_deal_product")
                    : SyntyCatalogBridge.STORE_AFFILIATE_URL;
                Application.OpenURL(purl);
            });
            
            return productBtn;
        }
        
        // Matches the asset buttons' product-button offset + scale for the current grid size,
        // so the deal button's product button stays the same size/position as the asset ones.
        private void ApplyDealProductOffsets(VisualElement productBtn)
        {
            if (productBtn == null) return;
            // Position from the deal-specific offset (editable in the options); scale tracks the asset grid size
            float prodScale = (_thumbnailColumns >= 5) ? _smallProductBtnScale
                            : (_thumbnailColumns >= 4) ? _medProductBtnScale : 1f;
            productBtn.style.left = _dealProductBtnX;
            productBtn.style.top = _dealProductBtnY;
            productBtn.style.scale = new Scale(new Vector3(prodScale, prodScale, 1f));
        }
        
        // Re-apply the product-button offset to every rendered deal button (used by the options panel).
        private void UpdateDealProductButtons()
        {
            if (_dealsContainer == null) return;
            _dealsContainer.Query<VisualElement>("deal-product-btn").ForEach(ApplyDealProductOffsets);
        }
        
        // Re-tint the always-on selected frame on every rendered deal button.
        private void UpdateDealSelectedAlways()
        {
            if (_dealsContainer == null) return;
            _dealsContainer.Query<VisualElement>("deal-selected-always")
                .ForEach(ov => ov.style.unityBackgroundImageTintColor = _dealSelectedAlwaysColor);
        }
        
        // Re-tint the asset-type background image on every rendered deal button — each deal
        // carries its own colour, so we walk the active list and match overlays to deals by id.
        private void UpdateDealTypeBg()
        {
            if (_dealsContainer == null) return;
            // Build id → color lookup so the foreach doesn't do an N² scan.
            var colorByDealId = new Dictionary<string, Color>();
            if (_activeDeals != null)
            {
                foreach (var d in _activeDeals)
                {
                    if (d == null || string.IsNullOrEmpty(d.id)) continue;
                    colorByDealId[d.id] = ParseHexColorOrDefault(d.type_bg_color, _dealTypeBgColor);
                }
            }
            _dealsContainer.Query<VisualElement>("deal-button").ForEach(btn =>
            {
                var ov = btn.Q<VisualElement>("deal-type-bg");
                if (ov == null) return;
                // The deal id lives on the button as a userData stash so we don't depend on
                // DOM order matching _activeDeals (which can re-order between renders).
                string dealId = btn.userData as string;
                if (!string.IsNullOrEmpty(dealId) && colorByDealId.TryGetValue(dealId, out var c))
                    ov.style.unityBackgroundImageTintColor = c;
                else
                    ov.style.unityBackgroundImageTintColor = _dealTypeBgColor;
            });
        }
        
        // Parse a "#RRGGBB" / "#RRGGBBAA" / "RRGGBB" hex string into a Color. Returns the
        // fallback unchanged if the input is null/empty/malformed.
        private Color ParseHexColorOrDefault(string hex, Color fallback)
        {
            if (string.IsNullOrEmpty(hex)) return fallback;
            string s = hex.Trim();
            if (!s.StartsWith("#")) s = "#" + s;
            if (ColorUtility.TryParseHtmlString(s, out var c)) return c;
            return fallback;
        }
        
        // Re-apply the fixed deal button width on every rendered deal button.
        private void UpdateDealButtonWidth()
        {
            if (_dealsContainer == null) return;
            _dealsContainer.Query<VisualElement>("deal-button").ForEach(b => b.style.width = _dealButtonWidth);
        }
        
        // Build the deal's price popup — strike-through original + sale price after the deal discount.
        // Returns null when the pack can't be resolved or the deal has no usable price.
        private VisualElement CreateDealPriceTooltip(ExclusiveDeal deal)
        {
            // Sum every eligible pack's price (the resolver already excludes owned items for
            // all/theme), then apply the discount to the total. This way the popup shows the
            // actual savings for a multi-item purchase.
            float origPrice = 0f;
            var items = ResolveDealEligibleItems(deal);
            foreach (var it in items)
                origPrice += it.price;
            if (origPrice <= 0f) return null;
            
            // Compute the deal sale price using the effective tier amount (ramps with the
            // customer's eligibility — a customer with more unowned packs sees a bigger %).
            float effectiveAmount = GetEffectiveDealDiscountAmount(deal);
            float salePrice = origPrice;
            if (string.IsNullOrEmpty(deal.discount_type) || deal.discount_type == "percentage")
                salePrice = origPrice * (1f - Mathf.Clamp(effectiveAmount, 0f, 100f) / 100f);
            else if (deal.discount_type == "fixed")
                salePrice = Mathf.Max(0f, origPrice - effectiveAmount);
            if (salePrice >= origPrice) return null; // nothing to display
            
            float saleFontSize = _salePriceFontSize > 0f ? _salePriceFontSize : _tooltipFontSize;
            
            var tip = new VisualElement();
            tip.name = "deal-price-tooltip";
            tip.style.position = Position.Absolute;
            tip.style.top = _dealPriceTooltipY;
            tip.style.right = _dealPriceTooltipX;
            tip.style.translate = new Translate(_dealPriceTooltipOffsetX, _dealPriceTooltipOffsetY);
            tip.style.scale = new Scale(new Vector3(_dealPriceTooltipScale, _dealPriceTooltipScale, 1f));
            tip.style.paddingLeft = 8;
            tip.style.paddingRight = 8;
            tip.style.paddingTop = 4;
            tip.style.paddingBottom = 4;
            tip.style.backgroundColor = _tooltipSaleBgColor;
            tip.style.borderTopLeftRadius = 4;
            tip.style.borderTopRightRadius = 4;
            tip.style.borderBottomLeftRadius = 4;
            tip.style.borderBottomRightRadius = 4;
            tip.style.flexDirection = FlexDirection.Column;
            tip.style.alignItems = Align.Center;
            tip.style.display = DisplayStyle.None;
            tip.pickingMode = PickingMode.Ignore;
            
            // Original price + strike line
            var origContainer = new VisualElement();
            origContainer.style.position = Position.Relative;
            origContainer.style.alignSelf = Align.Center;
            origContainer.pickingMode = PickingMode.Ignore;
            var origLabel = new Label(SyntyCurrency.Format(origPrice, false));
            origLabel.style.color = _saleOriginalPriceColor;
            origLabel.style.fontSize = saleFontSize;
            origLabel.style.unityTextAlign = TextAnchor.MiddleCenter;
            origLabel.pickingMode = PickingMode.Ignore;
            origContainer.Add(origLabel);
            var strikeLine = new VisualElement();
            strikeLine.style.position = Position.Absolute;
            strikeLine.style.top = Length.Percent(50);
            strikeLine.style.left = 0;
            strikeLine.style.right = 0;
            strikeLine.style.height = 1;
            strikeLine.style.backgroundColor = _saleStrikeColor;
            strikeLine.pickingMode = PickingMode.Ignore;
            origContainer.Add(strikeLine);
            tip.Add(origContainer);
            
            // Sale price
            var priceLabel = new Label(salePrice <= 0.005f ? "FREE" : SyntyCurrency.Format(salePrice));
            priceLabel.style.color = _salePriceColor;
            priceLabel.style.fontSize = saleFontSize;
            priceLabel.style.unityFontStyleAndWeight = _salePriceBold ? FontStyle.Bold : FontStyle.Normal;
            priceLabel.style.unityTextAlign = TextAnchor.MiddleCenter;
            priceLabel.pickingMode = PickingMode.Ignore;
            tip.Add(priceLabel);
            
            return tip;
        }
        
        // Live-apply deal price tooltip position/visibility, for the options panel.
        private void UpdateDealPriceTooltip()
        {
            if (_dealsContainer == null) return;
            _dealsContainer.Query<VisualElement>("deal-price-tooltip").ForEach(t =>
            {
                t.style.top = _dealPriceTooltipY;
                t.style.right = _dealPriceTooltipX;
                t.style.translate = new Translate(_dealPriceTooltipOffsetX, _dealPriceTooltipOffsetY);
                t.style.scale = new Scale(new Vector3(_dealPriceTooltipScale, _dealPriceTooltipScale, 1f));
            });
        }
        
        // Live-apply timer position, sizes and colors, for the options panel.
        private void UpdateDealTimer(){
            if (_dealsContainer == null) return;
            _dealsContainer.Query<VisualElement>("deal-timer").ForEach(t =>
            {
                t.style.right = _dealTimerX;
                t.style.bottom = _dealTimerY;
                t.style.scale = new Scale(new Vector3(_dealTimerScale, _dealTimerScale, 1f));
                t.style.display = _showDealTimer ? DisplayStyle.Flex : DisplayStyle.None;
                foreach (var box in t.Query<Label>().ToList())
                {
                    if (box.ClassListContains("deal-timer-colon"))
                    {
                        box.style.color = _dealTimerColonColor;
                        box.style.fontSize = _dealTimerColonFontSize;
                        box.style.height = _dealTimerBoxHeight;
                        box.style.marginLeft = _dealTimerGap;
                        box.style.marginRight = _dealTimerGap;
                        box.style.translate = new Translate(0, _dealTimerColonY);
                    }
                    else if (box.ClassListContains("deal-timer-unit-label"))
                    {
                        box.style.color = _dealTimerLabelColor;
                        box.style.fontSize = _dealTimerLabelFontSize;
                        box.style.minWidth = _dealTimerBoxWidth;
                        box.style.marginTop = _dealTimerLabelMarginTop;
                        box.style.translate = new Translate(_dealTimerLabelX, _dealTimerLabelY);
                    }
                    else
                    {
                        // digit box
                        box.style.width = _dealTimerBoxWidth;
                        box.style.height = _dealTimerBoxHeight;
                        box.style.backgroundColor = _dealTimerBoxColor;
                        box.style.color = _dealTimerBoxTextColor;
                        box.style.fontSize = _dealTimerBoxFontSize;
                        box.style.borderTopLeftRadius = _dealTimerBoxRadius;
                        box.style.borderTopRightRadius = _dealTimerBoxRadius;
                        box.style.borderBottomLeftRadius = _dealTimerBoxRadius;
                        box.style.borderBottomRightRadius = _dealTimerBoxRadius;
                    }
                }
            });
        }
        
        // "GET OFFER" button styled like the filter buttons (3-part texture + white outline on hover),
        // with the add-to-cart icon, pinned to the deal button's bottom-right.
        private VisualElement CreateDealOfferButton(ExclusiveDeal deal)
        {
            float h = _dealOfferBtnHeight;
            var offerBtn = new VisualElement();
            offerBtn.name = "deal-offer-btn";
            offerBtn.style.position = Position.Absolute;
            offerBtn.style.right = _dealOfferBtnX;
            offerBtn.style.bottom = _dealOfferBtnY;
            offerBtn.style.height = h;
            if (_dealOfferBtnWidth > 0f) offerBtn.style.width = _dealOfferBtnWidth;
            offerBtn.style.flexDirection = FlexDirection.Row;
            offerBtn.style.alignItems = Align.Center;
            offerBtn.style.justifyContent = Justify.Center;
            offerBtn.style.paddingLeft = h * 0.55f;
            offerBtn.style.paddingRight = h * 0.55f;
            offerBtn.AddToClassList("link-cursor");
            
            bool use3Part = _filterBtnEnd != null && _filterBtnMiddle != null;
            float endAspect = use3Part ? (float)_filterBtnEnd.width / _filterBtnEnd.height : 0.5f;
            float endWidth = Mathf.Ceil(h * endAspect);
            
            VisualElement hoverOverlay = null;
            if (use3Part)
            {
                var bg = new VisualElement();
                bg.name = "deal-offer-bg";
                bg.style.position = Position.Absolute;
                bg.style.left = 0; bg.style.right = 0; bg.style.top = 0; bg.style.bottom = 0;
                bg.style.flexDirection = FlexDirection.Row;
                bg.style.alignItems = Align.Stretch;
                bg.style.overflow = Overflow.Hidden;
                bg.pickingMode = PickingMode.Ignore;
                
                var leftEnd = new VisualElement();
                leftEnd.pickingMode = PickingMode.Ignore;
                leftEnd.style.flexShrink = 0; leftEnd.style.width = endWidth; leftEnd.style.height = Length.Percent(100);
                leftEnd.style.backgroundImage = new StyleBackground(_filterBtnEnd);
                leftEnd.style.SetBackgroundStretchToFill();
                leftEnd.style.unityBackgroundImageTintColor = _dealOfferBtnBg;
                bg.Add(leftEnd);
                
                var mid = new VisualElement();
                mid.pickingMode = PickingMode.Ignore;
                mid.style.flexGrow = 1; mid.style.flexShrink = 0; mid.style.height = Length.Percent(100);
                mid.style.marginLeft = -1; mid.style.marginRight = -1;
                mid.style.backgroundImage = new StyleBackground(_filterBtnMiddle);
                mid.style.SetBackgroundStretchToFill();
                mid.style.unityBackgroundImageTintColor = _dealOfferBtnBg;
                bg.Add(mid);
                
                var rightEnd = new VisualElement();
                rightEnd.pickingMode = PickingMode.Ignore;
                rightEnd.style.flexShrink = 0; rightEnd.style.width = endWidth; rightEnd.style.height = Length.Percent(100);
                rightEnd.style.backgroundImage = new StyleBackground(_filterBtnEnd);
                rightEnd.style.SetBackgroundStretchToFill();
                rightEnd.style.scale = new Scale(new Vector3(-1, 1, 1));
                rightEnd.style.unityBackgroundImageTintColor = _dealOfferBtnBg;
                bg.Add(rightEnd);
                
                offerBtn.Add(bg);
                
                hoverOverlay = new VisualElement();
                hoverOverlay.name = "deal-offer-hover";
                hoverOverlay.style.position = Position.Absolute;
                hoverOverlay.style.left = 2; hoverOverlay.style.right = 2; hoverOverlay.style.top = 2; hoverOverlay.style.bottom = 2;
                float r = endWidth - 2;
                hoverOverlay.style.borderTopLeftRadius = r; hoverOverlay.style.borderTopRightRadius = r;
                hoverOverlay.style.borderBottomLeftRadius = r; hoverOverlay.style.borderBottomRightRadius = r;
                hoverOverlay.style.borderTopWidth = 2f; hoverOverlay.style.borderBottomWidth = 2f;
                hoverOverlay.style.borderLeftWidth = 2f; hoverOverlay.style.borderRightWidth = 2f;
                hoverOverlay.style.borderTopColor = Color.white; hoverOverlay.style.borderBottomColor = Color.white;
                hoverOverlay.style.borderLeftColor = Color.white; hoverOverlay.style.borderRightColor = Color.white;
                hoverOverlay.style.display = DisplayStyle.None;
                hoverOverlay.pickingMode = PickingMode.Ignore;
                offerBtn.Add(hoverOverlay);
            }
            else
            {
                offerBtn.style.backgroundColor = _dealOfferBtnBg;
                offerBtn.style.borderTopLeftRadius = h / 2f; offerBtn.style.borderTopRightRadius = h / 2f;
                offerBtn.style.borderBottomLeftRadius = h / 2f; offerBtn.style.borderBottomRightRadius = h / 2f;
            }
            
            // Label
            var label = new Label(_dealOfferBtnText);
            label.name = "deal-offer-label";
            label.style.color = _dealOfferBtnTextColor;
            label.style.fontSize = _dealOfferBtnFontSize;
            label.style.unityFontStyleAndWeight = FontStyle.Bold;
            label.style.unityTextAlign = TextAnchor.MiddleCenter;
            label.style.translate = new Translate(_dealOfferTextX, _dealOfferTextY);
            label.pickingMode = PickingMode.Ignore;
            if (_newakeFont != null) label.style.unityFontDefinition = FontDefinition.FromFont(_newakeFont);
            offerBtn.Add(label);
            
            // Add-to-cart icon (right of the text)
            var icon = new VisualElement();
            icon.name = "deal-offer-icon";
            icon.pickingMode = PickingMode.Ignore;
            icon.style.flexShrink = 0;
            icon.style.width = h * 0.5f;
            icon.style.height = h * 0.5f;
            icon.style.marginLeft = 6;
            if (_cartIcon != null)
            {
                icon.style.backgroundImage = new StyleBackground(_cartIcon);
                icon.style.SetBackgroundScaleToFit();
            }
            icon.style.unityBackgroundImageTintColor = _dealOfferBtnTextColor;
            offerBtn.Add(icon);
            
            // Hover: scale up + show white outline
            offerBtn.style.transitionProperty = new List<StylePropertyName> { new StylePropertyName("scale") };
            offerBtn.style.transitionDuration = new List<TimeValue> { new TimeValue(100, TimeUnit.Millisecond) };
            offerBtn.style.transitionTimingFunction = new List<EasingFunction> { new EasingFunction(EasingMode.EaseOut) };
            var capturedHover = hoverOverlay;
            offerBtn.RegisterCallback<MouseEnterEvent>(_ => { offerBtn.style.scale = new Scale(new Vector3(1.04f, 1.04f, 1f)); if (capturedHover != null) capturedHover.style.display = DisplayStyle.Flex; });
            offerBtn.RegisterCallback<MouseLeaveEvent>(_ => { offerBtn.style.scale = new Scale(Vector3.one); if (capturedHover != null) capturedHover.style.display = DisplayStyle.None; });
            
            // Click → checkout with the deal's discount; stop the deal button's own checkout from also firing
            offerBtn.RegisterCallback<MouseDownEvent>(evt =>
            {
                evt.StopPropagation();
                SyntyAnalytics.Track("exclusive_deal_offer_click", new System.Collections.Generic.Dictionary<string, object>
                {
                    { "deal_id", deal.id },
                    { "product_handle", deal.product_handle ?? "" }
                });
                Application.OpenURL(BuildDealCartUrl(deal));
            });
            
            offerBtn.style.display = _showDealOfferBtn ? DisplayStyle.Flex : DisplayStyle.None;
            return offerBtn;
        }
        
        // Live-apply the offer button's position/size/text/colors, for the options panel.
        private void UpdateDealOfferButtons()
        {
            if (_dealsContainer == null) return;
            float endAspect = (_filterBtnEnd != null && _filterBtnEnd.height > 0) ? (float)_filterBtnEnd.width / _filterBtnEnd.height : 0.5f;
            float endWidth = Mathf.Ceil(_dealOfferBtnHeight * endAspect);
            _dealsContainer.Query<VisualElement>("deal-offer-btn").ForEach(b =>
            {
                b.style.right = _dealOfferBtnX;
                b.style.bottom = _dealOfferBtnY;
                b.style.height = _dealOfferBtnHeight;
                b.style.width = (_dealOfferBtnWidth > 0f) ? (StyleLength)_dealOfferBtnWidth : (StyleLength)StyleKeyword.Auto;
                b.style.paddingLeft = _dealOfferBtnHeight * 0.55f;
                b.style.paddingRight = _dealOfferBtnHeight * 0.55f;
                b.style.display = _showDealOfferBtn ? DisplayStyle.Flex : DisplayStyle.None;
                var lbl = b.Q<Label>("deal-offer-label");
                if (lbl != null) { lbl.text = _dealOfferBtnText; lbl.style.color = _dealOfferBtnTextColor; lbl.style.fontSize = _dealOfferBtnFontSize; lbl.style.translate = new Translate(_dealOfferTextX, _dealOfferTextY); }
                var icon = b.Q<VisualElement>("deal-offer-icon");
                if (icon != null) { icon.style.width = _dealOfferBtnHeight * 0.5f; icon.style.height = _dealOfferBtnHeight * 0.5f; icon.style.unityBackgroundImageTintColor = _dealOfferBtnTextColor; }
                var bg = b.Q<VisualElement>("deal-offer-bg");
                if (bg != null)
                {
                    var kids = bg.Children().ToList();
                    for (int i = 0; i < kids.Count; i++)
                    {
                        if (i == 0 || i == kids.Count - 1) kids[i].style.width = endWidth;
                        kids[i].style.unityBackgroundImageTintColor = _dealOfferBtnBg;
                    }
                }
            });
        }
        
        // Snap a deal discount to a 50-95 (step 5) bucket: nearest only when within 2%, else round down.
        private int ComputeDealSaleBucket(float pct)
        {
            if (pct >= 99.5f) return 100; // 100% off → the dedicated Sales_Amount_100_Deal image
            int nearest = Mathf.RoundToInt(pct / 5f) * 5;
            int bucket = (Mathf.Abs(pct - nearest) <= 2f) ? nearest : (Mathf.FloorToInt(pct / 5f) * 5);
            return Mathf.Clamp(bucket, 50, 95);
        }
        
