        private System.DateTime ParseDealEndTime(ExclusiveDeal deal)
        {
            try
            {
                if (!string.IsNullOrEmpty(deal.end_time))
                    return System.DateTime.Parse(deal.end_time, null, System.Globalization.DateTimeStyles.AdjustToUniversal | System.Globalization.DateTimeStyles.AssumeUniversal);
                var start = System.DateTime.Parse(deal.start_time, null, System.Globalization.DateTimeStyles.AdjustToUniversal | System.Globalization.DateTimeStyles.AssumeUniversal);
                return start.AddSeconds(deal.duration_seconds);
            }
            catch { return System.DateTime.UtcNow; }
        }
        
        private void ScheduleDealCountdown(VisualElement container, Label days, Label hours, Label mins, Label secs, System.DateTime endTimeUtc, ExclusiveDeal deal)
        {
            IVisualElementScheduledItem countdownTask = null;
            countdownTask = container.schedule.Execute(() =>
            {
                if (_reloadingDomain || container.panel == null) { SafePause(countdownTask); return; }
                var remaining = endTimeUtc - System.DateTime.UtcNow;
                if (remaining.TotalSeconds <= 0)
                {
                    days.text = "00"; hours.text = "00"; mins.text = "00"; secs.text = "00";
                    // Remove the deal from the list and re-render
                    _activeDeals.RemoveAll(d => d.id == deal.id);
                    RenderExclusiveDeals();
                    return;
                }
                int d = (int)remaining.TotalDays;
                int h = remaining.Hours;
                int m = remaining.Minutes;
                int s = remaining.Seconds;
                days.text  = d.ToString("00");
                hours.text = h.ToString("00");
                mins.text  = m.ToString("00");
                secs.text  = s.ToString("00");
            }).Every(1000);
            TrackScheduledItem(countdownTask);
        }
        
        // Produces sensible auto-defaults for the deal button's two text rows when the admin
        // hasn't typed an explicit override. Counts respect customer ownership for all/theme so
        // a customer who only needs 3 more packs sees "3 packs" rather than the full catalog total.
        private void ComputeDealTypeLabels(ExclusiveDeal deal, out string line1, out string line2)
        {
            string dealType = GetDealType(deal);
            
            if (dealType == "single")
            {
                line1 = deal.title ?? "";
                line2 = deal.product_name ?? "";
                return;
            }
            
            var items = ResolveDealEligibleItems(deal);
            int count = items.Count;
            string countSuffix = count == 1 ? "1 pack" : $"{count} packs";
            
            if (dealType == "multi")
            {
                line1 = "BUNDLE";
                line2 = !string.IsNullOrEmpty(deal.title) ? $"{deal.title} ({countSuffix})" : countSuffix;
            }
            else if (dealType == "theme")
            {
                string themeName = !string.IsNullOrEmpty(deal.theme) ? deal.theme.ToUpperInvariant() : "THEME";
                line1 = themeName;
                line2 = count > 0
                    ? $"Complete your {(deal.theme ?? "")} collection ({countSuffix})".Trim()
                    : $"You already own every {(deal.theme ?? "")} pack".Trim();
            }
            else if (dealType == "asset_type")
            {
                string typeName = !string.IsNullOrEmpty(deal.asset_type) ? deal.asset_type.ToUpperInvariant() : "ASSET TYPE";
                line1 = typeName;
                line2 = count > 0
                    ? $"Complete your {(deal.asset_type ?? "")} collection ({countSuffix})".Trim()
                    : $"You already own every {(deal.asset_type ?? "")} pack".Trim();
            }
            else // "all"
            {
                line1 = "COMPLETE";
                line2 = count > 0
                    ? $"Complete your Synty collection ({countSuffix})"
                    : "You already own everything";
            }
        }
        
        // Normalises deal.type — empty / null / unknown all map to "single" so legacy deals
        // (created before the type field existed) keep working without migration.
        private string GetDealType(ExclusiveDeal deal)
        {
            if (deal == null) return "single";
            string t = (deal.type ?? "").ToLowerInvariant().Trim();
            if (t == "multi" || t == "all" || t == "theme" || t == "asset_type") return t;
            return "single";
        }
        
        // Resolves the full list of (packName, variantId, price) the customer should receive
        // when they click GET OFFER on this deal. Filters out anything the customer already owns
        // for "all" / "theme" deals so a single-click cart doesn't try to re-buy owned packs.
        // Returns an empty list if nothing's eligible — caller should fall back to BuildDealCheckoutUrl.
        private List<(string handle, string variantId, float price)> ResolveDealEligibleItems(ExclusiveDeal deal)
        {
            var result = new List<(string handle, string variantId, float price)>();
            if (deal == null || _assetPackMapping == null) return result;
            
            string dealType = GetDealType(deal);
            // Entry-point trace: shows the raw deal fields exactly as the JSON deserialized
            // them. If deal.type is empty/null here, the worker isn't returning it in
            // /my-deals (or the deal wasn't saved with a type set). If deal.type is set
            // but dealType resolves to "single", GetDealType doesn't recognise the value.
            // UnityEngine.Debug.Log($"[DEAL CART RESOLVE/ENTRY] id='{deal.id}' raw_type='{deal.type}' resolved_dealType='{dealType}' asset_type='{deal.asset_type}' theme='{deal.theme}' product_handle='{deal.product_handle}' product_handles_len={(deal.product_handles?.Length ?? 0)}");
            
            // Build a lookup of packName → (variantId, price) from the loaded catalog
            var catalog = new Dictionary<string, (string variantId, float price)>(System.StringComparer.OrdinalIgnoreCase);
            foreach (var kv in _assetPackMapping)
            {
                var p = kv.Value;
                if (p == null || string.IsNullOrEmpty(p.packName)) continue;
                if (!catalog.ContainsKey(p.packName))
                    catalog[p.packName] = (p.shopifyVariantId, p.price);
            }
            
            var owned = SyntyStoreService.Instance.OwnedProductHandles;
            // Diagnostic counters — surfaced via [DEAL CART RESOLVE] log so an empty result is debuggable.
            int scanned = 0, skippedOwned = 0, skippedNoVariant = 0, skippedNoCatalog = 0, skippedTheme = 0, skippedFree = 0, added = 0;
            
            void AddIfHasVariant(string handle, bool excludeOwned)
            {
                if (string.IsNullOrEmpty(handle)) return;
                scanned++;
                if (excludeOwned && owned != null && owned.Contains(handle)) { skippedOwned++; return; }
                if (!catalog.TryGetValue(handle, out var info)) { skippedNoCatalog++; return; }
                if (string.IsNullOrEmpty(info.variantId)) { skippedNoVariant++; return; }
                // Skip free items — no discount can apply, and they'd just clutter the
                // checkout. Customers can still collect free assets through the normal
                // catalog flow; this just keeps exclusive-deal carts focused on paid items.
                if (info.price <= 0f) { skippedFree++; return; }
                result.Add((handle, info.variantId, info.price));
                added++;
            }
            
            if (dealType == "single")
            {
                AddIfHasVariant(deal.product_handle, excludeOwned: false);
            }
            else if (dealType == "multi")
            {
                if (deal.product_handles != null)
                    foreach (var h in deal.product_handles)
                        AddIfHasVariant(h, excludeOwned: true);
            }
            else if (dealType == "all" || dealType == "theme" || dealType == "asset_type")
            {
                // Iterate every loaded pack; filter by theme or asset_type when the deal
                // type calls for it. Both filters look up via SyntyCatalogBridge so the
                // values match what the catalog says, not what the pack name happens to
                // start with.
                string themeFilter = dealType == "theme" ? (deal.theme ?? "").Trim() : null;
                string typeFilter  = dealType == "asset_type" ? (deal.asset_type ?? "").Trim() : null;
                // Empty filter = misconfigured deal (asset_type field missing from the
                // /my-deals payload or never set on the deal). Bail loudly rather than
                // silently filtering everything out.
                if (dealType == "asset_type" && string.IsNullOrEmpty(typeFilter))
                {
                    // UnityEngine.Debug.LogError($"[DEAL CART RESOLVE] asset_type deal {deal.id} has empty asset_type field — check that (1) the worker migration added the asset_type column, (2) the deal was saved with a type selected in the portal, and (3) /my-deals returns asset_type in its response.");
                    return result;
                }
                int skippedType = 0;
                // Sample-log the first few packs' resolved asset types so we can confirm
                // SyntyCatalogBridge.GetAssetType returns the value the deal is filtering for.
                var typeSamples = new System.Collections.Generic.List<string>();
                int samplesLogged = 0;
                foreach (var kv in _assetPackMapping)
                {
                    var p = kv.Value;
                    if (p == null || string.IsNullOrEmpty(p.packName)) continue;
                    if (themeFilter != null)
                    {
                        string packTheme = SyntyCatalogBridge.GetTheme(p);
                        if (!string.Equals(packTheme, themeFilter, System.StringComparison.OrdinalIgnoreCase))
                        {
                            skippedTheme++;
                            continue;
                        }
                    }
                    if (typeFilter != null)
                    {
                        string packType = SyntyCatalogBridge.GetAssetType(p);
                        if (samplesLogged < 5)
                        {
                            typeSamples.Add($"'{p.packName}':'{packType}'");
                            samplesLogged++;
                        }
                        if (!string.Equals(packType, typeFilter, System.StringComparison.OrdinalIgnoreCase))
                        {
                            skippedType++;
                            continue;
                        }
                    }
                    AddIfHasVariant(p.packName, excludeOwned: true);
                }
                if (dealType == "asset_type")
                {
                    // UnityEngine.Debug.Log($"[DEAL CART RESOLVE] asset_type filter='{typeFilter}' skippedType={skippedType} samples=[{string.Join(", ", typeSamples)}]");
                }
            }
            
            // De-duplicate by handle in case the same pack appears via multiple mappings
            var seen = new HashSet<string>(System.StringComparer.OrdinalIgnoreCase);
            var deduped = new List<(string handle, string variantId, float price)>();
            foreach (var it in result)
            {
                if (seen.Add(it.handle)) deduped.Add(it);
            }
            // UnityEngine.Debug.Log($"[DEAL CART RESOLVE] type={dealType} mapping={_assetPackMapping.Count} catalog={catalog.Count} ownedSet={(owned?.Count ?? 0)} scanned={scanned} added={added} (skip: owned={skippedOwned}, noVariant={skippedNoVariant}, noCatalog={skippedNoCatalog}, themeMismatch={skippedTheme}, free={skippedFree}) → deduped={deduped.Count}");
            return deduped;
        }
        
        // Cart URL for the GET OFFER button: applies the deal's coupon, adds the product to the
        // cart, and lands on the cart page (discount cookie carries through to checkout).
        // Pick the right Shopify discount code for this customer's eligible-item count.
        // For tier-based deals: returns the code of the highest tier with min_quantity ≤
        // eligibleCount. Returns null if the customer doesn't qualify for any tier (their
        // eligible count is below even the lowest minimum). Falls back to deal.discount_code
        // when no tiers are configured.
        private string PickDiscountCode(ExclusiveDeal deal, int eligibleCount, out int chosenMinQty)
        {
            var tier = PickDealTier(deal, eligibleCount);
            if (tier != null) { chosenMinQty = tier.min_quantity; return tier.code; }
            chosenMinQty = 0;
            // If tiers are defined but none qualify, return null (no discount).
            if (deal?.discount_tiers != null && deal.discount_tiers.Length > 0) return null;
            return deal?.discount_code;
        }
        
        // Pick the highest tier whose min_quantity ≤ eligibleCount, or null if none qualify
        // (or if the deal has no tiers).
        private DealTier PickDealTier(ExclusiveDeal deal, int eligibleCount)
        {
            if (deal?.discount_tiers == null || deal.discount_tiers.Length == 0) return null;
            DealTier best = null;
            foreach (var t in deal.discount_tiers)
            {
                if (t == null || string.IsNullOrEmpty(t.code)) continue;
                if (t.min_quantity > eligibleCount) continue;
                if (best == null || t.min_quantity > best.min_quantity) best = t;
            }
            return best;
        }
        
        // Resolves the discount amount the customer should actually see for this deal —
        // accounts for the tier-based ramp (different % at different eligibility counts)
        // and falls back to the deal's flat amount when no tiers are configured. Caps the
        // eligibility count at Shopify's 100-item cart permalink limit so the tier we pick
        // is one the customer can actually meet at checkout.
        private float GetEffectiveDealDiscountAmount(ExclusiveDeal deal)
        {
            if (deal == null) return 0f;
            if (deal.discount_tiers != null && deal.discount_tiers.Length > 0)
            {
                var items = ResolveDealEligibleItems(deal);
                int cartCount = Mathf.Min(items.Count, 100);
                var tier = PickDealTier(deal, cartCount);
                if (tier != null && tier.discount_amount > 0) return tier.discount_amount;
            }
            return (float)deal.discount_amount;
        }
        
        private string BuildDealCartUrl(ExclusiveDeal deal)
        {
            string sid = SyntyAnalytics.InstallId ?? "";
            string utm = $"utm_source=synty_passport&utm_medium=unity_editor&utm_campaign=exclusive_deal&utm_content={deal.id}&sid={sid}";
            
            var items = ResolveDealEligibleItems(deal);
            // Shopify's cart permalink hard-caps at 100 line items. If a customer is eligible for
            // more than that on an "all"/"theme" deal, sort by price descending so the slice
            // picks the highest-value items — maximises the absolute discount the customer gets
            // out of their single-use code and avoids dumping the cheapest packs in front of them.
            // For other deal types ("single"/"multi") the resolver's ordering is already meaningful
            // (admin-defined order for multi, single item for single) so we leave those alone.
            string dt = GetDealType(deal);
            if ((dt == "all" || dt == "theme" || dt == "asset_type") && items.Count > 1)
            {
                items.Sort((a, b) => b.price.CompareTo(a.price));
            }
            const int SHOPIFY_CART_PERMALINK_MAX = 100;
            int included = Mathf.Min(items.Count, SHOPIFY_CART_PERMALINK_MAX);
            if (items.Count > SHOPIFY_CART_PERMALINK_MAX)
            {
                // UnityEngine.Debug.LogWarning($"[DEAL CART] {items.Count} eligible items exceeds Shopify's 100-item permalink limit — adding top {SHOPIFY_CART_PERMALINK_MAX} by price (highest first).");
            }
            
            // Pick the discount tier based on what's ACTUALLY going into the cart, not the
            // raw eligible count. Otherwise a customer with 200 eligible would pick tier
            // 150, the cart would only hold 100, and Shopify's prerequisite_quantity_range
            // (set to 150) would refuse to apply the discount at checkout.
            string code = PickDiscountCode(deal, included, out int chosenMinQty);
            Dbg($"[DEAL CART] type={GetDealType(deal)} eligible={items.Count} cartCount={included} tiers={(deal.discount_tiers?.Length ?? 0)} chosenCode='{code ?? ""}' chosenMin={chosenMinQty}");
            if (items.Count == 0)
            {
                // Nothing in the catalog matched (or customer already owns everything) — send to
                // the discount-only landing page so the coupon still applies if they browse manually.
                // UnityEngine.Debug.LogWarning("[DEAL CART] No eligible items — falling back to discount landing page (no cart will open).");
                return BuildDealCheckoutUrl(deal);
            }
            
            // Shopify's `/cart/{variants}?discount=CODE` query-string form is unreliable —
            // theme behaviour varies, and customer-locked codes get silently dropped. The
            // canonical pattern (documented by Shopify and confirmed across third-party
            // integrators) is `/discount/CODE?redirect=/cart/{variants}` — Shopify applies
            // the code to the customer's session first, then redirects to the cart, which
            // attaches the discount to those exact line items.
            //
            // We then wrap THAT in `/cart/clear?return_to=<encoded>` so the customer's
            // existing cart items get wiped before the deal items are added. Without this,
            // the customer ends up with their pre-existing cart contents mixed in with the
            // deal items, which dilutes the deal experience and can break the discount
            // calculation (the discount applies "across" all items in cart). Shopify's
            // default cart-permalink behaviour for clearing is theme-dependent, so we make
            // it explicit via /cart/clear.
            var cartPath = new System.Text.StringBuilder();
            cartPath.Append("/cart/");
            for (int i = 0; i < included; i++)
            {
                if (i > 0) cartPath.Append(',');
                cartPath.Append(items[i].variantId);
                cartPath.Append(":1");
            }
            
            // Build the inner path Shopify should land the customer on after clearing.
            // Put the UTM BEFORE the long variant list: Shopify truncates landing_site (~255 chars),
            // so a UTM placed after 100 variant IDs gets cut off and from_passport attribution is lost.
            string innerPath;
            if (!string.IsNullOrEmpty(code))
            {
                innerPath = $"/discount/{code}?{utm}&redirect={cartPath}";
            }
            else
            {
                innerPath = $"{cartPath}?{utm}";
            }
            
            // For a CODED deal, open Shopify's canonical, reliable pattern directly:
            //   /discount/CODE?redirect=/cart/{variants}
            // Shopify applies the code to the session, then redirects to the cart with those items.
            // Wrapping this in /cart/clear?return_to=… was dropping the discount at checkout — Shopify
            // doesn't reliably run the /discount cookie step when it's a cart-clear return target.
            // For an uncoded deal we still clear the existing cart first, then add the items.
            string finalUrl;
            if (!string.IsNullOrEmpty(code))
            {
                finalUrl = $"https://syntystore.com{innerPath}";
            }
            else
            {
                string encodedInner = System.Uri.EscapeDataString(innerPath);
                // UTM at the top level, before the long encoded return_to, so it isn't truncated away.
                finalUrl = $"https://syntystore.com/cart/clear?{utm}&return_to={encodedInner}";
            }
            Dbg($"[DEAL CART] Opening URL ({finalUrl.Length} chars, {included} items, {(string.IsNullOrEmpty(code) ? "clear-first" : "direct-discount")}): {finalUrl}");
            return finalUrl;
        }
        
        private string BuildDealCheckoutUrl(ExclusiveDeal deal)
        {
            string sid = SyntyAnalytics.InstallId ?? "";
            // If we have a discount code, route through cart with the code applied
            if (!string.IsNullOrEmpty(deal.discount_code))
            {
                string baseUrl = $"https://syntystore.com/discount/{deal.discount_code}";
                string ret = !string.IsNullOrEmpty(deal.product_handle)
                    ? $"?redirect=/products/{deal.product_handle}"
                    : "";
                return $"{baseUrl}{ret}{(ret.Contains("?") ? "&" : "?")}utm_source=synty_passport&utm_medium=unity_editor&utm_campaign=exclusive_deal&utm_content={deal.id}&sid={sid}";
            }
            // Fallback: product page
            string url = !string.IsNullOrEmpty(deal.product_handle)
                ? $"https://syntystore.com/products/{deal.product_handle}"
                : "https://syntystore.com";
            return AppendUtm(url, "exclusive_deal");
        }
        
        private void OnDownloadComplete(SyntyDownloadManager.DownloadItem item)
        {
            // Count this item as finished in the batch (drives the "X of N" badge, survives reload).
            if (_multiInstallTotal > 1 && _multiInstallDone < _multiInstallTotal)
                _multiInstallDone++;
            
            // Analytics: track download complete
            float duration = item.completedAt != null && item.startedAt != null
                ? (float)(item.completedAt.Value - item.startedAt.Value).TotalSeconds : 0f;
            bool success = item.status == SyntyDownloadManager.DownloadStatus.Completed;
            // If this handle had a pending update, report it as an update (the manager already logged
            // the generic "Installed" line; this adds the explicit update confirmation).
            if (success && _loggedUpdateHandles.Remove(item.productHandle))
            {
                Synty.Tools.SyntyLog.Info(string.IsNullOrEmpty(item.productVersion)
                    ? $"Updated {item.productTitle}"
                    : $"Updated {item.productTitle} to v{item.productVersion}");
            }
            SyntyAnalytics.TrackDownloadComplete(item.productHandle, duration, success, item.errorMessage);
            
            // Analytics: track install (asset imported into project — fires for cache and network alike)
            if (success)
            {
                AssetPackData installPack = null;
                foreach (var kvpA in _assetPackMapping)
                {
                    if (SyntyStoreService.ExtractHandleFromUrl(kvpA.Value.storeUrl) == item.productHandle)
                    {
                        installPack = kvpA.Value;
                        break;
                    }
                }
                SyntyAnalytics.TrackInstall(item.productHandle, installPack?.displayName ?? item.productHandle, 
                    installPack?.category.ToString() ?? "", item.isCacheHit);
            }
            
            // Find the matching asset button and apply installed state
            foreach (var kvp in _assetPackMapping)
            {
                string handle = SyntyStoreService.ExtractHandleFromUrl(kvp.Value.storeUrl);
                if (handle != item.productHandle) continue;
                if (kvp.Key < 0 || kvp.Key >= _assetItems.Count) continue;
                
                var assetBtn = _assetItems[kvp.Key].button;
                var dlBtn = assetBtn.Q<VisualElement>("download-btn");
                var dlIcon = dlBtn?.Q<VisualElement>("download-icon");
                var rRing = assetBtn.Q<VisualElement>("radial-ring");
                var rRingBg = assetBtn.Q<VisualElement>("radial-ring-bg");
                var btnVisual = assetBtn.Q<VisualElement>("asset-btn-visual");
                
                if (dlBtn != null)
                {
                    if (rRing != null) rRing.style.display = DisplayStyle.None;
                    if (rRingBg != null) rRingBg.style.display = DisplayStyle.None;
                    dlBtn.style.unityBackgroundImageTintColor = _installedBtnColor;
                    dlBtn.pickingMode = PickingMode.Position; // Keep clickable for uninstall
                    
                    if (dlIcon != null && _installedIcon != null)
                    {
                        dlIcon.style.backgroundImage = new StyleBackground(_installedIcon);
                        dlIcon.style.unityBackgroundImageTintColor = Color.white;
                        dlIcon.style.scale = new Scale(new Vector3(_installedIconScale, _installedIconScale, 1f));
                    }
                    
                    var pressedOvr = dlBtn.Q<VisualElement>("download-pressed-overlay");
                    if (pressedOvr != null)
                    {
                        pressedOvr.style.display = DisplayStyle.Flex;
                        pressedOvr.style.unityBackgroundImageTintColor = _installedBtnColor;
                    }
                    
                    btnVisual?.AddToClassList("asset-installed");
                    ForceRepaintNow();
                    btnVisual?.RemoveFromClassList("asset-has-update");
                    // Asset finished installing: deselect it now, and record it so the post-reload
                    // restore won't re-select it.
                    if (success)
                    {
                        _assetItems[kvp.Key].setSelected(false);
                        RemoveFromSessionSelection(_assetItems[kvp.Key].name);
                        AddToJustInstalled(_assetItems[kvp.Key].name);
                    }
                    
                    if (dlBtn.userData is object[] refs && refs.Length >= 3)
                    {
                        if (refs[0] is Color[] btnColorRef) btnColorRef[0] = _installedBtnColor;
                        if (refs[1] is Color[] iconColorRef) iconColorRef[0] = Color.white;
                        if (refs[2] is bool[] installedRef) installedRef[0] = true;
                    }
                    
                    float dbs = GetDlBtnBaseScale();
                    dlBtn.style.scale = new Scale(new Vector3(_installedBtnScale * dbs, _installedBtnScale * dbs, 1f));
                    
                    // Register uninstall hover handlers
                    Label ttLbl = null;
                    if (dlBtn != null) _downloadTooltipLabels.TryGetValue(dlBtn, out ttLbl);
                    if (ttLbl != null)
                    {
                        ttLbl.text = "Installed";
                        if (ttLbl.parent != null) ttLbl.parent.style.display = DisplayStyle.Flex;
                    }
                    if (dlIcon != null) RegisterUninstallHover(dlBtn, dlIcon, ttLbl);
                }
                
                // Show installed overlay on card
                var selectedOvr = assetBtn.Q<VisualElement>("asset-btn-selected");
                if (selectedOvr != null)
                {
                    selectedOvr.style.unityBackgroundImageTintColor = _installedBtnColor;
                    selectedOvr.style.opacity = 1;
                }
                
                // Remove the status badge from this card — but NOT during an active multi-install,
                // where a single badge moves card to card. Removing it per-item there can make a
                // fast asset look skipped (badge placed and removed within a frame). The moving
                // badge is repositioned by the sync and cleared when the whole batch finishes.
                if (_multiInstallTotal <= 1 || _multiInstallDone >= _multiInstallTotal)
                {
                    var badge = assetBtn.Q<Label>("download-status-badge");
                    if (badge != null) badge.RemoveFromHierarchy();
                }
                
                // Replace any update badge with installed badge
                RemoveInstalledBadge(assetBtn);
                ShowInstalledBadge(assetBtn);
                
                break;
            }
            
            // Decrement active count and remove dim when all downloads/imports are done
            _activeDownloadCount = Mathf.Max(0, _activeDownloadCount - 1);
            
            // If the cache-hit queue is waiting for real completion to advance, do it now that the
            // manager has actually finished importing this asset (keeps visuals in step so no
            // asset looks skipped). Consume the flag so it can't also advance a following network
            // item (which advances itself via its own ticker) — that double-advance was skipping
            // every second asset.
            if (_advanceQueueOnComplete)
            {
                _advanceQueueOnComplete = false;
                if (!_batchCancelled && _downloadQueue.Count > 0)
                {
                    // Ensure each asset is on screen for a minimum time before advancing, so a fast
                    // batch (no compile pauses) doesn't blink through all of them. Wait out the
                    // remainder of the dwell from when this item became the current one.
                    double shownFor = EditorApplication.timeSinceStartup - _currentItemShownAt;
                    double remaining = MIN_ITEM_DWELL - shownFor;
                    if (remaining < 0) remaining = 0;
                    ScheduleAdvanceAfter(remaining);
                }
            }
            
            if (_activeDownloadCount == 0)
            {
                _multiInstallTotal = 0;
                _multiInstallCurrent = 0;
                SessionState.SetInt(SESSION_BATCH_TOTAL, 0);
                _batchCancelled = false;
                _installProgressTotal = 0;
                EditorUtility.ClearProgressBar();
                if (_cancelBatchBtn != null) { _cancelBatchBtn.style.display = DisplayStyle.None; _cancelBatchBtn.text = "CANCEL"; }
                // Batch done — unlock assembly reloading so the queued recompile happens now (once).
                UnlockAssemblyReloadAfterBatch();
                SetDownloadingDimState(false);
                // _downloadingActive is now false; re-run the full sale-badge + amount
                // display logic so everything hidden during the download is restored
                // (just-installed/owned assets correctly stay hidden via the ownership check).
                UpdateSaleBadgeVisibility();
                UpdateSaleAmount();
                
                // Re-apply green overlay to all installed assets (may have been obscured during multi-download)
                // Retry a few times over ~1s: an import can settle slightly after completion,
                // so a single pass sometimes ran before IsInstalled caught up and the overlay
                // was skipped. The class-based check above plus these retries make it reliable.
                int refreshAttempts = 0;
                EditorApplication.CallbackFunction retryRefresh = null;
                double nextRefreshAt = EditorApplication.timeSinceStartup;
                retryRefresh = () =>
                {
                    if (_reloadingDomain || !this) { UnregisterAnonTicker(retryRefresh); return; }
                    if (EditorApplication.timeSinceStartup < nextRefreshAt) return;
                    RefreshInstalledOverlays();
                    refreshAttempts++;
                    nextRefreshAt = EditorApplication.timeSinceStartup + 0.35;
                    if (refreshAttempts >= 4) UnregisterAnonTicker(retryRefresh);
                };
                RegisterAnonTicker(retryRefresh);
                // ClearUnityConsole(); // removed — keep customer-facing messages visible
            }
            
            UpdateDownloadBar();
            UpdateSortDropdownChoices();
            FilterAssets();
            Repaint();

            // When debug logging is off, clear the console after each install so it doesn't fill up
            // with per-asset import output during a big batch. With debug on, everything is kept.
            if (!DebugLoggingEnabled)
                ClearUnityConsole();
        }
        
        // Watchdog state: when the UI is in the downloading state but the manager has no active
        // work, we wait briefly (debounce) before force-restoring, to avoid tripping during the
        // tiny gap between queued items.
        private double _downloadStuckSince = -1;
        private double _lastOrphanSweep = 0;
        private void DownloadStuckWatchdog()
        {
            if (_reloadingDomain || !this) return;
            
            bool managerBusy = false;
            try
            {
                var mgr = SyntyDownloadManager.Instance;
                if (mgr != null) managerBusy = mgr.HasActiveWork;
            }
            catch { managerBusy = false; }
            
            // Only relevant while the UI believes a download/install is happening.
            bool uiThinksBusy = _downloadingActive || _activeDownloadCount > 0;
            if (!uiThinksBusy)
            {
                _downloadStuckSince = -1;
                // Even when the UI flag is already clear, a dim overlay can be left orphaned on a
                // card (a late per-item dim got applied after the final clear). If the manager is
                // idle and not compiling, sweep any leftover dims so cards never stay "turned off".
                if (!managerBusy && !EditorApplication.isCompiling)
                {
                    double tnow = EditorApplication.timeSinceStartup;
                    if (tnow - _lastOrphanSweep >= 0.5)
                    {
                        _lastOrphanSweep = tnow;
                        ClearOrphanedDimOverlays();
                    }
                }
                return;
            }
            
            if (managerBusy)
            {
                // Keep the darken spotlight on the manager's actual current asset (survives the
                // between-item compile wait and mid-batch domain reloads).
                SyncSpotlightToManager();
                
                // The manager reports active work. If it's not actually progressing (a domain
                // reload from an asset's script recompile interrupted the batch, or an import
                // callback was lost), KickQueueIfStalled recovers it. It checks timeouts and
                // in-progress flags internally, so it no-ops unless genuinely stalled.
                if (!EditorApplication.isCompiling)
                {
                    double t = EditorApplication.timeSinceStartup;
                    if (_downloadStuckSince < 0) { _downloadStuckSince = t; }
                    else if (t - _downloadStuckSince >= 2.5)
                    {
                        _downloadStuckSince = -1;
                        try { SyntyDownloadManager.Instance?.KickQueueIfStalled(); } catch { }
                    }
                }
                else
                {
                    _downloadStuckSince = -1;
                }
                return;
            }
            
            // UI says busy, manager says idle: start (or continue) the debounce timer.
            double now = EditorApplication.timeSinceStartup;
            if (_downloadStuckSince < 0) { _downloadStuckSince = now; return; }
            if (now - _downloadStuckSince < 1.5) return; // wait out brief between-item gaps
            
            // Stuck long enough: force the UI back to normal.
            _downloadStuckSince = -1;
            _activeDownloadCount = 0;
            RestoreUiAfterDownloads();
        }
        
        // Sweeps any leftover download dim overlays off the asset cards. Called by the watchdog
        // when no download is active, as a safety net against a dim overlay being orphaned on a
        // card after a multi-install (which would leave that card looking "turned off"). Cheap:
        // returns immediately unless at least one visible dim overlay is found.
        private void ClearOrphanedDimOverlays()
        {
            if (_assetItems == null) return;
            bool anyDim = false;
            foreach (var item in _assetItems)
            {
                var bv = item.button?.Q<VisualElement>("asset-btn-visual");
                var dim = bv?.Q<VisualElement>("download-dim-overlay");
                if (dim != null && dim.resolvedStyle.display != DisplayStyle.None)
                {
                    anyDim = true;
                    break;
                }
            }
            if (!anyDim) return;
            
            foreach (var item in _assetItems)
            {
                var hitArea = item.button;
                if (hitArea == null) continue;
                var bv = hitArea.Q<VisualElement>("asset-btn-visual");
                var dim = bv?.Q<VisualElement>("download-dim-overlay");
                if (dim != null) dim.style.display = DisplayStyle.None;
                hitArea.pickingMode = PickingMode.Position;
                var saleBadgeEl = hitArea.Q<VisualElement>("sale-amount");
                if (saleBadgeEl != null)
                    saleBadgeEl.style.display = _showSaleAmount ? DisplayStyle.Flex : DisplayStyle.None;
            }
            SetDealPopupsVisible(true);
        }
        
        private void OnDownloadFailed(SyntyDownloadManager.DownloadItem item)
        {
            // A failed item must still count down the active batch, otherwise the dim overlay
            // and the bottom action bars (which are gated on _activeDownloadCount) never come
            // back and the UI looks stuck.
            _activeDownloadCount = Mathf.Max(0, _activeDownloadCount - 1);
            if (_activeDownloadCount == 0)
                RestoreUiAfterDownloads();
            UpdateDownloadBar();
            Repaint();
        }
        
        // Restores the normal UI after a download/install batch finishes (whether items
        // succeeded or failed): clears the dim overlay, brings the action bars back, and
        // refreshes badges/overlays. Safe to call more than once.
        private void RestoreUiAfterDownloads()
        {
            _multiInstallTotal = 0;
            _multiInstallCurrent = 0;
            _multiInstallDone = 0;
            SessionState.SetInt(SESSION_BATCH_TOTAL, 0);
            _spotlightCard = null;
            _lastVisualizedHandle = null;
            // Safety: ensure assembly reloading is unlocked if a batch ended via this path.
            UnlockAssemblyReloadAfterBatch();
            // Remove any lingering install/download status badge across the grid.
            foreach (var it in _assetItems)
            {
                var b = it.btnVisual?.Q<Label>("download-status-badge");
                if (b != null) b.RemoveFromHierarchy();
            }
            SetDownloadingDimState(false);
            // Re-apply the authoritative per-column sizing (width/height/scale/offset). Install
            // spotlight + dim overlays alter card scale/position; without this, cards left at a
            // non-largest thumbnail size keep a wrong scale and the layout breaks after a download.
            UpdateThumbnailSize();
            UpdateSaleBadgeVisibility();
            UpdateSaleAmount();
            RefreshInstalledOverlays();
            UpdateDownloadBar();
            UpdateSortDropdownChoices();
            FilterAssets();
            Repaint();
            // ClearUnityConsole(); // removed — keep customer-facing messages visible
        }
        
        // Clears the Unity Editor console. Uses the internal UnityEditor.LogEntries.Clear via
        // reflection (there is no public API). Best-effort: silently no-ops if the internal
        // method isn't found on this Unity version.
        // TEMP debug logger — writes to a file so logs survive console clears / recompiles.
        // Forces the editor window to redraw RIGHT NOW (synchronously), not just queue a repaint.
        // During a locked multi-install the normal Repaint() request doesn't get serviced until the
        // batch ends, so per-asset visuals never appear. RepaintImmediately() (internal) paints now.
        private System.Reflection.MethodInfo _repaintImmediatelyMI;
        private void ForceRepaintNow()
        {
            try
            {
                if (_repaintImmediatelyMI == null)
                    _repaintImmediatelyMI = typeof(EditorWindow).GetMethod("RepaintImmediately",
                        System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Public);
                _repaintImmediatelyMI?.Invoke(this, null);
            }
            catch { Repaint(); }
        }
        
        private static void ClearUnityConsole()
        {
            // Defer to the next editor tick so the clear never runs during GUI event processing.
            // Clearing the console mid-event forces the console window to repaint while an IMGUI
            // hotControl is active, which produces the "Should not be capturing when there is a
            // hotcontrol" warning.
            EditorApplication.delayCall += () =>
            {
                try
                {
                    var assembly = System.Reflection.Assembly.GetAssembly(typeof(UnityEditor.Editor));
                    var logEntries = assembly?.GetType("UnityEditor.LogEntries");
                    var clear = logEntries?.GetMethod("Clear", System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.Public);
                    clear?.Invoke(null, null);
                }
                catch { /* internal API may differ across Unity versions — ignore */ }
            };
        }
        
        /// <summary>
        /// Refreshes ownership state on all asset buttons from backend verification data.
        /// Called after background verify completes on fast path.
        /// </summary>
        // ── New-order detection on interaction ──
        // When the user clicks in the window we cheaply ask the backend for their current
        // order count (throttled to at most once per 60s). If it has increased since we last
        // saw it, the user has placed a new order, so we silently re-verify (refreshing owned
        // products + Synty Pass) and rebuild the asset display. Throttled + silent so it never
        // interrupts what the user is doing.
        private double _lastOrderCheckTime = -1000;
        private int _lastKnownOrderCount = -1;
        private bool _orderCheckInFlight;
        private const double ORDER_CHECK_THROTTLE_SEC = 60.0;
        
        private void OnRootPointerDownForOrders(PointerDownEvent evt)
        {
            OnWindowInteractionCheckOrders();
        }
        
        private void OnWindowInteractionCheckOrders()
        {
            if (_orderCheckInFlight) return;
            if (!SyntyLoginManager.IsLoggedIn) return;
            double now = EditorApplication.timeSinceStartup;
            if (now - _lastOrderCheckTime < ORDER_CHECK_THROTTLE_SEC) return;
            _lastOrderCheckTime = now;
            _orderCheckInFlight = true;
            _ = CheckForNewOrderAsync();
        }
        
        // Manual "refresh owned assets" action (toolbar button). Force re-verifies the user's
        // ownership + Synty Pass against the backend (bypassing the verify cache) and redraws
        // ownership on the asset buttons. Shows a loading spinner in place of the icon while
        // it runs, then restores the icon.
        private async System.Threading.Tasks.Task RefreshOwnedAssetsAsync(VisualElement iconEl)
        {
            if (_refreshAssetsInFlight) return;
            if (!SyntyLoginManager.IsLoggedIn) return;
            _refreshAssetsInFlight = true;
            
            // Hide the icon and drop a circular spinner in its place (a ring with one bright
            // quadrant, rotated). The spinner is parented to the button so it centers over it.
            VisualElement spinner = null;
            IVisualElementScheduledItem spin = null;
            float angle = 0f;
            if (iconEl != null && _refreshAssetsBtnRef != null)
            {
                iconEl.style.display = DisplayStyle.None;
                spinner = new VisualElement();
                spinner.name = "refresh-spinner";
                spinner.pickingMode = PickingMode.Ignore;
                float d = _thumbBtnSize * 0.55f;
                spinner.style.width = d;
                spinner.style.height = d;
                spinner.style.borderTopWidth = 2;
                spinner.style.borderBottomWidth = 2;
                spinner.style.borderLeftWidth = 2;
                spinner.style.borderRightWidth = 2;
                var dim = new Color(1f, 1f, 1f, 0.2f);
                var bright = new Color(1f, 1f, 1f, 0.9f);
                spinner.style.borderTopColor = bright;
                spinner.style.borderRightColor = dim;
                spinner.style.borderBottomColor = dim;
                spinner.style.borderLeftColor = dim;
                spinner.style.borderTopLeftRadius = d * 0.5f;
                spinner.style.borderTopRightRadius = d * 0.5f;
                spinner.style.borderBottomLeftRadius = d * 0.5f;
                spinner.style.borderBottomRightRadius = d * 0.5f;
                _refreshAssetsBtnRef.Add(spinner);
                spin = spinner.schedule.Execute(() =>
                {
                    if (_reloadingDomain || spinner.panel == null) { SafePause(spin); return; }
                    angle = (angle + 18f) % 360f;
                    spinner.style.rotate = new Rotate(new Angle(angle, AngleUnit.Degree));
                }).Every(33);
                TrackScheduledItem(spin);
            }
            
            try
            {
                bool ok = await SyntyStoreService.Instance.VerifyRestoredSessionAsync(true);
                if (!this) return;
                if (ok)
                {
                    UpdateOwnershipFromBackend();
                    ApplyServerBanner(); // refresh picks up any banner change too
                    // Keep the order-count baseline in sync so the auto-check doesn't re-fire.
                    int count = await SyntyStoreService.Instance.GetOrderCountAsync();
                    if (this && count >= 0) _lastKnownOrderCount = count;
                }
                
                // Re-pull the other live, account-dependent data so the refresh button is a
                // full "sync everything" action, not just ownership:
                //  - personalized exclusive deals (/my-deals) + their countdowns
                //  - refreshed currency exchange rates (prices re-render via OnCurrencyChanged)
                //  - the catalog (new assets, updated versions, current sale state); on reload
                //    we rebuild ownership/overlays so newly added or on-sale assets appear.
                FetchExclusiveDeals();
                _ = SyntyCurrency.EnsureRatesAsync();
                SyntyCatalogBridge.LoadCatalog((packs) =>
                {
                    if (!this) return;
                    UpdateOwnershipFromBackend();
                    RefreshInstalledOverlays();
                    UpdateSaleBadgeVisibility();
                    UpdateSaleAmount();
                    Repaint();
                });
                
                Repaint();
            }
            catch { }
            finally
            {
                _refreshAssetsInFlight = false;
                if (spin != null) SafePause(spin);
                if (spinner != null && spinner.parent != null) spinner.RemoveFromHierarchy();
                if (iconEl != null) iconEl.style.display = DisplayStyle.Flex;
            }
        }
        
        private async System.Threading.Tasks.Task SeedOrderCountBaselineAsync()
        {
            try
            {
                int count = await SyntyStoreService.Instance.GetOrderCountAsync();
                if (!this) return;
                if (count >= 0) _lastKnownOrderCount = count;
            }
            catch { }
        }
        
        private async System.Threading.Tasks.Task CheckForNewOrderAsync()
        {
            try
            {
                int count = await SyntyStoreService.Instance.GetOrderCountAsync();
                if (!this) return;
                if (count < 0) return; // unknown -> do nothing
                
                // First successful read just establishes the baseline; don't refresh.
                if (_lastKnownOrderCount < 0)
                {
                    _lastKnownOrderCount = count;
                    return;
                }
                
                if (count > _lastKnownOrderCount)
                {
                    _lastKnownOrderCount = count;
                    // New order detected: silently re-verify ownership + pass (force-refresh so
                    // the verify cache is bypassed and the new asset shows up immediately).
                    bool ok = await SyntyStoreService.Instance.VerifyRestoredSessionAsync(true);
                    if (!this || !ok) return;
                    UpdateOwnershipFromBackend();
                    ApplyServerBanner(); // a new purchase may change which banner applies (e.g. now owns the New Release product)
                    Repaint();
                }
                else
                {
                    _lastKnownOrderCount = count;
                }
            }
            catch { /* silent - never interrupt the user */ }
            finally { _orderCheckInFlight = false; }
        }
        
        private void UpdateOwnershipFromBackend()
        {
            if (_assetItems == null || _assetItems.Count == 0) return;
            
            bool hasSyntyPass = SyntyLoginManager.HasSyntyPass;
            SessionState.SetBool(SESSION_HAS_PASS, hasSyntyPass); // remember across reloads so the next build knows instantly
            SessionState.SetBool(SESSION_VERIFY_DONE, true);      // first verify done this session — later builds needn't wait
            _veilWaitVerify = false;                             // verify settled — the veil may reveal once the grid is stable
            
            // If the pass filter is on but the user does NOT own the pass, leave the filter
            // toggle as-is (do not force it off) but force the per-asset visuals to refresh
            // below, so the cards reflect only the assets the customer actually owns rather
            // than the "owns all" pass view.
            bool forcedPassOff = (!hasSyntyPass && _licenseSyntyPass);
            
            // NOTE: the Synty Pass filter is auto-enabled once at login (see
            // ScheduleSyntyPassAutoOn) for pass-holders. We deliberately do NOT auto-enable it
            // here, because UpdateOwnershipFromBackend also runs on post-install / refresh /
            // new-order paths — turning the filter on there would flip it back on after the user
            // had it off (e.g. right after an install). Respect the current toggle state.
            
            int ownedCount = 0;
            bool ownershipChanged = false;
            
            for (int i = 0; i < _assetItems.Count; i++)
            {
                bool shouldOwn;
                // The pass filter "owns all" view only applies when the user ACTUALLY holds
                // the Synty Pass. If the filter is on but they don't own the pass (e.g. a
                // stale toggle state), fall through to individual ownership so we don't
                // falsely mark every asset as owned.
                if (_licenseSyntyPass && hasSyntyPass)
                {
                    shouldOwn = true;
                }
                else if (_assetPackMapping.TryGetValue(i, out var pack))
                {
                    // Only count individually purchased assets when pass filter is OFF
                    shouldOwn = SyntyStoreService.Instance.OwnedProductHandles.Contains(pack.packName);
                }
                else
                {
                    shouldOwn = false;
                }
                
                if (forcedPassOff || _assetItems[i].getOwned() != shouldOwn)
                {
                    _assetItems[i].setOwned(shouldOwn);
                    ownershipChanged = true;
                }
                    
                if (shouldOwn) ownedCount++;
            }
            
            UpdateCollectionCounts();
            UpdateDownloadBar();
            
            // Re-check installed/update states (catalog may have newer version data now)
            RefreshInstalledOverlays();
            
            // Auto-default to "Updates" sort if any assets have updates available — but only once
            // per session (on the first ownership load), never on a post-install / refresh /
            // domain-reload re-verify, so the user's chosen sort isn't changed out from under them
            // after installing assets.
            if (!_autoUpdatesSortDone)
            {
                _autoUpdatesSortDone = true;
                bool anyUpdates = _assetItems.Any(i => i.btnVisual?.ClassListContains("asset-has-update") == true);
                if (anyUpdates && _sortMode != 2 && !_userPickedSort)
                {
                    _sortMode = 2;
                    _sortDirty = true;
                    if (_sortDropdown != null) _sortDropdown.value = "Updates";
                }
            }
            UpdateSortDropdownChoices();
            
            // Only re-filter/re-render when ownership actually changed. On a post-install / domain-
            // reload re-verify where nothing you own changed, the first paint (built from persisted
            // ownership) is already correct, so re-filtering here would just cause a visible flicker
            // (the grid briefly showing, then "correcting" itself).
            if (ownershipChanged || _sortDirty) FilterAssets();
            
            // Eligible-item counts on all/theme/multi deals depend on customer ownership, so
            // re-render whenever the backend updates that set. This keeps the "(N packs)"
            // label and the eligibility-based hiding rule in sync with reality.
            RenderExclusiveDeals();
        }
        
        /// <summary>
        /// Try to find and delete the Synty asset folder for a given product handle.
        /// Returns the deleted folder path, or null if not found.
        /// </summary>
        private string TryDeleteAssetFolder(string handle, string displayName)
        {
            var candidates = new List<string>();
            
            // From handle: sidekick-modular-characters-starter-pack → SidekickModularCharactersStarterPack
            string camelCase = "";
            foreach (var part in handle.Split('-'))
            {
                if (part.Length > 0)
                    camelCase += char.ToUpper(part[0]) + (part.Length > 1 ? part.Substring(1) : "");
            }
            candidates.Add(camelCase);
            
            // From display name
            if (!string.IsNullOrEmpty(displayName))
            {
                candidates.Add(displayName);
                candidates.Add(displayName.Replace(" ", "_"));
                candidates.Add(displayName.Replace(" ", ""));
                candidates.Add("POLYGON_" + displayName.Replace(" ", "_"));
                candidates.Add("POLYGON " + displayName);
                candidates.Add("POLYGON - " + displayName);
            }
            
            // Also try the manifest filename
            var entry = SyntyInstallManifest.GetEntry(handle);
            if (entry != null && !string.IsNullOrEmpty(entry.filename))
            {
                string stripped = System.Text.RegularExpressions.Regex.Replace(
                    entry.filename, @"_v[\d_.]+\.unitypackage$", "", System.Text.RegularExpressions.RegexOptions.IgnoreCase);
                stripped = stripped.Replace(".unitypackage", "");
                candidates.Add(stripped);
                candidates.Add(stripped.Replace("_", ""));
            }
            
            string handleClean = handle.Replace("-", "").ToLower();
            string displayClean = !string.IsNullOrEmpty(displayName) 
                ? displayName.ToLower().Replace(" ", "").Replace("_", "").Replace("-", "") 
                : "";
            
            // Build handle word parts for partial matching (e.g., "sidekick", "starter", "characters")
            var handleParts = new List<string>(handle.Split('-'));
            handleParts.RemoveAll(p => p.Length < 4); // skip short words like "and", "the"
            
            string[] searchRoots = { "Assets/Synty", "Assets/SyntyStudios", "Assets/PolygonAssets", "Assets" };
            
            foreach (var root in searchRoots)
            {
                if (!System.IO.Directory.Exists(root)) continue;
                
                // Exact match
                foreach (var candidate in candidates)
                {
                    string path = $"{root}/{candidate}";
                    if (System.IO.Directory.Exists(path))
                    {
                        System.IO.Directory.Delete(path, true);
                        if (System.IO.File.Exists(path + ".meta")) System.IO.File.Delete(path + ".meta");
                        return path;
                    }
                }
                
                // Fuzzy match
                try
                {
                    foreach (var dir in System.IO.Directory.GetDirectories(root))
                    {
                        string dirName = System.IO.Path.GetFileName(dir);
                        string dirClean = dirName.ToLower().Replace(" ", "").Replace("_", "").Replace("-", "");
                        
                        // Full string containment
                        if (dirClean.Length >= 4 && (
                            dirClean.Contains(handleClean) || handleClean.Contains(dirClean) ||
                            (!string.IsNullOrEmpty(displayClean) && displayClean.Length >= 4 && 
                             (dirClean.Contains(displayClean) || displayClean.Contains(dirClean)))))
                        {
                            System.IO.Directory.Delete(dir, true);
                            if (System.IO.File.Exists(dir + ".meta")) System.IO.File.Delete(dir + ".meta");
                            return dir;
                        }
                        
                        // Partial word match: if 2+ handle words appear in the dir name
                        int matchCount = 0;
                        foreach (var part in handleParts)
                        {
                            if (dirClean.Contains(part)) matchCount++;
                        }
                        if (matchCount >= 2 && dirClean.Length >= 4)
                        {
                            System.IO.Directory.Delete(dir, true);
                            if (System.IO.File.Exists(dir + ".meta")) System.IO.File.Delete(dir + ".meta");
                            return dir;
                        }
                    }
                }
                catch { }
            }
            
            // Not found — log what exists for debugging
            if (System.IO.Directory.Exists("Assets/Synty"))
            {
                var dirs = System.IO.Directory.GetDirectories("Assets/Synty");
            }
            return null;
        }
        
        private const string PREFS_PREFIX = "SyntyDownloaderV2_";
        private const string PREFS_SYNTY_PASS = PREFS_PREFIX + "SyntyPass";
        private const string PREFS_ASSET_TYPES = PREFS_PREFIX + "AssetTypes";
        private const string PREFS_THEMES = PREFS_PREFIX + "Themes";
        private const string PREFS_STATS_IN_LIBRARY = PREFS_PREFIX + "StatsInLibrary";
        private const string PREFS_STATS_NOT_IN_LIBRARY = PREFS_PREFIX + "StatsNotInLibrary";
        private const string PREFS_STATS_UPDATES = PREFS_PREFIX + "StatsUpdates";
        private const string PREFS_STATS_ON_SALE = PREFS_PREFIX + "StatsOnSale";
        private const string PREFS_SEARCH_QUERY = PREFS_PREFIX + "SearchQuery";
        private const string PREFS_SORT_MODE = PREFS_PREFIX + "SortMode";
        // Set once the user manually picks a sort from the dropdown. While true, the automatic
        // "switch to Updates / On Sale" re-sorts are suppressed, so installing/uninstalling (and the
        // domain reloads they cause) don't change the order the user deliberately chose.
        private const string PREFS_USER_PICKED_SORT = PREFS_PREFIX + "UserPickedSort";
        private bool _userPickedSort = false;
        private const string PREFS_PROFILE_IMAGE = PREFS_PREFIX + "ProfileImage";
        private const string PREFS_SELECTED_FILTERS = PREFS_PREFIX + "SelectedFilters";
        private const string PREFS_STATS_NEW = PREFS_PREFIX + "StatsNew";
        private const string PREFS_STATS_INSTALLED = PREFS_PREFIX + "StatsInstalled";
        private const string PREFS_NOTIFICATIONS = PREFS_PREFIX + "Notifications";
        
        private bool _hasNotifications = false;
        
        private void LoadFilterStates()
        {
            // Load Synty Pass state (retained in prefs)
            // Trust the saved value — background verify will correct if needed
            // Default the pass filter to the user's persisted pass state so a pass-holder's grid builds
            // showing the full library immediately. Read the pass flag DIRECTLY from EditorPrefs
            // ("SyntyStore_HasSyntyPass") rather than SyntyLoginManager.HasSyntyPass — on a domain
            // reload the store service hasn't re-loaded it from disk yet when this runs, so the proxy
            // reads false and the grid would briefly show only individually-owned packs.
            bool persistedHasPass = SessionState.GetBool(SESSION_HAS_PASS, EditorPrefs.GetBool("SyntyStore_HasSyntyPass", false));
            _licenseSyntyPass = SessionState.GetBool(SESSION_PASS_FILTER, persistedHasPass);
            _hasNotifications = EditorPrefs.GetBool(PREFS_NOTIFICATIONS, false);
            
            // Restore search query
            _searchQuery = EditorPrefs.GetString(PREFS_SEARCH_QUERY, "");
            
            _selectedProfileImage = EditorPrefs.GetString(PREFS_PROFILE_IMAGE, "Profile_Button");
            
            // Restore filter stats
            _statsInLibrary = EditorPrefs.GetBool(PREFS_STATS_IN_LIBRARY, true);
            _statsNotInLibrary = EditorPrefs.GetBool(PREFS_STATS_NOT_IN_LIBRARY, true);
            _statsUpdates = EditorPrefs.GetBool(PREFS_STATS_UPDATES, true);
            _statsOnSale = EditorPrefs.GetBool(PREFS_STATS_ON_SALE, true);
            _statsNew = EditorPrefs.GetBool(PREFS_STATS_NEW, true);
            _statsInstalled = EditorPrefs.GetBool(PREFS_STATS_INSTALLED, true);
            
            // A domain reload (e.g. a script recompile triggered by installing an asset) re-runs
            // OnEnable -> LoadFilterStates. On that path we must KEEP the user's current filters,
            // not reset them. _filtersSessionInit is [SerializeField] so it survives the reload;
            // it's false only on a genuine fresh window open.
            if (_filtersSessionInit)
            {
                // Domain-reload re-init: restore the filters exactly as the user left them.
                _sortMode = EditorPrefs.GetInt(PREFS_SORT_MODE, 0);
                _userPickedSort = EditorPrefs.GetBool(PREFS_USER_PICKED_SORT, false);
                _sortDirty = true;
                
                _selectedAssetTypes.Clear();
                string savedTypes = EditorPrefs.GetString(PREFS_SELECTED_FILTERS, "");
                if (!string.IsNullOrEmpty(savedTypes))
                    foreach (var t in savedTypes.Split(',')) if (!string.IsNullOrEmpty(t)) _selectedAssetTypes.Add(t);
                else
                    foreach (var (name, _) in AssetTypes) _selectedAssetTypes.Add(name);
                
                _selectedThemes.Clear();
                string savedThemes = EditorPrefs.GetString(PREFS_PREFIX + "SelectedThemes", "");
                if (!string.IsNullOrEmpty(savedThemes))
                    foreach (var t in savedThemes.Split(',')) if (!string.IsNullOrEmpty(t)) _selectedThemes.Add(t);
                else
                    foreach (var (name, _) in Themes) _selectedThemes.Add(name);
                
                _filterShowInstalled = EditorPrefs.GetBool(PREFS_PREFIX + "FilterShowInstalled", true);
                _filterShowNotInstalled = EditorPrefs.GetBool(PREFS_PREFIX + "FilterShowNotInstalled", true);
                return;
            }
            
            // Genuine fresh open: start on Release Date sort with everything shown, so the user
            // always sees the full catalog first. (SaveFilterStates still records toggles during
            // the session so a domain reload can restore them via the branch above.)
            _filtersSessionInit = true;
            _sortMode = 0;
            _sortDirty = true;
            
            _selectedAssetTypes.Clear();
            foreach (var (name, _) in AssetTypes)
                _selectedAssetTypes.Add(name);
            
            _selectedThemes.Clear();
            foreach (var (name, _) in Themes)
                _selectedThemes.Add(name);
            
            _filterShowInstalled = true;
            _filterShowNotInstalled = true;
        }
        
        private void SaveFilterStates()
        {
            EditorPrefs.SetBool(PREFS_SYNTY_PASS, _licenseSyntyPass);
            EditorPrefs.SetBool(PREFS_NOTIFICATIONS, _hasNotifications);
            EditorPrefs.SetString(PREFS_SEARCH_QUERY, _searchQuery ?? "");
            EditorPrefs.SetInt(PREFS_SORT_MODE, _sortMode);
            EditorPrefs.SetBool(PREFS_STATS_IN_LIBRARY, _statsInLibrary);
            EditorPrefs.SetBool(PREFS_STATS_NOT_IN_LIBRARY, _statsNotInLibrary);
            EditorPrefs.SetBool(PREFS_STATS_UPDATES, _statsUpdates);
            EditorPrefs.SetBool(PREFS_STATS_ON_SALE, _statsOnSale);
            EditorPrefs.SetBool(PREFS_STATS_NEW, _statsNew);
            EditorPrefs.SetBool(PREFS_STATS_INSTALLED, _statsInstalled);
            EditorPrefs.SetString(PREFS_SELECTED_FILTERS, string.Join(",", _selectedAssetTypes));
            EditorPrefs.SetString(PREFS_PREFIX + "SelectedThemes", string.Join(",", _selectedThemes));
            EditorPrefs.SetBool(PREFS_PREFIX + "FilterShowInstalled", _filterShowInstalled);
            EditorPrefs.SetBool(PREFS_PREFIX + "FilterShowNotInstalled", _filterShowNotInstalled);
        }
        
        private static void FindImagesPath()
        {
            // Check static cache first
            if (!string.IsNullOrEmpty(_imagesPath) && Directory.Exists(_imagesPath) &&
                File.Exists(Path.Combine(_imagesPath, "Background", "Background_Corner_TopRight.png").Replace("\\", "/")))
                return;
            
            // Check SessionState cache (survives domain reload, no AssetDatabase search)
            string cached = SessionState.GetString("SyntyPassport_ImagesPath", "");
            if (!string.IsNullOrEmpty(cached) && Directory.Exists(cached) &&
                File.Exists(Path.Combine(cached, "Background", "Background_Corner_TopRight.png").Replace("\\", "/")))
            {
                _imagesPath = cached;
                return;
            }
            
            // Fallback: AssetDatabase search (only on first run or after project restructure)
            string[] guids = AssetDatabase.FindAssets("SyntyAssetDownloaderV2 t:MonoScript");
            if (guids.Length > 0)
            {
                string scriptPath = AssetDatabase.GUIDToAssetPath(guids[0]);
                string editorFolder = Path.GetDirectoryName(scriptPath);
                _imagesPath = Path.Combine(editorFolder, "Images").Replace("\\", "/");
                SessionState.SetString("SyntyPassport_ImagesPath", _imagesPath);
            }
        }
        
        public static Texture2D LoadImage(string subfolder, string imageName)
        {
            string key = $"{subfolder}/{imageName}";
            if (_imageCache.TryGetValue(key, out var cached))
                return cached;
                
            FindImagesPath();
            
            string path = $"{_imagesPath}/{subfolder}/{imageName}.png";
            
            // Don't warn if file simply doesn't exist (e.g. grey variants before preprocessor runs)
            if (!System.IO.File.Exists(path))
            {
                // Diagnostic for the renamed logo images specifically.
                if (imageName.Contains("Synty_Logo_Large") || imageName.Contains("Synty_Importer_TextLogo"))
                    Synty.Tools.SyntyLog.Warn($"[Image] Not found: {path} (imagesPath='{_imagesPath}')");
                return null;
            }
            
            Texture2D tex = AssetDatabase.LoadAssetAtPath<Texture2D>(path);
            
            if (tex != null)
                _imageCache[key] = tex;
                
            return tex;
        }
        
        private const int INITIAL_BUTTON_BATCH = 6;  // Buttons to create immediately
        private const int DEFERRED_BUTTON_BATCH = 50; // Buttons per frame (grid is hidden so no layout cost)
        
        private struct PackBuildData
        {
            public AssetPackData pack;
            public string assetType, assetName, theme, iconName;
            public bool isOwned, isInstalled, hasUpdate, isNew, isOnSale, isFree;
            public float price;
            public int sortOrder;
        }
        
        private void BuildAssetsFromCatalog()
        {
            var packs = SyntyCatalogBridge.LoadedPacks;
            if (packs == null || packs.Count == 0) return;
            
            // Pre-load shared textures before the loop — prevents per-button cache misses
            LoadImage("Assets", "Asset_Background");
            LoadImage("Assets", "Asset_Background_Gradient");
            LoadImage("Assets", "Asset_Selected");
            LoadImage("Assets", "Asset_Button_TypeBackground");
            LoadImage("Assets", "Icon_ProductPage");
            LoadImage("Assets", "Update_Icon");
            LoadImage("Assets", "Cart_Icon");
            LoadImage("Assets", "Icon_Download");
            LoadImage("Assets", "Download_PercentageBar");
            LoadImage("Buttons", "Button_Round");
            LoadImage("Buttons", "Button_Round_Pressed");
            
            // Pre-compute all pack metadata (cheap, no UI work)
            var buildData = new List<PackBuildData>(packs.Count);
            int sortIdx = 0;
            foreach (var pack in packs)
            {
                var d = new PackBuildData();
                d.pack = pack;
                d.assetType = SyntyCatalogBridge.GetAssetType(pack);
                d.assetName = SyntyCatalogBridge.GetDisplayName(pack);
                d.theme = string.Join(",", SyntyCatalogBridge.GetThemes(pack)); // all themes a pack belongs to
                // Treat as owned if individually owned OR the Synty Pass is on (the pass grants
                // access to everything). Building with the correct owned state up front avoids a
                // flicker where pass-owned assets briefly render as not-owned before
                // OnAllButtonsCreated re-applies the pass.
                d.isOwned = SyntyStoreService.Instance.OwnedProductHandles.Contains(pack.packName)
                            || (_licenseSyntyPass && SyntyLoginManager.HasSyntyPass)
                            || _licenseSyntyPass;
                d.isInstalled = SyntyCatalogBridge.IsInstalled(pack);
                d.hasUpdate = SyntyCatalogBridge.HasUpdate(pack);
                d.isNew = false;
                if (!string.IsNullOrEmpty(pack.releaseDate))
                {
                    System.DateTime releaseDate;
                    if (System.DateTime.TryParse(pack.releaseDate, System.Globalization.CultureInfo.InvariantCulture, 
                        System.Globalization.DateTimeStyles.None, out releaseDate))
                        d.isNew = (System.DateTime.Now - releaseDate).TotalDays <= _newBadgeDays;
                }
                d.isOnSale = pack.isOnSale;
                d.price = pack.price;
                d.isFree = d.price <= 0f;
                if (d.isFree) d.isOnSale = false;
                d.sortOrder = pack.releaseOrder > 0 ? pack.releaseOrder : sortIdx;
                
                string iconFilename = SyntyCatalogBridge.GetIconFilename(pack);
                string iconNameBase = iconFilename.EndsWith(".png") ? iconFilename.Substring(0, iconFilename.Length - 4) : iconFilename;
                string processedPath = $"{_imagesPath}/AssetIcons/{iconFilename}";
                d.iconName = System.IO.File.Exists(processedPath) ? iconNameBase : null;
                
                buildData.Add(d);
                sortIdx++;
            }
            
            // Sort by release date (newest first) so initial batch shows the most recent assets
            buildData.Sort((a, b) => a.sortOrder.CompareTo(b.sortOrder));
            
            // Pre-load all per-button icons into cache, and ensure each has a desaturated copy
            // (used for not-owned assets). The copy is written next to the icon in AssetIcons/
            // as "<name>Desaturated.png" so LoadImage("AssetIcons", name+"Desaturated") finds it.
            foreach (var d in buildData)
            {
                if (d.iconName != null)
                {
                    LoadImage("AssetIcons", d.iconName);
                    EnsureDesaturatedCopy("AssetIcons", d.iconName);
                }
            }
            
            // Detach asset content from DOM during initial build
            var assetParent = _assetContent?.parent;
            int assetParentIndex = -1;
            if (assetParent != null)
            {
                assetParentIndex = assetParent.IndexOf(_assetContent);
                _assetContent.RemoveFromHierarchy();
            }
            
            // Hide asset grid until all buttons are built (prevents visible reordering)
            _assetContent.style.display = DisplayStyle.None;
            
            // Create first batch off-DOM
            int initialCount = Mathf.Min(INITIAL_BUTTON_BATCH, buildData.Count);
            for (int i = 0; i < initialCount; i++)
                CreateAndAddButton(buildData[i]);
            
            
            // Reattach to DOM
            if (assetParent != null)
            {
                if (assetParentIndex >= 0 && assetParentIndex < assetParent.childCount)
                    assetParent.Insert(assetParentIndex, _assetContent);
                else
                    assetParent.Add(_assetContent);
            }
            
            // Show the grid now that the first batch exists. (Previously it stayed hidden until
            // ALL deferred batches finished — but if the editor gets busy mid-build, e.g. a
            // resumed multi-install's recompile/domain reload, those deferred batches can stall
            // and the grid would stay blank for the rest of the batch. Showing after the first
            // batch guarantees the grid is always visible; later batches just fill in.)
            _assetContent.style.display = DisplayStyle.Flex;
            
            if (initialCount >= buildData.Count)
            {
                // All buttons created — run post-build
                OnAllButtonsCreated();
                return;
            }
            
            // If a download/install is active (e.g. this is a rebuild after a mid-batch domain
            // reload), the editor will be busy and frame-deferred batches get starved — leaving
            // only some buttons loaded. In that case build the rest synchronously now so the grid
            // is complete before the next asset installs.
            bool installActive = false;
            try { installActive = SyntyDownloadManager.Instance != null && SyntyDownloadManager.Instance.HasActiveWork; } catch { }
            if (installActive)
            {
                for (int i = initialCount; i < buildData.Count; i++)
                    CreateAndAddButton(buildData[i]);
                OnAllButtonsCreated();
                return;
            }
            
            // Schedule remaining buttons in batches across frames
            int nextIndex = initialCount;
            void BuildNextBatch()
            {
                if (this == null || _assetContent == null) return;
                
                int end = Mathf.Min(nextIndex + DEFERRED_BUTTON_BATCH, buildData.Count);
                for (int i = nextIndex; i < end; i++)
                    CreateAndAddButton(buildData[i]);
                nextIndex = end;
                
                if (nextIndex < buildData.Count)
                {
                    EditorApplication.delayCall += BuildNextBatch;
                }
                else
                {
                    // All built — show grid sorted
                    _assetContent.style.display = DisplayStyle.Flex;
                    OnAllButtonsCreated();
                }
            }
            EditorApplication.delayCall += BuildNextBatch;
        }
        
        private void CreateAndAddButton(PackBuildData d)
        {
            var (assetBtn, setSelected, getSelected, setOwned, getOwned) = CreateAssetButton(
                d.assetType, d.assetName, d.iconName, d.isNew, d.isOnSale, d.isOwned, d.price, d.pack.compareAtPrice);
            _assetContent.Add(assetBtn);
            
            int itemIndex = _assetItems.Count;
            _assetItems.Add((assetBtn, assetBtn.Q<VisualElement>("asset-btn-visual"), d.assetType, d.assetName, d.theme, 
                setSelected, getSelected, setOwned, getOwned, d.isNew, d.isOnSale, d.isFree, d.price, d.sortOrder));
            _assetPackMapping[itemIndex] = d.pack;
            
            // Installed state comes from the manifest and should show regardless of current
            // owned/pass state — on a fresh restart ownership loads asynchronously and may not be
            // ready when the grid builds, which previously left installed assets looking uninstalled.
            if (d.isInstalled && d.hasUpdate)
                ApplyUpdateState(assetBtn);
            else if (d.isInstalled)
                ApplyInstalledState(assetBtn);
        }
        
        private void OnAllButtonsCreated()
        {
            // Use the saved pass state (_licenseSyntyPass, persisted in EditorPrefs and restored on
            // domain reload) rather than SyntyLoginManager.HasSyntyPass, which may not be re-verified
            // yet right after a mid-install reload. Otherwise assets briefly show as not-owned even
            // though the pass is on. The background verify will correct it if the saved value is wrong.
            if (_licenseSyntyPass)
            {
                _prePassOwnedStates.Clear();
                _syntyPassChangedAssets.Clear();
                for (int i = 0; i < _assetItems.Count; i++)
                {
                    // Record genuine INDIVIDUAL ownership (not the pass-granted look the asset may
                    // already have been built with). Assets that are only owned via the pass are
                    // tracked so they revert correctly if the pass is later turned off.
                    var pack = _assetPackMapping.TryGetValue(i, out var p) ? p : null;
                    bool individuallyOwned = pack != null &&
                        SyntyStoreService.Instance.OwnedProductHandles.Contains(pack.packName);
                    _prePassOwnedStates[i] = individuallyOwned;
                    if (!individuallyOwned)
                    {
                        _syntyPassChangedAssets.Add(i);
                        if (!_assetItems[i].getOwned())
                            _assetItems[i].setOwned(true);
                        
                        // Show type background for pass-owned assets
                        var typeBgEl = _assetItems[i].button.Q<VisualElement>("asset-type-bg");
                        if (typeBgEl != null) typeBgEl.style.display = DisplayStyle.Flex;
                    }
                }
                UpdateCollectionCounts();
            }
            
            // Auto-default to "Updates" sort if any assets have updates available
            bool anyUpdates = _assetItems.Any(i => i.btnVisual?.ClassListContains("asset-has-update") == true);
            if (anyUpdates && !_userPickedSort)
            {
                _sortMode = 2;
                _sortDirty = true;
                if (_sortDropdown != null) _sortDropdown.value = "Updates";
            }
            else
            {
                // No updates — fall through to the sale auto-sort. Switches to "On Sale" when
                // there are on-sale, not-owned assets; otherwise stays on Release Date.
                AutoSortOnSale();
            }
            UpdateSortDropdownChoices();
            
            // Re-apply filters and sort now that all buttons exist
            _sortDirty = true;
            FilterAssets();
            UpdateCollectionCounts();
            UpdateDownloadBar();
            // Apply the current icon-size scaling to the freshly built cards so their resting scale is
            // correct immediately. Without this, after a reload (same window size, so no geometry-change
            // callback fires) the cards sit at the wrong resting scale, and the first hover "shrinks"
            // them to the correct size and leaves them there.
            if (_assetItems != null && _assetItems.Count > 0) UpdateThumbnailSize();
            
            // Apply SyntyPass visual state (100% bar, pass colors) after all buttons and counts are set
            if (_syntyPassBtn != null)
                UpdateSyntyPassButtonState(_syntyPassBtn, _licenseSyntyPass);
            // Arm the 2-minute attention pulse for the pass button (no-op if already clicked before).
            if (_syntyPassBtn != null) ArmPassButtonPulse();
            if (_syntyPassGlowBar != null)
                _syntyPassGlowBar.style.opacity = _licenseSyntyPass ? 1f : 0f;
            if (_licenseSyntyPass)
                ApplySyntyPassVisualState();
            
            // Mark new releases as seen — the user has now opened the tool and can see them
            SyntyNotificationService.MarkNewReleasesSeen();
            
            // Restore the saved scroll position after the grid has rebuilt (e.g. following an
            // install's domain reload, or a re-sort). Deferred so the content height resolves
            // first, otherwise the offset clamps back to the top.
            RestoreAssetScrollPosition();
            // Re-select assets that were selected before an install/uninstall/update action. The
            // domain reload after those actions wipes in-memory selection, so we persist the names
            // to SessionState (survives reloads) and restore them once the grid has rebuilt.
            RestoreSelectionFromSession();
        }
        
        // Saves the names of all currently-selected assets to SessionState so the selection can be
        // restored after a domain reload (install/uninstall/update triggers a recompile).
        private void SaveSelectionToSession()
        {
            SaveSelectionToSession(null);
        }
        
        // Same, but excludes the given asset names (e.g. assets being uninstalled, which should not
        // be re-selected after the reload).
        private void SaveSelectionToSession(System.Collections.Generic.HashSet<string> exclude)
        {
            var names = new System.Collections.Generic.List<string>();
            foreach (var it in _assetItems)
                if (it.getSelected() && (exclude == null || !exclude.Contains(it.name)))
                    names.Add(it.name);
            SessionState.SetString("SyntyPassport_SelectedAssets", string.Join("\n", names));
        }
        
        // Records an asset name as "just installed" so RestoreSelectionFromSession won't re-select
        // it after the reload. Persisted in SessionState so it survives the domain reload.
        private void AddToJustInstalled(string name)
        {
            string cur = SessionState.GetString("SyntyPassport_JustInstalled", "");
            var list = string.IsNullOrEmpty(cur)
                ? new System.Collections.Generic.List<string>()
                : new System.Collections.Generic.List<string>(cur.Split('\n'));
            if (!list.Contains(name)) list.Add(name);
            SessionState.SetString("SyntyPassport_JustInstalled", string.Join("\n", list));
        }
        
        // Removes one asset name from the persisted selection set (e.g. an asset that finished
        // installing should not be re-selected after the reload).
        private void RemoveFromSessionSelection(string name)
        {
            string saved = SessionState.GetString("SyntyPassport_SelectedAssets", "");
            if (string.IsNullOrEmpty(saved)) return;
            var list = new System.Collections.Generic.List<string>(saved.Split('\n'));
            if (list.Remove(name))
                SessionState.SetString("SyntyPassport_SelectedAssets", string.Join("\n", list));
        }
        
        // Re-selects assets named in SessionState (saved before an action's domain reload), then
        // clears the key so it only applies once.
        private void RestoreSelectionFromSession()
        {
            string saved = SessionState.GetString("SyntyPassport_SelectedAssets", "");
            if (string.IsNullOrEmpty(saved)) return;
            var wanted = new System.Collections.Generic.HashSet<string>(saved.Split('\n'));
            // Assets that just finished installing should NOT be re-selected.
            string installedThisRun = SessionState.GetString("SyntyPassport_JustInstalled", "");
            if (!string.IsNullOrEmpty(installedThisRun))
                foreach (var n in installedThisRun.Split('\n')) wanted.Remove(n);
            foreach (var it in _assetItems)
            {
                if (!wanted.Contains(it.name)) continue;
                // Don't re-select an asset that is now installed (installing it deselects it).
                bool installed = (it.btnVisual?.ClassListContains("asset-installed") ?? false)
                              || (it.button?.ClassListContains("asset-installed") ?? false);
                if (installed) continue;
                it.setSelected(true);
            }
            SessionState.EraseString("SyntyPassport_SelectedAssets");
            SessionState.EraseString("SyntyPassport_JustInstalled");
            UpdateDownloadBar();
        }
        
        // Restores the asset grid scroll position from the persisted offset, retrying over a few
        // frames so it sticks once the content height has settled.
        private void RestoreAssetScrollPosition()
        {
            if (!_hasSavedAssetScroll || _assetScrollView == null) return;
            float target = _savedAssetScrollY;
            int attempts = 0;
            void TryRestore()
            {
                if (_reloadingDomain || _assetScrollView == null || _assetScrollView.panel == null) { _suppressScrollSave = false; return; }
                _suppressScrollSave = true;
                _assetScrollView.scrollOffset = new Vector2(_assetScrollView.scrollOffset.x, target);
                _suppressScrollSave = false;
                attempts++;
                if (attempts < 6)
                    _assetScrollView.schedule.Execute(TryRestore).StartingIn(16);
            }
            _assetScrollView.schedule.Execute(TryRestore).StartingIn(0);
        }
        
        /// <summary>
        /// Apply installed visual state to an asset button (no animation).
        /// </summary>
        private void ApplyInstalledState(VisualElement assetBtn)
        {
            var dlBtn = assetBtn.Q<VisualElement>("download-btn");
            var dlIcon = dlBtn?.Q<VisualElement>("download-icon");
            var rRing = assetBtn.Q<VisualElement>("radial-ring");
            var rRingBg = assetBtn.Q<VisualElement>("radial-ring-bg");
            var btnVisual = assetBtn.Q<VisualElement>("asset-btn-visual");
            
            if (dlBtn != null)
            {
                if (rRing != null) rRing.style.display = DisplayStyle.None;
                if (rRingBg != null) rRingBg.style.display = DisplayStyle.None;
                
                // Ensure download button is visible (may be hidden if asset was not-owned initially)
                dlBtn.style.display = DisplayStyle.Flex;
                
                // Hide cart button
                var cartBtn = assetBtn.Q<VisualElement>("cart-btn");
                if (cartBtn != null) cartBtn.style.display = DisplayStyle.None;
                
                dlBtn.style.unityBackgroundImageTintColor = _installedBtnColor;
                dlBtn.pickingMode = PickingMode.Position;
                
                if (dlIcon != null && _installedIcon != null)
                {
                    dlIcon.style.backgroundImage = new StyleBackground(_installedIcon);
                    dlIcon.style.unityBackgroundImageTintColor = Color.white;
                    dlIcon.style.scale = new Scale(new Vector3(_installedIconScale, _installedIconScale, 1f));
                }
                
                var pressedOvr = dlBtn.Q<VisualElement>("download-pressed-overlay");
                if (pressedOvr != null)
                {
                    pressedOvr.style.display = DisplayStyle.Flex;
                    pressedOvr.style.unityBackgroundImageTintColor = _installedBtnColor;
                }
                
                btnVisual?.AddToClassList("asset-installed");
                
                if (dlBtn.userData is object[] refs && refs.Length >= 3)
                {
                    if (refs[0] is Color[] btnColorRef) btnColorRef[0] = _installedBtnColor;
                    if (refs[1] is Color[] iconColorRef) iconColorRef[0] = Color.white;
                    if (refs[2] is bool[] installedRef) installedRef[0] = true;
                }
                
                float dbs = GetDlBtnBaseScale();
                dlBtn.style.scale = new Scale(new Vector3(_installedBtnScale * dbs, _installedBtnScale * dbs, 1f));
                
                Label ttLbl2 = null;
                if (dlBtn != null) _downloadTooltipLabels.TryGetValue(dlBtn, out ttLbl2);
                if (dlIcon != null) RegisterUninstallHover(dlBtn, dlIcon, ttLbl2);
            }
            
            var selectedOvr = assetBtn.Q<VisualElement>("asset-btn-selected");
            if (selectedOvr != null)
            {
                selectedOvr.style.unityBackgroundImageTintColor = _installedBtnColor;
                selectedOvr.style.opacity = 1;
            }
            
            var gradOvr = btnVisual?.Q<VisualElement>("asset-btn-gradient");
            if (gradOvr != null)
            {
                gradOvr.style.unityBackgroundImageTintColor = _installedBtnColor;
                gradOvr.style.display = DisplayStyle.Flex;
            }
            
            ShowInstalledBadge(assetBtn);
        }
        
