        private void BuildAssetsFromIconPool()
        {
            BuildAssetIconPool();
            
            var iconFiles = new List<string>(_assetIconPool);
            iconFiles.Sort();
            
            var rng = new System.Random(42);
            int sortIdx = 0;
            foreach (var iconFile in iconFiles)
            {
                var (assetType, assetName, theme) = ParseAssetIconFilename(iconFile);
                bool isNew    = rng.Next(4) == 0;
                bool isOnSale = rng.Next(3) == 0;
                bool isOwned  = rng.Next(2) == 0;
                bool isFree   = rng.Next(10) == 0;
                if (isFree) isOwned = true;
                float price = isFree ? 0f : (float)(System.Math.Round(rng.NextDouble() * 45.0 + 4.99, 2));
                int sortOrder = sortIdx++;
                string iconName = iconFile;
                var (assetBtn, setSelected, getSelected, setOwned, getOwned) = CreateAssetButton(assetType, assetName, iconName, isNew, isOnSale, isOwned, price);
                _assetContent.Add(assetBtn);
                _assetItems.Add((assetBtn, assetBtn.Q<VisualElement>("asset-btn-visual"), assetType, assetName, theme, setSelected, getSelected, setOwned, getOwned, isNew, isOnSale, isFree, price, sortOrder));
            }
            
        }
        
        private void BuildAssetIconPool()
        {
            _assetIconPool.Clear();
            _assetIconPoolIndex = 0;
            
            FindImagesPath();
            if (string.IsNullOrEmpty(_imagesPath)) return;
            
            // Generate any missing Desaturated versions before building the pool
            EnsureGreyIcons();
            
            // Find source icons from AssetIcons/Source/ — baked outputs live in AssetIcons/
            string folderPath = $"{_imagesPath}/AssetIcons/Source";
            string[] guids = AssetDatabase.FindAssets("t:Texture2D", new[] { folderPath });
            
            foreach (string guid in guids)
            {
                string assetPath = AssetDatabase.GUIDToAssetPath(guid);
                string fileName = System.IO.Path.GetFileNameWithoutExtension(assetPath);
                if (!string.IsNullOrEmpty(fileName) && !fileName.EndsWith("Desaturated"))
                    _assetIconPool.Add(fileName);
            }
            
            // Fisher-Yates shuffle for random order
            var rng = new System.Random();
            for (int i = _assetIconPool.Count - 1; i > 0; i--)
            {
                int j = rng.Next(i + 1);
                var tmp = _assetIconPool[i];
                _assetIconPool[i] = _assetIconPool[j];
                _assetIconPool[j] = tmp;
            }
            
            if (_assetIconPool.Count == 0) { }
        }
        
        // Ensures a desaturated copy of a single icon exists at
        // {_imagesPath}/{subfolder}/{imageName}Desaturated.png. Loads the colored icon,
        // converts to greyscale (luminance, alpha preserved) via a readable RenderTexture
        // copy, and writes the PNG. No-op if the copy already exists or the source is missing.
        private void EnsureDesaturatedCopy(string subfolder, string imageName)
        {
            if (string.IsNullOrEmpty(_imagesPath) || string.IsNullOrEmpty(imageName)) return;
            if (imageName.EndsWith("Desaturated")) return;
            
            string desatPath = $"{_imagesPath}/{subfolder}/{imageName}Desaturated.png".Replace("\\", "/");
            string desatFull = System.IO.Path.Combine(System.IO.Directory.GetCurrentDirectory(), desatPath);
            string cacheKey = $"{subfolder}/{imageName}Desaturated";
            
            if (System.IO.File.Exists(desatFull))
            {
                // Already generated. Make sure it's in the in-memory cache so LoadImage returns
                // it immediately this session (AssetDatabase.LoadAssetAtPath can lag right after
                // import, which is why not-owned icons appeared colored until hovered). Load the
                // PNG bytes straight into a Texture2D rather than waiting on the AssetDatabase.
                if (!_imageCache.ContainsKey(cacheKey))
                {
                    try
                    {
                        byte[] bytes = System.IO.File.ReadAllBytes(desatFull);
                        var t = new Texture2D(2, 2, TextureFormat.RGBA32, false);
                        if (t.LoadImage(bytes))
                        {
                            t.hideFlags = HideFlags.HideAndDontSave;
                            _imageCache[cacheKey] = t;
                        }
                    }
                    catch { }
                }
                return;
            }
            
            var src = LoadImage(subfolder, imageName);
            if (src == null) return;
            
            try
            {
                // Readable copy via RenderTexture (source texture may not be Read/Write enabled).
                RenderTexture rt = RenderTexture.GetTemporary(src.width, src.height, 0, RenderTextureFormat.ARGB32);
                Graphics.Blit(src, rt);
                RenderTexture prev = RenderTexture.active;
                RenderTexture.active = rt;
                Texture2D readable = new Texture2D(src.width, src.height, TextureFormat.RGBA32, false);
                readable.ReadPixels(new Rect(0, 0, rt.width, rt.height), 0, 0);
                readable.Apply();
                RenderTexture.active = prev;
                RenderTexture.ReleaseTemporary(rt);
                
                Color[] px = readable.GetPixels();
                for (int i = 0; i < px.Length; i++)
                {
                    float g = px[i].r * 0.299f + px[i].g * 0.587f + px[i].b * 0.114f;
                    px[i] = new Color(g, g, g, px[i].a);
                }
                readable.SetPixels(px);
                readable.Apply();
                
                byte[] png = readable.EncodeToPNG();
                // _imagesPath is an Assets-relative path, so desatPath is a valid project path.
                System.IO.Directory.CreateDirectory(System.IO.Path.GetDirectoryName(desatFull));
                System.IO.File.WriteAllBytes(desatFull, png);
                
                // Import so LoadImage / AssetDatabase can find it across sessions.
                AssetDatabase.ImportAsset(desatPath, ImportAssetOptions.ForceSynchronousImport);
                
                // Also seed the in-memory image cache with the texture we just generated, so
                // LoadImage("<sub>", "<name>Desaturated") returns it immediately this session
                // even before the AssetDatabase import is queryable. Keep `readable` alive (do
                // not destroy it) since it's now the cached texture.
                readable.hideFlags = HideFlags.HideAndDontSave;
                _imageCache[cacheKey] = readable;
            }
            catch { /* best-effort: a missing desat copy just falls back to the colored icon */ }
        }
        
        private void EnsureGreyIcons()
        {
            FindImagesPath();
            if (string.IsNullOrEmpty(_imagesPath)) return;
            
            string folderPath = $"{_imagesPath}/AssetIcons/Source";
            string[] guids = AssetDatabase.FindAssets("t:Texture2D", new[] { folderPath });
            
            bool anyCreated = false;
            foreach (string guid in guids)
            {
                string assetPath = AssetDatabase.GUIDToAssetPath(guid);
                string fileName = System.IO.Path.GetFileNameWithoutExtension(assetPath);
                if (string.IsNullOrEmpty(fileName) || 
                    fileName.EndsWith("Desaturated") || 
                    fileName.EndsWith("_masked") || 
                    fileName.EndsWith("_maskedDesaturated")) continue;
                
                string greyPath = $"{folderPath}/{fileName}Desaturated.png";
                if (System.IO.File.Exists(System.IO.Path.Combine(System.IO.Directory.GetCurrentDirectory(), greyPath.TrimStart('/')))) continue;
                if (AssetDatabase.LoadAssetAtPath<Texture2D>(greyPath) != null) continue;
                
                Texture2D src = AssetDatabase.LoadAssetAtPath<Texture2D>(assetPath);
                if (src == null) continue;
                
                // Make readable copy via RenderTexture
                RenderTexture rt = RenderTexture.GetTemporary(src.width, src.height, 0, RenderTextureFormat.ARGB32);
                Graphics.Blit(src, rt);
                RenderTexture prev = RenderTexture.active;
                RenderTexture.active = rt;
                Texture2D readable = new Texture2D(src.width, src.height, TextureFormat.RGBA32, false);
                readable.ReadPixels(new Rect(0, 0, rt.width, rt.height), 0, 0);
                readable.Apply();
                RenderTexture.active = prev;
                RenderTexture.ReleaseTemporary(rt);
                
                // Convert to greyscale
                Color[] px = readable.GetPixels();
                for (int i = 0; i < px.Length; i++)
                {
                    float g = px[i].r * 0.299f + px[i].g * 0.587f + px[i].b * 0.114f;
                    px[i] = new Color(g, g, g, px[i].a);
                }
                readable.SetPixels(px);
                readable.Apply();
                
                // Save as PNG asset
                byte[] png = readable.EncodeToPNG();
                string fullPath = System.IO.Path.Combine(
                    System.IO.Path.GetDirectoryName(System.IO.Path.GetFullPath(Application.dataPath)),
                    greyPath.TrimStart('/'));
                System.IO.Directory.CreateDirectory(System.IO.Path.GetDirectoryName(fullPath));
                System.IO.File.WriteAllBytes(fullPath, png);
                
                anyCreated = true;
            }
            
            if (anyCreated)
                AssetDatabase.Refresh();
        }
        
        // Derives (type, name, theme) from an AssetIcons filename.
        // e.g. "SyntyStore_Icon_POLYGON_HorrorAsylum" → ("POLYGON", "Horror Asylum", "Horror")
        private (string type, string name, string theme) ParseAssetIconFilename(string filename)
        {
            // Known type prefixes in priority order
            string[] knownTypes = { "POLYGON", "SIDEKICK", "ANIMATION", "INTERFACE", "SIMPLE" };
            
            string type = "POLYGON";
            string rawName = filename;
            
            // Strip "SyntyStore_Icon_" prefix if present
            if (rawName.StartsWith("SyntyStore_Icon_"))
                rawName = rawName.Substring("SyntyStore_Icon_".Length);
            
            // Extract type prefix
            foreach (var t in knownTypes)
            {
                if (rawName.StartsWith(t + "_"))
                {
                    type = t;
                    rawName = rawName.Substring(t.Length + 1);
                    break;
                }
                if (rawName == t)
                {
                    type = t;
                    rawName = t;
                    break;
                }
            }
            
            // CamelCase → spaced words  e.g. "HorrorAsylum" → "Horror Asylum"
            var sb = new System.Text.StringBuilder();
            for (int i = 0; i < rawName.Length; i++)
            {
                if (i > 0 && char.IsUpper(rawName[i]) && !char.IsUpper(rawName[i - 1]))
                    sb.Append(' ');
                sb.Append(rawName[i]);
            }
            // Also split on underscores
            string name = sb.ToString().Replace('_', ' ').Trim();
            if (string.IsNullOrEmpty(name)) name = filename;
            
            // Derive theme from name keywords
            string nameLower = name.ToLower();
            string theme = "Fantasy";
            if (nameLower.Contains("zombie") || nameLower.Contains("apocalypse") || nameLower.Contains("horror") || nameLower.Contains("asylum") || nameLower.Contains("carnival"))
                theme = "Horror";
            else if (nameLower.Contains("scifi") || nameLower.Contains("sci-fi") || nameLower.Contains("soldiers") || nameLower.Contains("menus") || nameLower.Contains("space"))
                theme = "Sci-Fi";
            else if (nameLower.Contains("modern") || nameLower.Contains("city") || nameLower.Contains("civilian") || nameLower.Contains("interface") || nameLower.Contains("ui"))
                theme = "Modern";
            else if (nameLower.Contains("battle") || nameLower.Contains("combat") || nameLower.Contains("samurai") || nameLower.Contains("viking") || nameLower.Contains("locomotion"))
                theme = "Battle";
            else if (nameLower.Contains("nature") || nameLower.Contains("village") || nameLower.Contains("villager") || nameLower.Contains("biome"))
                theme = "Nature";
            
            return (type, name, theme);
        }
        
        private string NextAssetIconName()
        {
            if (_assetIconPool.Count == 0) return null;
            
            string name = _assetIconPool[_assetIconPoolIndex % _assetIconPool.Count];
            _assetIconPoolIndex++;
            
            // When we've used every image once, reshuffle and start again
            if (_assetIconPoolIndex >= _assetIconPool.Count)
            {
                _assetIconPoolIndex = 0;
                var rng = new System.Random();
                for (int i = _assetIconPool.Count - 1; i > 0; i--)
                {
                    int j = rng.Next(i + 1);
                    var tmp = _assetIconPool[i];
                    _assetIconPool[i] = _assetIconPool[j];
                    _assetIconPool[j] = tmp;
                }
            }
            
            return name;
        }
        
        private Font LoadFont(string fontName)
        {
            // Try SessionState cached path first (survives domain reload, no search)
            string cacheKey = $"SyntyPassport_Font_{fontName}";
            string cachedPath = SessionState.GetString(cacheKey, "");
            if (!string.IsNullOrEmpty(cachedPath))
            {
                Font cachedFont = AssetDatabase.LoadAssetAtPath<Font>(cachedPath);
                if (cachedFont != null) return cachedFont;
            }
            
            // Try direct path (no FindAssets)
            FindImagesPath();
            string editorPath = _imagesPath.Replace("/Images", "");
            string directPath = $"{editorPath}/Fonts/{fontName}.ttf";
            Font directFont = AssetDatabase.LoadAssetAtPath<Font>(directPath);
            if (directFont != null)
            {
                SessionState.SetString(cacheKey, directPath);
                return directFont;
            }
            
            // Try .otf
            directPath = $"{editorPath}/Fonts/{fontName}.otf";
            directFont = AssetDatabase.LoadAssetAtPath<Font>(directPath);
            if (directFont != null)
            {
                SessionState.SetString(cacheKey, directPath);
                return directFont;
            }
            
            // Last resort: AssetDatabase search
            var guids = AssetDatabase.FindAssets($"{fontName} t:Font");
            if (guids.Length > 0)
            {
                var path = AssetDatabase.GUIDToAssetPath(guids[0]);
                Font font = AssetDatabase.LoadAssetAtPath<Font>(path);
                if (font != null)
                {
                    SessionState.SetString(cacheKey, path);
                    return font;
                }
            }
            
            return null;
        }
        
        // Shrinks the window to a sensible height if it's over-tall, once per editor session. Older
        // builds set a huge min height (1250) and Unity persists window size, so a restored window
        // opens huge; this brings it down. Shrink-only + once-per-session, so it never fights a size
        // the user chose (and doesn't re-shrink on every domain reload/asset install).
        private void RightSizeWindowOnce()
        {
            if (!this) return;
            if (SessionState.GetBool("SyntyImporter_Rightsized", false)) return;
            SessionState.SetBool("SyntyImporter_Rightsized", true);
            float ppp = Mathf.Max(1f, EditorGUIUtility.pixelsPerPoint);
            float screenMaxH = Screen.currentResolution.height / ppp * 0.9f;
            float minH = SyntyLoginManager.IsLoggedIn ? _minHeight : _loginMinHeight;
            float wantH = Mathf.Clamp(SyntyLoginManager.IsLoggedIn ? 840f : 620f, minH, screenMaxH);
            var pos = position;
            if (pos.height > wantH)
            {
                pos.height = wantH;
                position = pos;
            }
        }

        public void CreateGUI()
        {
            var root = rootVisualElement;
            root.Clear();
            // Shrink an over-tall window to a sensible size once per session (older builds forced a
            // huge min height, and Unity restores that saved size on open). Deferred so it runs after
            // the layout is restored.
            rootVisualElement.schedule.Execute(RightSizeWindowOnce).StartingIn(0);
            // Log the version once per editor session (CreateGUI also runs after domain reloads).
            if (!SessionState.GetBool("SyntyPassport_VersionLogged", false))
            {
                SessionState.SetBool("SyntyPassport_VersionLogged", true);
                Synty.Tools.SyntyLog.Info($"Synty Importer v{Synty.Tools.SyntyToolVersion.VERSION}");
            }
            
            // Detect new orders on user interaction: any click in the window triggers a
            // throttled, silent order-count check that refreshes owned assets + pass if the
            // user has purchased something. Unregister first so re-entry (domain reload /
            // rebuild) doesn't stack duplicate handlers on the persistent root element.
            root.UnregisterCallback<PointerDownEvent>(OnRootPointerDownForOrders, TrickleDown.TrickleDown);
            root.RegisterCallback<PointerDownEvent>(OnRootPointerDownForOrders, TrickleDown.TrickleDown);
            
            // Unity 6 can leave the grid vertically stretched after the window is maximized or
            // restored (panel relayout glitch). When the root's size changes meaningfully, re-apply
            // the fixed card sizes on the next frame so the cards snap back to square.
            root.UnregisterCallback<GeometryChangedEvent>(OnRootGeometryChanged);
            root.RegisterCallback<GeometryChangedEvent>(OnRootGeometryChanged);
            
            // Track tool open for logged-out users (logged-in paths track via OnLoginCompleted
            // after the build, so install counts and ownership totals are populated).
            EditorApplication.delayCall += () =>
            {
                if (!this) return;
                if (!SyntyStoreHelper.IsLoggedIn)
                    SyntyAnalytics.TrackToolOpen(false, false, 0, 0);
            };
            
            // Set background immediately so window isn't white while loading
            root.style.flexGrow = 1;
            root.style.backgroundColor = new Color(0.094f, 0.078f, 0.145f, 1f);
            
            // Defer ALL work to next frame so the toolbar click returns instantly
            EditorApplication.delayCall += () =>
            {
                if (!this) return;
                CreateGUIDeferred();
            };
        }
        
        private void CreateGUIDeferred()
        {
            var root = rootVisualElement;
            
            // Reset download queue state (may be null/stale after domain reload)
            _downloadQueue = new Queue<System.Action>();
            _downloadQueueRunning = false;
            _downloadQueueFirstStarted = false;
            _activeDownloadCount = 0;
            
            // Load button textures
            _filterBtnBg = LoadImage("Buttons", "Button_Filter_BG");
            _filterBtnSelected = LoadImage("Buttons", "Button_Filter_Selected");
            _filterBtnEnd = LoadImage("Buttons", "Button_Filter_End");
            _filterBtnEndSelected = LoadImage("Buttons", "Button_Filter_End_Selected");
            _filterBtnMiddle = LoadImage("Buttons", "Button_Filter_Middle");
            _filterBtnMiddleSelected = LoadImage("Buttons", "Button_Filter_Middle_Selected");
            _filterBtnGlowEnd = LoadImage("Buttons", "Button_Filter_End_Glow");
            _filterBtnGlowMiddle = LoadImage("Buttons", "Button_Filter_Middle_Glow");
            _dropdownArrowDown = LoadImage("Icons/Misc", "DropdownArrow_Down_Icon");
            _dropdownArrowUp = LoadImage("Icons/Misc", "DropdownArrow_Up_Icon");
            // _assetImageMask no longer needed at runtime (masking done by SyntyIconPreprocessor)
            _btnGradient    = LoadImage("Assets", "Gradient_Bottom");
            _installedIcon  = LoadImage("Assets", "Installed_Icon");
            _uninstallIcon  = LoadImage("Icons/Misc", "Icon_Uninstall");
            if (_uninstallIcon == null) _uninstallIcon = EditorGUIUtility.IconContent("TreeEditor.Trash")?.image as Texture2D;
            _updateIcon     = LoadImage("Assets", "Update_Icon");
            _cartIcon       = LoadImage("Assets", "Cart_Icon");
            _downloadIcon   = LoadImage("Assets", "Icon_Download");
            _downloadRingTex = LoadImage("Assets", "Download_PercentageBar");
            
            // Load fonts
            _titleFont = LoadFont("Title_Font");
            _newakeFont = LoadFont("Newake-Font-Regular");
            
            if (_styleSheet == null)
            {
                // Try SessionState cached path first
                string cachedUssPath = SessionState.GetString("SyntyPassport_StyleSheet", "");
                if (!string.IsNullOrEmpty(cachedUssPath))
                    _styleSheet = AssetDatabase.LoadAssetAtPath<StyleSheet>(cachedUssPath);
                
                // Try direct path
                if (_styleSheet == null)
                {
                    FindImagesPath();
                    string editorPath = _imagesPath.Replace("/Images", "");
                    string directUss = $"{editorPath}/SyntyAssetDownloaderV2.uss";
                    _styleSheet = AssetDatabase.LoadAssetAtPath<StyleSheet>(directUss);
                    if (_styleSheet != null)
                        SessionState.SetString("SyntyPassport_StyleSheet", directUss);
                }
                
                // Last resort: FindAssets
                if (_styleSheet == null)
                {
                    var guids = AssetDatabase.FindAssets("SyntyAssetDownloaderV2 t:StyleSheet");
                    if (guids.Length > 0)
                    {
                        var path = AssetDatabase.GUIDToAssetPath(guids[0]);
                        _styleSheet = AssetDatabase.LoadAssetAtPath<StyleSheet>(path);
                        if (_styleSheet != null)
                            SessionState.SetString("SyntyPassport_StyleSheet", path);
                    }
                }
            }
            
            if (_styleSheet != null)
                root.styleSheets.Add(_styleSheet);
            
            // Fast path: if session credentials exist (from EditorPrefs, survives domain reload),
            // try to build UI immediately from cached data while verifying in background
            bool hasCredentials = SyntyLoginManager.IsLoggedIn || SyntyStoreService.Instance.IsAuthenticated;
            
            if (hasCredentials)
            {
                // Respect saved toggle state (user may have turned SyntyPass off in UI)
                if (!EditorPrefs.HasKey(PREFS_SYNTY_PASS))
                {
                    _licenseSyntyPass = SyntyLoginManager.HasSyntyPass;
                    EditorPrefs.SetBool(PREFS_SYNTY_PASS, _licenseSyntyPass);
                }
                
                bool canBuildNow = SyntyCatalogBridge.IsLoaded || SyntyCatalogBridge.TryLoadFromDiskCache();
                
                if (canBuildNow)
                {
                    // Check if all icons are on disk
                    var packs = SyntyCatalogBridge.LoadedPacks;
                    if (SyntyCatalogBridge.HasAllIcons(packs))
                    {
                        // All icons present — build immediately
                        OnLoginCompleted();
                        BuildUI(root);
                    }
                    else
                    {
                        // Download missing icons first, then build
                        var statusLabel = new Label("Downloading icons...");
                        statusLabel.style.color = new Color(1f, 1f, 1f, 0.5f);
                        statusLabel.style.fontSize = 12;
                        statusLabel.style.unityTextAlign = TextAnchor.MiddleCenter;
                        statusLabel.style.flexGrow = 1;
                        root.Add(statusLabel);
                        
                        SyntyCatalogBridge.EnsureIcons(packs,
                            onProgress: (current, total) =>
                            {
                                if (!this) return;
                                statusLabel.text = $"Downloading icons ({current}/{total})...";
                            },
                            onComplete: () =>
                            {
                                if (!this) return;
                                var r = rootVisualElement;
                                r.Clear();
                                if (_styleSheet != null) r.styleSheets.Add(_styleSheet);
                                OnLoginCompleted();
                                BuildUI(r);
                            }
                        );
                    }
                    
                    // Verify ownership in background (no loading screen)
                    EditorApplication.delayCall += () =>
                    {
                        if (!this) return;
                        if (SessionState.GetBool(SESSION_SKIP_VERIFY, false))
                        {
                            SessionState.SetBool(SESSION_SKIP_VERIFY, false);
                            return; // install/uninstall reload — ownership can't have changed, use the cached state
                        }
                        SyntyStoreHelper.TryRestoreSession(
                            onSuccess: () =>
                            {
                                if (!this) return;
                                UpdateOwnershipFromBackend();
                                // Refresh the banner on open: force-verify so the worker returns
                                // the current banner config, then apply it.
                                _ = RefreshBannerOnOpenAsync();
                                
                                // Background: refresh catalog and check for icon updates
                                SyntyCatalogBridge.LoadCatalog((freshPacks) =>
                                {
                                    if (!this || freshPacks == null || freshPacks.Count == 0) return;
                                    
                                    if (!SyntyCatalogBridge.HasAllIcons(freshPacks))
                                    {
                                        SyntyCatalogBridge.EnsureIcons(freshPacks, onComplete: () =>
                                        {
                                            if (!this) return;
                                            // Clear image cache for updated icons and rebuild
                                            var iconKeys = new List<string>();
                                            foreach (var key in _imageCache.Keys)
                                                if (key.Contains("AssetIcons")) iconKeys.Add(key);
                                            foreach (var key in iconKeys)
                                                _imageCache.Remove(key);
                                            
                                            // Rebuild UI to show new icons
                                            var r = rootVisualElement;
                                            r.Clear();
                                            if (_styleSheet != null) r.styleSheets.Add(_styleSheet);
                                            OnLoginCompleted();
                                            BuildUI(r);
                                        });
                                    }
                                }, forceRefresh: true);
                            },
                            onNoSession: () => { }
                        );
                    };
                    return;
                }
                
                // No cache — show loading screen
                ShowLoadingScreen(root, skipVerify: false);
                return;
            }
            
            // No credentials found — show login screen
            ShowLoginScreen(root);
        }
        
        private void ShowLoginScreen(VisualElement root)
        {
            root.Clear();
            // The login card is compact — lower the window's min height so it isn't forced tall and
            // the user can shrink it. Restored to _minHeight once the (taller) main UI loads.
            var lms = minSize; lms.y = _loginMinHeight; minSize = lms;
            var logoTex = LoadImage("Logo", "Synty_Logo_Large");
            var textLogoTex = LoadImage("Logo", "Synty_Importer_TextLogo");
            SyntyLoginManager.TextLogo = textLogoTex;
            SyntyLoginManager.TextLogoWidth = _loginTextLogoWidth;
            SyntyLoginManager.TextLogoHeight = _loginTextLogoHeight;
            SyntyLoginManager.TextLogoX = _loginTextLogoX;
            SyntyLoginManager.TextLogoY = _loginTextLogoY;
            SyntyLoginManager.TextLogoScale = _loginTextLogoScale;
            SyntyLoginManager.LogoWidth = _loginLogoWidth;
            SyntyLoginManager.LogoHeight = _loginLogoHeight;
            SyntyLoginManager.LogoX = _loginLogoX;
            SyntyLoginManager.LogoY = _loginLogoY;
            SyntyLoginManager.LogoScaleOverride = _loginLogoScale;
            // Debug toggle on the login screen — only when the dev unlock script is present.
            SyntyLoginManager.ShowDebugButton = IsDebugUnlocked();
            SyntyLoginManager.DebugPanelOn = EditorPrefs.GetBool(PREFS_DEBUG_PANEL_VISIBLE, false);
            SyntyLoginManager.DebugMiniPanel = SyntyLoginManager.DebugPanelOn ? BuildLoginMiniDebugPanel(root) : null;
            SyntyLoginManager.OnDebugToggle = () =>
            {
                EditorPrefs.SetBool(PREFS_DEBUG_PANEL_VISIBLE, SyntyLoginManager.DebugPanelOn);
                // Rebuild the login screen so the mini panel shows/hides immediately.
                ShowLoginScreen(root);
            };
            SyntyLoginManager.BuildLoginUI(root, logoTex, _titleFont, _newakeFont, _loginAccentColor, () =>
            {
                // Login success — show loading screen while fetching account data
                ShowLoadingScreen(rootVisualElement);
            });
        }
        
        // Builds a small debug panel for the login screen with only the controls that are safe
        // before the main UI exists (login accent + text logo). Each change rebuilds the login
        // screen so edits preview live. Full debug options remain post-login.
        private VisualElement BuildLoginMiniDebugPanel(VisualElement loginRoot)
        {
            var panel = new VisualElement();
            panel.name = "login-mini-debug";
            panel.style.width = 300;
            panel.style.flexShrink = 0;
            panel.style.backgroundColor = new Color(0.15f, 0.15f, 0.15f, 1f);
            panel.style.paddingLeft = 8;
            panel.style.paddingRight = 8;
            panel.style.paddingTop = 8;
            panel.style.paddingBottom = 8;

            var title = new Label("LOGIN DEBUG");
            title.style.fontSize = 12;
            title.style.unityFontStyleAndWeight = FontStyle.Bold;
            title.style.color = Color.white;
            title.style.marginBottom = 8;
            title.style.unityTextAlign = TextAnchor.MiddleCenter;
            panel.Add(title);

            System.Action rebuild = () =>
            {
                // Update the live login elements in place (no full teardown — avoids flicker and
                // losing slider focus mid-drag).
                var accent = loginRoot.Q<VisualElement>("login-accent-bar");
                if (accent != null) accent.style.backgroundColor = _loginAccentColor;
                var tl = loginRoot.Q<VisualElement>("login-text-logo");
                if (tl != null)
                {
                    tl.style.width = _loginTextLogoWidth;
                    tl.style.height = _loginTextLogoHeight;
                    tl.style.transformOrigin = new TransformOrigin(Length.Percent(50), Length.Percent(50));
                    float tlU6X = 0f;
#if UNITY_2022_2_OR_NEWER
                    tlU6X = -30f; // match SyntyLoginManager Unity 6 nudge
#endif
                    tl.style.translate = new Translate(
                        new Length(-_loginTextLogoWidth / 2f + _loginTextLogoX + tlU6X), new Length(_loginTextLogoY));
                    tl.style.scale = new Scale(new Vector3(_loginTextLogoScale, _loginTextLogoScale, 1f));
                }
                var ml = loginRoot.Q<VisualElement>("login-main-logo");
                if (ml != null)
                {
                    ml.style.width = _loginLogoWidth;
                    ml.style.height = _loginLogoHeight;
                    ml.style.translate = new Translate(new Length(_loginLogoX), new Length(_loginLogoY));
                    ml.style.scale = new Scale(new Vector3(_loginLogoScale, _loginLogoScale, 1f));
                }
            };

            AddColorOption(panel, "Accent Color", _loginAccentColor, v => { _loginAccentColor = v; rebuild(); });
            AddSliderOption(panel, "Text Logo Width", 50f, 400f, _loginTextLogoWidth, v => { _loginTextLogoWidth = v; rebuild(); });
            AddSliderOption(panel, "Text Logo Height", 20f, 200f, _loginTextLogoHeight, v => { _loginTextLogoHeight = v; rebuild(); });
            AddSliderOption(panel, "Text Logo X", -200f, 200f, _loginTextLogoX, v => { _loginTextLogoX = v; rebuild(); });
            AddSliderOption(panel, "Text Logo Y", -100f, 200f, _loginTextLogoY, v => { _loginTextLogoY = v; rebuild(); });
            AddSliderOption(panel, "Text Logo Scale", 0.2f, 3f, _loginTextLogoScale, v => { _loginTextLogoScale = v; rebuild(); });
            AddSliderOption(panel, "Logo Width", 50f, 400f, _loginLogoWidth, v => { _loginLogoWidth = v; rebuild(); });
            AddSliderOption(panel, "Logo Height", 20f, 200f, _loginLogoHeight, v => { _loginLogoHeight = v; rebuild(); });
            AddSliderOption(panel, "Logo X", -200f, 200f, _loginLogoX, v => { _loginLogoX = v; rebuild(); });
            AddSliderOption(panel, "Logo Y", -100f, 200f, _loginLogoY, v => { _loginLogoY = v; rebuild(); });
            AddSliderOption(panel, "Logo Scale", 0.2f, 3f, _loginLogoScale, v => { _loginLogoScale = v; rebuild(); });

            var copyBtn = new Button(() => EditorGUIUtility.systemCopyBuffer = GetLoginPanelSettings());
            copyBtn.text = "Copy Settings";
            copyBtn.style.marginTop = 10;
            copyBtn.style.height = 24;
            panel.Add(copyBtn);

            return panel;
        }

        private void ShowLoadingScreen(VisualElement root, bool skipVerify = false)
        {
            root.Clear();
            if (_styleSheet != null) root.styleSheets.Add(_styleSheet);
            
            root.style.flexGrow = 1;
            root.style.backgroundColor = new Color(0.094f, 0.078f, 0.145f, 1f);
            root.style.flexDirection = FlexDirection.Column;
            root.style.alignItems = Align.Center;
            root.style.justifyContent = Justify.Center;
            
            var card = new VisualElement();
            card.style.width = 340;
            card.style.paddingLeft = 32;
            card.style.paddingRight = 32;
            card.style.paddingTop = 32;
            card.style.paddingBottom = 32;
            card.style.backgroundColor = new Color(0.12f, 0.11f, 0.18f, 1f);
            card.style.borderTopLeftRadius = 12;
            card.style.borderTopRightRadius = 12;
            card.style.borderBottomLeftRadius = 12;
            card.style.borderBottomRightRadius = 12;
            card.style.alignItems = Align.Center;
            root.Add(card);
            
            // Status label
            var statusLabel = new Label("Verifying account...");
            statusLabel.style.color = new Color(1f, 1f, 1f, 0.7f);
            statusLabel.style.fontSize = 13;
            statusLabel.style.marginBottom = 16;
            statusLabel.style.unityTextAlign = TextAnchor.MiddleCenter;
            if (_newakeFont != null) statusLabel.style.unityFontDefinition = FontDefinition.FromFont(_newakeFont);
            card.Add(statusLabel);
            
            // Progress bar background
            var progressBg = new VisualElement();
            progressBg.style.width = Length.Percent(100);
            progressBg.style.height = 4;
            progressBg.style.backgroundColor = new Color(1f, 1f, 1f, 0.1f);
            progressBg.style.borderTopLeftRadius = 2;
            progressBg.style.borderTopRightRadius = 2;
            progressBg.style.borderBottomLeftRadius = 2;
            progressBg.style.borderBottomRightRadius = 2;
            card.Add(progressBg);
            
            // Progress bar fill
            var progressFill = new VisualElement();
            progressFill.style.height = Length.Percent(100);
            progressFill.style.width = Length.Percent(10);
            progressFill.style.backgroundColor = _loginAccentColor;
            progressFill.style.borderTopLeftRadius = 2;
            progressFill.style.borderTopRightRadius = 2;
            progressFill.style.borderBottomLeftRadius = 2;
            progressFill.style.borderBottomRightRadius = 2;
            progressFill.style.transitionProperty = new List<StylePropertyName> { new StylePropertyName("width") };
            progressFill.style.transitionDuration = new List<TimeValue> { new TimeValue(300, TimeUnit.Millisecond) };
            progressBg.Add(progressFill);
            
            // Email display
            var emailLabel = new Label(SyntyLoginManager.Email);
            emailLabel.style.color = new Color(1f, 1f, 1f, 0.3f);
            emailLabel.style.fontSize = 10;
            emailLabel.style.marginTop = 16;
            emailLabel.style.unityTextAlign = TextAnchor.MiddleCenter;
            card.Add(emailLabel);
            
            // Shared catalog + icons loading steps
            System.Action loadCatalogAndBuild = () =>
            {
                if (!this) return;
                
                statusLabel.text = "Loading catalog...";
                progressFill.style.width = Length.Percent(40);
                
                SyntyCatalogBridge.LoadCatalog((packs) =>
                {
                    if (!this) return;
                    
                    // If catalog failed (empty), show error with retry
                    if (packs == null || packs.Count == 0)
                    {
                        statusLabel.text = "Unable to load catalog. Service may be temporarily unavailable.";
                        statusLabel.style.color = new Color(1f, 0.4f, 0.4f, 0.9f);
                        progressFill.style.width = Length.Percent(0);
                        progressFill.style.backgroundColor = new Color(1f, 0.3f, 0.3f, 1f);
                        
                        var retryBtn = new Button(() =>
                        {
                            if (!this) return;
                            var r = rootVisualElement;
                            r.Clear();
                            if (_styleSheet != null) r.styleSheets.Add(_styleSheet);
                            ShowLoadingScreen(r, skipVerify: true);
                        });
                        retryBtn.text = "Retry";
                        retryBtn.style.width = 120;
                        retryBtn.style.height = 32;
                        retryBtn.style.marginTop = 16;
                        retryBtn.style.backgroundColor = _accentColor;
                        retryBtn.style.color = Color.white;
                        retryBtn.style.fontSize = 13;
                        retryBtn.style.unityFontStyleAndWeight = FontStyle.Bold;
                        retryBtn.style.borderTopWidth = 0;
                        retryBtn.style.borderBottomWidth = 0;
                        retryBtn.style.borderLeftWidth = 0;
                        retryBtn.style.borderRightWidth = 0;
                        retryBtn.style.borderTopLeftRadius = 6;
                        retryBtn.style.borderTopRightRadius = 6;
                        retryBtn.style.borderBottomLeftRadius = 6;
                        retryBtn.style.borderBottomRightRadius = 6;
                        if (_titleFont != null) retryBtn.style.unityFontDefinition = FontDefinition.FromFont(_titleFont);
                        card.Add(retryBtn);
                        return;
                    }
                    
                    statusLabel.text = "Loading asset icons...";
                    progressFill.style.width = Length.Percent(60);
                    
                    SyntyCatalogBridge.EnsureIcons(packs,
                        onProgress: (current, total) =>
                        {
                            if (!this) return;
                            float pct = 60f + (float)current / Mathf.Max(total, 1) * 35f;
                            progressFill.style.width = Length.Percent(pct);
                            statusLabel.text = $"Loading asset icons ({current}/{total})...";
                        },
                        onComplete: () =>
                        {
                            if (!this) return;
                            progressFill.style.width = Length.Percent(100);
                            statusLabel.text = "Ready!";
                            
                            EditorApplication.delayCall += () =>
                            {
                                if (!this) return;
                                var r = rootVisualElement;
                                r.Clear();
                                if (_styleSheet != null) r.styleSheets.Add(_styleSheet);
                                OnLoginCompleted();
                                BuildUI(r);
                            };
                        }
                    );
                });
            };
            
            if (skipVerify)
            {
                // Session already verified — go straight to catalog
                statusLabel.text = "Loading catalog...";
                progressFill.style.width = Length.Percent(30);
                loadCatalogAndBuild();
            }
            else
            {
                // Run verify and catalog fetch in parallel
                statusLabel.text = "Loading...";
                progressFill.style.width = Length.Percent(10);
                Repaint();
                
                bool verifyDone = false;
                bool verifySuccess = false;
                bool catalogDone = false;
                List<AssetPackData> catalogPacks = null;
                
                System.Action checkBothComplete = () =>
                {
                    if (!verifyDone || !catalogDone) return;
                    if (!this) return;
                    
                    if (!verifySuccess)
                    {
                        // Verify failed — show login
                        var r = rootVisualElement;
                        r.Clear();
                        ShowLoginScreen(r);
                        return;
                    }
                    
                    if (catalogPacks == null || catalogPacks.Count == 0)
                    {
                        // Catalog failed — show error
                        statusLabel.text = "Unable to load catalog. Service may be temporarily unavailable.";
                        statusLabel.style.color = new Color(1f, 0.4f, 0.4f, 0.9f);
                        progressFill.style.width = Length.Percent(0);
                        progressFill.style.backgroundColor = new Color(1f, 0.3f, 0.3f, 1f);
                        
                        var retryBtn = new Button(() =>
                        {
                            if (!this) return;
                            var r = rootVisualElement;
                            r.Clear();
                            if (_styleSheet != null) r.styleSheets.Add(_styleSheet);
                            ShowLoadingScreen(r, skipVerify: true);
                        });
                        retryBtn.text = "Retry";
                        retryBtn.style.width = 120;
                        retryBtn.style.height = 32;
                        retryBtn.style.marginTop = 16;
                        retryBtn.style.backgroundColor = _accentColor;
                        retryBtn.style.color = Color.white;
                        retryBtn.style.fontSize = 13;
                        retryBtn.style.unityFontStyleAndWeight = FontStyle.Bold;
                        retryBtn.style.borderTopWidth = 0;
                        retryBtn.style.borderBottomWidth = 0;
                        retryBtn.style.borderLeftWidth = 0;
                        retryBtn.style.borderRightWidth = 0;
                        retryBtn.style.borderTopLeftRadius = 6;
                        retryBtn.style.borderTopRightRadius = 6;
                        retryBtn.style.borderBottomLeftRadius = 6;
                        retryBtn.style.borderBottomRightRadius = 6;
                        if (_titleFont != null) retryBtn.style.unityFontDefinition = FontDefinition.FromFont(_titleFont);
                        card.Add(retryBtn);
                        return;
                    }
                    
                    // Both succeeded — load icons and build
                    statusLabel.text = "Loading asset icons...";
                    progressFill.style.width = Length.Percent(60);
                    
                    SyntyCatalogBridge.EnsureIcons(catalogPacks,
                        onProgress: (current, total) =>
                        {
                            if (!this) return;
                            float pct = 60f + (float)current / Mathf.Max(total, 1) * 35f;
                            progressFill.style.width = Length.Percent(pct);
                            statusLabel.text = $"Loading asset icons ({current}/{total})...";
                        },
                        onComplete: () =>
                        {
                            if (!this) return;
                            progressFill.style.width = Length.Percent(100);
                            statusLabel.text = "Ready!";
                            
                            EditorApplication.delayCall += () =>
                            {
                                if (!this) return;
                                var r = rootVisualElement;
                                r.Clear();
                                if (_styleSheet != null) r.styleSheets.Add(_styleSheet);
                                OnLoginCompleted();
                                BuildUI(r);
                            };
                        }
                    );
                };
                
                // Start both in parallel
                EditorApplication.delayCall += () =>
                {
                    if (!this) return;
                    
                    // Verify session — skipped on an install/uninstall reload (ownership can't have
                    // changed); the catalog load and completion below still run.
                    if (SessionState.GetBool(SESSION_SKIP_VERIFY, false))
                    {
                        SessionState.SetBool(SESSION_SKIP_VERIFY, false);
                        verifySuccess = true;
                        verifyDone = true;
                        checkBothComplete();
                    }
                    else
                    SyntyStoreHelper.TryRestoreSession(
                        onSuccess: () =>
                        {
                            verifySuccess = true;
                            verifyDone = true;
                            if (!this) return;
                            progressFill.style.width = Length.Percent(30);
                            checkBothComplete();
                        },
                        onNoSession: () =>
                        {
                            verifySuccess = false;
                            verifyDone = true;
                            checkBothComplete();
                        }
                    );
                    
                    // Fetch catalog simultaneously
                    SyntyCatalogBridge.LoadCatalog((packs) =>
                    {
                        catalogPacks = packs;
                        catalogDone = true;
                        if (!this) return;
                        progressFill.style.width = Length.Percent(40);
                        checkBothComplete();
                    });
                };
            }
        }
        
        
        // Centralized post-login init. Called from every code path that authenticates a user
        // (fresh login, fast-path resume from cache, background session verify, parallel
        // verify+catalog). Sets the pass to the user's actual entitlement, identifies them to
        // analytics, tracks the tool-open, and refetches the personalized deals list.
        //
        // Per design decisions: every login defaults the pass filter ON for pass-holders (any
        // prior manual off-toggle is session-scoped), OFF for non-holders. The asset grid's
        // OnAllButtonsCreated handler reads _licenseSyntyPass at the end of its async batch
        // build and applies the pass overlay to the visible buttons.
        // Rebuilds price-bearing UI when the display currency or exchange rates change. Runs
        // on the main thread via delayCall (EnsureRatesAsync completes off the UI tick).
        private void OnCurrencyChangedRebuild()
        {
            EditorApplication.delayCall += () =>
            {
                if (!this) return;
                // Re-render every tracked asset-card price label from its stored USD value, so
                // the prices on the buttons reflect the new currency without rebuilding the
                // grid (which would lose scroll position and selection).
                RefreshAllPriceLabels();
                // Reformat the SyntyPass promo monthly/annual prices into the new currency.
                RefreshPromoPriceStrings();
                // Also refresh the cart/download bar subtitle (totals) and any deal popups.
                try { UpdateDownloadBar(); } catch { }
                Repaint();
            };
        }
        
        // Reformats all tracked price labels (asset-card tooltips, sale strikethrough prices)
        // into the current currency from the USD amount captured when each was created.
        private void RefreshAllPriceLabels()
        {
            // Prune labels whose element left the tree (asset rebuilt) before reformatting.
            var stale = new List<Label>();
            foreach (var kv in _priceLabelUsd)
            {
                var lbl = kv.Key;
                if (lbl == null || lbl.panel == null) { stale.Add(lbl); continue; }
                bool withCode = _priceLabelHasCode.TryGetValue(lbl, out var c) && c;
                lbl.text = SyntyCurrency.Format(kv.Value, withCode);
            }
            foreach (var s in stale) { _priceLabelUsd.Remove(s); _priceLabelHasCode.Remove(s); }
        }
        
        // Formats the SyntyPass promo monthly/annual price strings in the current currency from
        // their USD base values. Updates the live price label (whichever term is selected).
        private void RefreshPromoPriceStrings()
        {
            _promoMonthlyPrice = SyntyCurrency.Format(_promoMonthlyValueUsd);
            _promoAnnualPrice = SyntyCurrency.Format(_promoAnnualValueUsd);
            if (_promoPriceLabelRef != null)
                _promoPriceLabelRef.text = _promoShowingAnnual ? _promoAnnualPrice : _promoMonthlyPrice;
        }
        
        // Asks the worker whether this account (by email hash) has opted out of analytics, and sets
        // SyntyAnalytics.AccountOptedOut so tracking stays off for opted-out accounts on any install.
        private void CheckAnalyticsOptOut()
        {
            string hash = SyntyAnalytics.EmailHash;
            if (string.IsNullOrEmpty(hash)) return;
            string json = "{\"emailHash\":\"" + hash + "\"}";
            var req = new UnityEngine.Networking.UnityWebRequest(
                "https://synty-downloads.syntystore.workers.dev/analytics/optout-status", "POST");
            req.uploadHandler = new UnityEngine.Networking.UploadHandlerRaw(
                System.Text.Encoding.UTF8.GetBytes(json));
            req.downloadHandler = new UnityEngine.Networking.DownloadHandlerBuffer();
            req.SetRequestHeader("Content-Type", "application/json");
            var op = req.SendWebRequest();
            op.completed += _ =>
            {
                try
                {
                    if (req.result == UnityEngine.Networking.UnityWebRequest.Result.Success)
                    {
                        var txt = req.downloadHandler.text ?? "";
                        // Lightweight parse: look for "optedOut":true
                        bool opted = txt.Replace(" ", "").Contains("\"optedOut\":true");
                        SyntyAnalytics.AccountOptedOut = opted;
                    }
                }
                catch { }
                finally { try { req.Dispose(); } catch { } }
            };
        }

        private void OnLoginCompleted()
        {
            if (!this || !SyntyLoginManager.IsLoggedIn) return;
            // Main UI is up — restore the (taller) main-view min height that the login screen lowered.
            var ms = minSize; if (ms.y < _minHeight) { ms.y = _minHeight; minSize = ms; }
            // Apply debug-panel visibility chosen on the login screen, once the main UI is up.
            if (IsDebugUnlocked() && EditorPrefs.GetBool(PREFS_DEBUG_PANEL_VISIBLE, false))
            {
                rootVisualElement.schedule.Execute(() =>
                {
                    if (_optionsPanel != null && !_optionsPanelVisible) OnDebugOptionsButtonClicked();
                }).StartingIn(150);
            }
            
            // Currency: subscribe once so any currency/rate change rebuilds visible prices.
            // Fetch live rates (cached) and auto-detect a default currency from the account's
            // country (unless the user already picked one manually).
            SyntyCurrency.OnCurrencyChanged -= OnCurrencyChangedRebuild;
            SyntyCurrency.OnCurrencyChanged += OnCurrencyChangedRebuild;
            SyntyCurrency.AutoSelectFromCountry(SyntyStoreService.Instance?.CountryCode);
            _ = SyntyCurrency.EnsureRatesAsync();
            
            // Seed the order-count baseline now (at login) rather than on the first click, so a
            // purchase made AFTER the tool is open is detected as an increase. Without this the
            // first click would set the baseline to the already-incremented count and miss it.
            _ = SeedOrderCountBaselineAsync();
            
            // Pass filter handling runs only once per editor session on a genuine fresh open, NOT
            // on a domain-reload re-init (installing an asset imports it and recompiles scripts,
            // which re-runs OnLoginCompleted; without this guard the auto-on would re-fire and flip
            // the filter on after every install/uninstall). The "done" marker lives in SessionState,
            // which survives a domain reload but clears on a full editor restart — so it runs again
            // on the next real launch even if the window was left docked/open.
            if (!SessionState.GetBool(SESSION_AUTOON_DONE, false))
            {
                SessionState.SetBool(SESSION_AUTOON_DONE, true);
                // Pass filter always starts OFF on login. For pass-holders it is then auto-
                // enabled a moment after the tool finishes opening (see ScheduleSyntyPassAutoOn),
                // which gives a subtle "settles on" effect and avoids any saved-pref conflict.
                // Do NOT force the pass filter off here. LoadFilterStates already set it from the
                // persisted pass state (on for pass-holders), so the grid builds with the full library
                // straight away. The auto-on ticker below remains as a safety for a first-ever login
                // where HasSyntyPass isn't cached yet (it fires once the verify confirms the pass).
                _syntyPassAutoOnCancelled = false; // fresh open: allow auto-on (until a download starts)
                // Always schedule; the ticker waits until the grid is built AND pass ownership is
                // confirmed before firing. On a cached open, HasSyntyPass may not be verified yet at
                // this instant, so gating the *scheduling* on it here would drop the auto-on for a
                // genuine pass-holder. Let the ticker make the ownership call instead.
                ScheduleSyntyPassAutoOn();
            }
            
            if (!string.IsNullOrEmpty(SyntyStoreHelper.LoggedInEmail))
                SyntyAnalytics.SetUserEmail(SyntyStoreHelper.LoggedInEmail);
            // Check the server opt-out list for this account before tracking. If opted out,
            // AccountOptedOut gates all tracking (including the tool-open below). The check is async;
            // tracking that fires before it returns is still gated by the local pref, and the open
            // event re-fires rarely enough that missing one opt-out-respecting open is acceptable.
            CheckAnalyticsOptOut();
            SyntyAnalytics.TrackToolOpen(true, _licenseSyntyPass,
                SyntyStoreService.Instance.OwnedProductHandles?.Count ?? 0,
                _assetItems?.Count(i => i.btnVisual?.ClassListContains("asset-installed") == true) ?? 0);
            
            // Refetch personalized deals — async; render guard handles arrival before
            // _dealsContainer exists, BuildUI re-renders at its end as a safety net.
            FetchExclusiveDeals();
            
            // Apply the server-selected banner (general / pass / new-release). Deferred so the
            // banner UI exists; ApplyServerBanner is also called at the end of BuildUI.
            EditorApplication.delayCall += () => { if (this) ApplyServerBanner(); };
        }
        
        // Forces a fresh verify so the worker returns the current banner config, then applies
        // it. Called on tool open so banner changes show without needing a manual refresh.
        private async System.Threading.Tasks.Task RefreshBannerOnOpenAsync()
        {
            try
            {
                bool ok = await SyntyStoreService.Instance.VerifyRestoredSessionAsync(true);
                if (!this || !ok) return;
                ApplyServerBanner();
            }
            catch { /* banner refresh is best-effort */ }
        }
        
        // Applies the banner the server selected for this customer. Each field overrides the
        // tool's default only when the server provided a non-empty value, so partially-filled
        // banners fall back to the built-in look. Safe to call before the banner UI exists.
        private void ApplyServerBanner()
        {
            var cfg = SyntyStoreService.Instance?.Banner;
            if (cfg == null) return;
            
            // Banner click target (empty = fall back to the default store link).
            _bannerLinkUrl = string.IsNullOrEmpty(cfg.link) ? null : cfg.link;
            
            // Tint — recolors the banner art (left/center/right images).
            if (!string.IsNullOrEmpty(cfg.tint))
            {
                _bannerTintColor = ParseHexColorOrDefault(cfg.tint, _bannerTintColor);
                ApplyBannerTintToElements();
            }
            
            // Line 1 (title) text + color
            if (!string.IsNullOrEmpty(cfg.line1))
            {
                _bannerTitleText = cfg.line1;
                if (_bannerTitle != null) _bannerTitle.text = cfg.line1;
            }
            if (!string.IsNullOrEmpty(cfg.line1Color))
            {
                _bannerTextColor = ParseHexColorOrDefault(cfg.line1Color, _bannerTextColor);
                if (_bannerTitle != null) _bannerTitle.style.color = _bannerTextColor;
            }
            
            // Line 2 (subtitle) text + color
            if (!string.IsNullOrEmpty(cfg.line2))
            {
                _bannerSubtitleText = cfg.line2;
                if (_bannerSubtitle != null) _bannerSubtitle.text = cfg.line2;
            }
            if (!string.IsNullOrEmpty(cfg.line2Color))
            {
                _shopNowTextColor = ParseHexColorOrDefault(cfg.line2Color, _shopNowTextColor);
                if (_bannerSubtitle != null) _bannerSubtitle.style.color = _shopNowTextColor;
            }
            
            // Icon color
            if (!string.IsNullOrEmpty(cfg.iconColor))
            {
                _shopNowIconColor = ParseHexColorOrDefault(cfg.iconColor, _shopNowIconColor);
                if (_shopNowIcon != null) _shopNowIcon.style.unityBackgroundImageTintColor = _shopNowIconColor;
            }
            
            // Numeric position / size overrides (parsed; empty or invalid = keep tool default).
            float num;
            if (TryParseInv(cfg.titleX, out num))
            {
                _bannerTitleX = num;
                if (_bannerTitle != null) _bannerTitle.style.translate = new Translate(num, 0);
            }
            if (TryParseInv(cfg.titleY, out num))
            {
                _bannerTitleY = num;
                if (_bannerTitle != null) _bannerTitle.style.top = num;
            }
            if (TryParseInv(cfg.titleFontSize, out num))
            {
                _bannerTitleFontSize = num;
                if (_bannerTitle != null) _bannerTitle.style.fontSize = num;
            }
            if (TryParseInv(cfg.line2X, out num))
            {
                _shopNowXOffset = num;
                if (_shopNowContainer != null) _shopNowContainer.style.marginLeft = num;
            }
            
            // Countdown timer: when enabled with a valid future end time, replace the shop-now
            // pill with the timer. Otherwise show the pill.
            bool timerShown = false;
            if (cfg.timerEnabled && !string.IsNullOrEmpty(cfg.timerEndTime))
            {
                System.DateTime endUtc;
                if (System.DateTime.TryParse(cfg.timerEndTime, null,
                        System.Globalization.DateTimeStyles.AdjustToUniversal | System.Globalization.DateTimeStyles.AssumeUniversal,
                        out endUtc)
                    && (endUtc - System.DateTime.UtcNow).TotalSeconds > 0)
                {
                    timerShown = true;
                    if (_shopNowContainer != null) _shopNowContainer.style.display = DisplayStyle.None;
                    if (_bannerTimer != null)
                    {
                        _bannerTimer.style.display = DisplayStyle.Flex;
                        ApplyBannerTimerStyle(cfg);
                        _bannerTimer.BringToFront();
                        ScheduleBannerCountdown(endUtc);
                    }
                }
            }
            if (!timerShown)
            {
                if (_bannerTimer != null) _bannerTimer.style.display = DisplayStyle.None;
                if (_shopNowContainer != null) _shopNowContainer.style.display = DisplayStyle.Flex;
            }
            
            // Banner image (right overlay) — load from disk cache if we already have this
            // version, otherwise download and cache it. Only re-downloads on a new version.
            if (cfg.hasImage && !string.IsNullOrEmpty(cfg.imageUrl))
            {
                // Remember this banner so it can be pre-applied at build time next open.
                EditorPrefs.SetString(PREF_LAST_BANNER_TYPE, cfg.type ?? "");
                EditorPrefs.SetString(PREF_LAST_BANNER_VERSION, cfg.imageVersion ?? "");
                LoadOrDownloadBannerImage(cfg.type, cfg.imageVersion, cfg.imageUrl);
            }
            else
            {
                // No image for this banner; clear the remembered one so we don't preload a stale
                // image over a banner that shouldn't have one.
                EditorPrefs.SetString(PREF_LAST_BANNER_TYPE, "");
                EditorPrefs.SetString(PREF_LAST_BANNER_VERSION, "");
            }
        }
        
        // Parses a float using invariant culture; returns false for null/empty/invalid.
        private static bool TryParseInv(string s, out float value)
        {
            value = 0f;
            if (string.IsNullOrEmpty(s)) return false;
            return float.TryParse(s, System.Globalization.NumberStyles.Float,
                System.Globalization.CultureInfo.InvariantCulture, out value);
        }
        
        // Applies _bannerTintColor to the banner art itself — the left/center/right image
        // elements — so the tint recolors the actual banner shape rather than painting a flat
        // rectangle behind the (opaque) images. The button background is left transparent.
        private void ApplyBannerTintToElements()
        {
            if (_bannerLeft != null) _bannerLeft.style.unityBackgroundImageTintColor = _bannerTintColor;
            if (_bannerCenter != null) _bannerCenter.style.unityBackgroundImageTintColor = _bannerTintColor;
            if (_bannerRight != null) _bannerRight.style.unityBackgroundImageTintColor = _bannerTintColor;
        }
        
        // Returns the local cache file path for a banner image of the given type + version.
        // Stored in the project's Images/Banner folder (Assets-relative) so it's a managed asset
        // and persists across sessions like the other banner images.
        private string BannerImageCachePath(string type, string version)
        {
            string safeType = string.IsNullOrEmpty(type) ? "banner" : type;
            string safeVer = string.IsNullOrEmpty(version) ? "0" : version;
            // Strip anything path-unsafe from the version token.
            foreach (var c in System.IO.Path.GetInvalidFileNameChars())
                safeVer = safeVer.Replace(c, '_');
            string folder = $"{_imagesPath}/Banner";
            return $"{folder}/{safeType}_{safeVer}.png".Replace("\\", "/");
        }
        
        // Loads the banner image from the on-disk cache if the current version is already cached;
        // otherwise downloads it, applies it, and writes it to the cache. Like asset icons, the
        // network fetch only happens when the version (set when the admin uploads a new image)
        // changes.
        // Keys for remembering the last banner image shown, so it can be pre-applied at build
        // time (before verify) to avoid a pop-in.
        private const string PREF_LAST_BANNER_TYPE = "SyntyPassport_LastBannerType";
        private const string PREF_LAST_BANNER_VERSION = "SyntyPassport_LastBannerVersion";
        
        // Applies the last-known banner image straight from disk during build, before the server
        // verify completes. No network. If nothing is cached, the default overlay stays until the
        // server banner applies.
        private void PreloadCachedBannerImage()
        {
            try
            {
                if (string.IsNullOrEmpty(_imagesPath)) return;
                string type = EditorPrefs.GetString(PREF_LAST_BANNER_TYPE, "");
                string version = EditorPrefs.GetString(PREF_LAST_BANNER_VERSION, "");
                if (string.IsNullOrEmpty(type)) return;
                string cachePath = BannerImageCachePath(type, version);
                if (!System.IO.File.Exists(cachePath)) return;
                byte[] bytes = System.IO.File.ReadAllBytes(cachePath);
                var tex = new Texture2D(2, 2);
                if (tex.LoadImage(bytes))
                {
                    tex.hideFlags = HideFlags.HideAndDontSave;
                    ApplyBannerImageTexture(tex);
                }
            }
            catch { /* best-effort preload */ }
        }
        
        private void LoadOrDownloadBannerImage(string type, string version, string imageUrl)
        {
            try
            {
                if (!string.IsNullOrEmpty(_imagesPath))
                {
                    string cachePath = BannerImageCachePath(type, version);
                    if (System.IO.File.Exists(cachePath))
                    {
                        // Cached: load from disk, no network.
                        byte[] bytes = System.IO.File.ReadAllBytes(cachePath);
                        var tex = new Texture2D(2, 2);
                        if (tex.LoadImage(bytes))
                        {
                            tex.hideFlags = HideFlags.HideAndDontSave;
                            ApplyBannerImageTexture(tex);
                            return;
                        }
                    }
                }
            }
            catch { /* fall through to download */ }
            DownloadBannerImage(imageUrl, type, version);
        }
        
        // Assigns a loaded texture to the banner overlay element.
        private void ApplyBannerImageTexture(Texture2D tex)
        {
            if (tex == null) return;
            var right = _mainFrame?.Q<VisualElement>("banner-overlay-right");
            if (right != null && right.panel != null)
            {
                right.style.backgroundImage = new StyleBackground(tex);
                right.style.unityBackgroundImageTintColor = Color.white; // image shown natural
            }
        }
        
        // Downloads a banner image from the server, applies it, and writes it to the on-disk
        // cache (keyed by type + version) so future opens load from disk. Tracks the request so
        // it can be aborted before a domain reload (avoids the "invalid GC handle from a previous
        // domain" warning), and uses op.completed instead of await so no continuation spans a
        // reload.
        private void DownloadBannerImage(string imageUrl, string type = null, string version = null)
        {
            if (string.IsNullOrEmpty(imageUrl)) return;
            // Cancel any previous in-flight banner image fetch.
            if (_bannerImageRequest != null)
            {
                try { _bannerImageRequest.Abort(); _bannerImageRequest.Dispose(); } catch { }
                _bannerImageRequest = null;
            }
            var req = UnityEngine.Networking.UnityWebRequestTexture.GetTexture(imageUrl);
            _bannerImageRequest = req;
            var op = req.SendWebRequest();
            op.completed += _ =>
            {
                try
                {
                    if (_reloadingDomain || !this) return;
                    if (req.result != UnityEngine.Networking.UnityWebRequest.Result.Success) return;
                    var tex = UnityEngine.Networking.DownloadHandlerTexture.GetContent(req);
                    if (tex == null) return;
                    tex.hideFlags = HideFlags.HideAndDontSave;
                    ApplyBannerImageTexture(tex);
                    // Write to the on-disk cache (and prune older versions for this type).
                    SaveBannerImageToCache(req.downloadHandler.data, type, version);
                }
                catch { /* banner image is best-effort */ }
                finally
                {
                    try { req.Dispose(); } catch { }
                    if (_bannerImageRequest == req) _bannerImageRequest = null;
                }
            };
        }
        
        // Writes downloaded banner image bytes to the versioned cache file in the project's
        // Images/Banner folder, removes older cached versions for the same banner type, and
        // imports it so it's a managed asset.
        private void SaveBannerImageToCache(byte[] data, string type, string version)
        {
            if (data == null || data.Length == 0 || string.IsNullOrEmpty(type)) return;
            if (string.IsNullOrEmpty(_imagesPath)) return;
            try
            {
                string cachePath = BannerImageCachePath(type, version);
                string folder = $"{_imagesPath}/Banner".Replace("\\", "/");
                if (!System.IO.Directory.Exists(folder))
                    System.IO.Directory.CreateDirectory(folder);
                // Prune older versions for this type (both the .png and its .meta).
                foreach (var f in System.IO.Directory.GetFiles(folder, $"{type}_*.png"))
                {
                    string norm = f.Replace("\\", "/");
                    if (!string.Equals(norm, cachePath, System.StringComparison.OrdinalIgnoreCase))
                    {
                        try { AssetDatabase.DeleteAsset(norm); } catch { }
                        try { if (System.IO.File.Exists(norm)) System.IO.File.Delete(norm); } catch { }
                    }
                }
                System.IO.File.WriteAllBytes(cachePath, data);
                // Import so it's a managed project asset (loadable next session).
                AssetDatabase.ImportAsset(cachePath, ImportAssetOptions.ForceSynchronousImport);
            }
            catch { /* cache write is best-effort */ }
        }
        
        // for pass-holders. Runs only if the user hasn't already toggled the filter in the
        // meantime, and only if they still have the pass and are still logged in. The small
        // delay lets the grid finish building so the switch-on is visible as a transition.
        private bool _syntyPassAutoOnPending = false;
        private bool _syntyPassAutoOnCancelled = false; // set when the user starts a download before auto-on fires
        // SessionState key marking that the Synty Pass auto-on has already been handled this editor
        // session. SessionState survives a domain reload (so the auto-on doesn't re-fire after
        // installing an asset recompiles scripts) but is cleared on a full editor restart (so it
        // DOES run again on the next genuine launch). A [SerializeField] bool was previously used
        // here, but it over-persisted: a docked/open window is serialized at editor quit and
        // restored on the next launch with the flag still true, which suppressed the auto-on on
        // what the user experiences as a fresh open.
        private const string SESSION_AUTOON_DONE = "SyntyPassport_AutoOnDone";
        // Current pass-filter on/off state, persisted for the SESSION only (survives a domain reload
        // from an install, clears on a full editor restart). Lets the post-install rebuild restore the
        // pass view immediately instead of repainting the off-state first (the install flicker).
        private const string SESSION_PASS_FILTER = "SyntyImporter_PassFilterOn_v2"; // _v2: bypasses a stale false written by an earlier build in the same editor session
        // Whether the signed-in user holds the Synty Pass, persisted for the SESSION (survives domain
        // reload; not gated by "Remember Me" the way the EditorPrefs copy is). Lets a reload know at
        // build time that the full library should show, without waiting for the backend re-verify.
        private const string SESSION_HAS_PASS = "SyntyImporter_HasPass";
        // Set right before an install/uninstall (which triggers a domain reload). Ownership can't
        // change from installing/uninstalling something you already own, so the restore flow skips
        // its ~5s backend ownership re-verify on that reload and uses the cached state.
        private const string SESSION_SKIP_VERIFY = "SyntyImporter_SkipVerifyReload";
        // Set only when the user explicitly turns the pass filter OFF, so a pass-holder otherwise
        // defaults to their full library at build (and we don't fight that with the settle veil).
        private const string SESSION_PASS_TOGGLED_OFF = "SyntyImporter_PassToggledOff";
        private static void MarkOwnershipUnchangedReload() { SessionState.SetBool(SESSION_SKIP_VERIFY, true); }
        // Original multi-install batch size, stored in SessionState so the "X of Y" counter survives
        // the domain reloads scripted installs trigger (window fields can reset on reload).
        private const string SESSION_BATCH_TOTAL = "SyntyImporter_BatchTotal";
        
        // Cancels the pending Synty Pass auto-on. Called when the user starts a download/install
        // so the filter doesn't flip on by itself once the install finishes.
        private void CancelSyntyPassAutoOn()
        {
            _syntyPassAutoOnCancelled = true;
            _syntyPassAutoOnPending = false;
        }
        
        private void ScheduleSyntyPassAutoOn()
        {
            if (_syntyPassAutoOnPending) return;
            if (_syntyPassAutoOnCancelled) return;
            _syntyPassAutoOnPending = true;
            double fireAt = EditorApplication.timeSinceStartup + 0.6; // ~0.6s after login
            double giveUpAt = EditorApplication.timeSinceStartup + 10.0; // safety: stop trying after 10s
            EditorApplication.CallbackFunction tick = null;
            tick = () =>
            {
                if (_reloadingDomain || !this) { UnregisterAnonTicker(tick); return; }
                // Safety timeout: if the grid never finishes building, stop polling.
                if (EditorApplication.timeSinceStartup > giveUpAt)
                {
                    UnregisterAnonTicker(tick);
                    _syntyPassAutoOnPending = false;
                    return;
                }
                if (EditorApplication.timeSinceStartup < fireAt) return; // wait for the delay
                // Bail if the user started an install/uninstall in the meantime (we don't want
                // the filter flipping on by itself after install/uninstall finishes).
                if (_syntyPassAutoOnCancelled) { UnregisterAnonTicker(tick); _syntyPassAutoOnPending = false; return; }
                // Hard deadline: only ever fire within the brief window after the tool opened. If
                // the grid isn't ready by then, GIVE UP rather than firing late (which is what
                // caused the filter to turn on after a later install/uninstall rebuilt the grid).
                if (EditorApplication.timeSinceStartup > giveUpAt)
                {
                    UnregisterAnonTicker(tick);
                    _syntyPassAutoOnPending = false;
                    _syntyPassAutoOnCancelled = true; // never fire for the rest of this session
                    return;
                }
                // Also wait until the grid has actually been built, so the toggle has buttons
                // and items to act on (login can complete before the asset list exists).
                if (_assetItems == null || _assetItems.Count == 0 || _syntyPassBtn == null) return;
                // Logged out in the meantime → nothing to do, stop.
                if (!SyntyLoginManager.IsLoggedIn) { UnregisterAnonTicker(tick); _syntyPassAutoOnPending = false; return; }
                // User already turned it on → leave it alone, stop.
                if (_licenseSyntyPass) { UnregisterAnonTicker(tick); _syntyPassAutoOnPending = false; return; }
                // Wait for pass ownership to be confirmed. On a cached open the background verify can
                // land AFTER the grid is built, so keep ticking (up to giveUpAt) rather than bailing
                // permanently the first time HasSyntyPass reads false — that permanent bail was why a
                // genuine pass-holder's filter never turned on.
                if (!SyntyLoginManager.HasSyntyPass) return;
                UnregisterAnonTicker(tick);
                _syntyPassAutoOnPending = false;
                ApplySyntyPassFilterOn();
            };
            RegisterAnonTicker(tick);
        }
        
        // Turns the Synty Pass filter ON programmatically, running the same updates the
        // filter button's click performs for pass-holders so the view matches a manual toggle.
        // Fades out and removes the grid settle veil (see AddAssetSection), fading the grid cards
        // back in.
        private void RevealGridVeil()
        {
            _gridSettling = false;
            UpdateCollectionCounts(); // final authoritative count now that the view has settled
            if (_assetScrollView != null) _assetScrollView.style.opacity = 1f;
            if (_gridSettleVeil == null) return;
            _gridSettleVeil.style.opacity = 0f;
            _gridSettleVeil.schedule.Execute(() =>
            {
                if (_gridSettleVeil != null) _gridSettleVeil.style.display = DisplayStyle.None;
            }).StartingIn(220);
        }

        private void ApplySyntyPassFilterOn()
        {
            _licenseSyntyPass = true;
            SessionState.SetBool(SESSION_PASS_FILTER, true); // survive domain reload so post-install rebuild keeps the pass view
            UpdateDealsVisibility();
            if (_assetItems != null)
            {
                foreach (var item in _assetItems)
                    if (item.getSelected()) item.setSelected(false);
            }
            UpdateDownloadBar();
            if (_syntyPassBtn != null) UpdateSyntyPassButtonState(_syntyPassBtn, true);
            if (_syntyPassGlowBar != null) _syntyPassGlowBar.style.opacity = 1f;
            ApplySyntyPassOwnership(true);
            SaveFilterStates();
            UpdateSaleBadgeVisibility();
        }
        
        // Centralized logout. Clears the deal list (so the next user doesn't see the previous
        // customer's offers), then hands off to SyntyLoginManager.Logout(). The caller is
        // responsible for routing back to the login screen.
        private void OnLogoutInitiated()
        {
            _activeDeals?.Clear();
            if (_dealsContainer != null) RenderExclusiveDeals();
            SyntyLoginManager.Logout();
            _licenseSyntyPass = false;
            EditorPrefs.SetBool(PREFS_SYNTY_PASS, false);
            SessionState.SetBool(SESSION_PASS_FILTER, false);
            SessionState.SetBool(SESSION_AUTOON_DONE, false); // a fresh login should run the auto-on again
            StopSaleBadgePulse();
        }
        
        private void BuildUI(VisualElement root)
        {
            // A pass-holder defaults to their full library at build (pass filter on) unless they
            // explicitly turned it off this session. Set here — the last point before the grid builds
            // and where the pass status is reliably known — so it wins over the restore-flow paths
            // that can leave it off, and so the grid builds at 155 with no later flip/veil wait.
            if (SyntyLoginManager.HasSyntyPass && !SessionState.GetBool(SESSION_PASS_TOGGLED_OFF, false))
                _licenseSyntyPass = true;
            // Update SyntyPass promo prices from catalog if available
            var cachedCatalog = SyntyStoreService.Instance.GetCachedCatalog();
            if (cachedCatalog?.syntyPass != null)
            {
                var sp = cachedCatalog.syntyPass;
                if (!string.IsNullOrEmpty(sp.monthly))
                {
                    float monthlyVal;
                    if (float.TryParse(sp.monthly, System.Globalization.NumberStyles.Float, 
                        System.Globalization.CultureInfo.InvariantCulture, out monthlyVal))
                    {
                        _promoMonthlyValueUsd = monthlyVal;
                    }
                }
                if (!string.IsNullOrEmpty(sp.annual))
                {
                    float annualVal;
                    if (float.TryParse(sp.annual, System.Globalization.NumberStyles.Float, 
                        System.Globalization.CultureInfo.InvariantCulture, out annualVal))
                    {
                        _promoAnnualValueUsd = annualVal;
                    }
                }
            }
            // Format the promo price strings in the user's selected currency.
            RefreshPromoPriceStrings();
            
            root.style.flexGrow = 1;
            root.style.backgroundColor = new Color(0.094f, 0.078f, 0.145f, 1f);
            root.style.flexDirection = FlexDirection.Row;
            root.style.alignItems = Align.Stretch;
            root.style.justifyContent = Justify.FlexStart;
            
            // Main tool container (left side)
            _toolContainer = new VisualElement();
            _toolContainer.name = "tool-container";
            _toolContainer.style.flexGrow = 1;
            _toolContainer.style.minWidth = _toolWidth;
            root.Add(_toolContainer);
            
            // Tooltip overlay — sits above everything so tooltips render on top of all buttons
            _tooltipOverlay = new VisualElement();
            _tooltipOverlay.name = "tooltip-overlay";
            _tooltipOverlay.pickingMode = PickingMode.Ignore;
            _tooltipOverlay.style.position = Position.Absolute;
            _tooltipOverlay.style.top = 0;
            _tooltipOverlay.style.left = 0;
            _tooltipOverlay.style.right = 0;
            _tooltipOverlay.style.bottom = 0;
            _tooltipOverlay.style.overflow = Overflow.Visible;
            // Download active layer — on root so it sits above ALL tool content including dim overlays
            // Active downloading buttons are temporarily moved here during download
            _downloadActiveLayer = new VisualElement();
            _downloadActiveLayer.name = "download-active-layer";
            _downloadActiveLayer.pickingMode = PickingMode.Ignore;
            _downloadActiveLayer.style.position = Position.Absolute;
            _downloadActiveLayer.style.top = 0;
            _downloadActiveLayer.style.left = 0;
            _downloadActiveLayer.style.right = 0;
            _downloadActiveLayer.style.bottom = 0;
            _downloadActiveLayer.style.overflow = Overflow.Visible;
            root.Add(_downloadActiveLayer);
            
            root.Add(_tooltipOverlay);
            
            _mainFrame = new VisualElement();
            _mainFrame.name = "main-frame";
            _mainFrame.AddToClassList("main-frame");
            _mainFrame.style.backgroundColor = _backgroundColor;
            
            _toolContainer.Add(_mainFrame);
            
            AddFrameBorder(_mainFrame);
            AddBackgroundGradient(_mainFrame);
            AddLogo(_mainFrame);
            
            var content = new VisualElement();
            content.name = "content";
            content.AddToClassList("content");
            content.style.overflow = Overflow.Visible;
            _mainFrame.Add(content);
            // Move the bottom gradient so it renders behind the asset buttons as a fixed glow under
            // the cards. It goes into the asset section just before the scroll view: the scroll's
            // background is transparent, so the gradient shows through the gaps between cards, and it
            // stays put (doesn't scroll with the grid). Absolute + pickingMode Ignore = no layout or
            // click impact.
            if (_bottomGradient != null && _assetScrollView != null && _assetScrollView.parent != null)
            {
                var section = _assetScrollView.parent;
                _bottomGradient.RemoveFromHierarchy();
                int idx = section.IndexOf(_assetScrollView);
                section.Insert(Mathf.Max(0, idx), _bottomGradient);
            }
            
            var mainLayout = new VisualElement();
            mainLayout.name = "main-layout";
            mainLayout.AddToClassList("main-layout");
            mainLayout.style.overflow = Overflow.Visible;
            content.Add(mainLayout);
            
            AddFilterSection(mainLayout);
            
            var rightPanel = new VisualElement();
            rightPanel.name = "right-panel";
            rightPanel.AddToClassList("right-panel");
            mainLayout.Add(rightPanel);
            
            AddCollectionSection(rightPanel);
            AddAssetOptionsSection(rightPanel);
            
            AddAssetSection(rightPanel);
            // Bars/labels now exist — reflect any selection restored during AddAssetSection
            // (UpdateDownloadBar was skipped earlier because the bars weren't built yet).
            UpdateDownloadBar();
            
            AddBanner(_mainFrame);
            AddNotificationButton(_mainFrame);
            AddProfileButton(_mainFrame);
            BuildProfilePanel(_mainFrame);
            
            // Single tool waiting overlay — on _mainFrame as last child, covers everything
            // Active downloading button is promoted to _downloadActiveLayer on root (above this)
            _toolWaitingOverlay = new VisualElement();
            _toolWaitingOverlay.name = "tool-waiting-overlay";
            _toolWaitingOverlay.pickingMode = PickingMode.Ignore;
            _toolWaitingOverlay.style.position = Position.Absolute;
            _toolWaitingOverlay.style.top = -2000;
            _toolWaitingOverlay.style.left = -2000;
            _toolWaitingOverlay.style.right = -2000;
            _toolWaitingOverlay.style.bottom = -2000;
            _toolWaitingOverlay.style.backgroundColor = _toolWaitingColor;
            _toolWaitingOverlay.style.opacity = 0;
            _toolWaitingOverlay.style.display = DisplayStyle.None;
            _toolWaitingOverlay.style.transitionProperty = new List<StylePropertyName> { new StylePropertyName("opacity") };
            _toolWaitingOverlay.style.transitionDuration = new List<TimeValue> { new TimeValue(200, TimeUnit.Millisecond) };
            _toolWaitingOverlay.style.transitionTimingFunction = new List<EasingFunction> { new EasingFunction(EasingMode.EaseOut) };
            _mainFrame.Add(_toolWaitingOverlay);
            
            // Vertical divider
            _verticalDivider = new VisualElement();
            _verticalDivider.name = "options-divider";
            _verticalDivider.style.width = 2;
            _verticalDivider.style.backgroundColor = new Color(0.3f, 0.3f, 0.3f, 1f);
            _verticalDivider.style.display = _optionsPanelVisible ? DisplayStyle.Flex : DisplayStyle.None;
            root.Add(_verticalDivider);
            
            // Options panel (right side)
            AddOptionsPanel(root);
            // Honor the debug-panel visibility set from the login screen (dev/QA only). Deferred a
            // moment so the window has finished building/laying out before we resize and show it,
            // otherwise the mid-build resize gets ignored.
            if (IsDebugUnlocked() && EditorPrefs.GetBool(PREFS_DEBUG_PANEL_VISIBLE, false))
            {
                rootVisualElement.schedule.Execute(() =>
                {
                    if (!_optionsPanelVisible) OnDebugOptionsButtonClicked();
                }).StartingIn(150);
            }
            
            // Apply filter variable values (USS defaults may differ from C# variables)
            UpdateFilterFontSizes();
            UpdateFilterIconSizes();
            UpdateFilterIconMargins();
            UpdateFilterPadding();
            UpdateFilterTextY();
            UpdateFilterSectionPadding();
            UpdateFilterGroupSpacing();
            
            // Start sale badge pulse animation
            if (_saleBadgePulseEnabled)
                StartSaleBadgePulse();
            
            // Note: FilterAssets is called by OnAllButtonsCreated after all buttons are built
            // Note: ApplySyntyPassVisualState is called by OnAllButtonsCreated after ownership is set
            
            // Pre-set bar to correct state before buttons exist (user sees bar before grid)
            var packs = SyntyCatalogBridge.LoadedPacks;
            int packCount = packs?.Count ?? 0;
            if (_licenseSyntyPass && SyntyLoginManager.HasSyntyPass && packCount > 0)
            {
                // SyntyPass = 100% owned
                _currentPercentage = 100f;
                if (_progressBarFill != null)
                {
                    _progressBarFill.style.transitionDuration = new List<TimeValue> { new TimeValue(0, TimeUnit.Millisecond) };
                    _progressBarFill.style.width = Length.Percent(100);
                }
                if (_percentageText != null) _percentageText.text = "100";
                if (_ownedCountLabel != null) _ownedCountLabel.text = packCount.ToString();
                if (_totalCountLabel != null) _totalCountLabel.text = $"/{packCount}";
                if (_barGradientEnabled) UpdateBarGradientForState(true, false);
                else SetBarFillTint(_progressBarFillLeft, _progressBarFillMid, _progressBarFillRight, _syntyPassColor);
                if (_percentageText != null) _percentageText.style.color = _syntyPassColor;
                if (_percentageSymbol != null) _percentageSymbol.style.color = _syntyPassColor;
            }
            else if (packCount > 0)
            {
                // Count owned from server-verified ownership only
                int preOwned = 0;
                if (packs != null)
                {
                    foreach (var pack in packs)
                    {
                        if (SyntyStoreService.Instance.OwnedProductHandles.Contains(pack.packName))
                            preOwned++;
                    }
                }
                _currentPercentage = Mathf.Round((float)preOwned / packCount * 100f);
                if (_progressBarFill != null)
                {
                    _progressBarFill.style.transitionDuration = new List<TimeValue> { new TimeValue(0, TimeUnit.Millisecond) };
                    SetProgressBarPercent(_currentPercentage);
                }
                if (_percentageText != null) _percentageText.text = $"{(int)_currentPercentage}";
                if (_ownedCountLabel != null) _ownedCountLabel.text = preOwned.ToString();
                if (_totalCountLabel != null) _totalCountLabel.text = $"/{packCount}";
            }
            
            // Resume any downloads that were in progress before domain reload
            EditorApplication.delayCall += () =>
            {
                if (!this) return;
                ResumePendingDownloads();
                // If a batch was interrupted by a full Unity restart/crash, a disk resume file
                // remains. Offer to continue it. (SessionState-based resume above handles the
                // normal domain-reload case; this covers the harder restart case.)
                TryOfferBatchResume();
            };
            
            // If FetchExclusiveDeals returned BEFORE the deals container existed (race when
            // OnLoginCompleted fires just before BuildUI), the render is a no-op. Render now so
            // any already-fetched deals get displayed on this initial build.
            RenderExclusiveDeals();
            
            // Apply the server-selected banner now that the banner UI exists (OnLoginCompleted
            // also calls this; whichever runs last wins, both are idempotent).
            ApplyServerBanner();
        }
        
        /// <summary>
        /// Apply SyntyPass visual state (100% bar, pass colors, hide sale badges).
        /// Called after all asset buttons are built.
        /// </summary>
        private void ApplySyntyPassVisualState()
        {
            // The 100%/owns-all pass visual only applies to actual pass-holders. If the filter
            // is on but the user doesn't own the pass, skip it so the bar reflects real owned %.
            if (!_licenseSyntyPass || !SyntyLoginManager.HasSyntyPass) return;
            
            if (_progressBarFill != null)
            {
                _progressBarFill.style.transitionDuration = new List<TimeValue> { new TimeValue(0, TimeUnit.Millisecond) };
                if (_progressBarContainer != null) _progressBarContainer.style.display = DisplayStyle.Flex;
                if (_progressBarBgTrack != null) _progressBarBgTrack.style.display = DisplayStyle.Flex;
                _progressBarFill.style.display = DisplayStyle.Flex;
                if (_progressBarFillRight != null) _progressBarFillRight.style.display = DisplayStyle.Flex;
                if (_percentageTextContainer != null) _percentageTextContainer.style.display = DisplayStyle.Flex;
                _progressBarFill.style.width = Length.Percent(100);
            }
            if (_barGradientEnabled)
                UpdateBarGradientForState(true, false);
            else
                SetBarFillTint(_progressBarFillLeft, _progressBarFillMid, _progressBarFillRight, _syntyPassColor);
            
            if (_percentageText != null)
            {
                _percentageText.text = "100";
                _percentageText.style.color = _syntyPassColor;
            }
            if (_percentageSymbol != null)
                _percentageSymbol.style.color = _syntyPassColor;
            
            _currentPercentage = 100f;
            
            int total = _assetItems.Count;
            if (_ownedCountLabel != null) _ownedCountLabel.text = total.ToString();
            if (_totalCountLabel != null) _totalCountLabel.text = $"/{total}";
            
            if (_syntyPassGlowBar != null)
                _syntyPassGlowBar.style.opacity = 1f;
            
            if (_libraryFilterGroup != null)
                _libraryFilterGroup.style.display = DisplayStyle.None;
            
            SetBgGradientState(_bgGradientOnColor, _bgGradientOnOpacity);
            UpdateSaleBadgeVisibility();
        }
        
