            hoverWrapper.pickingMode = PickingMode.Position;
            
            hoverWrapper.Add(bannerContainer);
            
            // ADD TO CART button (below banner, no gap)
            var addToCartBtn = new Button(() => {
                bool monthly = _syntyPassPromoMonthly;
                SyntyAnalytics.TrackSubscribeClick(monthly ? "monthly" : "annual");
                // Two-page like asset add-to-cart: open the affiliate pass page first so it loads with
                // bg_ref (BixGrow registers the referral + sets the cookie), then a beat later add the
                // SELECTED plan (monthly/annual) to the cart and land on the cart on top. The cart-add
                // can't carry the ref, but the cookie from the pass page attributes the subscription.
                Application.OpenURL(AppendUtm(SyntyCatalogBridge.PASS_AFFILIATE_URL, monthly ? "subscription_monthly" : "subscription_annual"));
                string sellingPlan = monthly ? "4327670012" : "4310237436";
                string cartUrl = "https://syntystore.com/cart/clear?return_to=/cart/add?items[][id]=46402065072380%26items[][quantity]=1%26items[][selling_plan]=" + sellingPlan + "%26return_to=/cart";
                cartUrl = AppendUtm(cartUrl, monthly ? "subscription_monthly" : "subscription_annual");
                double openAt = EditorApplication.timeSinceStartup + 0.6;
                EditorApplication.CallbackFunction openCart = null;
                openCart = () => {
