            addToCartBtn.style.transitionTimingFunction = new List<EasingFunction> { new EasingFunction(EasingMode.EaseOut) };
            var capturedCartHover = cartHoverOverlay;
            addToCartBtn.RegisterCallback<MouseEnterEvent>(evt => {
