            // Hover: show color. Leave: show grey.
            var capturedColorOverlay = colorOverlay;
            var capturedChecks = checkMarks;
            hoverWrapper.RegisterCallback<MouseEnterEvent>(evt => {
                if (capturedColorOverlay != null) capturedColorOverlay.style.opacity = 1f;
                foreach (var c in capturedChecks) c.style.color = _promoCheckColor;
