            hoverWrapper.RegisterCallback<MouseLeaveEvent>(evt => {
                if (capturedColorOverlay != null) capturedColorOverlay.style.opacity = 0f;
                foreach (var c in capturedChecks) c.style.color = new Color(1f, 1f, 1f, 0.7f);
