            monthlyBtn.style.transitionProperty = new List<StylePropertyName> { new StylePropertyName("scale"), new StylePropertyName("color") };
            monthlyBtn.style.transitionDuration = new List<TimeValue> { new TimeValue(100, TimeUnit.Millisecond), new TimeValue(100, TimeUnit.Millisecond) };
            monthlyBtn.style.transitionTimingFunction = new List<EasingFunction> { new EasingFunction(EasingMode.EaseOut), new EasingFunction(EasingMode.EaseOut) };
            float toggleBtnRadius = (toggleHeight - togglePad * 2) * 0.5f;
            monthlyBtn.style.borderTopLeftRadius = toggleBtnRadius;
            monthlyBtn.style.borderTopRightRadius = toggleBtnRadius;
            monthlyBtn.style.borderBottomLeftRadius = toggleBtnRadius;
            monthlyBtn.style.borderBottomRightRadius = toggleBtnRadius;
            annualBtn.style.transitionProperty = new List<StylePropertyName> { new StylePropertyName("scale"), new StylePropertyName("color") };
            annualBtn.style.transitionDuration = new List<TimeValue> { new TimeValue(100, TimeUnit.Millisecond), new TimeValue(100, TimeUnit.Millisecond) };
            annualBtn.style.transitionTimingFunction = new List<EasingFunction> { new EasingFunction(EasingMode.EaseOut), new EasingFunction(EasingMode.EaseOut) };
            annualBtn.style.borderTopLeftRadius = toggleBtnRadius;
            annualBtn.style.borderTopRightRadius = toggleBtnRadius;
            annualBtn.style.borderBottomLeftRadius = toggleBtnRadius;
            annualBtn.style.borderBottomRightRadius = toggleBtnRadius;
