            monthlyHoverPill.style.left = togglePad + 6;
            monthlyHoverPill.style.top = togglePad + 4;
            monthlyHoverPill.style.width = toggleBtnWidth - 12;
            monthlyHoverPill.style.height = toggleHeight - togglePad * 2 - 8;
            float hoverPillRadius = (toggleHeight - togglePad * 2 - 8) * 0.5f;
            monthlyHoverPill.style.borderTopLeftRadius = hoverPillRadius;
            monthlyHoverPill.style.borderTopRightRadius = hoverPillRadius;
            monthlyHoverPill.style.borderBottomLeftRadius = hoverPillRadius;
            monthlyHoverPill.style.borderBottomRightRadius = hoverPillRadius;
            monthlyHoverPill.style.backgroundColor = new Color(1f, 1f, 1f, 0.2f);
            monthlyHoverPill.style.display = DisplayStyle.None;
            monthlyHoverPill.style.transitionProperty = new List<StylePropertyName> { new StylePropertyName("opacity") };
            monthlyHoverPill.style.transitionDuration = new List<TimeValue> { new TimeValue(100, TimeUnit.Millisecond) };
            monthlyHoverPill.pickingMode = PickingMode.Ignore;
            toggleRow.Add(monthlyHoverPill);
            
            var annualHoverPill = new VisualElement();
            annualHoverPill.style.position = Position.Absolute;
            annualHoverPill.style.left = toggleBtnWidth + togglePad + 6;
            annualHoverPill.style.top = togglePad + 4;
            annualHoverPill.style.width = toggleBtnWidth - 12;
            annualHoverPill.style.height = toggleHeight - togglePad * 2 - 8;
            annualHoverPill.style.borderTopLeftRadius = hoverPillRadius;
            annualHoverPill.style.borderTopRightRadius = hoverPillRadius;
            annualHoverPill.style.borderBottomLeftRadius = hoverPillRadius;
            annualHoverPill.style.borderBottomRightRadius = hoverPillRadius;
            annualHoverPill.style.backgroundColor = new Color(1f, 1f, 1f, 0.2f);
            annualHoverPill.style.display = DisplayStyle.None;
            annualHoverPill.style.transitionProperty = new List<StylePropertyName> { new StylePropertyName("opacity") };
            annualHoverPill.style.transitionDuration = new List<TimeValue> { new TimeValue(100, TimeUnit.Millisecond) };
            annualHoverPill.pickingMode = PickingMode.Ignore;
            toggleRow.Add(annualHoverPill);
            
            monthlyBtn.RegisterCallback<MouseEnterEvent>(evt => {
                if (!_syntyPassPromoMonthly) { monthlyBtn.style.color = _promoToggleHoverColor; monthlyBtn.style.scale = new Scale(new Vector3(1.1f, 1.1f, 1f)); monthlyHoverPill.style.display = DisplayStyle.Flex; }
            });
            monthlyBtn.RegisterCallback<MouseLeaveEvent>(evt => {
                if (!_syntyPassPromoMonthly) { monthlyBtn.style.color = inactiveColor; monthlyBtn.style.scale = new Scale(Vector3.one); monthlyHoverPill.style.display = DisplayStyle.None; }
            });
            annualBtn.RegisterCallback<MouseEnterEvent>(evt => {
                if (_syntyPassPromoMonthly) { annualBtn.style.color = _promoToggleHoverColor; annualBtn.style.scale = new Scale(new Vector3(1.1f, 1.1f, 1f)); annualHoverPill.style.display = DisplayStyle.Flex; }
            });
            annualBtn.RegisterCallback<MouseLeaveEvent>(evt => {
                if (_syntyPassPromoMonthly) { annualBtn.style.color = inactiveColor; annualBtn.style.scale = new Scale(Vector3.one); annualHoverPill.style.display = DisplayStyle.None; }
            });
            
            System.Action updateToggle = () =>
            {
                if (_syntyPassPromoMonthly)
                {
                    toggleSlider.style.left = togglePad;
                    monthlyBtn.style.color = Color.black;
                    annualBtn.style.color = inactiveColor;
                    monthlyBtn.RemoveFromClassList("link-cursor");
                    annualBtn.AddToClassList("link-cursor");
                    monthlyBtn.pickingMode = PickingMode.Ignore;
                    annualBtn.pickingMode = PickingMode.Position;
                    monthlyBtn.style.scale = new Scale(Vector3.one);
                    annualBtn.style.scale = new Scale(Vector3.one);
                    monthlyHoverPill.style.display = DisplayStyle.None;
                    annualHoverPill.style.display = DisplayStyle.None;
                    priceLabel.text = _promoMonthlyPrice;
                    perMonth.text = " /mo.";
                    termLabel.text = _promoMonthlyTerm;
                    _promoShowingAnnual = false;
                }
                else
                {
                    toggleSlider.style.left = toggleBtnWidth + togglePad;
                    annualBtn.style.color = Color.black;
                    monthlyBtn.style.color = inactiveColor;
                    annualBtn.RemoveFromClassList("link-cursor");
                    monthlyBtn.AddToClassList("link-cursor");
                    annualBtn.pickingMode = PickingMode.Ignore;
                    monthlyBtn.pickingMode = PickingMode.Position;
                    monthlyBtn.style.scale = new Scale(Vector3.one);
                    annualBtn.style.scale = new Scale(Vector3.one);
                    monthlyHoverPill.style.display = DisplayStyle.None;
                    annualHoverPill.style.display = DisplayStyle.None;
                    priceLabel.text = _promoAnnualPrice;
                    perMonth.text = " /mo.";
                    termLabel.text = _promoAnnualTerm;
                    _promoShowingAnnual = true;
                }
            };
            
            monthlyBtn.clicked += () => { _syntyPassPromoMonthly = true; updateToggle(); };
            annualBtn.clicked += () => { _syntyPassPromoMonthly = false; updateToggle(); };
            updateToggle();
            
            parent.Add(_syntyPassPromo);
            
            if (_licenseSyntyPass && !SyntyLoginManager.HasSyntyPass)
            {
                if (_assetContent != null) _assetContent.style.display = DisplayStyle.None;
                _syntyPassPromo.style.display = DisplayStyle.Flex;
            }
        }
        
        private void RebuildSyntyPassPromo()
        {
            if (_syntyPassPromo == null || _syntyPassPromoParent == null) return;
            bool wasVisible = _syntyPassPromo.style.display == DisplayStyle.Flex;
            _syntyPassPromo.RemoveFromHierarchy();
            BuildSyntyPassPromo(_syntyPassPromoParent);
            if (wasVisible) _syntyPassPromo.style.display = DisplayStyle.Flex;
        }
        
