        private void AddFrameBorder(VisualElement parent)
        {
            _frameBorders.Clear();
            
            var frameContainer = new VisualElement();
            frameContainer.name = "frame-container";
            frameContainer.AddToClassList("frame-container");
            parent.Add(frameContainer);
            
            // Top Left Corner - anchored to top left
            var cornerTL = new VisualElement();
            cornerTL.name = "corner-tl";
            cornerTL.style.position = Position.Absolute;
            cornerTL.style.top = 0;
            cornerTL.style.left = 0;
            cornerTL.style.width = _borderScale;
            cornerTL.style.height = _borderScale;
            var tlTex = LoadImage("Background", "Background_Corner_TopLeft");
            if (tlTex != null) { cornerTL.style.backgroundImage = new StyleBackground(tlTex); cornerTL.style.SetBackgroundStretchToFill(); }
            frameContainer.Add(cornerTL);
            _frameBorders.Add(cornerTL);
            
            // Top Right Corner - anchored to top right
            var cornerTR = new VisualElement();
            cornerTR.name = "corner-tr";
            cornerTR.style.position = Position.Absolute;
            cornerTR.style.top = 0;
            cornerTR.style.right = 0;
            cornerTR.style.width = _borderScale;
            cornerTR.style.height = _borderScale;
            var trTex = LoadImage("Background", "Background_Corner_TopRight");
            if (trTex != null) { cornerTR.style.backgroundImage = new StyleBackground(trTex); cornerTR.style.SetBackgroundStretchToFill(); }
            frameContainer.Add(cornerTR);
            _frameBorders.Add(cornerTR);
            
            // Bottom Left Corner - anchored to bottom left
            var cornerBL = new VisualElement();
            cornerBL.name = "corner-bl";
            cornerBL.style.position = Position.Absolute;
            cornerBL.style.bottom = 0;
            cornerBL.style.left = 0;
            cornerBL.style.width = _borderScale;
            cornerBL.style.height = _borderScale;
            var blTex = LoadImage("Background", "Background_Corner_BottomLeft");
            if (blTex != null) { cornerBL.style.backgroundImage = new StyleBackground(blTex); cornerBL.style.SetBackgroundStretchToFill(); }
            frameContainer.Add(cornerBL);
            _frameBorders.Add(cornerBL);
            
            // Bottom Right Corner - anchored to bottom right
            var cornerBR = new VisualElement();
            cornerBR.name = "corner-br";
            cornerBR.style.position = Position.Absolute;
            cornerBR.style.bottom = 0;
            cornerBR.style.right = 0;
            cornerBR.style.width = _borderScale;
            cornerBR.style.height = _borderScale;
            var brTex = LoadImage("Background", "Background_Corner_BottomRight");
            if (brTex != null) { cornerBR.style.backgroundImage = new StyleBackground(brTex); cornerBR.style.SetBackgroundStretchToFill(); }
            frameContainer.Add(cornerBR);
            _frameBorders.Add(cornerBR);
            
            // Top Edge - stretched between top corners
            var edgeTop = new VisualElement();
            edgeTop.name = "edge-top";
            edgeTop.style.position = Position.Absolute;
            edgeTop.style.top = 0;
            edgeTop.style.left = _borderScale;
            edgeTop.style.right = _borderScale;
            edgeTop.style.height = _borderScale;
            var topTex = LoadImage("Background", "Background_Edge_Top");
            if (topTex != null) { edgeTop.style.backgroundImage = new StyleBackground(topTex); edgeTop.style.SetBackgroundStretchToFill(); }
            frameContainer.Add(edgeTop);
            _frameBorders.Add(edgeTop);
            
            // Bottom Edge - stretched between bottom corners
            var edgeBottom = new VisualElement();
            edgeBottom.name = "edge-bottom";
            edgeBottom.style.position = Position.Absolute;
            edgeBottom.style.bottom = 0;
            edgeBottom.style.left = _borderScale;
            edgeBottom.style.right = _borderScale;
            edgeBottom.style.height = _borderScale;
            var bottomTex = LoadImage("Background", "Background_Edge_Bottom");
            if (bottomTex != null) { edgeBottom.style.backgroundImage = new StyleBackground(bottomTex); edgeBottom.style.SetBackgroundStretchToFill(); }
            frameContainer.Add(edgeBottom);
            _frameBorders.Add(edgeBottom);
            
            // Left Edge - stretched between top-left and bottom-left corners
            var edgeLeft = new VisualElement();
            edgeLeft.name = "edge-left";
            edgeLeft.style.position = Position.Absolute;
            edgeLeft.style.left = 0;
            edgeLeft.style.top = _borderScale;
            edgeLeft.style.bottom = _borderScale;
            edgeLeft.style.width = _borderScale;
            var leftTex = LoadImage("Background", "Background_Edge_Left");
            if (leftTex != null) { edgeLeft.style.backgroundImage = new StyleBackground(leftTex); edgeLeft.style.SetBackgroundStretchToFill(); }
            frameContainer.Add(edgeLeft);
            _frameBorders.Add(edgeLeft);
            
            // Right Edge - stretched between top-right and bottom-right corners
            var edgeRight = new VisualElement();
            edgeRight.name = "edge-right";
            edgeRight.style.position = Position.Absolute;
            edgeRight.style.right = 0;
            edgeRight.style.top = _borderScale;
            edgeRight.style.bottom = _borderScale;
            edgeRight.style.width = _borderScale;
            var rightTex = LoadImage("Background", "Background_Edge_Right");
            if (rightTex != null) { edgeRight.style.backgroundImage = new StyleBackground(rightTex); edgeRight.style.SetBackgroundStretchToFill(); }
            frameContainer.Add(edgeRight);
            _frameBorders.Add(edgeRight);
            
            // Center Fill - fills the gap between all edges
            var centerFill = new VisualElement();
            centerFill.name = "center-fill";
            centerFill.style.position = Position.Absolute;
            centerFill.style.top = _borderScale;
            centerFill.style.bottom = _borderScale;
            centerFill.style.left = _borderScale;
            centerFill.style.right = _borderScale;
            var centerTex = LoadImage("Background", "Background_Center");
            if (centerTex != null) { centerFill.style.backgroundImage = new StyleBackground(centerTex); centerFill.style.SetBackgroundStretchToFill(); }
            frameContainer.Add(centerFill);
            _frameBorders.Add(centerFill);
        }
        
        private void AddFilterSection(VisualElement parent)
        {
            _filterSection = new VisualElement();
            _filterSection.name = "filter-section";
            _filterSection.AddToClassList("filter-section");
            _filterSection.style.width = _filterSectionWidth;
            parent.Add(_filterSection);
            
            var filterScroll = new ScrollView(ScrollViewMode.Vertical);
            filterScroll.name = "filter-scroll";
            filterScroll.AddToClassList("filter-scroll");
            filterScroll.horizontalScrollerVisibility = ScrollerVisibility.Hidden;
            // Overlay the vertical scrollbar (float it over the right edge) instead of letting it shrink
            // the content viewport — otherwise the filter headers lose width when it appears and the
            // All/None buttons end up on top of the title. Content keeps full width; the bar floats.
            filterScroll.verticalScroller.style.position = Position.Absolute;
            filterScroll.verticalScroller.style.right = 0;
            filterScroll.verticalScroller.style.top = 0;
            filterScroll.verticalScroller.style.bottom = 0;
            _filterSection.Add(filterScroll);
            _filterScrollRef = filterScroll;
            _filterChevrons.Clear();
            // When the scrollbar appears/disappears (content or size change), pull the chevrons in
            // against None only while it's showing, so they clear the floating bar.
            filterScroll.RegisterCallback<GeometryChangedEvent>(_ => UpdateChevronScrollState());
            filterScroll.verticalScroller.RegisterCallback<GeometryChangedEvent>(_ => UpdateChevronScrollState());
            
            var filterContent = new VisualElement();
            filterContent.name = "filter-content";
            filterContent.AddToClassList("filter-content");
            filterContent.style.overflow = Overflow.Visible; // let pass-button glow spill past edges
            filterScroll.Add(filterContent);
            
            // Clear filter button lists
            _licenseFilterBtns.Clear();
            _libraryFilterBtns.Clear();
            _statusFilterBtns.Clear();
            _assetFilterBtns.Clear();
            _themeFilterBtns.Clear();
            _priceFilterBtns.Clear();
            
            // License Filter
            AddFilterGroup(filterContent, _filterTitleLicense, false, null, null, (container) =>
            {
                bool userHasPass = SyntyLoginManager.HasSyntyPass;
                string btnText = userHasPass ? "SYNTY PASS" : "GET SYNTY PASS";
                _syntyPassBtn = CreateToggleButtonWithFont(btnText, "Icon_SyntyPass", _licenseSyntyPass && userHasPass, null, _licenseBtnOnBgColor, showRemoveIcon: true);
                // Keep the button from growing to fit the longer "GET SYNTY PASS" text (the label is
                // hidden and only drives width). Force it to the panel width so it never clips off
                // the right edge for non-Pass accounts.
                // Inset the button horizontally by the glow bleed so the glow lands INSIDE the filter
                // panel. The panel is a ScrollView whose viewport clips for scrolling, so a full-width
                // button's glow always got sliced at the panel edge. Stretch fills the width minus the
                // insets; the glow then bleeds into that inset space rather than past the panel.
                _syntyPassBtn.style.width = StyleKeyword.Auto;
                _syntyPassBtn.style.maxWidth = StyleKeyword.None;
                _syntyPassBtn.style.alignSelf = Align.Stretch;
                _syntyPassBtn.style.marginLeft = _passGlowInset;
                _syntyPassBtn.style.marginRight = _passGlowInset;
                _syntyPassBtn.style.flexShrink = 1;
                // Overflow visible so the pass-button glow (a child that bleeds past the button edges)
                // reaches the inset margin space instead of being clipped at the button edge.
                _syntyPassBtn.style.overflow = Overflow.Visible;
                // Kill the default Unity button border + focus outline. The other filter buttons
                // auto-size so their 3-part background hides it, but this one is stretched to full
                // width, which exposed the border/focus ring around the whole button.
                _syntyPassBtn.style.borderTopWidth = 0;
                _syntyPassBtn.style.borderBottomWidth = 0;
                _syntyPassBtn.style.borderLeftWidth = 0;
                _syntyPassBtn.style.borderRightWidth = 0;
                _syntyPassBtn.focusable = false;
                
                // Hide default label and icon visually but keep label for layout width
                var spLabel = _syntyPassBtn.Q<Label>(className: "filter-btn-label");
                if (spLabel != null) { spLabel.style.opacity = 0; spLabel.text = "SYNTY PASS"; spLabel.style.whiteSpace = WhiteSpace.NoWrap; }
                var spIcon = _syntyPassBtn.Q<VisualElement>(className: "filter-btn-icon");
                if (spIcon != null) spIcon.style.opacity = 0;
                
                // Add SyntyPass_Filter image overlay
                var spFilterTex = LoadImage("Buttons", "SyntyPass_Filter");
                if (spFilterTex == null) spFilterTex = LoadImage("Filter", "SyntyPass_Filter");
                if (spFilterTex == null) spFilterTex = LoadImage("Icons/Misc", "SyntyPass_Filter");
                if (spFilterTex == null) spFilterTex = LoadImage("Logo", "SyntyPass_Filter");
                if (spFilterTex != null)
                {
                    _syntyPassFilterImage = new VisualElement();
                    _syntyPassFilterImage.name = "syntypass-filter-image";
                    _syntyPassFilterImage.pickingMode = PickingMode.Ignore;
                    _syntyPassFilterImage.style.position = Position.Absolute;
                    _syntyPassFilterImage.style.top = 0;
                    _syntyPassFilterImage.style.left = 0;
                    _syntyPassFilterImage.style.right = 0;
                    _syntyPassFilterImage.style.bottom = 0;
                    _syntyPassFilterImage.style.backgroundImage = new StyleBackground(spFilterTex);
                    _syntyPassFilterImage.style.SetBackgroundScaleToFit();
                    _syntyPassFilterImage.style.scale = new Scale(new Vector3(_syntyPassFilterScale, _syntyPassFilterScale, 1f));
                    _syntyPassFilterImage.style.translate = new Translate(_syntyPassFilterX, 0);
                    _syntyPassFilterImage.style.unityBackgroundImageTintColor = _licenseSyntyPass ? _syntyPassFilterOnColor : _syntyPassFilterOffColor;
                    _syntyPassBtn.Add(_syntyPassFilterImage);
                }
                else
                {
                    // Image not found — restore label/icon visibility
                    if (spLabel != null) spLabel.style.opacity = 1;
                    if (spIcon != null) spIcon.style.opacity = 1;
                }
                
                // Apply Synty Pass colors for initial state
                UpdateSyntyPassButtonState(_syntyPassBtn, _licenseSyntyPass);
                _syntyPassBtn.clicked += () =>
                {
                    MarkPassButtonClicked(); // stop the attention pulse for good
                    // Toggle state immediately — defer ALL work to next frame to keep click frame clean
                    _licenseSyntyPass = !_licenseSyntyPass;
                    SessionState.SetBool(SESSION_PASS_FILTER, _licenseSyntyPass); // remember across domain reloads
                    SessionState.SetBool(SESSION_PASS_TOGGLED_OFF, !_licenseSyntyPass); // explicit off wins over the pass-holder default
                    UpdateDealsVisibility(); // hide deals when the pass filter is on
                    SyntyAnalytics.TrackSyntyPassToggle(_licenseSyntyPass);
                    EditorApplication.delayCall += () =>
                    {
                        if (!this) return;
                        
                        // Non-pass users: show/hide promo panel instead of applying ownership
                        if (!SyntyLoginManager.HasSyntyPass)
                        {
                            UpdateSyntyPassButtonState(_syntyPassBtn, _licenseSyntyPass);
                            if (_syntyPassGlowBar != null)
                                _syntyPassGlowBar.style.opacity = _licenseSyntyPass ? 1f : 0f;
                            
                            // Toggle library filters
                            if (_libraryFilterGroup != null)
                            {
                                if (_licenseSyntyPass) SelectAllLibrary();
                                _libraryFilterGroup.style.display = _licenseSyntyPass ? DisplayStyle.None : DisplayStyle.Flex;
                            }
                            
                            if (_licenseSyntyPass)
                            {
                                // Deselect all assets so action bars disappear
                                foreach (var item in _assetItems)
                                {
                                    if (item.getSelected())
                                        item.setSelected(false);
                                }
                                
                                // Show promo, hide assets
                                if (_assetContent != null) _assetContent.style.display = DisplayStyle.None;
                                if (_syntyPassPromo != null) _syntyPassPromo.style.display = DisplayStyle.Flex;
                                if (_emptyStateContainer != null) _emptyStateContainer.style.display = DisplayStyle.None;
                            }
                            else
                            {
                                // Hide promo, show assets
                                if (_syntyPassPromo != null) _syntyPassPromo.style.display = DisplayStyle.None;
                                if (_assetContent != null) _assetContent.style.display = DisplayStyle.Flex;
                                AutoSortOnSale(); // if a sale is on, switch to On Sale ordering
                                FilterAssets();
                            }
                            
                            SaveFilterStates();
                            UpdateDownloadBar();
                            return;
                        }
                        
                        // Deselect all assets before applying SyntyPass changes
                        foreach (var item in _assetItems)
                        {
                            if (item.getSelected())
                                item.setSelected(false);
                        }
                        UpdateDownloadBar();
                        
                        UpdateSyntyPassButtonState(_syntyPassBtn, _licenseSyntyPass);
                        if (_syntyPassGlowBar != null)
                            _syntyPassGlowBar.style.opacity = _licenseSyntyPass ? 1f : 0f;
                        ApplySyntyPassOwnership(_licenseSyntyPass);
                        SaveFilterStates();
                        UpdateSaleBadgeVisibility();
                        // ApplySyntyPassOwnership recomputes the collection % inside a generation-guarded
                        // delayCall that gets skipped if it's superseded — which left the bar showing a
                        // stale percentage (e.g. 10%) after toggling the pass off, until a manual refresh.
                        // Recompute unconditionally on the next tick so the percentage is always correct.
                        EditorApplication.delayCall += () => { if (this) UpdateCollectionCounts(); };
                    };
                };
                container.Add(_syntyPassBtn);
                _licenseFilterBtns.Add(_syntyPassBtn);
                
                // Glow bar: child of button at index 0 — renders behind bgContainer, icon, label
                // Caps are positioned absolutely so their INNER edge aligns with the bg cap seam
                // The glow image is 2x bigger than the bg end, so caps overflow outward at each end
                if (_filterBtnGlowEnd != null && _filterBtnGlowMiddle != null)
                {
                    // Scale factor = button display height / bg end native height
                    float btnH    = 32f;
                    float bgEndH  = _filterBtnEnd != null ? (float)_filterBtnEnd.height : 64f;
                    float bgEndW  = _filterBtnEnd != null ? (float)_filterBtnEnd.width  : 32f;
                    float scale   = btnH / bgEndH;                          // e.g. 32/64 = 0.5
                    float bgCapW  = Mathf.Ceil(bgEndW * scale);             // bg seam position (16px)
                    float glowCapW = Mathf.Ceil(_filterBtnGlowEnd.width  * scale); // glow cap width (32px)
                    float glowCapH = Mathf.Ceil(_filterBtnGlowEnd.height * scale); // glow cap height (64px)
                    float glowMidH = Mathf.Ceil(_filterBtnGlowMiddle.height * scale);
                    float overflow = glowCapW - bgCapW;                     // how far glow extends beyond seam (16px)
                    Color glowTint = _licenseBtnOnBgColor;
                    
                    // Container: fills button, overflow visible so caps can bleed out
                    var glowBar = new VisualElement();
                    glowBar.name = "synty-pass-glow-bar";
                    glowBar.style.position = Position.Absolute;
                    glowBar.style.left   = 0;
                    glowBar.style.right  = 0;
                    glowBar.style.top    = 0;
                    glowBar.style.bottom = 0;
                    glowBar.style.overflow = Overflow.Visible;
                    glowBar.pickingMode = PickingMode.Ignore;
                    // Start invisible; fades in/out via transition when button is toggled
                    glowBar.style.opacity = _licenseSyntyPass ? 1f : 0f;
                    glowBar.style.transitionProperty = new StyleList<StylePropertyName>(new List<StylePropertyName> { new StylePropertyName("opacity") });
                    glowBar.style.transitionDuration = new StyleList<TimeValue>(new List<TimeValue> { new TimeValue(1f, TimeUnit.Second) });
                    glowBar.style.transitionTimingFunction = new StyleList<EasingFunction>(new List<EasingFunction> { new EasingFunction(EasingMode.EaseInOut) });
                    _syntyPassGlowBar = glowBar;
                    
                    // Left cap: right edge at bgCapW, extends left by glowCapW
                    var glowLeft = new VisualElement();
                    glowLeft.style.position = Position.Absolute;
                    glowLeft.style.left   = bgCapW - glowCapW;   // = -overflow (bleeds left)
                    glowLeft.style.width  = glowCapW;
                    glowLeft.style.height = glowCapH;
                    glowLeft.style.top    = Length.Percent(50);
                    glowLeft.style.marginTop = -glowCapH * 0.5f;
                    glowLeft.style.backgroundImage = new StyleBackground(_filterBtnGlowEnd);
                    glowLeft.style.unityBackgroundImageTintColor = glowTint;
                    glowLeft.style.SetBackgroundStretchToFill();
                    glowLeft.pickingMode = PickingMode.Ignore;
                    glowBar.Add(glowLeft);
                    
                    // Middle: spans between the two seams
                    var glowMid = new VisualElement();
                    glowMid.style.position = Position.Absolute;
                    glowMid.style.left   = bgCapW;
                    glowMid.style.right  = bgCapW;
                    glowMid.style.height = glowMidH;
                    glowMid.style.top    = Length.Percent(50);
                    glowMid.style.marginTop = -glowMidH * 0.5f;
                    glowMid.style.backgroundImage = new StyleBackground(_filterBtnGlowMiddle);
                    glowMid.style.unityBackgroundImageTintColor = glowTint;
                    glowMid.style.SetBackgroundStretchToFill();
                    glowMid.pickingMode = PickingMode.Ignore;
                    glowBar.Add(glowMid);
                    
                    // Right cap: left edge at (button.width - bgCapW), extends right by overflow
                    var glowRight = new VisualElement();
                    glowRight.style.position = Position.Absolute;
                    glowRight.style.right = bgCapW - glowCapW;   // = -overflow (bleeds right)
                    glowRight.style.width  = glowCapW;
                    glowRight.style.height = glowCapH;
                    glowRight.style.top    = Length.Percent(50);
                    glowRight.style.marginTop = -glowCapH * 0.5f;
                    glowRight.style.backgroundImage = new StyleBackground(_filterBtnGlowEnd);
                    glowRight.style.unityBackgroundImageTintColor = glowTint;
                    glowRight.style.SetBackgroundStretchToFill();
                    glowRight.style.transformOrigin = new TransformOrigin(Length.Percent(50), Length.Percent(50));
                    glowRight.style.scale = new Scale(new Vector3(-1, 1, 1));
                    glowRight.pickingMode = PickingMode.Ignore;
                    glowBar.Add(glowRight);
                    
                    // Insert at index 0 inside the button — behind bgContainer, icon, label
                    _syntyPassBtn.Insert(0, glowBar);
                }
            });
            
            // Library Filter
            AddFilterGroup(filterContent, _filterTitleLibrary, true,
                () => SelectAllLibrary(),
                () => SelectNoLibrary(),
                (container) =>
            {
                // In Library (Owned)
                _statsInLibraryBtn = CreateToggleButtonWithFont("In Library", "Icon_InLibrary", _statsInLibrary, null, _themeBtnOnBgColor, showRemoveIcon: true);
                ApplyLibraryBtnColors(_statsInLibraryBtn, _statsInLibrary, _libraryInOnColor, _libraryInOffColor);
                _statsInLibraryBtn.clicked += () =>
                {
                    _statsInLibrary = !_statsInLibrary;
                    ApplyLibraryBtnColors(_statsInLibraryBtn, _statsInLibrary, _libraryInOnColor, _libraryInOffColor);
                    UpdateLibraryAllNoneButtons();
                    FilterAssets();
                    SaveFilterStates();
                };
                container.Add(_statsInLibraryBtn);
                _libraryFilterBtns.Add(_statsInLibraryBtn);
                
                // Not in Library (Not Owned)
                _statsNotInLibraryBtn = CreateToggleButtonWithFont("Not in Library", "Icon_NotInLibrary", _statsNotInLibrary, null, _themeBtnOnBgColor, showRemoveIcon: true);
                ApplyLibraryBtnColors(_statsNotInLibraryBtn, _statsNotInLibrary, _libraryNotInOnColor, _libraryNotInOffColor);
                _statsNotInLibraryBtn.clicked += () =>
                {
                    _statsNotInLibrary = !_statsNotInLibrary;
                    ApplyLibraryBtnColors(_statsNotInLibraryBtn, _statsNotInLibrary, _libraryNotInOnColor, _libraryNotInOffColor);
                    UpdateLibraryAllNoneButtons();
                    FilterAssets();
                    SaveFilterStates();
                };
                container.Add(_statsNotInLibraryBtn);
                _libraryFilterBtns.Add(_statsNotInLibraryBtn);
            },
            out _libraryAllBtn, out _libraryNoneBtn, out _libraryAllNoneContainer);
            _libraryFilterGroup = filterContent.Q<VisualElement>("filter-group-library");
            if (_libraryFilterGroup != null && _licenseSyntyPass)
                _libraryFilterGroup.style.display = DisplayStyle.None;
            
            // Price filter removed from UI — _priceFree/_pricePaid stay true (show all)
            
            // Asset Filter
            AddFilterGroup(filterContent, _filterTitleAsset, true, 
                () => SelectAllAssetTypes(), 
                () => SelectNoAssetTypes(), 
                (container) =>
                {
                    // Only show types that have assets in the catalog
                    var packs = SyntyCatalogBridge.LoadedPacks;
                    var typesInCatalog = new HashSet<string>();
                    if (packs != null)
                    {
                        foreach (var pack in packs)
                        {
                            string t = SyntyCatalogBridge.GetAssetType(pack);
                            if (!string.IsNullOrEmpty(t)) typesInCatalog.Add(t);
                        }
                    }
                    
                    foreach (var (name, icon) in AssetTypes)
                    {
                        if (!typesInCatalog.Contains(name)) continue;
                        var (themeColor, _) = GetAssetTypeColors(name);
                        bool isOn = _selectedAssetTypes.Contains(name);
                        var btn = CreateToggleButtonWithFont(name, icon, isOn, themeColor, themeColor, showRemoveIcon: true);
                        _assetButtons[name] = btn;
                        
                        // Get per-type colors
                        var (onBg, offBg, onText, offText) = GetAssetFilterColors(name);
                        
                        // Apply initial text/icon color based on state
                        var label = btn.Q<Label>(className: "filter-btn-label");
                        var iconEl = btn.Q<VisualElement>(className: "filter-btn-icon");
                        if (isOn)
                        {
                            SetFilterBgVisible(btn, true);
                            UpdateFilterButtonBgColor(btn, onBg);
                            if (label != null) label.style.color = onText;
                            if (iconEl != null) iconEl.style.unityBackgroundImageTintColor = onText;
                            UpdateFilterRemoveIcon(btn, true, onText);
                        }
                        else
                        {
                            SetFilterBgVisible(btn, false);
                            UpdateFilterButtonBgColor(btn, offBg);
                            if (label != null) label.style.color = offText;
                            if (iconEl != null) iconEl.style.unityBackgroundImageTintColor = offText;
                            UpdateFilterRemoveIcon(btn, false, offText);
                        }
                        
                        btn.clicked += () =>
                        {
                            ToggleAssetType(name);
                            UpdateAssetToggleButtonState(btn, _selectedAssetTypes.Contains(name));
                            UpdateAssetAllNoneButtons();
                        };
                        container.Add(btn);
                        _assetFilterBtns.Add(btn);
                    }
                },
                out _assetAllBtn, out _assetNoneBtn, out _assetAllNoneContainer);
            
            int preInstalledCount = filterContent.childCount;
            _installedFilterGroup = null;
            AddFilterGroup(filterContent, _filterTitleInstalled, true,
                () => { _filterShowInstalled = true; _filterShowNotInstalled = true; UpdateInstalledFilterButtons(); FilterAssets(); SaveFilterStates(); },
                () => { _filterShowInstalled = false; _filterShowNotInstalled = false; UpdateInstalledFilterButtons(); FilterAssets(); SaveFilterStates(); },
                (container) =>
                {
                    // "Installed" button
                    _installedFilterBtn = CreateToggleButtonWithFont("Installed", "Icon_Installed", _filterShowInstalled, null, _themeBtnOnBgColor, showRemoveIcon: true);
                    ApplyFilterBtnState(_installedFilterBtn, _filterShowInstalled);
                    _installedFilterBtn.RegisterCallback<ClickEvent>(evt =>
                    {
                        _filterShowInstalled = !_filterShowInstalled;
                        ApplyFilterBtnState(_installedFilterBtn, _filterShowInstalled);
                        UpdateInstalledFilterButtons();
                        FilterAssets();
                        SaveFilterStates();
                    });
                    container.Add(_installedFilterBtn);
                    
                    // "Not Installed" button
                    _notInstalledFilterBtn = CreateToggleButtonWithFont("Not Installed", "Icon_NotInLibrary", _filterShowNotInstalled, null, _themeBtnOnBgColor, showRemoveIcon: true);
                    ApplyFilterBtnState(_notInstalledFilterBtn, _filterShowNotInstalled);
                    _notInstalledFilterBtn.RegisterCallback<ClickEvent>(evt =>
                    {
                        _filterShowNotInstalled = !_filterShowNotInstalled;
                        ApplyFilterBtnState(_notInstalledFilterBtn, _filterShowNotInstalled);
                        UpdateInstalledFilterButtons();
                        FilterAssets();
                        SaveFilterStates();
                    });
                    container.Add(_notInstalledFilterBtn);
                    
                    // Use same font size/scale as Library buttons
                    _libraryFilterBtns.Add(_installedFilterBtn);
                    _libraryFilterBtns.Add(_notInstalledFilterBtn);
                },
                out _installedAllBtn, out _installedNoneBtn, out _installedAllNoneContainer);
            
            if (filterContent.childCount > preInstalledCount)
                _installedFilterGroup = filterContent[filterContent.childCount - 1];
            
            // Theme Filter  
            AddFilterGroup(filterContent, _filterTitleTheme, true,
                () => SelectAllThemes(),
                () => SelectNoThemes(),
                (container) =>
                {
                    // Only show themes that have assets in the catalog
                    var themePacks = SyntyCatalogBridge.LoadedPacks;
                    var themesInCatalog = new HashSet<string>();
                    if (themePacks != null)
                    {
                        foreach (var pack in themePacks)
                        {
                            foreach (var t in SyntyCatalogBridge.GetThemes(pack))
                                if (!string.IsNullOrEmpty(t)) themesInCatalog.Add(t);
                        }
                    }
                    
                    // Theme filter buttons in alphabetical order, with "Other" always last.
                    var orderedThemes = Themes
                        .OrderBy(t => string.Equals(t.Item1, "Other", System.StringComparison.OrdinalIgnoreCase) ? 1 : 0)
                        .ThenBy(t => t.Item1, System.StringComparer.OrdinalIgnoreCase);
                    foreach (var (name, icon) in orderedThemes)
                    {
                        if (!themesInCatalog.Contains(name)) continue;
                        bool isOn = _selectedThemes.Contains(name);
                        var btn = CreateToggleButtonWithFont(name, icon, isOn, null, _themeBtnOnBgColor, showRemoveIcon: true);
                        _themeButtons[name] = btn;
                        
                        // Apply initial text/icon color based on state
                        var label = btn.Q<Label>(className: "filter-btn-label");
                        var iconEl = btn.Q<VisualElement>(className: "filter-btn-icon");
                        if (isOn)
                        {
                            SetFilterBgVisible(btn, true);
                            UpdateFilterButtonBgColor(btn, _themeBtnOnBgColor);
                            Color onCol = GetThemeOnColor(name);
                            if (label != null) label.style.color = onCol;
                            if (iconEl != null) iconEl.style.unityBackgroundImageTintColor = onCol;
                            UpdateFilterRemoveIcon(btn, true, onCol);
                        }
                        else
                        {
                            SetFilterBgVisible(btn, false);
                            UpdateFilterButtonBgColor(btn, _themeBtnOffBgColor);
                            Color offCol = GetThemeOffColor(name);
                            if (label != null) label.style.color = offCol;
                            if (iconEl != null) iconEl.style.unityBackgroundImageTintColor = offCol;
                            UpdateFilterRemoveIcon(btn, false, offCol);
                        }
                        
                        btn.clicked += () =>
                        {
                            ToggleTheme(name);
                            bool nowOn = _selectedThemes.Contains(name);
                            var lbl = btn.Q<Label>(className: "filter-btn-label");
                            var ico = btn.Q<VisualElement>(className: "filter-btn-icon");
                            if (nowOn)
                            {
                                btn.AddToClassList("filter-toggle-btn--active");
                                SetFilterBgVisible(btn, true);
                                UpdateFilterButtonBgColor(btn, _themeBtnOnBgColor);
                                Color onC = GetThemeOnColor(name);
                                if (lbl != null) lbl.style.color = onC;
                                if (ico != null) ico.style.unityBackgroundImageTintColor = onC;
                                UpdateFilterRemoveIcon(btn, true, onC);
                            }
                            else
                            {
                                btn.RemoveFromClassList("filter-toggle-btn--active");
                                SetFilterBgVisible(btn, false);
                                UpdateFilterButtonBgColor(btn, _themeBtnOffBgColor);
                                Color offC = GetThemeOffColor(name);
                                if (lbl != null) lbl.style.color = offC;
                                if (ico != null) ico.style.unityBackgroundImageTintColor = offC;
                                UpdateFilterRemoveIcon(btn, false, offC);
                            }
                            UpdateThemeAllNoneButtons();
                        };
                        container.Add(btn);
                        _themeFilterBtns.Add(btn);
                    }
                },
                out _themeAllBtn, out _themeNoneBtn, out _themeAllNoneContainer);
            
            UpdateAssetAllNoneButtons();
            UpdateThemeAllNoneButtons();
            UpdateLibraryAllNoneButtons();
            UpdatePriceAllNoneButtons();
            UpdateInstalledFilterButtons();
            
            // Apply per-category font sizes (buttons are built with _filterFontSize; override here)
            UpdateFilterFontSizesByCategory();
            
            // Debug: show per-filter asset counts if the option is on.
            ApplyFilterCounts();
            
            // Social links bar — pinned to bottom of filter section
            // Debug Options is only shown when the developer marker script is present in
            // the project (see SyntyDebugUnlock.cs). That file is kept in the Synty dev
            // project and excluded from the customer .unitypackage, so customers never see
            // debug options and there is nothing in the shipped build to spoof.
            if (IsDebugUnlocked())
            {
                AddForceDownloadDevButton(_filterSection);
                AddDebugOptionsButton(_filterSection);
            }
            AddSocialLinksBar(_filterSection);
        }
        
        // True if the developer debug-unlock marker type exists in any loaded assembly.
        // Located by name via reflection so the tool compiles fine whether or not the
        // marker script is present.
        private static bool IsDebugUnlocked()
        {
            // Scan ALL loaded assemblies — the SyntyDebugUnlock marker may live in Assembly-CSharp
            // (if it's a plain script under Assets/) rather than Assembly-CSharp-Editor, so a
            // qualified Type.GetType would miss it and wrongly hide/grey the dev menu.
            foreach (var asm in System.AppDomain.CurrentDomain.GetAssemblies())
            {
                try { if (asm.GetType("Synty.Passport.Dev.SyntyDebugUnlock") != null) return true; }
                catch { }
            }
            return false;
        }
        
        // Dev-only: force-downloads and installs the newest DEV build of the tool, regardless of
        // whether it's a higher version than what's installed. Sits above Debug Options.
        private void AddForceDownloadDevButton(VisualElement parent)
        {
            var btn = new Button();
            btn.text = "Force Download Dev";
            btn.name = "force-dev-btn";
            btn.style.marginLeft   = 8;
            btn.style.marginRight  = 8;
            btn.style.marginTop    = 4;
            btn.style.marginBottom = 4;
            btn.style.height = 26;
            btn.style.fontSize = 10;
            btn.style.backgroundColor = new Color(0f, 0.686f, 1f, 0.18f); // accent tint so it stands out
            btn.style.color = new Color(1f, 1f, 1f, 0.85f);
            btn.style.borderTopLeftRadius = 5;
            btn.style.borderTopRightRadius = 5;
            btn.style.borderBottomLeftRadius = 5;
            btn.style.borderBottomRightRadius = 5;
            btn.clicked += () =>
            {
                if (!EditorUtility.DisplayDialog("Force Download Dev Version",
                    "Download and install the newest DEV build of the Synty Importer, replacing the current version?",
                    "Download Dev", "Cancel")) return;
                SyntyCatalogBridge.ForceDownloadDev((ok, info) =>
                {
                    if (ok) Synty.Tools.SyntyLog.Info("Synty Importer DEV build installed, reloading...");
                    else EditorUtility.DisplayDialog("Force Download Dev Version",
                        $"Could not download the dev build:\n{info}", "OK");
                });
            };
            parent.Add(btn);
        }

        private void AddDebugOptionsButton(VisualElement parent)
        {
            var btn = new Button();
            btn.text = "Debug Options";
            btn.name = "debug-options-btn";
            btn.style.marginLeft   = 8;
            btn.style.marginRight  = 8;
            btn.style.marginTop    = 4;
            btn.style.marginBottom = 4;
            btn.style.height = 26;
            btn.style.fontSize = 11;
            btn.style.backgroundColor = new Color(1f, 1f, 1f, 0.06f);
            btn.style.color = new Color(1f, 1f, 1f, 0.5f);
            btn.style.borderTopLeftRadius = 5;
            btn.style.borderTopRightRadius = 5;
            btn.style.borderBottomLeftRadius = 5;
            btn.style.borderBottomRightRadius = 5;
            btn.style.borderTopWidth = 0;
            btn.style.borderBottomWidth = 0;
            btn.style.borderLeftWidth = 0;
            btn.style.borderRightWidth = 0;
            btn.clicked += OnDebugOptionsButtonClicked;
            parent.Add(btn);
        }
        
        private void AddSocialLinksBar(VisualElement parent)
        {
            // Vertical wrapper so the version line can sit directly under the social icons.
            var wrapper = new VisualElement();
            wrapper.name = "social-links-wrapper";
            wrapper.style.flexDirection = FlexDirection.Column;
            wrapper.style.alignItems = Align.Center;
            wrapper.style.flexShrink = 0;
            parent.Add(wrapper);
            
            var bar = new VisualElement();
            bar.name = "social-links-bar";
            bar.style.flexDirection = FlexDirection.Row;
            bar.style.justifyContent = Justify.Center;
            bar.style.alignItems = Align.Center;
            bar.style.paddingTop = 8;
            bar.style.paddingBottom = 4;
            bar.style.flexShrink = 0;
            wrapper.Add(bar);
            
            var links = new[]
            {
                ("Icon_Discord",   "https://discord.gg/syntystudios"),
                ("Icon_YouTube",   "https://www.youtube.com/@SyntyStudios"),
                ("Icon_Instagram", "https://www.instagram.com/synty.studios/"),
                ("Icon_Facebook",  "https://www.facebook.com/syntystudios"),
            };
            
            foreach (var (iconName, url) in links)
            {
                var capturedUrl = url;
                var btn = new VisualElement();
                btn.style.width = 28;
                btn.style.height = 28;
                btn.style.marginLeft = 3;
                btn.style.marginRight = 3;
                btn.style.borderTopLeftRadius = 6;
                btn.style.borderTopRightRadius = 6;
                btn.style.borderBottomLeftRadius = 6;
                btn.style.borderBottomRightRadius = 6;
                btn.style.backgroundColor = new Color(1f, 1f, 1f, 0.06f);
                btn.style.alignItems = Align.Center;
                btn.style.justifyContent = Justify.Center;
                btn.style.cursor = new StyleCursor(new UnityEngine.UIElements.Cursor());
                btn.style.transitionProperty = new List<StylePropertyName> {
                    new StylePropertyName("background-color"),
                    new StylePropertyName("scale")
                };
                btn.style.transitionDuration = new List<TimeValue> {
                    new TimeValue(120, TimeUnit.Millisecond),
                    new TimeValue(120, TimeUnit.Millisecond)
                };
                btn.style.transitionTimingFunction = new List<EasingFunction> {
                    new EasingFunction(EasingMode.EaseOut),
                    new EasingFunction(EasingMode.EaseOut)
                };
                
                var icon = new VisualElement();
                icon.style.width = 16;
                icon.style.height = 16;
                icon.style.SetBackgroundScaleToFit();
                icon.style.unityBackgroundImageTintColor = new Color(1f, 1f, 1f, 0.55f);
                icon.pickingMode = PickingMode.Ignore;
                var tex = LoadImage("Social", iconName);
                if (tex != null) icon.style.backgroundImage = new StyleBackground(tex);
                btn.Add(icon);
                
                btn.RegisterCallback<MouseEnterEvent>(_ => {
                    btn.style.backgroundColor = new Color(1f, 1f, 1f, 0.14f);
                    btn.style.scale = new Scale(new Vector3(1.1f, 1.1f, 1f));
                    icon.style.unityBackgroundImageTintColor = Color.white;
                });
                btn.RegisterCallback<MouseLeaveEvent>(_ => {
                    btn.style.backgroundColor = new Color(1f, 1f, 1f, 0.06f);
                    btn.style.scale = new Scale(Vector3.one);
                    icon.style.unityBackgroundImageTintColor = new Color(1f, 1f, 1f, 0.55f);
                });
                var capturedIconName = iconName;
                btn.RegisterCallback<MouseDownEvent>(_ => {
                    SyntyAnalytics.TrackExternalLink(capturedIconName.Replace("Icon_", ""), capturedUrl);
                    UnityEngine.Application.OpenURL(capturedUrl);
                });
                
                bar.Add(btn);
            }
            
            // Tool version line, centered under the social icons. Show the version captured from the
            // installed package's filename (what the admin panel derives from the .unitypackage name)
            // — the installer stores it in EditorPrefs. Fall back to the baked-in constant only when
            // that isn't present (e.g. a fresh manual install before the installer has run).
            string displayVersion = EditorPrefs.GetString("SyntyPassport_DisplayVersion", "");
            if (string.IsNullOrEmpty(displayVersion))
                displayVersion = Synty.Tools.SyntyToolVersion.VERSION;
            var versionLabel = new Label("v" + displayVersion);
            versionLabel.name = "tool-version-label";
            versionLabel.style.fontSize = 10;
            versionLabel.style.color = new Color(1f, 1f, 1f, 0.35f);
            versionLabel.style.unityTextAlign = TextAnchor.MiddleCenter;
            versionLabel.style.marginTop = 1;
            versionLabel.style.marginBottom = 6;
            versionLabel.pickingMode = PickingMode.Ignore;
            
            // Row: privacy-policy link on the left, version centered.
            var versionRow = new VisualElement();
            versionRow.style.flexDirection = FlexDirection.Row;
            versionRow.style.justifyContent = Justify.Center;
            versionRow.style.alignItems = Align.Center;
            
            var privacyLink = new Label("Privacy Policy");
            privacyLink.name = "privacy-link";
            privacyLink.style.fontSize = 10;
            privacyLink.style.color = new Color(1f, 1f, 1f, 0.35f);
            privacyLink.style.marginRight = 8;
            privacyLink.style.marginBottom = 6;
            privacyLink.style.marginTop = 1;
            privacyLink.AddToClassList("link-cursor");
            privacyLink.RegisterCallback<MouseEnterEvent>(evt => privacyLink.style.color = new Color(1f, 1f, 1f, 0.7f));
            privacyLink.RegisterCallback<MouseLeaveEvent>(evt => privacyLink.style.color = new Color(1f, 1f, 1f, 0.35f));
            privacyLink.RegisterCallback<MouseDownEvent>(evt => Application.OpenURL("https://syntystore.com/pages/privacy-policy"));
            
            versionRow.Add(privacyLink);
            versionRow.Add(versionLabel);
            wrapper.Add(versionRow);
        }
        
        // Styles a filter group's All/None button to match the grid's Select All/None pills
        // (same background, corner radius, padding, font, and hover) instead of the darker
        // .all-none-btn USS look.
        private void StyleFilterAllNoneLikeGrid(Button b)
        {
            b.style.fontSize = _selectBtnFontSize;
            b.style.paddingLeft = _selectBtnPaddingH;
            b.style.paddingRight = _selectBtnPaddingH;
            b.style.borderTopLeftRadius = _selectBtnRadius;
            b.style.borderTopRightRadius = _selectBtnRadius;
            b.style.borderBottomLeftRadius = _selectBtnRadius;
            b.style.borderBottomRightRadius = _selectBtnRadius;
            b.style.backgroundColor = _assetOptionsSelectBtnBg;
            b.style.color = _assetOptionsSelectBtnText;
            AddSelectBtnHover(b);
        }

        // Pulls the filter chevrons in against None (via the "scroll-tight" class) only while the
        // vertical scrollbar is showing, so they clear the floating bar; restores original position
        // when there's nothing to scroll.
        private void UpdateChevronScrollState()
        {
            if (_filterScrollRef == null) return;
            var scroller = _filterScrollRef.verticalScroller;
            bool scrolling = scroller != null
                && scroller.resolvedStyle.display != DisplayStyle.None
                && scroller.resolvedStyle.visibility != Visibility.Hidden
                && scroller.resolvedStyle.width > 1f;
            foreach (var ch in _filterChevrons)
            {
                if (ch == null) continue;
                if (scrolling) ch.AddToClassList("scroll-tight");
                else ch.RemoveFromClassList("scroll-tight");
                // Pull the whole header in 14px to clear the floating scrollbar ONLY while it's showing.
                // When it's off, full width is used so the title + All/None don't get squeezed/overlap.
                var hdr = ch.parent;
                if (hdr != null) hdr.style.marginRight = scrolling ? 14 : 0;
            }
        }

        private void AddFilterGroup(VisualElement parent, string title, bool hasAllNone, 
            System.Action onAll, System.Action onNone, System.Action<VisualElement> addButtons)
        {
            Button allBtn = null, noneBtn = null;
            VisualElement allNoneContainer = null;
            AddFilterGroup(parent, title, hasAllNone, onAll, onNone, addButtons, out allBtn, out noneBtn, out allNoneContainer);
        }
        
        private void AddFilterGroup(VisualElement parent, string title, bool hasAllNone,
            System.Action onAll, System.Action onNone, System.Action<VisualElement> addButtons,
            out Button allBtn, out Button noneBtn, out VisualElement allNoneContainer)
        {
            allBtn = null;
            noneBtn = null;
            allNoneContainer = null;
            
            var group = new VisualElement();
            group.name = $"filter-group-{title.ToLower().Replace(" ", "-")}";
            group.AddToClassList("filter-group");
            group.style.marginBottom = _filterGroupSpacing;
            parent.Add(group);
            
            // Header row
            var header = new VisualElement();
            header.name = "filter-header";
            header.AddToClassList("filter-header");
            group.Add(header);
            
            // Title
            var titleLabel = new Label(title);
            titleLabel.AddToClassList("filter-title");
            header.Add(titleLabel);
            _filterTitleLabels[group.name] = titleLabel;
            
            // Spacer to push everything else to the right
            var spacer = new VisualElement();
            spacer.style.flexGrow = 1;
            header.Add(spacer);
            
            // All/None buttons container (now before chevron)
            if (hasAllNone)
            {
                allNoneContainer = new VisualElement();
                allNoneContainer.AddToClassList("all-none-container");
                allNoneContainer.style.marginTop = _allNoneBtnY;
                header.Add(allNoneContainer);
                
                allBtn = new Button();
                allBtn.text = "All";
                allBtn.AddToClassList("all-none-btn");
                allBtn.style.marginRight = _allNoneBtnSpacing;
                StyleFilterAllNoneLikeGrid(allBtn);
                allBtn.clicked += () => onAll?.Invoke();
                allNoneContainer.Add(allBtn);
                
                noneBtn = new Button();
                noneBtn.text = "None";
                noneBtn.AddToClassList("all-none-btn");
                StyleFilterAllNoneLikeGrid(noneBtn);
                noneBtn.clicked += () => onNone?.Invoke();
                allNoneContainer.Add(noneBtn);
            }
            
            // Chevron (on far right, after All/None)
            var chevronContainer = new VisualElement();
            chevronContainer.AddToClassList("chevron-container");
            header.Add(chevronContainer);
            
            // Use image-based chevron if textures loaded, otherwise use text fallback
            VisualElement chevron;
            Label chevronLabel = null;
            
            if (_dropdownArrowDown != null)
            {
                chevron = new VisualElement();
                chevron.AddToClassList("filter-chevron");
                chevron.pickingMode = PickingMode.Ignore;
                chevron.style.width = 12;
                chevron.style.height = 12;
                chevron.style.backgroundImage = new StyleBackground(_dropdownArrowDown);
            }
            else
            {
                // Fallback to text chevron if image not found
                chevronLabel = new Label("▼");
                chevronLabel.style.fontSize = 10;
                chevronLabel.style.color = new Color(0.53f, 0.53f, 0.53f);
                chevron = chevronLabel;
            }
            chevronContainer.Add(chevron);
            _filterChevrons.Add(chevronContainer);
            
            // Content container (collapsible)
            var content = new VisualElement();
            content.name = "filter-group-content";
            content.AddToClassList("filter-group-content");
            group.Add(content);
            
            // Add the buttons
            addButtons?.Invoke(content);
            
            // Toggle collapse on chevron click
            bool isExpanded = true;
            chevronContainer.RegisterCallback<ClickEvent>(evt =>
            {
                isExpanded = !isExpanded;
                content.style.display = isExpanded ? DisplayStyle.Flex : DisplayStyle.None;
                
                if (_dropdownArrowDown != null && _dropdownArrowUp != null)
                {
                    chevron.style.backgroundImage = new StyleBackground(isExpanded ? _dropdownArrowDown : _dropdownArrowUp);
                }
                else if (chevronLabel != null)
                {
                    chevronLabel.text = isExpanded ? "▼" : "▲";
                }
            });

            // Filter titles are sized statically via the .filter-title USS rule (8px) so they fit
            // without a dynamic per-title shrink — the dynamic version caused recursive-layout warnings.
        }
        
        private Button CreateToggleButton(string text, string iconName, bool isOn, Color? activeColor = null, Color? hoverColor = null, bool showRemoveIcon = false)
        {
            var btn = new Button();
            btn.AddToClassList("filter-toggle-btn");
            btn.style.backgroundColor = Color.clear; // Clear background, we use images
            btn.style.overflow = Overflow.Visible; // Allow absolute positioned children to show
            
            // Store the active color for this button (used by asset type buttons)
            Color btnActiveColor = activeColor ?? _themeBtnOnBgColor;
            btn.userData = btnActiveColor;
            Color hoverTint = hoverColor ?? btnActiveColor;
            
            Color currentTintColor = isOn ? btnActiveColor : _themeBtnOffBgColor;
            
            // Check if we have the 3-part images, otherwise fall back to single image
            bool use3PartBg = _filterBtnEnd != null && _filterBtnMiddle != null;
            
            // End aspect ratio — width must equal height * aspect to stay non-distorted
            float endAspect = (use3PartBg) ? (float)_filterBtnEnd.width / _filterBtnEnd.height : 0.5f;
            float initialEndWidth = Mathf.Ceil(32f * endAspect); // ceil avoids sub-pixel gap at seam
            
            // Track end elements so we can resize them dynamically
            VisualElement leftEnd = null, rightEnd = null;
            VisualElement leftEndHover = null, rightEndHover = null;
            
            if (use3PartBg)
            {
                // Create 3-part background container
                var bgContainer = new VisualElement();
                bgContainer.name = "filter-btn-bg";
                bgContainer.style.position = Position.Absolute;
                bgContainer.style.left = 0;
                bgContainer.style.right = 0;
                bgContainer.style.top = 0;
                bgContainer.style.bottom = 0;
                bgContainer.style.flexDirection = FlexDirection.Row;
                bgContainer.style.alignItems = Align.Stretch;
                bgContainer.style.overflow = Overflow.Hidden;
                bgContainer.pickingMode = PickingMode.Ignore;
                
                // Left end
                leftEnd = new VisualElement();
                leftEnd.name = "filter-btn-left";
                leftEnd.pickingMode = PickingMode.Ignore;
                leftEnd.style.flexShrink = 0;
                leftEnd.style.width = initialEndWidth;
                leftEnd.style.height = Length.Percent(100);
                leftEnd.style.backgroundImage = new StyleBackground(_filterBtnEnd);
                leftEnd.style.SetBackgroundStretchToFill();
                leftEnd.style.unityBackgroundImageTintColor = currentTintColor;
                bgContainer.Add(leftEnd);
                
                // Middle (stretches)
                var middle = new VisualElement();
                middle.name = "filter-btn-middle";
                middle.pickingMode = PickingMode.Ignore;
                middle.style.flexGrow = 1;
                middle.style.flexShrink = 0;
                middle.style.height = Length.Percent(100);
                middle.style.marginLeft = -1;
                middle.style.marginRight = -1;
                middle.style.backgroundImage = new StyleBackground(_filterBtnMiddle);
                middle.style.SetBackgroundStretchToFill();
                middle.style.unityBackgroundImageTintColor = currentTintColor;
                bgContainer.Add(middle);
                
                // Right end (flipped horizontally)
                rightEnd = new VisualElement();
                rightEnd.name = "filter-btn-right";
                rightEnd.pickingMode = PickingMode.Ignore;
                rightEnd.style.flexShrink = 0;
                rightEnd.style.width = initialEndWidth;
                rightEnd.style.height = Length.Percent(100);
                rightEnd.style.backgroundImage = new StyleBackground(_filterBtnEnd);
                rightEnd.style.SetBackgroundStretchToFill();
                rightEnd.style.scale = new Scale(new Vector3(-1, 1, 1)); // Flip horizontally
                rightEnd.style.unityBackgroundImageTintColor = currentTintColor;
                bgContainer.Add(rightEnd);
                
                btn.Add(bgContainer);
            }
            else if (_filterBtnBg != null)
            {
                // Fallback to single 9-slice image
                btn.style.backgroundImage = new StyleBackground(_filterBtnBg);
                btn.style.unityBackgroundImageTintColor = currentTintColor;
            }
            
            // Background always visible — color changes indicate ON/OFF state
            var bgContainerRef = btn.Q<VisualElement>("filter-btn-bg");
            if (bgContainerRef != null)
                bgContainerRef.style.display = DisplayStyle.Flex;
            
            if (isOn)
                btn.AddToClassList("filter-toggle-btn--active");
            
            // Hover overlay
            VisualElement hoverContainer = null;
            if (use3PartBg && _filterBtnEndSelected != null && _filterBtnMiddleSelected != null)
            {
                // 3-part hover overlay
                hoverContainer = new VisualElement();
                hoverContainer.name = "filter-btn-hover";
                hoverContainer.style.position = Position.Absolute;
                hoverContainer.style.left = 0;
                hoverContainer.style.right = 0;
                hoverContainer.style.top = 0;
                hoverContainer.style.bottom = 0;
                hoverContainer.style.flexDirection = FlexDirection.Row;
                hoverContainer.style.alignItems = Align.Stretch;
                hoverContainer.style.overflow = Overflow.Hidden;
                hoverContainer.style.display = DisplayStyle.None;
                hoverContainer.pickingMode = PickingMode.Ignore;
                
                // Left end selected
                leftEndHover = new VisualElement();
                leftEndHover.pickingMode = PickingMode.Ignore;
                leftEndHover.style.backgroundImage = new StyleBackground(_filterBtnEndSelected);
                leftEndHover.style.unityBackgroundImageTintColor = Color.white;
                leftEndHover.style.flexShrink = 0;
                leftEndHover.style.width = initialEndWidth;
                leftEndHover.style.height = Length.Percent(100);
                leftEndHover.style.SetBackgroundStretchToFill();
                hoverContainer.Add(leftEndHover);
                
                // Middle selected (stretches)
                var middleHover = new VisualElement();
                middleHover.pickingMode = PickingMode.Ignore;
                middleHover.style.flexGrow = 1;
                middleHover.style.flexShrink = 0;
                middleHover.style.height = Length.Percent(100);
                middleHover.style.marginLeft = -1;
                middleHover.style.marginRight = -1;
                middleHover.style.backgroundImage = new StyleBackground(_filterBtnMiddleSelected);
                middleHover.style.unityBackgroundImageTintColor = Color.white;
                middleHover.style.SetBackgroundStretchToFill();
                hoverContainer.Add(middleHover);
                
                // Right end selected (flipped)
                rightEndHover = new VisualElement();
                rightEndHover.pickingMode = PickingMode.Ignore;
                rightEndHover.style.backgroundImage = new StyleBackground(_filterBtnEndSelected);
                rightEndHover.style.unityBackgroundImageTintColor = Color.white;
                rightEndHover.style.flexShrink = 0;
                rightEndHover.style.width = initialEndWidth;
                rightEndHover.style.height = Length.Percent(100);
                rightEndHover.style.SetBackgroundStretchToFill();
                rightEndHover.style.scale = new Scale(new Vector3(-1, 1, 1)); // Flip horizontally
                hoverContainer.Add(rightEndHover);
                
                btn.Add(hoverContainer);
            }
            else if (_filterBtnSelected != null)
            {
                // Fallback to single image hover
                hoverContainer = new VisualElement();
                hoverContainer.name = "filter-btn-hover";
                hoverContainer.AddToClassList("filter-btn-hover-overlay");
                hoverContainer.style.backgroundImage = new StyleBackground(_filterBtnSelected);
                hoverContainer.style.display = DisplayStyle.None;
                hoverContainer.pickingMode = PickingMode.Ignore;
                btn.Add(hoverContainer);
            }
            
            // Dynamically keep end widths = height * endAspect so caps stay perfectly circular.
            // We register on bgContainer (not btn) so we get its actual resolved height directly.
            if (use3PartBg && leftEnd != null && rightEnd != null)
            {
                var capturedLeft = leftEnd;
                var capturedRight = rightEnd;
                var capturedLeftHover = leftEndHover;
                var capturedRightHover = rightEndHover;
                float capturedAspect = endAspect;
                
                btn.RegisterCallback<GeometryChangedEvent>(evt =>
                {
                    float h = evt.newRect.height;
                    if (h <= 0) return;
                    float w = Mathf.Ceil(h * capturedAspect);
                    capturedLeft.style.width = w;
                    capturedRight.style.width = w;
                    if (capturedLeftHover != null)  capturedLeftHover.style.width = w;
                    if (capturedRightHover != null) capturedRightHover.style.width = w;
                });
            }
            
            // Icon
            var icon = new VisualElement();
            icon.AddToClassList("filter-btn-icon");
            icon.pickingMode = PickingMode.Ignore;
            var iconTex = string.IsNullOrEmpty(iconName) ? null 
                : LoadImage("Icons/Themes", iconName) 
                ?? LoadImage("Icons/AssetTypes", iconName) 
                ?? LoadImage("Icons/Misc", iconName)
                ?? LoadImage("Icons", iconName);
            if (iconTex != null) icon.style.backgroundImage = new StyleBackground(iconTex);
            btn.Add(icon);
            
            // Label
            var label = new Label(text);
            label.AddToClassList("filter-btn-label");
            label.pickingMode = PickingMode.Ignore;
            label.style.fontSize = _filterFontSize;
            label.style.marginTop = _filterBtnTextY;
            btn.Add(label);
            
            // Optional remove (X) icon on the right — appears on theme/type filter buttons so the
            // user can deselect that filter. Excluded from the Synty Pass button.
            if (showRemoveIcon)
            {
                var removeIcon = new VisualElement();
                removeIcon.name = "filter-btn-remove";
                removeIcon.AddToClassList("filter-btn-remove");
                removeIcon.pickingMode = PickingMode.Ignore; // the whole button handles the click
                // Absolutely positioned on the right edge so "From Right" directly controls its
                // distance from the edge, independent of the button's flex content layout.
                removeIcon.style.position = Position.Absolute;
                removeIcon.style.right = _filterRemoveIconRightPad;
                removeIcon.style.top = Length.Percent(50);
                removeIcon.style.translate = new Translate(0, Length.Percent(-50)); // vertical centre
                removeIcon.style.marginTop = _filterRemoveIconY; // nudge up/down from centre
                removeIcon.style.width = _filterRemoveIconSize;
                removeIcon.style.height = _filterRemoveIconSize;
                removeIcon.style.flexShrink = 0;
                var removeTex = LoadImage("Icons/Misc", isOn ? "Remove_Icon" : "Add_Icon");
                if (removeTex != null)
                {
                    removeIcon.style.backgroundImage = new StyleBackground(removeTex);
                    removeIcon.style.SetBackgroundStretchToFill();
                }
                // Initial tint matches the label colour; the per-state update refines it on refresh.
                var lblCol = label.style.color.keyword == StyleKeyword.Undefined ? label.style.color.value : Color.white;
                removeIcon.style.unityBackgroundImageTintColor = lblCol;
                btn.Add(removeIcon);
                // Reserve space on the right so the label doesn't sit under the absolute icon.
                btn.style.paddingRight = _filterBtnPaddingH + _filterRemoveIconExtraWidth + _filterRemoveIconSize;
            }
            
            // Hover overlay — added LAST so it renders above bg (and below icon/label which are in-flow)
            // Re-add hoverContainer here if created above
            if (hoverContainer != null)
            {
                // Remove from btn (was added before icon/label) and re-add after
                btn.Remove(hoverContainer);
                // Re-insert between bg container and icon: just re-add (UI Toolkit renders in order)
                // Actually we want hover ABOVE bg but BELOW icon/label — insert at index 1
                // bg is index 0, we insert hover at 1, icon/label come after
                btn.Insert(1, hoverContainer);
            }
            
            // Register hover events
            if (hoverContainer != null)
            {
                var capturedHover = hoverContainer;
                btn.RegisterCallback<MouseEnterEvent>(evt => {
                    capturedHover.style.display = DisplayStyle.Flex;
                });
                btn.RegisterCallback<MouseLeaveEvent>(evt => {
                    capturedHover.style.display = DisplayStyle.None;
                });
            }
            
            return btn;
        }
        
        private Button CreateToggleButtonWithFont(string text, string iconName, bool isOn, Color? activeColor = null, Color? hoverColor = null, bool showRemoveIcon = false)
        {
            var btn = CreateToggleButton(text, iconName, isOn, activeColor, hoverColor, showRemoveIcon);
            
            var label = btn.Q<Label>(className: "filter-btn-label");
            if (label != null && _titleFont != null)
                label.style.unityFontDefinition = FontDefinition.FromFont(_titleFont);
            
            return btn;
        }
        
        // Show or hide the 3-part background container on a filter button
        private void SetFilterBgVisible(Button btn, bool visible)
        {
            var bgContainer = btn.Q<VisualElement>("filter-btn-bg");
            if (bgContainer != null)
            {
                bgContainer.style.display = DisplayStyle.Flex;
            }
        }
        
        // Helper method to update filter button background color
        private void UpdateFilterButtonBgColor(Button btn, Color color)
        {
            // Try 3-part background first
            var bgContainer = btn.Q<VisualElement>("filter-btn-bg");
            if (bgContainer != null)
            {
                var leftEnd = bgContainer.Q<VisualElement>("filter-btn-left");
                var middle = bgContainer.Q<VisualElement>("filter-btn-middle");
                var rightEnd = bgContainer.Q<VisualElement>("filter-btn-right");
                
                if (leftEnd != null) leftEnd.style.unityBackgroundImageTintColor = color;
                if (middle != null) middle.style.unityBackgroundImageTintColor = color;
                if (rightEnd != null) rightEnd.style.unityBackgroundImageTintColor = color;
            }
            else
            {
                // Fallback to single image tint
                btn.style.unityBackgroundImageTintColor = color;
            }
        }
        
        // Used for theme buttons
        // Swaps the right-side filter icon between Remove (X, when selected) and Add (+, when not),
        // and tints it to match the button's current text colour.
        private void UpdateFilterRemoveIcon(Button btn, bool isOn, Color? textColor = null)
        {
            var rem = btn.Q<VisualElement>("filter-btn-remove");
            if (rem == null) return;
            var tex = LoadImage("Icons/Misc", isOn ? "Remove_Icon" : "Add_Icon");
            if (tex != null) rem.style.backgroundImage = new StyleBackground(tex);
            if (textColor.HasValue) rem.style.unityBackgroundImageTintColor = textColor.Value;
        }

        private void UpdateToggleButtonState(Button btn, bool isOn)
        {
            var label = btn.Q<Label>(className: "filter-btn-label");
            var icon = btn.Q<VisualElement>(className: "filter-btn-icon");
            
            if (isOn)
            {
                btn.AddToClassList("filter-toggle-btn--active");
                SetFilterBgVisible(btn, true);
                UpdateFilterButtonBgColor(btn, _themeBtnOnBgColor);
                if (label != null) label.style.color = _themeBtnOnTextColor;
                if (icon != null) icon.style.unityBackgroundImageTintColor = _themeBtnOnTextColor;
                UpdateFilterRemoveIcon(btn, true, _themeBtnOnTextColor);
            }
            else
            {
                btn.RemoveFromClassList("filter-toggle-btn--active");
                SetFilterBgVisible(btn, false);
                UpdateFilterButtonBgColor(btn, _themeBtnOffBgColor);
                if (label != null) label.style.color = _themeBtnOffTextColor;
                if (icon != null) icon.style.unityBackgroundImageTintColor = _themeBtnOffTextColor;
                UpdateFilterRemoveIcon(btn, false, _themeBtnOffTextColor);
            }
        }
        
        // Used for asset type buttons (POLYGON, SIDEKICK, etc.)
        private void UpdateAssetToggleButtonState(Button btn, bool isOn)
        {
            // Get type name from the label text
            var label = btn.Q<Label>(className: "filter-btn-label");
            var icon = btn.Q<VisualElement>(className: "filter-btn-icon");
            string typeName = label?.text ?? "";
            
            // Get per-type colors
            var (onBg, offBg, onText, offText) = GetAssetFilterColors(typeName);
            
            if (isOn)
            {
                btn.AddToClassList("filter-toggle-btn--active");
                SetFilterBgVisible(btn, true);
                UpdateFilterButtonBgColor(btn, onBg);
                if (label != null) label.style.color = onText;
                if (icon != null) icon.style.unityBackgroundImageTintColor = onText;
                UpdateFilterRemoveIcon(btn, true, onText);
            }
            else
            {
                btn.RemoveFromClassList("filter-toggle-btn--active");
                SetFilterBgVisible(btn, false);
                UpdateFilterButtonBgColor(btn, offBg);
                if (label != null) label.style.color = offText;
                if (icon != null) icon.style.unityBackgroundImageTintColor = offText;
                UpdateFilterRemoveIcon(btn, false, offText);
            }
        }
        
