                }
                if (label != null) label.style.color = _licenseBtnOffTextColor;
                if (icon  != null) icon.style.unityBackgroundImageTintColor = _licenseBtnOffTextColor;
                if (_syntyPassFilterImage != null) _syntyPassFilterImage.style.unityBackgroundImageTintColor = _syntyPassFilterOffColor;
                UpdateFilterRemoveIcon(btn, false, _licenseBtnOffTextColor);
            }
        }
        
        private void UpdateProgressBarForSyntyPass(bool isSyntyPass)
        {
            if (_progressBarFill == null || _percentageText == null) return;
            
            if (isSyntyPass)
            {
                // Set ease-in for going up to 100%, fast transition
                _progressBarFill.style.transitionDuration = new List<TimeValue> { new TimeValue(400, TimeUnit.Millisecond) };
                _progressBarFill.style.transitionTimingFunction = new List<EasingFunction> { 
                    new EasingFunction(EasingMode.EaseIn)
                };
                _percentageText.style.transitionProperty = new List<StylePropertyName> { new StylePropertyName("color") };
                _percentageText.style.transitionDuration = new List<TimeValue> { new TimeValue(400, TimeUnit.Millisecond) };
                _percentageText.style.transitionTimingFunction = new List<EasingFunction> { 
                    new EasingFunction(EasingMode.EaseIn)
                };
                if (_percentageSymbol != null)
                {
                    _percentageSymbol.style.transitionProperty = new List<StylePropertyName> { new StylePropertyName("color") };
                    _percentageSymbol.style.transitionDuration = new List<TimeValue> { new TimeValue(400, TimeUnit.Millisecond) };
                    _percentageSymbol.style.transitionTimingFunction = new List<EasingFunction> { 
                        new EasingFunction(EasingMode.EaseIn)
                    };
                }
                
                // Animate to 100% and synty pass color
                if (_progressBarContainer != null) _progressBarContainer.style.display = DisplayStyle.Flex;
                if (_progressBarBgTrack != null) _progressBarBgTrack.style.display = DisplayStyle.Flex;
                _progressBarFill.style.display = DisplayStyle.Flex;
                if (_progressBarFillRight != null) _progressBarFillRight.style.display = DisplayStyle.Flex;
                if (_percentageTextContainer != null) _percentageTextContainer.style.display = DisplayStyle.Flex;
                _progressBarFill.style.width = Length.Percent(100);
                // Ease bar fill color
                SetBarFillTransitions(_progressBarFillLeft, _progressBarFillMid, _progressBarFillRight, 400, EasingMode.EaseIn);
                if (_barGradientEnabled)
                    UpdateBarGradientForState(true, false);
                else
                    SetBarFillTint(_progressBarFillLeft, _progressBarFillMid, _progressBarFillRight, _syntyPassColor);
                _percentageText.style.color = _syntyPassColor;
                if (_percentageSymbol != null)
                    _percentageSymbol.style.color = _syntyPassColor;
                
                // Animate percentage text by tracking the bar's actual resolved width each frame
                AnimatePercentageTextFromBar((int)_currentPercentage, 100, true, true);
                
                // Restore normal transition duration after animation
                var fillRef2 = _progressBarFill;
                var textRef2 = _percentageText;
                var symRef2 = _percentageSymbol;
                var fillL2 = _progressBarFillLeft;
                var fillM2 = _progressBarFillMid;
                var fillR2 = _progressBarFillRight;
                EditorApplication.delayCall += () => {
                    if (fillRef2 != null)
                        fillRef2.style.transitionDuration = new List<TimeValue> { new TimeValue(400, TimeUnit.Millisecond) };
                    if (textRef2 != null)
                        textRef2.style.transitionDuration = new List<TimeValue> { new TimeValue(400, TimeUnit.Millisecond) };
                    if (symRef2 != null)
                        symRef2.style.transitionDuration = new List<TimeValue> { new TimeValue(400, TimeUnit.Millisecond) };
                    SetBarFillTransitions(fillL2, fillM2, fillR2, 400, EasingMode.EaseOut);
                };
            }
            else
            {
                // Set ease-out for going down, 1s duration
                _progressBarFill.style.transitionDuration = new List<TimeValue> { new TimeValue(1000, TimeUnit.Millisecond) };
                _progressBarFill.style.transitionTimingFunction = new List<EasingFunction> { 
                    new EasingFunction(EasingMode.EaseOut)
                };
                _percentageText.style.transitionProperty = new List<StylePropertyName> { new StylePropertyName("color") };
                _percentageText.style.transitionDuration = new List<TimeValue> { new TimeValue(1000, TimeUnit.Millisecond) };
                _percentageText.style.transitionTimingFunction = new List<EasingFunction> { 
                    new EasingFunction(EasingMode.EaseOut)
                };
                if (_percentageSymbol != null)
                {
                    _percentageSymbol.style.transitionProperty = new List<StylePropertyName> { new StylePropertyName("color") };
                    _percentageSymbol.style.transitionDuration = new List<TimeValue> { new TimeValue(1000, TimeUnit.Millisecond) };
                    _percentageSymbol.style.transitionTimingFunction = new List<EasingFunction> { 
                        new EasingFunction(EasingMode.EaseOut)
                    };
                }
                
                // Reset scale if it was popped
                _percentageText.style.scale = new Scale(Vector3.one);
                
                // Animate back to original percentage and accent color
                SetProgressBarPercent(_currentPercentage);
                // Ease bar fill color
                SetBarFillTransitions(_progressBarFillLeft, _progressBarFillMid, _progressBarFillRight, 1000, EasingMode.EaseOut);
                if (_barGradientEnabled)
                    UpdateBarGradientForState(false, false);
                else
                    SetBarFillTint(_progressBarFillLeft, _progressBarFillMid, _progressBarFillRight, _accentColor);
                _percentageText.style.color = _percentageTextColor;
                if (_percentageSymbol != null)
                    _percentageSymbol.style.color = _percentageSymColor;
                
                // Animate percentage text by tracking the bar's actual resolved width each frame
                AnimatePercentageTextFromBar(100, (int)_currentPercentage, false, false);
                
                // Restore normal transition duration after animation
                var fillRef = _progressBarFill;
                var textRef = _percentageText;
                var symRef = _percentageSymbol;
                var fillL = _progressBarFillLeft;
                var fillM = _progressBarFillMid;
                var fillR = _progressBarFillRight;
                EditorApplication.delayCall += () => {
                    if (fillRef != null)
                        fillRef.style.transitionDuration = new List<TimeValue> { new TimeValue(400, TimeUnit.Millisecond) };
                    if (textRef != null)
                        textRef.style.transitionDuration = new List<TimeValue> { new TimeValue(400, TimeUnit.Millisecond) };
                    if (symRef != null)
                        symRef.style.transitionDuration = new List<TimeValue> { new TimeValue(400, TimeUnit.Millisecond) };
                    SetBarFillTransitions(fillL, fillM, fillR, 400, EasingMode.EaseOut);
                };
            }
        }
        
        // Stores owned state per-item before Synty Pass is turned on, so we can restore on toggle off
        private Dictionary<int, bool> _prePassOwnedStates = new Dictionary<int, bool>();
        private HashSet<int> _syntyPassChangedAssets = new HashSet<int>(); // indices of assets that actually changed when Synty Pass turned ON
        private float _syntyPassOnStaggerMs  = 50f;  // ms delay between each asset turning ON
        private float _syntyPassOffStaggerMs = 10f;  // ms delay between each asset turning OFF
        private float _syntyPassOnDecay      = 0.85f; // multiplier applied to each step's delay (< 1 = faster, > 1 = slower)
        private float _syntyPassOnPopScale   = 1.08f; // scale to pop button to when it turns owned
        private float _syntyPassOnPopMs      = 80f;  // duration of pop up in ms
        private int   _syntyPassGeneration   = 0;    // incremented on toggle to instantly cancel all stale update callbacks
        
        // Single-scheduler queue — avoids registering hundreds of update delegates
        private struct StaggerEntry { public double fireAt; public System.Action action; }
        private List<StaggerEntry> _staggerQueue = new List<StaggerEntry>();
        private bool _staggerSchedulerActive = false;
        
        private void EnqueueStagger(double fireAt, System.Action action)
        {
            _staggerQueue.Add(new StaggerEntry { fireAt = fireAt, action = action });
            if (!_staggerSchedulerActive)
            {
                _staggerSchedulerActive = true;
                EditorApplication.update += RunStaggerQueue;
            }
        }
        
        private void RunStaggerQueue()
        {
            if (_reloadingDomain || !this) { EditorApplication.update -= RunStaggerQueue; _staggerSchedulerActive = false; return; }
            double now = EditorApplication.timeSinceStartup;
            for (int i = _staggerQueue.Count - 1; i >= 0; i--)
            {
                if (now >= _staggerQueue[i].fireAt)
                {
                    var entry = _staggerQueue[i];
                    _staggerQueue.RemoveAt(i);
                    entry.action?.Invoke();
                }
            }
            if (_staggerQueue.Count == 0)
            {
                EditorApplication.update -= RunStaggerQueue;
                _staggerSchedulerActive = false;
            }
        }
        
        private void ClearStaggerQueue()
        {
            _staggerQueue.Clear();
            if (_staggerSchedulerActive)
            {
                EditorApplication.update -= RunStaggerQueue;
                _staggerSchedulerActive = false;
            }
        }
                private void ApplySyntyPassOwnership(bool syntyPassOn)
        {
            // Cancel any in-progress stagger and start fresh
            ClearStaggerQueue();
            int gen = ++_syntyPassGeneration;
            
            // Toggle library filter visibility immediately
            if (_libraryFilterGroup != null)
            {
                if (syntyPassOn)
                    SelectAllLibrary();
                _libraryFilterGroup.style.display = syntyPassOn ? DisplayStyle.None : DisplayStyle.Flex;
            }
            
            if (syntyPassOn)
            {
                // Save current states AND track which assets actually change
                _prePassOwnedStates.Clear();
                _syntyPassChangedAssets.Clear();
                for (int i = 0; i < _assetItems.Count; i++)
                {
                    bool currentlyOwned = _assetItems[i].getOwned();
                    _prePassOwnedStates[i] = currentlyOwned;
                    if (!currentlyOwned) _syntyPassChangedAssets.Add(i);
                }
                
                // Capture pre-pass percentage for bar animation starting point
                int prePassOwned = 0;
                int totalCount = _assetItems.Count;
                for (int i = 0; i < totalCount; i++)
                {
                    if (_assetPackMapping.TryGetValue(i, out var pack))
                    {
                        if (SyntyStoreService.Instance.OwnedProductHandles.Contains(pack.packName))
                            prePassOwned++;
                    }
                }
                _currentPercentage = totalCount > 0 ? Mathf.Round((float)prePassOwned / totalCount * 100f) : 0f;
                
                // Update labels and kick off bar animation immediately
                if (_ownedCountLabel != null) _ownedCountLabel.text = totalCount.ToString();
                if (_totalCountLabel != null) _totalCountLabel.text = $"/{totalCount}";
                UpdateDownloadBar();
                UpdateProgressBarForSyntyPass(true);
                
                // Apply ownership and set the sort order up front, so the list reorders at the
                // START of the transition. The stagger below is then just a scale-pop flourish.
                foreach (var ci in _syntyPassChangedAssets)
                    if (ci < _assetItems.Count) _assetItems[ci].setOwned(true);
                UpdateCollectionCounts();
                AutoSortOnSale();
                FilterAssets();
                UpdateDownloadBar();
                
                // Stagger only the assets that actually change — no point popping already-owned ones
                var changedList = new List<int>(_syntyPassChangedAssets);
                // Sort by current visual order (top-left to bottom-right)
                if (_assetContent != null)
                    changedList.Sort((a, b) => _assetContent.IndexOf(_assetItems[a].button).CompareTo(_assetContent.IndexOf(_assetItems[b].button)));
                double cumulative = 0.0;
                double stepMs = _syntyPassOnStaggerMs;
                double startTime = EditorApplication.timeSinceStartup;
                float popScale   = _syntyPassOnPopScale;
                float popMs      = _syntyPassOnPopMs;
                
                // Don't show TypeBackground immediately — let stagger handle all visual changes together
                // via setOwned(true) which updates type bg, gradient, icon, and buttons in sync
                
                for (int n = 0; n < changedList.Count; n++)
                {
                    int idx = changedList[n];
                    double fireAt = startTime + cumulative / 1000.0;
                    cumulative += stepMs;
                    stepMs *= _syntyPassOnDecay;
                    if (stepMs < 0.5) stepMs = 0.5;
                    int capturedGen = gen;
                    
                    EnqueueStagger(fireAt, () =>
                    {
                        if (capturedGen != _syntyPassGeneration || !_licenseSyntyPass) return;
                        if (idx >= _assetItems.Count) return;
                        
                        var visual = _assetItems[idx].button.Q("asset-btn-visual");
                        if (visual == null) return;
                        visual.style.transitionDuration = new List<TimeValue> { new TimeValue(popMs, TimeUnit.Millisecond) };
                        visual.style.transitionTimingFunction = new List<EasingFunction> { new EasingFunction(EasingMode.EaseOut) };
                        float bs = GetBtnBaseScale();
                        visual.style.scale = new Scale(new Vector3(popScale * bs, popScale * bs, 1f));
                        
                        double returnAt = EditorApplication.timeSinceStartup + popMs / 1000.0;
                        EnqueueStagger(returnAt, () =>
                        {
                            if (capturedGen != _syntyPassGeneration) return;
                            visual.style.transitionDuration = new List<TimeValue> { new TimeValue(popMs * 1.5f, TimeUnit.Millisecond) };
                            visual.style.transitionTimingFunction = new List<EasingFunction> { new EasingFunction(EasingMode.EaseIn) };
                            float bs2 = GetBtnBaseScale();
                            visual.style.scale = new Scale(new Vector3(bs2, bs2, 1f));
                        });
                    });
                }
            }
            else
            {
                // SyntyPass OFF — revert to real individual ownership
                // Check each asset against OwnedProductHandles
                var changedIndices = new List<int>();
                int ownedCount = 0;
                
                for (int i = 0; i < _assetItems.Count; i++)
                {
                    bool individuallyOwned = false;
                    
                    // Check if this asset is individually owned via order history
                    // Don't count IsInstalled here — assets installed via SyntyPass should
                    // revert to not-owned when the pass filter is off
                    if (_assetPackMapping.TryGetValue(i, out var pack))
                    {
                        individuallyOwned = SyntyStoreService.Instance.OwnedProductHandles.Contains(pack.packName);
                    }
                    
                    if (individuallyOwned)
                    {
                        ownedCount++;
                    }
                    else if (_assetItems[i].getOwned())
                    {
                        // This asset was owned via SyntyPass but not individually — revert it
                        changedIndices.Add(i);
                    }
                }
                
                _syntyPassChangedAssets.Clear();
                _prePassOwnedStates.Clear();
                
                int totalCount = _assetItems.Count;
                _currentPercentage = totalCount > 0 ? Mathf.Round((float)ownedCount / totalCount * 100f) : 0f;
                if (_ownedCountLabel != null) _ownedCountLabel.text = ownedCount.ToString();
                if (_totalCountLabel != null) _totalCountLabel.text = $"/{totalCount}";
                
                // Sort by visual order for stagger animation
                if (_assetContent != null)
                    changedIndices.Sort((a, b) => _assetContent.IndexOf(_assetItems[a].button).CompareTo(_assetContent.IndexOf(_assetItems[b].button)));
                
                int capturedGen = gen;
                EditorApplication.delayCall += () =>
                {
                    if (!this || capturedGen != _syntyPassGeneration) return;
                    UpdateProgressBarForSyntyPass(false);
                    UpdateDownloadBar();
                    
                    // Apply the revert and set the sort order up front, so the list reorders at the
                    // START of the transition. The stagger below is then just a scale-pop flourish.
                    foreach (var ci in changedIndices)
                        if (ci < _assetItems.Count)
                        {
                            if (_assetItems[ci].getSelected()) _assetItems[ci].setSelected(false);
                            _assetItems[ci].setOwned(false);
                        }
                    UpdateCollectionCounts();
                    AutoSortOnSale();
                    FilterAssets();
                    UpdateDownloadBar();
                    UpdateSaleBadgeVisibility();
                    
                    // Re-order the changed list by the NEW visual order so the pop wave flows naturally
                    if (_assetContent != null)
                        changedIndices.Sort((a, b) => _assetContent.IndexOf(_assetItems[a].button).CompareTo(_assetContent.IndexOf(_assetItems[b].button)));
                    
                    // Pre-fetch all visuals NOW (one batch of DOM queries, not one per stagger tick)
                    var visuals = new VisualElement[changedIndices.Count];
                    for (int i = 0; i < changedIndices.Count; i++)
                    {
                        int idx = changedIndices[i];
                        visuals[i] = idx < _assetItems.Count ? _assetItems[idx].button.Q("asset-btn-visual") : null;
                    }
                    
                    float popMs = _syntyPassOnPopMs;
                    float popSc = _syntyPassOnPopScale;
                    float delayMs = _syntyPassOffStaggerMs;
                    double offStart = EditorApplication.timeSinceStartup;
                    
                    for (int n = 0; n < changedIndices.Count; n++)
                    {
                        int idx = changedIndices[n];
                        var visual = visuals[n]; // already fetched — no DOM query at fire time
                        double fireAt = offStart + (n * delayMs / 1000.0);
                        
                        EnqueueStagger(fireAt, () =>
                        {
                            if (capturedGen != _syntyPassGeneration || _licenseSyntyPass) return;
                            
                            if (visual != null)
                            {
                                float bs = GetBtnBaseScale();
                                visual.style.transitionDuration = new List<TimeValue> { new TimeValue(popMs, TimeUnit.Millisecond) };
                                visual.style.transitionTimingFunction = new List<EasingFunction> { new EasingFunction(EasingMode.EaseOut) };
                                visual.style.scale = new Scale(new Vector3(popSc * bs, popSc * bs, 1f));
                                
                                double returnAt = EditorApplication.timeSinceStartup + popMs / 1000.0;
                                EnqueueStagger(returnAt, () =>
                                {
                                    if (capturedGen != _syntyPassGeneration || _licenseSyntyPass) return;
                                    float bs2 = GetBtnBaseScale();
                                    visual.style.transitionDuration = new List<TimeValue> { new TimeValue(popMs * 1.5f, TimeUnit.Millisecond) };
                                    visual.style.transitionTimingFunction = new List<EasingFunction> { new EasingFunction(EasingMode.EaseIn) };
                                    visual.style.scale = new Scale(new Vector3(bs2, bs2, 1f));
                                });
                            }
                        });
                    }
                };
            }
        }
        
        private void AutoSortOnSale()
        {
            // If the user has manually chosen a sort, never override it (e.g. after install/uninstall).
            if (_userPickedSort) return;
            // When SyntyPass is ON, all assets are owned — always use Release Date
            if (_licenseSyntyPass)
            {
                _sortMode = 0;
                _sortDirty = true;
                UpdateSortDropdownChoices();
                if (_sortDropdown != null) _sortDropdown.value = "Release Date";
                return;
            }
            
            bool hasOnSale = _assetItems.Any(i => i.isOnSale && !i.getOwned());
            if (hasOnSale)
            {
                _sortMode = 1;
                _sortDirty = true;
                UpdateSortDropdownChoices();
                if (_sortDropdown != null) _sortDropdown.value = "On Sale";
            }
            else
            {
                _sortMode = 0;
                _sortDirty = true;
                UpdateSortDropdownChoices();
                if (_sortDropdown != null) _sortDropdown.value = "Release Date";
            }
        }
        
        // Pre-set sort for SyntyPass OFF using known changed indices (items not yet unowned)
        private void AutoSortOnSaleForOff(List<int> changedIndices)
        {
            if (_userPickedSort) return; // don't override a manually chosen sort
            bool hasOnSale = changedIndices.Any(idx => idx < _assetItems.Count && _assetItems[idx].isOnSale)
                          || _assetItems.Any(i => i.isOnSale && !i.getOwned());
            if (hasOnSale)
            {
                _sortMode = 1;
                _sortDirty = true;
                UpdateSortDropdownChoices();
                if (_sortDropdown != null) _sortDropdown.value = "On Sale";
            }
            else
            {
                _sortMode = 0;
                _sortDirty = true;
                UpdateSortDropdownChoices();
                if (_sortDropdown != null) _sortDropdown.value = "Release Date";
            }
        }
        
        private void UpdateSaleBadgeVisibility()
        {
            // Hide/show sale badges based on Synty Pass state and ownership
            foreach (var item in _assetItems)
            {
                // Badge may be directly on the button or nested under asset-btn-visual
                var saleBadge = item.button.Q<VisualElement>("sale-badge") 
                             ?? item.btnVisual?.Q<VisualElement>("sale-badge");
                if (saleBadge != null)
                {
                    bool owned;
                    if (_licenseSyntyPass)
                    {
                        // Pass toggle ON → everything owned → hide all sale badges
                        owned = true;
                    }
                    else
                    {
                        // Pass toggle OFF → check individual ownership (not pass-derived)
                        int idx = _assetItems.IndexOf(item);
                        if (_assetPackMapping.TryGetValue(idx, out var pack))
                        {
                            owned = SyntyStoreService.Instance.OwnedProductHandles.Contains(pack.packName);
                        }
                        else
                        {
                            owned = item.getOwned();
                        }
                    }
                    saleBadge.style.display = (!owned && !_licenseSyntyPass && _showSaleBadges) ? DisplayStyle.Flex : DisplayStyle.None;
                    // Offset sale badge down if installed badge is also showing
                    bool hasInstalledBadge = item.button.Q<Label>("installed-badge") != null;
                    saleBadge.style.top = _saleBadgeY + (hasInstalledBadge ? _saleBadgeInstalledOffsetY : 0f);
                    saleBadge.style.right = _saleBadgeX + (hasInstalledBadge ? _saleBadgeInstalledOffsetX : 0f);
                }
                
                // Sale amount image mirrors the sale badge's visibility
                var saleAmountEl = item.button.Q<VisualElement>("sale-amount") ?? item.btnVisual?.Q<VisualElement>("sale-amount");
                if (saleAmountEl != null)
                {
                    bool owned2;
                    if (_licenseSyntyPass) owned2 = true;
                    else
                    {
                        int idx2 = _assetItems.IndexOf(item);
                        owned2 = _assetPackMapping.TryGetValue(idx2, out var pack2)
                            ? SyntyStoreService.Instance.OwnedProductHandles.Contains(pack2.packName)
                            : item.getOwned();
                    }
                    saleAmountEl.style.display = (!_downloadingActive && !owned2 && !_licenseSyntyPass && _showSaleAmount) ? DisplayStyle.Flex : DisplayStyle.None;
                }
                if (item.isOnSale && !item.getOwned() && !item.getSelected())
                {
                    var overlay = item.button.Q<VisualElement>("asset-btn-selected");
                    if (overlay != null)
                    {
                        bool showSaleOverlay = _showSaleBadges && !_licenseSyntyPass;
                        if (showSaleOverlay)
                        {
                            overlay.style.unityBackgroundImageTintColor = _saleOutlineColor;
                            overlay.style.opacity = _saleOutlineOpacity;
                        }
                        else
                        {
                            overlay.style.opacity = 0;
                        }
                    }
                }
            }
        }
        
        private void AnimatePercentageText(int fromValue, int toValue, int durationMs, bool popAtEnd)
        {
            int steps = 20;
            int stepDuration = durationMs / steps;
            int currentStep = 0;
            
            // Font size range: use configurable values
            float baseFontSize = _percentageFontSize;
            float maxFontSize = _percentageMaxFontSize;
            
            // Set transform origin to center for scaling
            _percentageText.style.transformOrigin = new TransformOrigin(Length.Percent(50), Length.Percent(50), 0);
            
            System.Action updateStep = null;
            updateStep = () =>
            {
                currentStep++;
                float t = (float)currentStep / steps;
                
                // Apply easing (match the bar's EaseOut)
                float easedT = EaseOut(t);
                
                int currentValue = Mathf.RoundToInt(Mathf.Lerp(fromValue, toValue, easedT));
                _percentageText.text = $"{currentValue}";
                
                // Interpolate font size based on current percentage value (0-100 range)
                // Avoid division by zero when _currentPercentage is 100
                float fontSizeT;
                if (Mathf.Approximately(100f - _currentPercentage, 0f))
                {
                    fontSizeT = currentValue >= 100 ? 1f : 0f;
                }
                else
                {
                    fontSizeT = (currentValue - _currentPercentage) / (100f - _currentPercentage);
                }
                fontSizeT = Mathf.Clamp01(fontSizeT);
                float currentFontSize = Mathf.Lerp(baseFontSize, maxFontSize, fontSizeT);
                _percentageText.style.fontSize = currentFontSize;
                // Symbol is 75% of main text size
                if (_percentageSymbol != null)
                    _percentageSymbol.style.fontSize = currentFontSize * 0.75f;
                
                if (currentStep < steps)
                {
                    _percentageText.schedule.Execute(updateStep).ExecuteLater(stepDuration);
                }
                else if (popAtEnd && toValue == 100)
                {
                    // Flash white when hitting 100%
                    _percentageText.style.color = Color.white;
                    if (_percentageSymbol != null)
                        _percentageSymbol.style.color = Color.white;
                    
                    // Pop effect when reaching 100%
                    _percentageText.style.transitionProperty = new List<StylePropertyName> { 
                        new StylePropertyName("scale"),
                        new StylePropertyName("color")
                    };
                    _percentageText.style.transitionDuration = new List<TimeValue> { 
                        new TimeValue(150, TimeUnit.Millisecond),
                        new TimeValue(200, TimeUnit.Millisecond)
                    };
                    _percentageText.style.transitionTimingFunction = new List<EasingFunction> { 
                        new EasingFunction(EasingMode.EaseOut),
                        new EasingFunction(EasingMode.EaseOut)
                    };
                    
                    // Scale up
                    _percentageText.style.scale = new Scale(new Vector3(1.2f, 1.2f, 1f));
                    
                    // Flash background gradient to celebration state
                    SetBgGradientState(_bgGradient100Color, _bgGradient100Opacity);
                    TriggerGradient100ScalePop();
                    if (_barGradientEnabled) UpdateBarGradientForState(true, true);
                    
                    // After a few frames, transition back to the colour matching the current pass state
                    _percentageText.schedule.Execute(() => {
                        _percentageText.style.color = _syntyPassColor;
                        if (_percentageSymbol != null)
                            _percentageSymbol.style.color = _syntyPassColor;
                        _percentageText.style.scale = new Scale(Vector3.one);
                        // Honor the toggle button's visible state — the user-facing source of truth
                        if (SyntyPassFilterIsActive())
                        {
                            SetBgGradientState(_bgGradientOnColor, _bgGradientOnOpacity);
                            if (_barGradientEnabled) UpdateBarGradientForState(true, false);
                        }
                        else
                        {
                            SetBgGradientState(_bgGradientOffColor, _bgGradientOffOpacity);
                            if (_barGradientEnabled) UpdateBarGradientForState(false, false);
                        }
                    }).ExecuteLater(100);
                }
            };
            
            _percentageText.schedule.Execute(updateStep).ExecuteLater(stepDuration);
        }
        
        private void AnimatePercentageTextFromBar(int fromValue, int toValue, bool popAtEnd, bool? targetPassOn = null)
        {
            if (_progressBarFill == null || _percentageText == null) return;
            
            // Effective target pass state — read from the toggle button's visible state when the
            // explicit override isn't supplied, so the gradient mirrors what the user is looking at.
            bool effectivePass = targetPassOn ?? SyntyPassFilterIsActive();
            
            float cachedParentWidth = _progressBarFill.parent != null ? _progressBarFill.parent.resolvedStyle.width : 0f;
            float baseFontSize = _percentageFontSize;
            float maxFontSize  = _percentageMaxFontSize;
            int   lastDisplayed = fromValue;
            double lastChangeTime = EditorApplication.timeSinceStartup;
            bool  done          = false;
            bool  popFired      = false;
            int   generation    = _syntyPassGeneration;
            
            // Gradient interpolation: target the pass-state colour (not the percentage direction).
            bool  goingUp       = toValue > fromValue;
            Color gradFromColor = effectivePass ? _bgGradientOffColor : _bgGradientOnColor;
            float gradFromAlpha = effectivePass ? _bgGradientOffOpacity : _bgGradientOnOpacity;
            Color gradToColor   = effectivePass ? _bgGradientOnColor : _bgGradientOffColor;
            float gradToAlpha   = effectivePass ? _bgGradientOnOpacity : _bgGradientOffOpacity;
            
            // Disable CSS transitions so we can drive gradient manually each frame
            SetBgGradientImmediate(gradFromColor, gradFromAlpha);
            
            _percentageText.style.transformOrigin = new TransformOrigin(Length.Percent(50), Length.Percent(50), 0);
            
            EditorApplication.CallbackFunction ticker = null;
            ticker = () =>
            {
                // Bail only on hard cancellation (window closed, fill removed) or on a NEW pass
                // toggle (generation bump). The older _percentageGeneration check used to be here
                // to kill stale time-based animations, but this bar-tracking variant tracks the
                // bar's actual resolved width — if something else changes the width mid-flight,
                // the ticker just follows. Adding pctGen back would re-introduce the bug where
                // UpdateCollectionCounts (called from inside the toggle handler) cancels the
                // gradient lerp before it completes, leaving the bg stuck mid-animation.
                if (_reloadingDomain || done || !this || _progressBarFill == null || _percentageText == null || generation != _syntyPassGeneration)
                {
                    EditorApplication.update -= ticker;
                    // Restore transitions and set final gradient state on cancel
                    RestoreBgGradientTransitions();
                    return;
                }
                
                float parentW = _progressBarFill.parent != null ? _progressBarFill.parent.resolvedStyle.width : cachedParentWidth;
                if (parentW <= 0f) parentW = cachedParentWidth;
                if (parentW <= 0f) return;
                
                float barW      = _progressBarFill.resolvedStyle.width;
                float actualPct = Mathf.Clamp(barW / parentW * 100f,
                    Mathf.Min(fromValue, toValue), Mathf.Max(fromValue, toValue));
                
                // Compute progress t (0→1) based on how far the bar has moved
                float range = Mathf.Abs(toValue - fromValue);
                float t = range > 0f ? Mathf.Abs(actualPct - fromValue) / range : 1f;
                t = Mathf.Clamp01(t);
                
                // Interpolate gradient color and opacity based on bar progress
                Color lerpedColor = Color.Lerp(gradFromColor, gradToColor, t);
                float lerpedAlpha = Mathf.Lerp(gradFromAlpha, gradToAlpha, t);
                SetBgGradientImmediate(lerpedColor, lerpedAlpha);
                
                int displayValue = Mathf.RoundToInt(actualPct);
                if (displayValue != lastDisplayed)
                {
                    lastDisplayed = displayValue;
                    lastChangeTime = EditorApplication.timeSinceStartup;
                    _percentageText.text = displayValue.ToString();
                    
                    float fontT = range > 0f ? Mathf.Abs(actualPct - fromValue) / range : 1f;
                    float fs    = Mathf.Lerp(baseFontSize, maxFontSize, fontT);
                    _percentageText.style.fontSize = fs;
                    if (_percentageSymbol != null) _percentageSymbol.style.fontSize = fs * 0.75f;
                }
                
                // The bar can't render narrower than its min-width, so for small target percentages
                // (e.g. 2%) the tracked value floors above toValue and reachedTarget would never fire —
                // leaving the text stuck at the floor (e.g. "10"). Treat "bar stopped moving for a
                // moment" as reaching the target and snap the text to the true logical value.
                bool stalled = (EditorApplication.timeSinceStartup - lastChangeTime) > 0.3;
                bool reachedTarget = (toValue > fromValue ? (displayValue >= toValue) : (displayValue <= toValue)) || stalled;
                if (reachedTarget)
                {
                    done = true;
                    EditorApplication.update -= ticker;
                    
                    _percentageText.text = toValue.ToString();
                    _percentageText.style.fontSize = maxFontSize;
                    if (_percentageSymbol != null) _percentageSymbol.style.fontSize = maxFontSize * 0.75f;
                    
                    // Set final gradient state and restore CSS transitions
                    SetBgGradientImmediate(gradToColor, gradToAlpha);
                    RestoreBgGradientTransitions();
                    
                    if (popAtEnd && toValue == 100 && !popFired)
                    {
                        popFired = true;
                        _percentageText.style.color = Color.white;
                        if (_percentageSymbol != null) _percentageSymbol.style.color = Color.white;
                        _percentageText.style.transitionProperty = new List<StylePropertyName>
                            { new StylePropertyName("scale"), new StylePropertyName("color") };
                        _percentageText.style.transitionDuration = new List<TimeValue>
                            { new TimeValue(150, TimeUnit.Millisecond), new TimeValue(200, TimeUnit.Millisecond) };
                        _percentageText.style.transitionTimingFunction = new List<EasingFunction>
                            { new EasingFunction(EasingMode.EaseOut), new EasingFunction(EasingMode.EaseOut) };
                        _percentageText.style.scale = new Scale(new Vector3(1.2f, 1.2f, 1f));
                        // Flash background gradient to celebration state (uses CSS transition)
                        SetBgGradientState(_bgGradient100Color, _bgGradient100Opacity);
                    TriggerGradient100ScalePop();
                        if (_barGradientEnabled) UpdateBarGradientForState(true, true);
                        _percentageText.schedule.Execute(() =>
                        {
                            _percentageText.style.color = _syntyPassColor;
                            if (_percentageSymbol != null) _percentageSymbol.style.color = _syntyPassColor;
                            // Honor the captured target pass state — user may have toggled during the celebration
                            if (effectivePass)
                            {
                                SetBgGradientState(_bgGradientOnColor, _bgGradientOnOpacity);
                                if (_barGradientEnabled) UpdateBarGradientForState(true, false);
                            }
                            else
                            {
                                SetBgGradientState(_bgGradientOffColor, _bgGradientOffOpacity);
                                if (_barGradientEnabled) UpdateBarGradientForState(false, false);
                            }
                            _percentageText.schedule.Execute(() =>
                            {
                                _percentageText.style.scale = new Scale(Vector3.one);
                            }).ExecuteLater(100);
                        }).ExecuteLater(150);
                    }
                }
            };
            EditorApplication.update += ticker;
        }
        
        private void UpdateBottomBarGradient()
        {
            if (_bottomBarGradient == null) return;
            bool anyBarVisible = 
                (_downloadBar  != null && _downloadBar.style.bottom.value.value  >= 0) ||
                (_cartBar      != null && _cartBar.style.bottom.value.value      >= 0) ||
                (_updatesBar   != null && _updatesBar.style.bottom.value.value   >= 0) ||
                (_uninstallBar != null && _uninstallBar.style.bottom.value.value >= 0);
            _bottomBarGradient.style.opacity = anyBarVisible ? 1 : 0;
            _bottomBarGradient.pickingMode = anyBarVisible ? PickingMode.Position : PickingMode.Ignore;
        }
        
        private void ForceUnhoverAllAssets()
        {
            foreach (var item in _assetItems)
            {
                var hitArea = item.button;
                // Reset hover state via stored action
                if (hitArea.userData is System.Action resetHover)
                    resetHover();
                
                // Reset visual state
                var btn = hitArea.Q<VisualElement>("asset-btn-visual");
                if (btn == null) continue;
                
                if (!item.getSelected())
                {
                    btn.style.transitionDuration = new List<TimeValue> { new TimeValue(_animDuration, TimeUnit.Millisecond) };
                    float bs = GetBtnBaseScale();
                    btn.style.scale = new Scale(new Vector3(bs, bs, 1f));
                    
                    var selOverlay = btn.Q<VisualElement>("asset-btn-selected");
                    if (selOverlay != null)
                    {
                        if (btn.ClassListContains("asset-has-update"))
                        {
                            selOverlay.style.unityBackgroundImageTintColor = _updateBtnColor;
                            selOverlay.style.opacity = 1;
                        }
                        else if (btn.ClassListContains("asset-installed"))
                        {
                            selOverlay.style.unityBackgroundImageTintColor = _installedBtnColor;
                            selOverlay.style.opacity = 1;
                        }
                        else if (item.isOnSale && !item.getOwned() && _showSaleBadges)
                        {
                            selOverlay.style.unityBackgroundImageTintColor = _saleOutlineColor;
                            selOverlay.style.opacity = _saleOutlineOpacity;
                        }
                        else
                        {
                            selOverlay.style.opacity = 0;
                        }
                    }
                    
                    // Restore not-owned label colors
                    if (!item.getOwned())
                    {
                        var coloredOverlay = btn.Q<VisualElement>("asset-colored-overlay");
                        if (coloredOverlay != null) coloredOverlay.style.opacity = (item.isOnSale && _saleColorOverlayOpacity > 0f) ? _saleColorOverlayOpacity : 0f;
                        var typeLabel = btn.Q<Label>("asset-type-label");
                        if (typeLabel != null) typeLabel.style.color = _notOwnedTypeTextColor;
                        var nameLabel = btn.Q<Label>("asset-name-label");
                        if (nameLabel != null) nameLabel.style.color = _notOwnedNameTextColor;
                    }
                }
            }
        }
        
        // Current 1-based position in the batch = the FIXED batchIndex of the pack currently being
        // processed. Stable across focus changes and domain reloads (batchIndex is assigned once and
        // the queue is persisted), so the number never restarts or shifts.
        private int MultiInstallCurrentNumber()
        {
            try
            {
                var q = SyntyDownloadManager.Instance.Queue;
                var cur = q.Find(d => d.status == SyntyDownloadManager.DownloadStatus.Importing)
                       ?? q.Find(d => d.status == SyntyDownloadManager.DownloadStatus.Downloading);
                if (cur != null && cur.batchIndex > 0) return cur.batchIndex;
            }
            catch { }
            // Fallback if no fixed index is available yet.
            int total = BatchTotal();
            int n = _multiInstallDone + 1;
            if (n < 1) n = 1;
            if (total > 0 && n > total) n = total;
            return n;
        }

        // The locked batch total. Read from SessionState (set when install was clicked) so it can't
        // shrink or reset when Unity rebuilds/refocuses the window mid-batch.
        private int BatchTotal()
        {
            int t = SessionState.GetInt(SESSION_BATCH_TOTAL, 0);
            return t > 0 ? t : _multiInstallTotal;
        }

        private string GetInstallBadgeText()
        {
            int total = BatchTotal();
            if (total > 1)
                return $"INSTALLING {MultiInstallCurrentNumber()} OF {total}";
            return "INSTALLING";
        }

        private string GetDownloadBadgeText()
        {
            int total = BatchTotal();
            if (total > 1)
                return $"DOWNLOADING {DownloadPhaseCurrentNumber()} OF {total}";
            return "DOWNLOADING";
        }

        // Current pack number during the download-only phase: counts packs already downloaded
        // (Completed in the manager queue during download-only) + 1 for the one in progress.
        private int DownloadPhaseCurrentNumber()
        {
            // Use the SAME current-asset index as the install badge, so one asset shows the same
            // number while downloading and while installing (e.g. "Downloading 3 of 17" then
            // "Installing 3 of 17"). In the interleaved flow each asset is downloaded then installed
            // before the next, so the current asset is simply (assets finished) + 1.
            return MultiInstallCurrentNumber();
        }
        
        private void EnqueueDownload(System.Action downloadAction)
        {
            _downloadQueue.Enqueue(downloadAction);
            if (!_downloadQueueRunning)
                ProcessDownloadQueue();
        }

        // While a batch install is running, force the editor to keep pumping its update loop even when
        // the window is unfocused — otherwise Unity throttles the editor when it loses focus and the
        // install crawls. Gated strictly to active installs (stopped the moment the batch ends) so it
        // never burns CPU while idle.
        private EditorApplication.CallbackFunction _installKeepAliveTick;
        private void EnsureInstallKeepAlive(bool active)
        {
            if (active)
            {
                if (_installKeepAliveTick != null) return; // already running
                _installKeepAliveTick = () =>
                {
                    EditorApplication.QueuePlayerLoopUpdate(); // request the next tick immediately, defeating the unfocused throttle
                    if (this) Repaint();
                };
                EditorApplication.update += _installKeepAliveTick;
            }
            else if (_installKeepAliveTick != null)
            {
                EditorApplication.update -= _installKeepAliveTick;
                _installKeepAliveTick = null;
            }
        }
        
        private bool _downloadQueueFirstStarted = false;
        // When true, the queue advances to the next item only when the manager actually completes
        // the current import (OnDownloadComplete), instead of on a fixed delay. Keeps the visuals
        // in step with the real install so no asset looks skipped.
        private bool _advanceQueueOnComplete = false;
        // Minimum time (seconds) each asset stays visible as "current" before the batch advances,
        // so a fast multi-install doesn't blink through every asset.
        private const double MIN_ITEM_DWELL = 0.7;
        private double _currentItemShownAt = 0;
        
        // Advances the download queue after the given delay (used to enforce MIN_ITEM_DWELL).
        private void ScheduleAdvanceAfter(double seconds)
        {
            double dueAt = EditorApplication.timeSinceStartup + seconds;
            EditorApplication.CallbackFunction tick = null;
            tick = () =>
            {
                if (!this) { EditorApplication.update -= tick; return; }
                if (EditorApplication.timeSinceStartup < dueAt) return;
                EditorApplication.update -= tick;
                ProcessDownloadQueue();
            };
            EditorApplication.update += tick;
        }
        // User-initiated cancel of a running multi-install batch. Safe by design: already-installed
        // packs are kept, not-yet-started packs are dropped, and the pack currently downloading or
        // importing is allowed to finish cleanly (never deleted mid-flight). Once the in-flight pack
        // completes, the normal batch-done path runs (unlocks reloads, restores the UI).
        private void CancelBatch()
        {
            if (_multiInstallTotal < 1 && _downloadQueue.Count == 0) return;
            _batchCancelled = true;
            // Drop everything that hasn't started yet.
            _downloadQueue.Clear();
            // Shrink the total so the badge reads correctly for the pack still finishing. The
            // in-flight pack counts as the last one.
            _multiInstallTotal = _multiInstallDone + (_activeDownloadCount > 0 ? 1 : 0);
            if (_multiInstallTotal < 1) _multiInstallTotal = _multiInstallDone;
            UpdateDownloadBar();
            // If nothing is actively downloading/importing right now (e.g. between items), finish the
            // batch immediately.
            if (_activeDownloadCount == 0)
            {
                FinishCancelledBatch();
            }
        }

        // Cleans up after a cancel once the in-flight pack (if any) has finished.
        private void FinishCancelledBatch()
        {
            _multiInstallTotal = 0;
            _multiInstallCurrent = 0;
            _multiInstallDone = 0;
            SessionState.SetInt(SESSION_BATCH_TOTAL, 0);
            _downloadQueueRunning = false;
            _downloadQueueFirstStarted = false;
            _batchCancelled = false;
            _installProgressTotal = 0;
            EditorUtility.ClearProgressBar();
            UnlockAssemblyReloadAfterBatch();
            SetDownloadingDimState(false);
            if (_cancelBatchBtn != null) { _cancelBatchBtn.style.display = DisplayStyle.None; _cancelBatchBtn.text = "CANCEL"; }
            RestoreUiAfterDownloads();
            Synty.Tools.SyntyLog.Info("Batch cancelled by user. Completed packs kept; remaining packs skipped.");
        }

        private void ProcessDownloadQueue()
        {
            // Honor a user cancel: stop advancing, keep completed packs, finish any in-flight pack.
            if (_batchCancelled)
            {
                _downloadQueue.Clear();
                _downloadQueueRunning = false;
                EnsureInstallKeepAlive(false);
                if (_activeDownloadCount == 0) FinishCancelledBatch();
                return;
            }
            if (_downloadQueue.Count == 0)
            {
                _downloadQueueRunning = false;
                _downloadQueueFirstStarted = false;
                EnsureInstallKeepAlive(false);
                return;
            }
            _downloadQueueRunning = true;
            EnsureInstallKeepAlive(true);
            
            // Start the FIRST item immediately — nothing has compiled yet, so there's no need to
            // wait, and waiting would delay the install + hide the "Installing 1 of..." badge.
            if (!_downloadQueueFirstStarted)
            {
                _downloadQueueFirstStarted = true;
                var first = _downloadQueue.Dequeue();
                first();
                return;
            }
            
            // For subsequent items, wait for any pending script recompile (from the asset just
            // installed) to finish before starting the next, so its domain reload doesn't
            // interrupt the next download.
            WaitForCompileSettleThenDequeue();
        }
        
        private double _uiQueueSettleStart = -1;
        private bool _uiQueueSawCompile = false;
        private void WaitForCompileSettleThenDequeue()
        {
            if (_batchCancelled)
            {
                _downloadQueue.Clear();
                _downloadQueueRunning = false;
                if (_activeDownloadCount == 0) FinishCancelledBatch();
                return;
            }
            // While assemblies are locked for the batch, no compile can run, so don't wait — just
            // advance to the next item (waiting would hang the queue).
            if (_assemblyReloadLocked)
            {
                if (_downloadQueue.Count == 0) { _downloadQueueRunning = false; return; }
                var nextItem = _downloadQueue.Dequeue();
                nextItem();
                return;
            }
            _uiQueueSettleStart = EditorApplication.timeSinceStartup;
            _uiQueueSawCompile = false;
            EditorApplication.CallbackFunction tick = null;
            tick = () =>
            {
                if (!this) { EditorApplication.update -= tick; return; }
                if (_batchCancelled)
                {
                    EditorApplication.update -= tick;
                    _downloadQueue.Clear();
                    _downloadQueueRunning = false;
                    if (_activeDownloadCount == 0) FinishCancelledBatch();
                    return;
                }
                bool busy = EditorApplication.isCompiling || EditorApplication.isUpdating;
                if (busy) { _uiQueueSawCompile = true; return; } // wait it out (or a reload takes over)
                double elapsed = EditorApplication.timeSinceStartup - _uiQueueSettleStart;
                // Advance once a compile we saw has finished, or after a short grace period if no
                // compile ever started (the package had no scripts).
                if (_uiQueueSawCompile || elapsed >= 0.5)
                {
                    EditorApplication.update -= tick;
                    if (_downloadQueue.Count == 0) { _downloadQueueRunning = false; return; }
                    var next = _downloadQueue.Dequeue();
                    next();
                }
            };
            EditorApplication.update += tick;
        }
        
        // Runs a 3-second mock download for one asset, then transitions it to Installed state.
        // onComplete is called when finished so the queue can advance.
        /// <summary>
        /// Immediately applies installed visual state for cache-hit downloads.
        /// Skips radial ring animation — the asset goes straight to installed look.
        /// </summary>
        private void ApplyInstalledStateImmediate(
            VisualElement downloadBtn,
            VisualElement downloadIcon,
            VisualElement selectedOverlay,
            VisualElement hitArea,
            Color[] downloadBtnColorRef,
            Color[] downloadIconColorRef,
            string productHandle)
        {
            var btnVisual = hitArea.Q<VisualElement>("asset-btn-visual");
            
            if (_multiInstallTotal > 1)
            {
                // Multi-install: spotlight this card (darken the rest) and place the single moving
                // badge here. This fires when this item's turn comes, so even a fast cache-hit
                // asset is shown as the current one.
                SpotlightCard(hitArea);
                MoveInstallBadgeToCard(hitArea, productHandle);
                _currentItemShownAt = EditorApplication.timeSinceStartup;
                hitArea.pickingMode = PickingMode.Position;
            }
            else
            {
                // Single install: dim all other cards while this one installs.
                hitArea.pickingMode = PickingMode.Ignore;
                SetDownloadingDimState(true, hitArea);
            }
            
            // Analytics: track cache hit install
            if (!string.IsNullOrEmpty(productHandle))
            {
                AssetPackData trackPack = null;
                int trackIdx = _assetItems.FindIndex(x => x.button == hitArea);
                if (trackIdx >= 0) _assetPackMapping.TryGetValue(trackIdx, out trackPack);
                SyntyAnalytics.TrackDownload(productHandle, trackPack?.displayName ?? productHandle, trackPack?.category.ToString() ?? "", true);
            }
            
            // Show INSTALLING badge. In a MULTI install the single moving badge is managed by
            // SyncSpotlightToManager (it follows the manager's current card), so don't create a
            // per-card badge here. For a SINGLE install, create it on this card.
            _multiInstallCurrent++;
            if (_multiInstallTotal <= 1)
            {
            var statusBadge = new Label(GetInstallBadgeText());
            statusBadge.name = "download-status-badge";
            statusBadge.pickingMode = PickingMode.Ignore;
            statusBadge.style.position = Position.Absolute;
            statusBadge.style.left = 0;
            statusBadge.style.right = 0;
            statusBadge.style.top = Length.Percent(50);
            statusBadge.style.translate = new Translate(0, Length.Percent(-50));
            statusBadge.style.unityTextAlign = TextAnchor.MiddleCenter;
            statusBadge.style.backgroundColor = new Color(0f, 0f, 0f, 0.8f);
            statusBadge.style.color = Color.white;
            statusBadge.style.fontSize = 10;
            statusBadge.style.unityFontStyleAndWeight = FontStyle.Bold;
            statusBadge.style.paddingTop = 5;
            statusBadge.style.paddingBottom = 5;
            statusBadge.style.paddingLeft = 8;
            statusBadge.style.paddingRight = 8;
            statusBadge.style.letterSpacing = 1;
            if (_titleFont != null) statusBadge.style.unityFontDefinition = FontDefinition.FromFont(_titleFont);
            if (btnVisual != null)
            {
                btnVisual.Query<Label>("download-status-badge").ForEach(b => b.RemoveFromHierarchy());
                btnVisual.Add(statusBadge);
                statusBadge.BringToFront();
            }
            }
            else
            {
                // Multi: place/refresh the single moving badge on this card immediately so it
                // shows without waiting for the next watchdog tick.
                MoveInstallBadgeToCard(hitArea, productHandle);
            }
            
            // Ensure download button is visible and green
            downloadBtn.style.display = DisplayStyle.Flex;
            downloadBtn.style.unityBackgroundImageTintColor = _installedBtnColor;
            downloadBtn.pickingMode = PickingMode.Position;
            
            // Keep download arrow icon during install — OnDownloadComplete will set the tick
            // downloadIcon stays as-is (arrow)
            
            // Show pressed overlay green
            var pressedOvr = downloadBtn.Q<VisualElement>("download-pressed-overlay");
            if (pressedOvr != null)
            {
                pressedOvr.style.display = DisplayStyle.Flex;
                pressedOvr.style.unityBackgroundImageTintColor = _installedBtnColor;
            }
            
            // Don't add asset-installed class yet — OnDownloadComplete will add it
            // This prevents the installed filter from hiding the asset mid-install
            btnVisual?.RemoveFromClassList("asset-has-update");
            
            // Update color refs so GeometryChangedEvent doesn't revert
            if (downloadBtnColorRef != null) downloadBtnColorRef[0] = _installedBtnColor;
            if (downloadIconColorRef != null) downloadIconColorRef[0] = Color.white;
            if (downloadBtn.userData is object[] refs && refs.Length >= 3)
            {
                if (refs[0] is Color[] btnColorRef) btnColorRef[0] = _installedBtnColor;
                if (refs[1] is Color[] iconColorRef) iconColorRef[0] = Color.white;
                if (refs[2] is bool[] installedRef) installedRef[0] = true;
            }
            
            // Apply installed scales
            float _dbs = GetDlBtnBaseScale();
            downloadBtn.style.scale = new Scale(new Vector3(_installedBtnScale * _dbs, _installedBtnScale * _dbs, 1f));
            
            // Show installed green overlay on the card
            if (selectedOverlay != null)
            {
                selectedOverlay.style.unityBackgroundImageTintColor = _installedBtnColor;
                selectedOverlay.style.opacity = 1;
            }
            
            // Tint gradient green and restore
            var gradientOvr = btnVisual?.Q<VisualElement>("asset-btn-gradient");
            if (gradientOvr != null)
            {
                gradientOvr.style.display = DisplayStyle.Flex;
                gradientOvr.style.unityBackgroundImageTintColor = _installedBtnColor;
            }
            
            // Register uninstall hover
            Label ttLabel = null;
            _downloadTooltipLabels.TryGetValue(downloadBtn, out ttLabel);
            // Hide tooltip while installing — OnDownloadComplete will restore it
            if (ttLabel != null && ttLabel.parent != null)
                ttLabel.parent.style.display = DisplayStyle.None;
            RegisterUninstallHover(downloadBtn, downloadIcon, ttLabel);
            
            // NOTE: the green INSTALLED badge is intentionally NOT shown here — it must only
            // appear once the install has actually completed (INSTALLING badge gone). It is shown
            // in the completion delayCall below.
            RemoveInstalledBadge(hitArea);
            
            // Mark owned
            int idx = _assetItems.FindIndex(x => x.button == hitArea);
            if (idx >= 0 && !_assetItems[idx].getOwned())
                _assetItems[idx].setOwned(true);
            
            UpdateCollectionCounts();
            UpdateDownloadBar();
            UpdateSaleBadgeVisibility();
            
            // Re-apply after a frame in case GeometryChangedEvent or layout reverts the visuals
            var capturedDlBtn = downloadBtn;
            var capturedDlIcon = downloadIcon;
            var capturedBtnVisual = btnVisual;
            var capturedSelOvr = selectedOverlay;
            var capturedBadge = btnVisual?.Q<Label>("download-status-badge");
            var capturedHitArea = hitArea;
            EditorApplication.delayCall += () =>
            {
                if (capturedDlBtn == null) return;
                capturedDlBtn.style.display = DisplayStyle.Flex;
                capturedDlBtn.style.unityBackgroundImageTintColor = _installedBtnColor;
                // Don't set tick icon here — keep arrow until OnDownloadComplete
                var pOvr = capturedDlBtn.Q<VisualElement>("download-pressed-overlay");
                if (pOvr != null) { pOvr.style.display = DisplayStyle.Flex; pOvr.style.unityBackgroundImageTintColor = _installedBtnColor; }
                if (capturedSelOvr != null) { capturedSelOvr.style.unityBackgroundImageTintColor = _installedBtnColor; capturedSelOvr.style.opacity = 1; }
                // Remove the INSTALLING badge, but do NOT show the green INSTALLED badge yet — it
                // must appear only when the asset is fully installed (the moment the download
                // button flips to the installed icon). That happens in OnDownloadComplete, which
                // fires on the real importPackageCompleted event. Showing it here would light the
                // badge a frame after install STARTED, before the button shows the installed icon.
                if (capturedBadge != null) capturedBadge.RemoveFromHierarchy();
                RemoveInstalledBadge(capturedHitArea);
                if (_multiInstallTotal <= 1)
                {
                    SetDownloadingDimState(false);
                    UpdateSaleBadgeVisibility();
                    UpdateSaleAmount();
                    // ClearUnityConsole(); // removed — keep customer-facing messages visible
                }
            };
        }
        
        private void RunSingleDownload(
            VisualElement radialRing,
            VisualElement radialRingBg,
            VisualElement downloadBtn,
            VisualElement downloadIcon,
            VisualElement selectedOverlay,
            VisualElement hitArea,
            Color[] downloadBtnColorRef,
            Color[] downloadIconColorRef,
            System.Action onComplete,
            string productHandle = null)
        {
            // Resolve refs from userData if not passed directly (e.g. from the Download+Install bar)
            if (downloadBtnColorRef == null && downloadBtn?.userData is object[] refsArr && refsArr.Length >= 3)
            {
                downloadBtnColorRef  = refsArr[0] as Color[];
                downloadIconColorRef = refsArr[1] as Color[];
            }
            bool[] isInstalledRefResolved = (downloadBtn?.userData is object[] ra && ra.Length >= 3) ? ra[2] as bool[] : null;
            // If the pack is already cached, this is the install (import) phase — Unity blocks the
            // main thread during ImportPackage so the ring can't animate. Hide it in that case;
            // only show the animated ring while actually downloading (thread free).
            bool ringForInstall = false;
            if (!string.IsNullOrEmpty(productHandle))
            {
                foreach (var kvpR in _assetPackMapping)
                {
                    if (kvpR.Value == null) continue;
                    if (SyntyStoreService.ExtractHandleFromUrl(kvpR.Value.storeUrl) == productHandle)
                    {
                        ringForInstall = !string.IsNullOrEmpty(kvpR.Value.bucketFilename) &&
                                         SyntyDownloadManager.IsInDownloadCache(kvpR.Value.bucketFilename);
                        break;
                    }
                }
            }
            if (ringForInstall)
            {
                radialRing.style.display = DisplayStyle.None;
                if (radialRingBg != null) radialRingBg.style.display = DisplayStyle.None;
                // Install phase: no ring, so keep the download button (arrow icon) visible.
                downloadBtn.style.display = DisplayStyle.Flex;
            }
            else
            {
                radialRing.style.display = DisplayStyle.Flex;
                if (radialRingBg != null) { radialRingBg.style.unityBackgroundImageTintColor = _radialRingBgColor; radialRingBg.style.display = DisplayStyle.Flex; radialRingBg.style.scale = new Scale(new Vector3(_ringBgScale, _ringBgScale, 1f)); }
                // Download phase: the ring covers the button area, so hide the button.
                downloadBtn.style.display = DisplayStyle.None;
            }
            // Hide this card's sale "% OFF" badge while it installs — it overflows the card and
            // would paint over the install overlay. Restored by RestoreUiAfterDownloads.
            if (hitArea != null)
            {
                var saleDuringDl = hitArea.Q<VisualElement>("sale-amount");
                if (saleDuringDl != null) saleDuringDl.style.display = DisplayStyle.None;
            }
            // In a multi-install keep the card interactive (it's installing, stays bright); for a
            // single install, block this card while it downloads.
            if (_multiInstallTotal <= 1) hitArea.pickingMode = PickingMode.Ignore;
            
            // Analytics: track download start
            if (!string.IsNullOrEmpty(productHandle))
            {
                AssetPackData trackPack = null;
                int trackIdx = _assetItems.FindIndex(x => x.button == hitArea);
                if (trackIdx >= 0) _assetPackMapping.TryGetValue(trackIdx, out trackPack);
                SyntyAnalytics.TrackDownload(productHandle, trackPack?.displayName ?? productHandle, trackPack?.category.ToString() ?? "", false);
            }
            // Multi-install: darken every other card, keep this one bright while it downloads.
            // Single install: dim all other cards while this downloads.
            if (_multiInstallTotal > 1)
                SpotlightCard(hitArea);
            else
                SetDownloadingDimState(true, hitArea);
            
            // Add status badge. If the pack's file is already cached, we're in the install phase
            // (no download needed) so show "Installing"; otherwise it's still downloading.
            _multiInstallCurrent++;
            bool showInstalling = false;
            if (!string.IsNullOrEmpty(productHandle))
            {
                foreach (var kvpC in _assetPackMapping)
                {
                    if (kvpC.Value == null) continue;
                    if (SyntyStoreService.ExtractHandleFromUrl(kvpC.Value.storeUrl) == productHandle)
                    {
                        showInstalling = !string.IsNullOrEmpty(kvpC.Value.bucketFilename) &&
                                         SyntyDownloadManager.IsInDownloadCache(kvpC.Value.bucketFilename);
                        break;
                    }
                }
            }
            var statusBadge = new Label(showInstalling ? GetInstallBadgeText() : GetDownloadBadgeText());
            statusBadge.name = "download-status-badge";
            statusBadge.pickingMode = PickingMode.Ignore;
            statusBadge.style.position = Position.Absolute;
            statusBadge.style.left = 0;
            statusBadge.style.right = 0;
            statusBadge.style.top = Length.Percent(50);
            statusBadge.style.translate = new Translate(0, Length.Percent(-50));
            statusBadge.style.unityTextAlign = TextAnchor.MiddleCenter;
            statusBadge.style.backgroundColor = new Color(0f, 0f, 0f, 0.8f);
            statusBadge.style.color = Color.white;
            statusBadge.style.fontSize = 10;
            statusBadge.style.unityFontStyleAndWeight = FontStyle.Bold;
            statusBadge.style.paddingTop = 5;
            statusBadge.style.paddingBottom = 5;
            statusBadge.style.paddingLeft = 8;
            statusBadge.style.paddingRight = 8;
            statusBadge.style.letterSpacing = 1;
            if (_titleFont != null) statusBadge.style.unityFontDefinition = FontDefinition.FromFont(_titleFont);
            var btnVisualForBadge = hitArea.Q<VisualElement>("asset-btn-visual");
            if (btnVisualForBadge != null)
            {
                // Remove any existing badge on this card so a leftover "Downloading" one can't sit
                // behind the new one.
                btnVisualForBadge.Query<Label>("download-status-badge").ForEach(b => b.RemoveFromHierarchy());
                btnVisualForBadge.Add(statusBadge);
            }
            
            // Hide the gradient while downloading
            var gradientOvrDownload = downloadBtn.parent?.Q<VisualElement>("asset-btn-gradient");
            if (gradientOvrDownload != null) gradientOvrDownload.style.display = DisplayStyle.None;
            
            if (selectedOverlay != null)
            {
                selectedOverlay.style.unityBackgroundImageTintColor = _installedBtnColor;
                selectedOverlay.style.opacity = 1;
            }
            
            float[] progressRef = new float[]{ 0f };
            radialRing.userData = progressRef;
            
            int    gen       = _syntyPassGeneration;
            bool   hasTransitioned = false;
            float  fallbackTimer = 0f;
            float  minDisplayTime = 2f;
            bool   backendComplete = false;
            double lastTime  = EditorApplication.timeSinceStartup;
            
            EditorApplication.CallbackFunction ticker = null;
            ticker = () =>
            {
                if (_reloadingDomain || !this || gen != _syntyPassGeneration)
                {
                    EditorApplication.update -= ticker;
                    ProcessDownloadQueue();
                    return;
                }
                
                double now = EditorApplication.timeSinceStartup;
                float dt = (float)(now - lastTime);
                lastTime = now;
                fallbackTimer += dt;
                
                // Poll actual download progress from backend
                float realProgress = 0f;
                bool isComplete = false;
                bool isImporting = false;
                
                if (!string.IsNullOrEmpty(productHandle))
                {
                    var queueItem = SyntyDownloadManager.Instance.Queue.Find(d => d.productHandle == productHandle);
                    if (queueItem != null)
                    {
                        realProgress = queueItem.progress;
                        isImporting = queueItem.status == SyntyDownloadManager.DownloadStatus.Importing;
                        
                        if (queueItem.completedAt != null)
                        {
                            isComplete = true;
                            realProgress = 1f;
                        }
                    }
                    else
                    {
                        // Item not in queue — might have been already processed
                        if (SyntyInstallManifest.HasManifest(productHandle))
                        {
                            isComplete = true;
                            realProgress = 1f;
                        }
                    }
                }
                else
                {
                    // No handle — use fallback timer
                    realProgress = Mathf.Clamp01(fallbackTimer / 3f);
                    isComplete = fallbackTimer >= 3f;
                }
                
                // Track when backend finishes
                if (isComplete) backendComplete = true;
                
                // Smoothly animate progress (don't jump)
                float displayProgress = progressRef[0];
                float targetProgress = backendComplete ? 1f : Mathf.Clamp01(realProgress);
                displayProgress = Mathf.MoveTowards(displayProgress, targetProgress, dt * 0.8f);
                // Ensure minimum visible progress so ring is always visible during download
                if (!backendComplete && displayProgress < 0.15f)
                    displayProgress = Mathf.Max(displayProgress, Mathf.Clamp01(fallbackTimer / minDisplayTime) * 0.15f);
                
                progressRef[0] = displayProgress;
                radialRing.MarkDirtyRepaint();
                
                // Update badge: DOWNLOADING while the file downloads, INSTALLING once importing.
                // If the pack was already cached (install phase), always show INSTALLING.
                if (statusBadge != null && !hasTransitioned)
                {
                    if (showInstalling || isImporting)
                        statusBadge.text = GetInstallBadgeText();
                    else
                        statusBadge.text = GetDownloadBadgeText();
                }
                
                // Safety timeout: 5 minutes max per asset
                if (fallbackTimer > 300f) { backendComplete = true; isComplete = true; }
                
                // Only transition after: backend done + minimum display time met + progress visually at 100%
                if (backendComplete && fallbackTimer >= minDisplayTime && displayProgress >= 0.99f && !hasTransitioned)
                {
                    hasTransitioned = true;
                    EditorApplication.update -= ticker;
                    
                    // Transition to Installed state
                    radialRing.style.display = DisplayStyle.None;
                    if (radialRingBg != null) radialRingBg.style.display = DisplayStyle.None;
                    // Reset progress so if ring is ever re-shown it doesn't flash full
                    if (radialRing.userData is float[] pRef) pRef[0] = 0f;
                    radialRing.MarkDirtyRepaint();
                    downloadBtn.style.display = DisplayStyle.Flex;
                    downloadBtn.style.unityBackgroundImageTintColor = _installedBtnColor;
                    downloadBtn.pickingMode = PickingMode.Position; // Keep clickable for uninstall
                    if (_installedIcon != null)
                    {
                        downloadIcon.style.backgroundImage = new StyleBackground(_installedIcon);
                        downloadIcon.style.unityBackgroundImageTintColor = Color.white;
                    }
                    
                    // Remove the INSTALLING/DOWNLOADING status badge — this transition IS the
                    // completion of the install, so the badge should clear here even if the
                    // OnDownloadComplete event doesn't fire (e.g. the last item triggered a
                    // recompile/domain reload and its completion event was lost).
                    var installingBadge = btnVisualForBadge?.Q<Label>("download-status-badge");
                    if (installingBadge != null) installingBadge.RemoveFromHierarchy();
                    
                    // Show pressed overlay green (installed resting state)
                    var pressedOvr = downloadBtn.Q<VisualElement>("download-pressed-overlay");
                    if (pressedOvr != null)
                    {
                        pressedOvr.style.display = DisplayStyle.Flex;
                        pressedOvr.style.unityBackgroundImageTintColor = _installedBtnColor;
                    }
                    
                    // Register hover handlers on the installed button — show uninstall icon on hover
                    downloadBtn.pickingMode = PickingMode.Position; // Keep clickable for uninstall
                    Label ttLabel = null;
                    _downloadTooltipLabels.TryGetValue(downloadBtn, out ttLabel);
                    if (ttLabel != null) ttLabel.text = "Installed";
                    RegisterUninstallHover(downloadBtn, downloadIcon, ttLabel);
                    
                    // Update color refs so GeometryChangedEvent doesn't revert back
                    if (downloadBtnColorRef  != null) downloadBtnColorRef[0]  = _installedBtnColor;
                    if (downloadIconColorRef != null) downloadIconColorRef[0] = Color.white;
                    if (isInstalledRefResolved != null) isInstalledRefResolved[0] = true;
                    // Mark the visual element with a CSS class for reliable installed state detection
                    downloadBtn.parent?.AddToClassList("asset-installed");
                    downloadBtn.parent?.RemoveFromClassList("asset-has-update");
                    
                    // Replace UPDATE AVAILABLE badge with INSTALLED badge
                    RemoveInstalledBadge(hitArea);
                    ShowInstalledBadge(hitArea);
                    
                    // Apply installed scales to button and icon
                    { float _dbs = GetDlBtnBaseScale(); downloadBtn.style.scale = new Scale(new Vector3(_installedBtnScale * _dbs, _installedBtnScale * _dbs, 1f)); }
                    if (downloadIcon != null)
                        downloadIcon.style.scale = new Scale(new Vector3(_installedIconScale, _installedIconScale, 1f));
                    
                    // Show installed green overlay on the card
                    if (selectedOverlay != null)
                    {
                        selectedOverlay.style.unityBackgroundImageTintColor = _installedBtnColor;
                        selectedOverlay.style.opacity = 1;
                    }
                    
                    // Tint the gradient overlay green to match and restore it
                    var gradientOvr = downloadBtn.parent?.Q<VisualElement>("asset-btn-gradient");
                    if (gradientOvr != null)
                    {
                        gradientOvr.style.unityBackgroundImageTintColor = _installedBtnColor;
                        gradientOvr.style.display = DisplayStyle.Flex;
                    }
                    
                    hitArea.pickingMode = PickingMode.Position;
                    // Reset hover state so mouse-enter fires fresh on the next hover
                    if (hitArea.userData is System.Action resetHover) resetHover();
                    
                    // Reset type/name label colors to correct installed state
                    var btnVisualForLabels = downloadBtn.parent;
                    if (btnVisualForLabels != null)
                    {
                        var typeLbl = btnVisualForLabels.Q<Label>("asset-type-label");
                        var nameLbl = btnVisualForLabels.Q<Label>("asset-name-label");
                        // Determine textColor from the asset type
                        var typeLblText = typeLbl?.text ?? "";
                        var (_, installedTextColor) = GetAssetTypeColors(typeLblText);
                        if (typeLbl != null) typeLbl.style.color = installedTextColor;
                        if (nameLbl != null) nameLbl.style.color = Color.white;
                    }
                    
                    // Reset scale back to normal - mouse will re-enter and scale up again naturally
                    var btnVisual = hitArea.Q<VisualElement>("asset-btn-visual");
                    if (btnVisual != null)
                    {
                        btnVisual.style.transitionDuration = new List<TimeValue> { new TimeValue(_animDuration, TimeUnit.Millisecond) };
                        float bs = GetBtnBaseScale();
                        btnVisual.style.scale = new Scale(new Vector3(bs, bs, 1f));
                    }
                    // Don't clear dim overlay here — keep it dark until import completes
                    // (OnDownloadComplete handles cleanup after Unity finishes importing)
                    
                    // Refresh the download bar so it hides if no more selected assets remain
                    UpdateDownloadBar();
                    
                    onComplete?.Invoke();
                }
            };
            EditorApplication.update += ticker;
        }
        
        private float _dimOverlayAlpha = 0.85f; // alpha for the download-in-progress dim on other cards
        private float _dimOverlayScale = 1.045f; // scale of the dim overlay image
        private Color DimOverlayColor => new Color(0.094f, 0.078f, 0.145f, _dimOverlayAlpha);
        
        // Tool waiting overlay — dims everything except asset buttons during download/install/uninstall
        private VisualElement _toolWaitingOverlay;
        private VisualElement _downloadActiveLayer; // Sits above the tool waiting overlay for active downloads
        private VisualElement _activeDownloadBtn; // The hitArea currently being downloaded
        private VisualElement _downloadPlaceholder; // Invisible spacer to preserve grid layout during download
        private int _activeDownloadOriginalIndex = -1; // Original DOM index for reinsertion
        private Color _toolWaitingColor = new Color(23f/255f, 19f/255f, 36f/255f, 1f); // #171324
        private float _toolWaitingOpacity = 0.35f;
        
        // Computes negative position insets so the overlay extends equally beyond all edges (centered scale)
        private void ApplyDimOverlayExtension(VisualElement dimOvr)
        {
            float buttonSize = GetCurrentButtonSize();
            float ext = ((_dimOverlayScale - 1f) * 0.5f) * buttonSize;
            dimOvr.style.top    = -ext;
            dimOvr.style.left   = -ext;
            dimOvr.style.right  = -ext;
            dimOvr.style.bottom = -ext;
        }
        
        private void RefreshDimOverlayColors()
        {
            foreach (var item in _assetItems)
            {
                var dimOvr = item.button.Q<VisualElement>("download-dim-overlay");
                if (dimOvr != null)
                {
                    dimOvr.style.unityBackgroundImageTintColor = DimOverlayColor;
                    ApplyDimOverlayExtension(dimOvr);
                }
            }
        }
        
        private void ShowToolWaiting()
        {
            if (_toolWaitingOverlay == null) return;
            _toolWaitingOverlay.style.display = DisplayStyle.Flex;
            _toolWaitingOverlay.style.backgroundColor = _toolWaitingColor;
            _toolWaitingOverlay.schedule.Execute(() =>
            {
                _toolWaitingOverlay.style.opacity = _toolWaitingOpacity;
            }).StartingIn(10);
        }
        
        private void HideToolWaiting()
        {
            if (_toolWaitingOverlay == null) return;
            _toolWaitingOverlay.style.opacity = 0;
            _toolWaitingOverlay.style.display = DisplayStyle.None;
        }
        
        private void PromoteToActiveLayer(VisualElement hitArea)
        {
            if (hitArea == null || _downloadActiveLayer == null || _assetContent == null) return;
            
            // Save original index for reinsertion
            _activeDownloadOriginalIndex = _assetContent.IndexOf(hitArea);
            _activeDownloadBtn = hitArea;
            
            // Get world position before reparenting
            var bounds = hitArea.worldBound;
            var layerBounds = _downloadActiveLayer.worldBound;
            
            // Calculate button size from current style
            float width = bounds.width;
            float height = bounds.height;
            
            // Insert invisible placeholder to preserve grid layout
            _downloadPlaceholder = new VisualElement();
            _downloadPlaceholder.name = "download-placeholder";
            _downloadPlaceholder.style.width = width;
            _downloadPlaceholder.style.height = height;
            _downloadPlaceholder.style.marginLeft = _assetBtnMargin;
            _downloadPlaceholder.style.marginRight = _assetBtnMargin;
            _downloadPlaceholder.style.marginTop = _assetBtnMargin;
            _downloadPlaceholder.style.marginBottom = _assetBtnMargin;
            _downloadPlaceholder.style.visibility = Visibility.Hidden;
            _downloadPlaceholder.pickingMode = PickingMode.Ignore;
            if (_activeDownloadOriginalIndex >= 0 && _activeDownloadOriginalIndex < _assetContent.childCount)
                _assetContent.Insert(_activeDownloadOriginalIndex, _downloadPlaceholder);
            
            // Remove from grid and add to active layer
            hitArea.RemoveFromHierarchy();
            _downloadActiveLayer.Add(hitArea);
            
            // Position absolutely at the same visual location
            hitArea.style.position = Position.Absolute;
            hitArea.style.left = bounds.x - layerBounds.x;
            hitArea.style.top = bounds.y - layerBounds.y;
            hitArea.style.width = width;
            hitArea.style.height = height;
            hitArea.style.marginLeft = 0;
            hitArea.style.marginRight = 0;
            hitArea.style.marginTop = 0;
            hitArea.style.marginBottom = 0;
        }
        
        private void DemoteFromActiveLayer()
        {
            if (_activeDownloadBtn == null || _assetContent == null) return;
            
            // Remove placeholder
            if (_downloadPlaceholder != null && _downloadPlaceholder.panel != null)
            {
                int placeholderIdx = _assetContent.IndexOf(_downloadPlaceholder);
                _downloadPlaceholder.RemoveFromHierarchy();
                if (placeholderIdx >= 0) _activeDownloadOriginalIndex = placeholderIdx;
            }
            _downloadPlaceholder = null;
            
            // Remove from active layer
            _activeDownloadBtn.RemoveFromHierarchy();
            
            // Restore flex layout styles (only clear position-related overrides from promote)
            _activeDownloadBtn.style.position = StyleKeyword.Null;
            _activeDownloadBtn.style.left = StyleKeyword.Null;
            _activeDownloadBtn.style.top = StyleKeyword.Null;
            _activeDownloadBtn.style.marginLeft = StyleKeyword.Null;
            _activeDownloadBtn.style.marginRight = StyleKeyword.Null;
            _activeDownloadBtn.style.marginTop = StyleKeyword.Null;
            _activeDownloadBtn.style.marginBottom = StyleKeyword.Null;
            
            // Reinsert at original position (or end if index is invalid)
            if (_activeDownloadOriginalIndex >= 0 && _activeDownloadOriginalIndex < _assetContent.childCount)
                _assetContent.Insert(_activeDownloadOriginalIndex, _activeDownloadBtn);
            else
                _assetContent.Add(_activeDownloadBtn);
            
            _activeDownloadBtn = null;
            _activeDownloadOriginalIndex = -1;
        }
        
        // Tracks which card is currently the bright (spotlighted) one during a multi-install.
        private VisualElement _spotlightCard;
        
        // Multi-install spotlight: makes hitArea the single bright card and re-darkens whichever
        // card was bright before. Guarantees the currently-installing card is always the lit one,
        // and only ever touches two cards, so there's no full-grid churn that could flicker every
        // card off.
        private void SpotlightCard(VisualElement hitArea)
        {
            if (_spotlightCard != null && _spotlightCard != hitArea)
                DimCard(_spotlightCard);
            UndimCard(hitArea);
            _spotlightCard = hitArea;
        }
        
        // Keeps the spotlight correct during a multi-install by following the download manager's
        // actual current item: the card for the handle being downloaded/imported is the bright
        // one, every other batch card stays dimmed. Driven by the watchdog so it self-corrects
        // through the between-item compile wait and any gaps (and re-applies dims that a card
        // briefly lost). Returns quietly when there's nothing to do.
        private void SyncSpotlightToManager()
        {
            if (_multiInstallTotal <= 1) return;
            string currentHandle = null;
            try { currentHandle = SyntyDownloadManager.Instance?.CurrentProductHandle; } catch { }
            if (string.IsNullOrEmpty(currentHandle)) return;
            
            // Find the card whose pack maps to the current handle.
            VisualElement currentCard = null;
            foreach (var kvp in _assetPackMapping)
            {
                if (kvp.Key < 0 || kvp.Key >= _assetItems.Count) continue;
                if (SyntyStoreService.ExtractHandleFromUrl(kvp.Value.storeUrl) == currentHandle)
                {
                    currentCard = _assetItems[kvp.Key].button;
                    break;
                }
            }
            if (currentCard == null) return;
            
            // Make it the spotlight if it isn't already (dims the previously-bright one), and move
            // the single INSTALLING badge onto it so the badge follows the real install card to
            // card and stays in step with the manager's progress.
            if (_spotlightCard != currentCard)
            {
                SpotlightCard(currentCard);
                MoveInstallBadgeToCard(currentCard, currentHandle);
            }
        }
        
        // Ensures exactly one "INSTALLING X of N" badge exists and lives on the given card. Removes
        // any badge from other cards first, so only the currently-installing card shows it.
        private void MoveInstallBadgeToCard(VisualElement card, string productHandle = null)
        {
            if (card == null) return;
            // Remove any existing install badges across the grid (only one should ever show).
            foreach (var it in _assetItems)
            {
                var bv = it.btnVisual;
                var existing = bv?.Q<Label>("download-status-badge");
                if (existing != null && it.button != card)
                    existing.RemoveFromHierarchy();
            }
            
            var btnVisual = card.Q<VisualElement>("asset-btn-visual");
            if (btnVisual == null) return;
            var badge = btnVisual.Q<Label>("download-status-badge");
            if (badge == null)
            {
                badge = new Label();
                badge.name = "download-status-badge";
                badge.pickingMode = PickingMode.Ignore;
                badge.style.position = Position.Absolute;
                badge.style.left = 0;
                badge.style.right = 0;
                badge.style.top = Length.Percent(50);
                badge.style.translate = new Translate(0, Length.Percent(-50));
                badge.style.unityTextAlign = TextAnchor.MiddleCenter;
                badge.style.backgroundColor = new Color(0f, 0f, 0f, 0.8f);
                badge.style.color = Color.white;
                badge.style.fontSize = 10;
                badge.style.unityFontStyleAndWeight = FontStyle.Bold;
                badge.style.letterSpacing = 1;
                if (_titleFont != null) badge.style.unityFontDefinition = FontDefinition.FromFont(_titleFont);
                badge.style.paddingTop = 5;
                badge.style.paddingBottom = 5;
                badge.style.paddingLeft = 8;
                badge.style.paddingRight = 8;
                btnVisual.Add(badge);
            }
            // Text reflects actual status: "Downloading" while downloading, "Installing" when importing.
            bool importing = false;
            if (!string.IsNullOrEmpty(productHandle))
            {
                var mi = SyntyDownloadManager.Instance.Queue.Find(d => d.productHandle == productHandle);
                importing = mi != null && mi.status == SyntyDownloadManager.DownloadStatus.Importing;
            }
            badge.text = importing ? GetInstallBadgeText() : GetDownloadBadgeText();
            badge.style.display = DisplayStyle.Flex;
            badge.BringToFront();
        }
        
        // Permanently un-dims a single card: used during a multi-install when a card's turn to
        // install comes up, so it stays bright from then on (never re-darkened as the batch moves
        // to later items). Restores its interactivity and sale badge too.
        private void UndimCard(VisualElement hitArea)
        {
            if (hitArea == null) return;
            var btnVisual = hitArea.Q<VisualElement>("asset-btn-visual");
            var dimOvr = btnVisual?.Q<VisualElement>("download-dim-overlay");
            if (dimOvr != null) dimOvr.style.display = DisplayStyle.None;
            var saleBadgeEl = hitArea.Q<VisualElement>("sale-amount");
            if (saleBadgeEl != null)
                saleBadgeEl.style.display = _showSaleAmount ? DisplayStyle.Flex : DisplayStyle.None;
        }
        
        // Dims a single card (the "waiting to install" look during a multi-install). Creates the
        // dim overlay if needed. Other cards in the grid are left untouched.
        private void DimCard(VisualElement hitArea)
        {
            if (hitArea == null) return;
            var btnVisual = hitArea.Q<VisualElement>("asset-btn-visual");
            if (btnVisual == null) return;
            var saleBadgeEl = hitArea.Q<VisualElement>("sale-amount");
            if (saleBadgeEl != null) saleBadgeEl.style.display = DisplayStyle.None;
            var dimOvr = btnVisual.Q<VisualElement>("download-dim-overlay");
            if (dimOvr == null)
            {
                var assetBgTex = LoadImage("Assets", "Asset_Background");
                dimOvr = new VisualElement();
                dimOvr.name = "download-dim-overlay";
                dimOvr.pickingMode = PickingMode.Ignore;
                dimOvr.style.position = Position.Absolute;
                dimOvr.style.borderBottomLeftRadius = 8;
                dimOvr.style.borderBottomRightRadius = 8;
                dimOvr.style.borderTopLeftRadius = 8;
                dimOvr.style.borderTopRightRadius = 8;
                dimOvr.style.overflow = Overflow.Hidden;
                if (assetBgTex != null)
                {
                    dimOvr.style.backgroundImage = new StyleBackground(assetBgTex);
                    dimOvr.style.SetBackgroundStretchToFill();
                    dimOvr.style.unityBackgroundImageTintColor = DimOverlayColor;
                }
                else
                {
                    dimOvr.style.backgroundColor = DimOverlayColor;
                }
                ApplyDimOverlayExtension(dimOvr);
                btnVisual.Add(dimOvr);
            }
            dimOvr.style.display = DisplayStyle.Flex;
            dimOvr.BringToFront();
        }
        
        // Applies or removes a dim overlay on every asset card that is NOT currently downloading.
        // Also locks/unlocks the hitArea and any external link/action buttons on those cards.
        // Transparent full-window overlay that swallows all pointer input while a batch runs, so the
        // grid, filters, search, toolbar and every other control are inert until it finishes. The
        // install visuals (spotlight, badges, progress) still render beneath it and stay visible.
        private VisualElement _inputBlocker;
        private void SetInputBlocked(bool blocked)
        {
            try
            {
                if (blocked)
                {
                    if (_inputBlocker == null)
                    {
                        _inputBlocker = new VisualElement { name = "input-blocker" };
                        _inputBlocker.style.position = Position.Absolute;
                        _inputBlocker.style.left = 0; _inputBlocker.style.right = 0;
                        _inputBlocker.style.top = 0; _inputBlocker.style.bottom = 0;
                        _inputBlocker.pickingMode = PickingMode.Position; // capture pointer events
                        // Swallow the common input events so nothing beneath reacts.
                        _inputBlocker.RegisterCallback<MouseDownEvent>(e => { e.StopImmediatePropagation(); });
                        _inputBlocker.RegisterCallback<MouseUpEvent>(e => { e.StopImmediatePropagation(); });
                        _inputBlocker.RegisterCallback<ClickEvent>(e => { e.StopImmediatePropagation(); });
                        _inputBlocker.RegisterCallback<WheelEvent>(e => { e.StopImmediatePropagation(); });
                        _inputBlocker.RegisterCallback<KeyDownEvent>(e => { e.StopImmediatePropagation(); });
                    }
                    if (_inputBlocker.parent == null) rootVisualElement.Add(_inputBlocker);
                    _inputBlocker.BringToFront();
                }
                else if (_inputBlocker != null && _inputBlocker.parent != null)
                {
                    _inputBlocker.RemoveFromHierarchy();
                }
            }
            catch { }
        }

        private void SetDownloadingDimState(bool downloading, VisualElement excludeBtn = null, bool dimCards = true)
        {
            // Never dim the card that is currently spotlighted (the asset installing right now),
            // even if this dim pass runs after the spotlight was set (the batch dim is delayed by
            // the action-bar animation, so it can land after the first asset is already current).
            if (downloading && excludeBtn == null && _spotlightCard != null)
                excludeBtn = _spotlightCard;
            _downloadingActive = downloading;
            // Block ALL tool input while a batch is downloading/installing/updating so nothing can
            // interfere mid-run; released when the batch ends.
            SetInputBlocked(downloading);
            // Clear spotlight tracking when the batch ends.
            if (!downloading) _spotlightCard = null;
            // Once the user kicks off a download/install, cancel any pending Synty Pass auto-on
            // so the filter doesn't turn itself on when the install finishes.
            if (downloading) CancelSyntyPassAutoOn();
            // Animate the action bars off screen when a download starts and let them return
            // when it ends. UpdateDownloadBar honors _downloadingActive: it forces every bar
            // to the hidden position while true, and lays them out normally once false.
            UpdateDownloadBar();
            // When dimCards is false (multi-install), keep all the asset cards visible/interactive
            // and skip the per-card dim overlay — the user wanted to still see the grid while a
            // batch installs. We still need to RESTORE cards when downloading ends, so only the
            // "apply dim" pass is skipped, not the "clear dim" pass.
            if (downloading && !dimCards)
                return;
            var assetBgTex = LoadImage("Assets", "Asset_Background");
            
            foreach (var item in _assetItems)
            {
                var hitArea = item.button; // item.button is the hitArea element
                bool isThisOne = (hitArea == excludeBtn);
                bool shouldDim = downloading && !isThisOne;
                
                // Hide this card's "% OFF" sale badge while dimmed - done FIRST, before any
                // early-continue below, so it always runs. The sale-amount element is a
                // SIBLING of the inner btn-visual (added to hitArea so it can spill past the
                // card edges), which means it draws ABOVE the dim overlay that lives inside
                // btn-visual. Hiding it is the reliable way to keep it under the dim. It is
                // restored to the user's _showSaleAmount preference when downloading ends.
                var saleBadgeEl = hitArea.Q<VisualElement>("sale-amount");
                if (saleBadgeEl != null)
                {
                    if (shouldDim)
                        saleBadgeEl.style.display = DisplayStyle.None;
                    else if (!downloading)
                        saleBadgeEl.style.display = _showSaleAmount ? DisplayStyle.Flex : DisplayStyle.None;
                }
                
                var btnVisual = hitArea.Q<VisualElement>("asset-btn-visual");
                if (btnVisual == null) continue;
                
                // Find or create the dim overlay on the inner btn-visual (matches single-asset download)
                var dimOvr = btnVisual.Q<VisualElement>("download-dim-overlay");
                if (dimOvr == null && shouldDim)
                {
                    dimOvr = new VisualElement();
                    dimOvr.name = "download-dim-overlay";
                    dimOvr.pickingMode = PickingMode.Ignore;
                    dimOvr.style.position = Position.Absolute;
                    dimOvr.style.borderBottomLeftRadius = 8;
                    dimOvr.style.borderBottomRightRadius = 8;
                    dimOvr.style.borderTopLeftRadius = 8;
                    dimOvr.style.borderTopRightRadius = 8;
                    dimOvr.style.overflow = Overflow.Hidden;
                    if (assetBgTex != null)
                    {
                        dimOvr.style.backgroundImage = new StyleBackground(assetBgTex);
                        dimOvr.style.SetBackgroundStretchToFill();
                        dimOvr.style.unityBackgroundImageTintColor = DimOverlayColor;
                    }
                    else
                    {
                        dimOvr.style.backgroundColor = DimOverlayColor;
                    }
                    ApplyDimOverlayExtension(dimOvr);
                    btnVisual.Add(dimOvr);
                    dimOvr.BringToFront();
                }
                else if (dimOvr != null)
                {
                    dimOvr.style.display = shouldDim ? DisplayStyle.Flex : DisplayStyle.None;
                    if (shouldDim) dimOvr.BringToFront();
                }
                
                // Lock/unlock input — never touch the downloading card's hitArea (RunSingleDownload manages it)
                if (!isThisOne)
                    hitArea.pickingMode = shouldDim ? PickingMode.Ignore : PickingMode.Position;
            }
            
            // Hide the exclusive-deal popups (the scaled "% OFF" sale badges, the
            // "EXCLUSIVE DEAL" badges, and any open price tooltip) while a download is in
            // progress. These elements are scaled up and overflow their cards, so a flat
            // dim rectangle cannot cover them - turning them off entirely is the reliable
            // fix. They are turned back on when the download finishes.
            SetDealPopupsVisible(!downloading);
        }
        
        // Shows or hides every exclusive-deal popup element across all deal cards. Called
        // with false at download start and true at download end. Uses display:none so the
        // elements take up no space and definitely cannot paint over the download dim.
        private void SetDealPopupsVisible(bool visible)
        {
            if (_dealsContainer == null) return;
            var disp = visible ? DisplayStyle.Flex : DisplayStyle.None;
            _dealsContainer.Query<VisualElement>("deal-sale-amount").ForEach(e => e.style.display = disp);
            _dealsContainer.Query<VisualElement>("deal-price-tooltip").ForEach(e => e.style.display = DisplayStyle.None);
            _dealsContainer.Query<VisualElement>("deal-badge").ForEach(e =>
                e.style.display = (visible && _showDealBadge) ? DisplayStyle.Flex : DisplayStyle.None);
        }
        
        /// <summary>
        /// Re-apply the green installed overlay to all assets that are installed.
        /// Ensures overlays are correct after multi-download sequences where dimming may have obscured them.
        /// </summary>
        /// <summary>
        /// Resume downloads that were in progress before a domain reload.
        /// The SyntyDownloadManager persists its queue, but the UI-side queue is lost.
        /// This re-creates the visual download animations for pending items.
        /// </summary>
        // If a batch was interrupted by a full Unity restart/crash, a disk resume file remains.
        // Prompt the user to continue installing the remaining packs (or discard).
        private void TryOfferBatchResume()
        {
            int remaining = 0;
            try { remaining = SyntyDownloadManager.Instance.PendingDiskResumeCount(); } catch { }
            if (remaining <= 0) return;
            // Auto-discard an interrupted batch instead of prompting to resume. The "Resume Install"
            // prompt was intrusive — it reappeared on every open until acted on. Discarding is safe:
            // already-installed packs stay installed, and the user can just re-run the install for any
            // that are missing (cached packs re-install instantly). The normal in-session domain-reload
            // resume (ResumePendingDownloads) is separate and unaffected.
            Dbg($"[Install] Auto-discarding interrupted batch ({remaining} pack(s) left).");
            try { SyntyDownloadManager.Instance.DiscardDiskResume(); } catch { }
        }

        private void ResumePendingDownloads()
        {
            var queue = SyntyDownloadManager.Instance.Queue;
            if (queue == null || queue.Count == 0) return;
            
            // Remove already-installed items from the queue
            queue.RemoveAll(d => SyntyInstallManifest.HasManifest(d.productHandle));
            
            var pending = queue.FindAll(d => 
                d.status == SyntyDownloadManager.DownloadStatus.Queued || 
                d.status == SyntyDownloadManager.DownloadStatus.Downloading ||
                d.status == SyntyDownloadManager.DownloadStatus.Importing);
            
            if (pending.Count == 0) return;
            
            // Set batch counters for resumed downloads. Read the ORIGINAL batch total from
            // SessionState (survives the domain reload reliably, unlike the window's fields which can
            // reset), so the "X of Y" count stays correct — total stays put and the current number
            // keeps climbing instead of restarting (which caused "1 of 17" then "1 of 16"). done =
            // how many have already finished = original total minus what's still pending.
            int origTotal = SessionState.GetInt(SESSION_BATCH_TOTAL, 0);
            if (origTotal < pending.Count) origTotal = pending.Count; // safety if the store was lost
            _activeDownloadCount = pending.Count;
            _multiInstallTotal = origTotal;
            _multiInstallDone = Mathf.Clamp(origTotal - pending.Count, 0, origTotal);
            _multiInstallCurrent = 0;

            // Re-apply the grid dim. A domain reload (from a pack's script recompile) rebuilds the
            // window UI without it, so without this the screen darken vanishes for the rest of the
            // batch — matching the "dim doesn't always turn on" symptom. Mirrors the install start;
            // the current card is spotlighted bright as each pack is processed below.
            _spotlightCard = null;
            SetDownloadingDimState(true);

            // Restart backend processing
            SyntyDownloadManager.Instance.StartProcessing();
            
            foreach (var item in pending)
            {
                // Find the matching asset button
                int btnIdx = -1;
                foreach (var kvp in _assetPackMapping)
                {
                    string handle = SyntyStoreService.ExtractHandleFromUrl(kvp.Value.storeUrl);
                    if (handle == item.productHandle)
                    {
                        btnIdx = kvp.Key;
                        break;
                    }
                }
                
                if (btnIdx < 0 || btnIdx >= _assetItems.Count) continue;
                
                var btn = _assetItems[btnIdx].button;
                var rRing = btn.Q<VisualElement>("radial-ring");
                var rRingBg = btn.Q<VisualElement>("radial-ring-bg");
                var dlBtn = btn.Q<VisualElement>("download-btn");
                var dlIcon = dlBtn?.Q<VisualElement>("download-icon");
                var selOvr = btn.Q<VisualElement>("asset-btn-selected");
                
                if (rRing == null || dlBtn == null) continue;
                
                string capturedHandle = item.productHandle;
                
                EnqueueDownload(() =>
                {
                    RunSingleDownload(rRing, rRingBg, dlBtn, dlIcon, selOvr, btn, null, null, () =>
                    {
                        ProcessDownloadQueue();
                    }, capturedHandle);
                });
            }
        }
        
        // Downloads every pack in the batch to the shared cache first (pure network I/O, so the
        // editor stays responsive and Cancel works during this phase), then runs the install pass
        // which imports from cache. Cancelling during download keeps already-downloaded files cached
        // for an instant re-run later.
        // Fetches the total download size for the batch from the worker, shows a confirm prompt
        // (always for multi-installs; flags large batches over 1GB), then runs the pre-download +
        // install on confirm, or restores the UI on cancel (nothing has downloaded yet, so it's safe).
        private async void ConfirmMultiInstallSizeThenRun(List<AssetPackData> packs, System.Action startInstallPass)
        {
            Dbg($"[Install] ConfirmMultiInstallSizeThenRun entered, packs={packs.Count}");
            // Hold assembly reloads locked across the async size fetch below. Without this, a stray
            // domain reload (e.g. a background recompile) during the await discards this async
            // continuation and silently aborts the whole install — which is what stranded a 136-pack
            // "install all" (the log showed a reload immediately after this method was entered).
            // Released with a plain unlock right after the fetch; downloads/install past that point
            // already survive reloads via the manager's queue resume.
            LockAssemblyReloadForBatch();
            long totalBytes = -1;
            try
            {
                var handles = new List<string>();
                foreach (var p in packs)
                {
                    // Don't count packs already in the local cache — they won't be downloaded again.
                    if (!string.IsNullOrEmpty(p.bucketFilename) &&
                        SyntyDownloadManager.IsInDownloadCache(p.bucketFilename))
                        continue;
                    string h = SyntyStoreService.ExtractHandleFromUrl(p.storeUrl);
                    if (!string.IsNullOrEmpty(h)) handles.Add(h);
                }
                if (handles.Count == 0)
                {
                    // Everything is already cached — no download needed. Skip the size request.
                    totalBytes = 0;
                }
                else
                {
                string json = "{\"handles\":[" + string.Join(",", handles.ConvertAll(h => "\"" + h + "\"")) + "]}";
                var req = new UnityEngine.Networking.UnityWebRequest(
                    "https://synty-downloads.syntystore.workers.dev/download-size", "POST");
                req.uploadHandler = new UnityEngine.Networking.UploadHandlerRaw(
                    System.Text.Encoding.UTF8.GetBytes(json));
                req.downloadHandler = new UnityEngine.Networking.DownloadHandlerBuffer();
                req.SetRequestHeader("Content-Type", "application/json");
                req.timeout = 15; // seconds — server-side per-request cap
                var op = req.SendWebRequest();
                // Wall-clock guard: if the request stalls (large handle lists can be slow or the
                // endpoint may not respond), give up after 12s and proceed with an unknown size
                // rather than hanging the whole install.
                double startT = EditorApplication.timeSinceStartup;
                while (!op.isDone)
                {
                    if (EditorApplication.timeSinceStartup - startT > 12.0)
                    {
                        Synty.Tools.SyntyLog.Warn("[Install] size request timed out; proceeding with unknown size.");
                        break;
                    }
                    await System.Threading.Tasks.Task.Yield();
                }
                if (!this) return;
                if (op.isDone && req.result == UnityEngine.Networking.UnityWebRequest.Result.Success)
                {
                    var txt = req.downloadHandler.text ?? "";
                    var m = System.Text.RegularExpressions.Regex.Match(txt, "\"totalBytes\"\\s*:\\s*(\\d+)");
                    if (m.Success) long.TryParse(m.Groups[1].Value, out totalBytes);
                }
                try { req.Dispose(); } catch { }
                }
            }
            catch (System.Exception e)
            {
                Synty.Tools.SyntyLog.Warn($"Could not fetch download size: {e.Message}");
            }
            // NOTE: do NOT unlock assembly reload here. The batch lock (taken before this method) must
            // hold through the whole install so a scripted asset can't trigger a domain reload
            // mid-batch — a mid-batch reload restarts the queue with only the remaining packs and
            // resets the "X of Y" counter (e.g. "1 of 6" then "1 of 5"). The lock is released once
            // when the batch finishes, or on cancel below.
            if (!this) return;

            string sizeText = totalBytes >= 0 ? FormatBytes(totalBytes) : "an unknown size";
            const long PROMPT_THRESHOLD = 500L * 1024 * 1024; // 500 MB
            bool large = totalBytes >= 1073741824L; // 1 GB
            Dbg($"[Install] size fetch done. totalBytes={totalBytes}");
            // If nothing needs downloading (everything already cached), or the download is small
            // (under 500 MB), skip the prompt and go straight to installing. Only ask for larger
            // downloads (500 MB or more), where the user may want to decide before committing.
            if (totalBytes == 0 || (totalBytes > 0 && totalBytes < PROMPT_THRESHOLD))
            {
                Dbg("[Install] under threshold or all cached -> startInstallPass");
                startInstallPass();
                return;
            }

            string msg;
            if (totalBytes < 0)
                msg = $"You are about to download and install {packs.Count} asset packs.";
            else
                msg = $"You are about to download and install {packs.Count} asset packs ({sizeText} to download).";
            if (large)
                msg += "\n\nThis is a large download and may take a while. It cannot be cancelled once installing begins.";
            msg += "\n\nContinue?";

            bool ok = EditorUtility.DisplayDialog("Download Asset Packs", msg, "Continue", "Cancel");
            if (!ok)
            {
                // Nothing downloaded yet — just restore the UI to its normal state.
                _multiInstallTotal = 0;
                _multiInstallCurrent = 0;
                _multiInstallDone = 0;
                SessionState.SetInt(SESSION_BATCH_TOTAL, 0);
                _downloadQueueRunning = false;
                _batchCancelled = false;
                _installProgressTotal = 0;
                EditorUtility.ClearProgressBar();
                UnlockAssemblyReloadPlain();
                SetDownloadingDimState(false);
                RestoreUiAfterDownloads();
                return;
            }
            // Downloads + installs are handled by the manager's proven queue (survives domain
            // reloads, downloads then imports each pack). The size prompt above is the safe cancel
            // point; once this runs, the batch proceeds through the manager.
            startInstallPass();
        }

        // Human-readable byte size (e.g. "4.2 GB", "780 MB").
        private static string FormatBytes(long bytes)
        {
            if (bytes >= 1073741824L) return (bytes / 1073741824.0).ToString("0.0") + " GB";
            if (bytes >= 1048576L) return (bytes / 1048576.0).ToString("0") + " MB";
            if (bytes >= 1024L) return (bytes / 1024.0).ToString("0") + " KB";
            return bytes + " B";
        }

        private void RefreshInstalledOverlays()
        {
            foreach (var kvp in _assetPackMapping)
            {
                if (kvp.Key < 0 || kvp.Key >= _assetItems.Count) continue;
                
                var pack = kvp.Value;
                var assetBtnEarly = _assetItems[kvp.Key].button;
                var btnVisualEarly = assetBtnEarly.Q<VisualElement>("asset-btn-visual");
                // Treat a card as installed if EITHER the catalog bridge reports it installed
                // OR it was already marked with the asset-installed class during this session.
                // The filesystem check (IsInstalled) can briefly lag right after an import, so
                // relying on it alone caused the green overlay to sometimes not appear.
                bool markedInstalled = btnVisualEarly?.ClassListContains("asset-installed") ?? false;
                if (!SyntyCatalogBridge.IsInstalled(pack) && !markedInstalled) continue;
                
                // Only show installed state if the user actually owns this asset
                bool isOwned = _assetItems[kvp.Key].getOwned() || _licenseSyntyPass;
                if (!isOwned) continue;
                
                var assetBtn = _assetItems[kvp.Key].button;
                var btnVisual = assetBtn.Q<VisualElement>("asset-btn-visual");
                
                // Baseline legacy installs: if this asset is installed but has no recorded version
                // (installed before version tracking), stamp it with the current catalog version so
                // it reads as up-to-date now and only flags on genuine future bumps. Never overwrites
                // a real recorded version.
                {
                    string upHandle = pack.packName;
                    if (string.IsNullOrEmpty(upHandle))
                        upHandle = SyntyStoreService.ExtractHandleFromUrl(pack.storeUrl);
                    SyntyInstallManifest.StampInstalledVersionIfMissing(upHandle, pack.version);
                }
                
                bool hasUpdate = SyntyCatalogBridge.HasUpdate(pack);
                if (hasUpdate)
                {
                    string upH = pack.packName;
                    if (string.IsNullOrEmpty(upH)) upH = SyntyStoreService.ExtractHandleFromUrl(pack.storeUrl);
                    if (!string.IsNullOrEmpty(upH) && _loggedUpdateHandles.Add(upH))
                    {
                        var ie = SyntyInstallManifest.GetEntry(upH);
                        string oldV = ie != null ? ie.installedVersion : "";
                        if (!string.IsNullOrEmpty(oldV) && !string.IsNullOrEmpty(pack.version))
                            Synty.Tools.SyntyLog.Info($"Update available for {pack.displayName}: v{oldV} to v{pack.version}");
                        else
                            Synty.Tools.SyntyLog.Info($"Update available for {pack.displayName}");
                    }
                }
                Color overlayColor = hasUpdate ? _updateBtnColor : _installedBtnColor;
                
                // Ensure overlay is visible with correct color
                var selOvr = assetBtn.Q<VisualElement>("asset-btn-selected");
                if (selOvr != null)
                {
                    selOvr.style.unityBackgroundImageTintColor = overlayColor;
                    selOvr.style.opacity = 1;
                }
                
                // Ensure gradient has correct color
                var gradOvr = btnVisual?.Q<VisualElement>("asset-btn-gradient");
                if (gradOvr != null)
                {
                    gradOvr.style.unityBackgroundImageTintColor = overlayColor;
                    gradOvr.style.display = DisplayStyle.Flex;
                }
                
                // Ensure correct class is set
                if (hasUpdate)
                {
                    btnVisual?.AddToClassList("asset-has-update");
                    btnVisual?.RemoveFromClassList("asset-installed");
                    
                    // Update download button to show update icon/color
                    var dlBtn = assetBtn.Q<VisualElement>("download-btn");
                    if (dlBtn != null)
                    {
                        dlBtn.style.unityBackgroundImageTintColor = _updateBtnColor;
                        dlBtn.style.display = DisplayStyle.Flex;
                        var dlIcon = dlBtn.Q<VisualElement>("download-icon");
                        if (dlIcon != null && _updateIcon != null)
                        {
                            dlIcon.style.backgroundImage = new StyleBackground(_updateIcon);
                            dlIcon.style.unityBackgroundImageTintColor = _downloadBtnWhiteBg ? Color.white : Color.black;
                        }
                        var pressedOvr = dlBtn.Q<VisualElement>("download-pressed-overlay");
                        if (pressedOvr != null)
                        {
                            pressedOvr.style.display = DisplayStyle.Flex;
                            pressedOvr.style.unityBackgroundImageTintColor = _updateBtnColor;
                        }
                        if (dlBtn.userData is object[] refs && refs.Length >= 3)
                        {
                            if (refs[0] is Color[] btnColorRef) btnColorRef[0] = _updateBtnColor;
                            if (refs[1] is Color[] iconColorRef) iconColorRef[0] = Color.black;
                            if (refs[2] is bool[] installedRef) installedRef[0] = false;
                        }
                        // Update tooltip
                        Label ttLbl = null;
                        _downloadTooltipLabels.TryGetValue(dlBtn, out ttLbl);
                        if (ttLbl != null) ttLbl.text = "Update";
                        
                        // Trigger pop animation
                        TriggerUpdateBtnPop(dlBtn);
                    }
                    
                    // Show update badge instead of installed badge
                    RemoveInstalledBadge(assetBtn);
                    ShowUpdateBadge(assetBtn);
                }
                else
                {
                    btnVisual?.AddToClassList("asset-installed");
                    
                    // Clear any lingering DOWNLOADING/INSTALLING status badge. This is the key
                    // recovery for an asset that finished installing across a domain reload (e.g.
                    // it contained scripts): its completion event was lost, so the badge would
                    // otherwise stay on the card.
                    var stuckStatusBadge = assetBtn.Q<Label>("download-status-badge");
                    if (stuckStatusBadge != null) stuckStatusBadge.RemoveFromHierarchy();
                    
                    // Make sure the download button shows the finished (installed) look, in case
                    // the per-asset install animation ticker was killed by the reload before it
                    // could transition.
                    var dlBtnInstalled = assetBtn.Q<VisualElement>("download-btn");
                    if (dlBtnInstalled != null)
                    {
                        dlBtnInstalled.style.display = DisplayStyle.Flex;
                        dlBtnInstalled.style.unityBackgroundImageTintColor = _installedBtnColor;
                        dlBtnInstalled.pickingMode = PickingMode.Position;
                        var dlIconInstalled = dlBtnInstalled.Q<VisualElement>("download-icon");
                        if (dlIconInstalled != null && _installedIcon != null)
                        {
                            dlIconInstalled.style.backgroundImage = new StyleBackground(_installedIcon);
                            dlIconInstalled.style.unityBackgroundImageTintColor = Color.white;
                        }
                        var pressedOvrI = dlBtnInstalled.Q<VisualElement>("download-pressed-overlay");
                        if (pressedOvrI != null)
                        {
                            pressedOvrI.style.display = DisplayStyle.Flex;
                            pressedOvrI.style.unityBackgroundImageTintColor = _installedBtnColor;
                        }
                        if (dlBtnInstalled.userData is object[] refsI && refsI.Length >= 3)
                        {
                            if (refsI[0] is Color[] bc) bc[0] = _installedBtnColor;
                            if (refsI[1] is Color[] ic) ic[0] = Color.white;
                            if (refsI[2] is bool[] inst) inst[0] = true;
                        }
                        Label ttI = null;
                        _downloadTooltipLabels.TryGetValue(dlBtnInstalled, out ttI);
                        if (ttI != null) ttI.text = "Installed";
                    }
                    // Hide any leftover radial progress ring from the interrupted animation.
                    var ring = assetBtn.Q<VisualElement>("radial-ring");
                    if (ring != null) ring.style.display = DisplayStyle.None;
                    var ringBg = assetBtn.Q<VisualElement>("radial-ring-bg");
                    if (ringBg != null) ringBg.style.display = DisplayStyle.None;
                    
                    // Ensure installed badge is shown
                    if (assetBtn.Q<Label>("installed-badge") == null)
                        ShowInstalledBadge(assetBtn);
                }
            }
        }
        
        private void UpdateCollectionCounts()
        {
            // Keep the debug per-filter asset counts live as install/uninstall changes state.
            if (_debugFilterCounts) ApplyFilterCounts();
            if (_ownedCountLabel == null || _totalCountLabel == null) return;
            
            // Cancel any running percentage animation
            _percentageGeneration++;
            
            int totalCount = _assetItems.Count;
            int ownedCount = 0;
            
            // The "owns all" count only applies when the user ACTUALLY holds the Synty Pass.
            // If the filter is on but they don't own the pass, count individual purchases so
            // the percentage reflects real ownership instead of falsely showing 100%.
            if (_licenseSyntyPass && SyntyLoginManager.HasSyntyPass)
            {
                ownedCount = totalCount;
            }
            else
            {
                for (int i = 0; i < _assetItems.Count; i++)
                {
                    if (_assetPackMapping.TryGetValue(i, out var pack))
                    {
                        if (SyntyStoreService.Instance.OwnedProductHandles.Contains(pack.packName))
                            ownedCount++;
                    }
                }
            }
            
            int dispOwned = ownedCount, dispTotal = totalCount;
            if (_gridSettling)
            {
                // While the veil is up (fresh-open verify/rebuild can transiently dip the catalog),
                // show the last stable count so the header number doesn't flicker down and back up.
                dispOwned = SessionState.GetInt("SyntyImporter_LastOwned", ownedCount);
                dispTotal = SessionState.GetInt("SyntyImporter_LastTotal", totalCount);
            }
            else
            {
                SessionState.SetInt("SyntyImporter_LastOwned", ownedCount);
                SessionState.SetInt("SyntyImporter_LastTotal", totalCount);
            }
            _ownedCountLabel.text = dispOwned.ToString();
            _totalCountLabel.text = $"/{dispTotal}";
            
            // Single source of truth: percentage always derived from owned/total
            _currentPercentage = dispTotal > 0 ? Mathf.Round((float)dispOwned / dispTotal * 100f) : 0f;
            SetProgressBarPercent(_currentPercentage);
            if (_percentageText != null)
            {
                _percentageText.text = $"{(int)_currentPercentage}";
                _percentageText.style.fontSize = _percentageMaxFontSize;
            }
            if (_percentageSymbol != null)
                _percentageSymbol.style.fontSize = _percentageMaxFontSize * 0.75f;
        }
        
        private void UpdateProjectedBar()
        {
            if (_projectedBarFill == null) return;
            
            int selectedNotOwned = _assetItems.Count(i => i.getSelected() && !i.getOwned() && i.button.style.display != DisplayStyle.None);
            
            if (selectedNotOwned > 0)
            {
                int totalCount = _assetItems.Count;
                int ownedCount = _assetItems.Count(i => i.getOwned());
                float projectedPct = totalCount > 0 ? Mathf.Min((float)(ownedCount + selectedNotOwned) / totalCount * 100f, 100f) : 0f;
                if (_barGradientEnabled) UpdateProjectedBarGradient(); else SetBarFillTint(_projectedBarFillLeft, _projectedBarFillMid, _projectedBarFillRight, _cartBtnColor);
                _projectedBarFill.style.display = DisplayStyle.Flex;
                _projectedBarFill.style.width = Length.Percent(projectedPct);
            }
            else
            {
                // Hide entirely when nothing's selected — width 0 would still show the rounded caps
                _projectedBarFill.style.display = DisplayStyle.None;
                _projectedBarFill.style.width = Length.Percent(0);
            }
        }
        
        private float EaseIn(float t)
        {
            return t * t;
        }
        
        private float EaseOut(float t)
        {
            return 1f - (1f - t) * (1f - t);
        }
        
