        // An asset's themes are stored comma-joined in item.theme; it passes the theme filter when
        // ANY of its themes is currently selected.
        private bool ThemeMatches(string commaThemes)
        {
            if (string.IsNullOrEmpty(commaThemes)) return _selectedThemes.Contains("Other");
            foreach (var t in commaThemes.Split(','))
                if (_selectedThemes.Contains(t)) return true;
            return false;
        }

