        private void AddCollectionSection(VisualElement parent)
        {
            _collectionSection = new VisualElement();
            _collectionSection.name = "collection-section";
            _collectionSection.AddToClassList("collection-section");
            _collectionSection.style.paddingLeft = _collectionPadding;
            _collectionSection.style.paddingRight = _collectionPadding;
            _collectionSection.style.paddingTop = _collectionPadding;
            _collectionSection.style.paddingBottom = 0;
            _collectionSection.style.marginBottom = 0;
            parent.Add(_collectionSection);

            // ── Title ──────────────────────────────────────────────────────
            _collectionTitleLabel = new Label("ASSET PACK COLLECTION");
            _collectionTitleLabel.AddToClassList("collection-title");
            _collectionTitleLabel.style.marginLeft  = _collectionTitleX;
            _collectionTitleLabel.style.marginTop   = _collectionTitleY;
            _collectionTitleLabel.style.marginBottom = 4;
            _collectionSection.Add(_collectionTitleLabel);

            // ── Main row: [count | bar | percentage] ───────────────────────
            var mainRow = new VisualElement();
            mainRow.name = "collection-main-row";
            mainRow.AddToClassList("collection-main-row");
            _collectionSection.Add(mainRow);

            // ── Left: owned number + /total + PACKS ───────────────────────
            var countBlock = new VisualElement();
            countBlock.AddToClassList("collection-count-block");
            mainRow.Add(countBlock);

            // Stats row: large number + /total PACKS
            var statsRow = new VisualElement();
            statsRow.AddToClassList("collection-stats-row");
            countBlock.Add(statsRow);

            _ownedCountLabel = new Label("0");
            _ownedCountLabel.AddToClassList("collection-owned-count");
            _ownedCountLabel.style.fontSize = _ownedFontSize;
            _ownedCountLabel.style.marginLeft = _collectionOwnedX;
            _ownedCountLabel.style.marginTop   = _collectionOwnedY;
            statsRow.Add(_ownedCountLabel);

            var totalSection = new VisualElement();
            totalSection.AddToClassList("collection-total-section");
            statsRow.Add(totalSection);

            _totalWrapper = new VisualElement();
            _totalWrapper.style.marginLeft = _collectionTotalX;
            _totalWrapper.style.marginTop  = _collectionTotalY;
            totalSection.Add(_totalWrapper);

            _totalCountLabel = new Label("/100");
            _totalCountLabel.AddToClassList("collection-total-count");
            _totalCountLabel.style.fontSize = _totalFontSize;
            _totalWrapper.Add(_totalCountLabel);

            _packsWrapper = new VisualElement();
            _packsWrapper.style.marginLeft = _collectionPacksX;
            _packsWrapper.style.marginTop  = _collectionPacksY;
            totalSection.Add(_packsWrapper);

            _collectionPacksLabel = new Label("PACKS");
            _collectionPacksLabel.AddToClassList("collection-packs-label");
            _packsWrapper.Add(_collectionPacksLabel);

            // ── Centre: progress bar ───────────────────────────────────────
            _progressBarContainer = new VisualElement();
            _progressBarContainer.AddToClassList("progress-bar-container");
            _progressBarContainer.style.height = _progressBarHeight;
            mainRow.Add(_progressBarContainer);

            _progressBarBg = new VisualElement();
            _progressBarBg.AddToClassList("progress-bar-bg");
            // Remove USS bg color/radius — we use a 3-part cap track instead
            _progressBarBg.style.backgroundColor = Color.clear;
            _progressBarBg.style.borderTopLeftRadius = 0;
            _progressBarBg.style.borderTopRightRadius = 0;
            _progressBarBg.style.borderBottomLeftRadius = 0;
            _progressBarBg.style.borderBottomRightRadius = 0;
            _progressBarBg.style.overflow = Overflow.Visible;
            _progressBarContainer.Add(_progressBarBg);

            var capLeftTex  = LoadImage("Collection", "Percentage_Left");
            var capMidTex   = LoadImage("Collection", "Percentage_Mid");
            var capRightTex = LoadImage("Collection", "Percentage_Right");

            // Background track — simple rounded rect, no texture seams
            var bgTrack = new VisualElement();
            bgTrack.name = "progress-bar-bg-track";
            bgTrack.pickingMode = PickingMode.Ignore;
            bgTrack.style.position = Position.Absolute;
            bgTrack.style.top = 0; bgTrack.style.left = 0; bgTrack.style.right = 0; bgTrack.style.bottom = 0;
            bgTrack.style.backgroundColor = _progressBarBgColor;
            // Match the visual height of the scaled caps
            float bgTrackHeight = _progressBarHeight * _progressBarCapScaleY;
            float bgTrackOffset = (_progressBarHeight - bgTrackHeight) / 2f;
            bgTrack.style.height = bgTrackHeight;
            bgTrack.style.top = bgTrackOffset;
            bgTrack.style.borderTopLeftRadius = bgTrackHeight / 2f;
            bgTrack.style.borderTopRightRadius = bgTrackHeight / 2f;
            bgTrack.style.borderBottomLeftRadius = bgTrackHeight / 2f;
            bgTrack.style.borderBottomRightRadius = bgTrackHeight / 2f;
            _progressBarBg.Add(bgTrack);
            _progressBarBgTrack = bgTrack;

            (_progressBarFill, _progressBarFillLeft, _progressBarFillMid, _progressBarFillRight) =
                BuildBarFill(capLeftTex, capMidTex, capRightTex, _currentPercentage, _accentColor, true);
            _progressBarFill.style.transitionProperty = new List<StylePropertyName> { new StylePropertyName("width") };
            _progressBarFill.style.transitionDuration = new List<TimeValue> { new TimeValue(400, TimeUnit.Millisecond) };
            _progressBarFill.style.transitionTimingFunction = new List<EasingFunction> { new EasingFunction(EasingMode.EaseOut) };
            // Hide the fill outright when starting at 0% — the caps have fixed pixel widths so a
            // 0%-wide container still shows a small pill artifact otherwise.
            if (_currentPercentage <= 0f) _progressBarFill.style.display = DisplayStyle.None;
            _progressBarBg.Add(_progressBarFill);
            
            // Bar gradient overlay (vertex-colored mesh on fill container, clipped by border radius)
            // Bar gradient overlay (vertex-colored mesh on mid section, caps keep rounded texture)
            if (_barGradientEnabled)
            {
                _barGradCurrentLeft[0] = _barGradLeftColor;
                _barGradCurrentRight[0] = _barGradRightColor;
                _barGradientOverlay = CreateBarGradientOverlay(_progressBarFillMid, _barGradCurrentLeft, _barGradCurrentRight);
                _progressBarFillLeft.style.unityBackgroundImageTintColor = _barGradLeftColor;
                _progressBarFillMid.style.unityBackgroundImageTintColor = Color.clear;
                _progressBarFillRight.style.unityBackgroundImageTintColor = _barGradRightColor;
            }

            (_projectedBarFill, _projectedBarFillLeft, _projectedBarFillMid, _projectedBarFillRight) =
                BuildBarFill(capLeftTex, capMidTex, capRightTex, 0f, _cartBtnColor, true);
            _projectedBarFill.style.transitionProperty = new List<StylePropertyName> { new StylePropertyName("width") };
            _projectedBarFill.style.transitionDuration = new List<TimeValue> { new TimeValue((int)_projectedBarEaseDuration, TimeUnit.Millisecond) };
            _projectedBarFill.style.transitionTimingFunction = new List<EasingFunction> { new EasingFunction(EasingMode.EaseOut) };
            // Hide projected fill until something's actually selected — same pill artifact otherwise.
            _projectedBarFill.style.display = DisplayStyle.None;
            _progressBarBg.Insert(1, _projectedBarFill);
            
            // Projected bar gradient overlay
            if (_barGradientEnabled)
            {
                _projGradCurrentLeft[0] = _barGradProjectedLeftColor;
                _projGradCurrentRight[0] = _barGradProjectedRightColor;
                _projectedGradientOverlay = CreateBarGradientOverlay(_projectedBarFillMid, _projGradCurrentLeft, _projGradCurrentRight);
                _projectedBarFillLeft.style.unityBackgroundImageTintColor = _barGradProjectedLeftColor;
                _projectedBarFillMid.style.unityBackgroundImageTintColor = Color.clear;
                _projectedBarFillRight.style.unityBackgroundImageTintColor = _barGradProjectedRightColor;
            }
            
            // Centered "no assets" label — added LAST so it sits on top of the bg track AND the
            // fill bars. Position-absolute with all four sides at 0 spans the bar; flex centering
            // puts the text in the middle. Visible only at 0%.
            _emptyCollectionLabel = new Label(_emptyCollectionText);
            _emptyCollectionLabel.name = "empty-collection-label";
            _emptyCollectionLabel.pickingMode = PickingMode.Ignore;
            _emptyCollectionLabel.style.position = Position.Absolute;
            _emptyCollectionLabel.style.top = 0; _emptyCollectionLabel.style.left = 0;
            _emptyCollectionLabel.style.right = 0; _emptyCollectionLabel.style.bottom = 0;
            _emptyCollectionLabel.style.unityTextAlign = TextAnchor.MiddleCenter;
            _emptyCollectionLabel.style.color = _emptyCollectionTextColor;
            _emptyCollectionLabel.style.fontSize = 11;
            _emptyCollectionLabel.style.unityFontStyleAndWeight = FontStyle.Bold;
            _emptyCollectionLabel.style.display = _currentPercentage <= 0f ? DisplayStyle.Flex : DisplayStyle.None;
            _progressBarBg.Add(_emptyCollectionLabel);

            // ── Right: percentage number + % symbol ───────────────────────
            _percentageTextContainer = new VisualElement();
            _percentageTextContainer.AddToClassList("percentage-text-container");
            _percentageTextContainer.style.marginLeft = _progressTextX;
            _percentageTextContainer.style.marginTop  = _progressTextY;
            mainRow.Add(_percentageTextContainer);

            _percentageText = new Label($"{(int)_currentPercentage}");
            _percentageText.AddToClassList("percentage-text");
            _percentageText.style.color = _percentageTextColor;
            _percentageText.style.transitionProperty = new List<StylePropertyName> { new StylePropertyName("color") };
            _percentageText.style.transitionDuration = new List<TimeValue> { new TimeValue(400, TimeUnit.Millisecond) };
            _percentageText.style.transitionTimingFunction = new List<EasingFunction> { new EasingFunction(EasingMode.EaseOut) };
            _percentageTextContainer.Add(_percentageText);

            _percentageSymbol = new Label("%");
            _percentageSymbol.AddToClassList("percentage-symbol");
            _percentageSymbol.style.color = _percentageSymColor;
            _percentageSymbol.style.marginLeft = _progressSymbolX;
            _percentageSymbol.style.marginTop  = _progressSymbolY;
            _percentageSymbol.style.transitionProperty = new List<StylePropertyName> { new StylePropertyName("color") };
            _percentageSymbol.style.transitionDuration = new List<TimeValue> { new TimeValue(400, TimeUnit.Millisecond) };
            _percentageSymbol.style.transitionTimingFunction = new List<EasingFunction> { new EasingFunction(EasingMode.EaseOut) };
            _percentageTextContainer.Add(_percentageSymbol);
        }

