                        item.setSelected(true);
                UpdateDownloadBar();
                UpdateSelectButtonStates();
            });
            allBtn.text = "All";
            allBtn.AddToClassList("asset-options-select-btn");
            allBtn.style.fontSize = _selectBtnFontSize;
            allBtn.style.paddingLeft = _selectBtnPaddingH;
            allBtn.style.paddingRight = _selectBtnPaddingH;
            allBtn.style.borderTopLeftRadius = _selectBtnRadius;
            allBtn.style.borderTopRightRadius = _selectBtnRadius;
            allBtn.style.borderBottomLeftRadius = _selectBtnRadius;
            allBtn.style.borderBottomRightRadius = _selectBtnRadius;
            allBtn.style.backgroundColor = _assetOptionsSelectBtnBg;
            allBtn.style.color = _assetOptionsSelectBtnText;
            AddSelectBtnHover(allBtn);
            _selectAllBtn = allBtn;
            selectBtnRow.Add(allBtn);
            
            var noneBtn = new Button(() => {
                if (NoneVisibleSelected()) return; // already none selected
                foreach (var item in _assetItems)
                    item.setSelected(false);
                UpdateDownloadBar();
                UpdateSelectButtonStates();
            });
            noneBtn.text = "None";
            noneBtn.AddToClassList("asset-options-select-btn");
            noneBtn.style.fontSize = _selectBtnFontSize;
            noneBtn.style.paddingLeft = _selectBtnPaddingH;
            noneBtn.style.paddingRight = _selectBtnPaddingH;
            noneBtn.style.borderTopLeftRadius = _selectBtnRadius;
            noneBtn.style.borderTopRightRadius = _selectBtnRadius;
            noneBtn.style.borderBottomLeftRadius = _selectBtnRadius;
            noneBtn.style.borderBottomRightRadius = _selectBtnRadius;
            noneBtn.style.backgroundColor = _assetOptionsSelectBtnBg;
            noneBtn.style.color = _assetOptionsSelectBtnText;
            AddSelectBtnHover(noneBtn);
            _selectNoneBtn = noneBtn;
            selectBtnRow.Add(noneBtn);
            
            // Search field with icon (no label, just grows)
            _searchContainer = new VisualElement();
            _searchContainer.AddToClassList("asset-options-search-container");
            _searchContainer.style.height = _searchBarHeight;
            _searchContainer.style.borderTopLeftRadius = _searchBarRadius;
            _searchContainer.style.borderTopRightRadius = _searchBarRadius;
            _searchContainer.style.borderBottomLeftRadius = _searchBarRadius;
            _searchContainer.style.borderBottomRightRadius = _searchBarRadius;
            _searchContainer.style.paddingLeft = _searchBarPaddingH;
            _searchContainer.style.paddingRight = _searchBarPaddingH;
            _searchContainer.style.marginRight = _assetOptionsSpacing;
            _searchContainer.style.marginLeft = _selectSearchSpacing;
            _searchContainer.style.backgroundColor = _assetOptionsSearchBg;
            _assetOptionsSection.Add(_searchContainer);
            
            var searchIcon = new VisualElement();
            searchIcon.AddToClassList("asset-options-search-icon");
            searchIcon.style.marginLeft = _searchIconX;
            searchIcon.style.unityBackgroundImageTintColor = _searchIconColor;
            var searchIconTex = LoadImage("Icons/Misc", "Icon_Search");
            if (searchIconTex != null) searchIcon.style.backgroundImage = new StyleBackground(searchIconTex);
            _searchIconRef = searchIcon;
            _searchContainer.Add(searchIcon);
            
            _searchField = new TextField();
            _searchField.AddToClassList("asset-options-search-field");
            _searchField.style.fontSize = _searchFontSize;
            _searchField.style.marginLeft = _searchTextX;
            _searchField.style.color = _searchTextColor;
            _searchField.value = _searchQuery ?? "";
            _searchPlaceholder = new Label("Search Assets...");
            _searchPlaceholder.AddToClassList("asset-options-search-placeholder");
            _searchPlaceholder.style.fontSize = _searchFontSize;
            _searchPlaceholder.pickingMode = PickingMode.Ignore;
            if (!string.IsNullOrEmpty(_searchQuery)) _searchPlaceholder.style.display = DisplayStyle.None;
            _searchField.Add(_searchPlaceholder);
            _searchField.RegisterCallback<FocusInEvent>(evt => _searchPlaceholder.style.display = DisplayStyle.None);
            _searchField.RegisterCallback<FocusOutEvent>(evt => {
                if (string.IsNullOrEmpty(_searchField.value))
                    _searchPlaceholder.style.display = DisplayStyle.Flex;
            });
            _searchField.RegisterValueChangedCallback(evt => {
                _searchQuery = evt.newValue;
                if (!string.IsNullOrEmpty(evt.newValue) && evt.newValue.Length >= 3)
                    SyntyAnalytics.TrackSearch(evt.newValue);
                SaveFilterStates();
                FilterAssets();
                // Show/hide clear button based on content
                _searchClearBtn.style.display = string.IsNullOrEmpty(evt.newValue) ? DisplayStyle.None : DisplayStyle.Flex;
            });
            _searchContainer.Add(_searchField);
            
            // Clear button (X) — uses Button for reliable click handling
            var clearBtn = new Button(() => {
                _searchField.value = "";
                _searchQuery = "";
                FilterAssets();
                _searchClearBtn.style.display = DisplayStyle.None;
                _searchPlaceholder.style.display = DisplayStyle.Flex;
            });
            clearBtn.text = "✕";
            clearBtn.AddToClassList("asset-options-search-clear");
            clearBtn.style.fontSize = 11;
            clearBtn.style.color = new Color(0.7f, 0.7f, 0.7f, 1f);
            clearBtn.style.unityFontStyleAndWeight = FontStyle.Bold;
            clearBtn.style.unityTextAlign = TextAnchor.MiddleCenter;
            clearBtn.style.paddingLeft = 0;
            clearBtn.style.paddingRight = 0;
            clearBtn.style.paddingTop = 0;
            clearBtn.style.paddingBottom = 0;
            clearBtn.style.borderTopWidth = 0;
            clearBtn.style.borderBottomWidth = 0;
            clearBtn.style.borderLeftWidth = 0;
            clearBtn.style.borderRightWidth = 0;
            clearBtn.style.display = string.IsNullOrEmpty(_searchQuery) ? DisplayStyle.None : DisplayStyle.Flex;
            // The search field has flex-grow:1 and fills the row, which pushed this button
            // past the container's right edge (so it was invisible). flex-shrink:0 + a fixed
            // size keeps the X reserved on the right, and we make the field yield space.
            clearBtn.style.flexShrink = 0;
            clearBtn.style.flexGrow = 0;
            clearBtn.style.width = 20;
            clearBtn.style.height = 20;
            clearBtn.style.minWidth = 20;
            _searchField.style.flexShrink = 1;
            _searchClearBtn = clearBtn;
            _searchContainer.Add(_searchClearBtn);
            
            // Sort group (label above dropdown)
            _sortGroup = new VisualElement();
            _sortGroup.AddToClassList("asset-options-group");
            _sortGroup.style.marginLeft = _sortDropdownX;
            _sortGroup.style.marginTop = _sortDropdownY;
            _sortGroup.style.flexDirection = FlexDirection.Column;
            _sortGroup.style.flexGrow = 0;
            _sortGroup.style.flexShrink = 0;
            _sortGroup.style.width = _sortDropdownWidth;
            _assetOptionsSection.Add(_sortGroup);
            
            var sortLabel = new Label(_labelUppercase ? "SORT" : "Sort");
            sortLabel.AddToClassList("asset-options-label");
            sortLabel.style.fontSize = _selectLabelFontSize;
            sortLabel.style.marginBottom = _sortLabelY;
            sortLabel.style.color = _assetOptionsLabelColor;
            sortLabel.style.unityFontStyleAndWeight = _labelBold ? FontStyle.Bold : FontStyle.Normal;
            _sortLabelRef = sortLabel;
            _sortGroup.Add(sortLabel);
            
            _sortDropdown = new DropdownField(new List<string> { "Release Date", "On Sale", "Updates", "Installed", "Name", "Price (Low to High)", "Price (High to Low)" }, _sortMode);
            _sortDropdown.AddToClassList("asset-options-sort");
            _sortDropdown.style.width = _sortDropdownWidth;
            _sortDropdown.style.maxWidth = _sortDropdownWidth;
            _sortDropdown.style.flexShrink = 0;
            // Refresh available sort options when dropdown is clicked (before it opens)
            _sortDropdown.RegisterCallback<MouseDownEvent>(evt => {
                UpdateSortDropdownChoices();
            }, TrickleDown.TrickleDown);
            _sortDropdown.RegisterValueChangedCallback(evt => {
                _sortMode = evt.newValue switch {
                    "On Sale" => 1,
                    "Updates" => 2,
                    "Installed" => 3,
                    "Name" => 4,
                    "Price (Low to High)" => 5,
                    "Price (High to Low)" => 6,
                    _ => 0 // Release Date
                };
                _userPickedSort = true; // respect this choice; stop auto-sort from overriding it
                EditorPrefs.SetBool(PREFS_USER_PICKED_SORT, true);
                _sortDirty = true;
                SaveFilterStates();
                FilterAssets();
            });
            _sortGroup.Add(_sortDropdown);
            _sortDropdown.AddToClassList("link-cursor");
            // Hover visual on the sort dropdown: lighten its input background on mouse-over.
            _sortDropdown.RegisterCallback<MouseEnterEvent>(_ => {
                var ve = _sortDropdown.Q<VisualElement>(className: "unity-base-popup-field__input");
                if (ve != null) ve.style.backgroundColor = new Color(
                    Mathf.Min(1f, _assetOptionsSortBg.r + 0.08f),
                    Mathf.Min(1f, _assetOptionsSortBg.g + 0.08f),
                    Mathf.Min(1f, _assetOptionsSortBg.b + 0.08f), 1f);
            });
            _sortDropdown.RegisterCallback<MouseLeaveEvent>(_ => {
                var ve = _sortDropdown.Q<VisualElement>(className: "unity-base-popup-field__input");
                if (ve != null) ve.style.backgroundColor = _assetOptionsSortBg;
            });
            
            // Replace the default arrow with custom one after dropdown is added
            _sortDropdown.RegisterCallback<GeometryChangedEvent>(evt => {
                if (_dropdownArrowDown != null)
                {
                    // Find and replace the default arrow
                    var defaultArrow = _sortDropdown.Q(className: "unity-base-popup-field__arrow");
                    if (defaultArrow != null)
                    {
                        defaultArrow.style.backgroundImage = new StyleBackground(_dropdownArrowDown);
                        defaultArrow.style.width = 12;
                        defaultArrow.style.height = 12;
                        defaultArrow.style.SetBackgroundScaleToFit();
                    }
                }
                // Apply sort text color, bold, and bg
                var sortInputVe = _sortDropdown.Q<VisualElement>(className: "unity-base-popup-field__input");
                if (sortInputVe != null)
                {
                    sortInputVe.style.backgroundColor = _assetOptionsSortBg;
                    sortInputVe.style.borderTopLeftRadius = _sortDropdownRadius;
                    sortInputVe.style.borderTopRightRadius = _sortDropdownRadius;
                    sortInputVe.style.borderBottomLeftRadius = _sortDropdownRadius;
                    sortInputVe.style.borderBottomRightRadius = _sortDropdownRadius;
                    // Reduce the dropdown height ~20% and scale it from the bottom: trim more
                    // off the TOP padding than the bottom so the lower edge stays put while the
                    // box gets shorter. Base padding is 6px top/bottom; ~20% off the total
                    // vertical padding (12px -> ~9.6px) with the cut weighted to the top.
                    sortInputVe.style.paddingTop = 3f;
                    sortInputVe.style.paddingBottom = 6f;
                }
                var sortTextEl = _sortDropdown.Q<TextElement>();
                if (sortTextEl != null)
                {
                    sortTextEl.style.color = _assetOptionsSortText;
                    sortTextEl.style.fontSize = _sortFontSize;
                    sortTextEl.style.unityFontStyleAndWeight = _sortTextBold ? FontStyle.Bold : FontStyle.Normal;
                }
            });
            
            // Thumbnail size toggle button
            var thumbGroup = new VisualElement();
            thumbGroup.style.flexShrink = 0;
            thumbGroup.style.marginLeft = _sortThumbSpacing;
            thumbGroup.style.alignItems = Align.Center;
            thumbGroup.style.justifyContent = Justify.Center;
            _assetOptionsSection.Add(thumbGroup);
            
            _thumbToggleBtnRef = new Button();
            _thumbToggleBtnRef.AddToClassList("asset-options-thumb-btn");
            _thumbToggleBtnRef.style.width = _thumbBtnSize;
            _thumbToggleBtnRef.style.height = _thumbBtnSize;
            _thumbToggleBtnRef.style.borderTopLeftRadius = _thumbBtnRadius;
            _thumbToggleBtnRef.style.borderTopRightRadius = _thumbBtnRadius;
            _thumbToggleBtnRef.style.borderBottomLeftRadius = _thumbBtnRadius;
            _thumbToggleBtnRef.style.borderBottomRightRadius = _thumbBtnRadius;
            _thumbToggleBtnRef.style.backgroundColor = _assetOptionsThumbBg;
            
            // Grid icon element
            var gridIcon = new VisualElement();
            gridIcon.name = "grid-size-icon";
            gridIcon.pickingMode = PickingMode.Ignore;
            gridIcon.style.width = _thumbBtnSize * 0.6f;
            gridIcon.style.height = _thumbBtnSize * 0.6f;
            gridIcon.style.alignSelf = Align.Center;
            gridIcon.style.SetBackgroundScaleToFit();
            _thumbToggleBtnRef.Add(gridIcon);
            _thumbToggleBtnRef.style.justifyContent = Justify.Center;
            _thumbToggleBtnRef.style.alignItems = Align.Center;
            _thumbToggleBtnRef.style.translate = new Translate(_thumbBtnX, _thumbBtnY);
            
            // Load grid icons
            _gridIconBig = LoadImage("Icons/Misc", "Icon_Grid_Big");
            if (_gridIconBig == null) _gridIconBig = LoadImage("Filter", "Icon_Grid_Big");
            _gridIconMedium = LoadImage("Icons/Misc", "Icon_Grid_Medium");
            if (_gridIconMedium == null) _gridIconMedium = LoadImage("Filter", "Icon_Grid_Medium");
            _gridIconSmall = LoadImage("Icons/Misc", "Icon_Grid_Small");
            if (_gridIconSmall == null) _gridIconSmall = LoadImage("Filter", "Icon_Grid_Small");
            
            UpdateGridIcon(gridIcon);
            
            ((Button)_thumbToggleBtnRef).clicked += () => {
                _thumbnailColumns = _thumbnailColumns >= MAX_COLUMNS ? MIN_COLUMNS : _thumbnailColumns + 1;
                SyntyAnalytics.TrackGridSize(_thumbnailColumns);
                UpdateGridIcon(gridIcon);
                UpdateThumbnailSize();
            };
            thumbGroup.Add(_thumbToggleBtnRef);
            // Hover visual on the thumbnail size button (lighten on mouse-over) + link cursor.
            _thumbToggleBtnRef.AddToClassList("link-cursor");
            var thumbBaseBg = _assetOptionsThumbBg;
            var thumbHoverBg = new Color(
                Mathf.Min(1f, _assetOptionsThumbBg.r + 0.08f),
                Mathf.Min(1f, _assetOptionsThumbBg.g + 0.08f),
                Mathf.Min(1f, _assetOptionsThumbBg.b + 0.08f), 1f);
            _thumbToggleBtnRef.RegisterCallback<MouseEnterEvent>(_ => _thumbToggleBtnRef.style.backgroundColor = thumbHoverBg);
            _thumbToggleBtnRef.RegisterCallback<MouseLeaveEvent>(_ => _thumbToggleBtnRef.style.backgroundColor = thumbBaseBg);
            
            // ── Refresh Assets button (same size as the thumbnail button) ──
            // Re-checks the user's actual owned assets + Synty Pass from the backend (force
            // refresh, bypassing the verify cache) and redraws ownership on the asset buttons.
            var refreshGroup = new VisualElement();
            refreshGroup.style.flexShrink = 0;
            refreshGroup.style.marginLeft = _sortThumbSpacing;
            refreshGroup.style.alignItems = Align.Center;
            refreshGroup.style.justifyContent = Justify.Center;
            _assetOptionsSection.Add(refreshGroup);
            
            _refreshAssetsBtnRef = new Button();
            _refreshAssetsBtnRef.AddToClassList("asset-options-thumb-btn");
            _refreshAssetsBtnRef.AddToClassList("link-cursor");
            _refreshAssetsBtnRef.style.width = _thumbBtnSize;
            _refreshAssetsBtnRef.style.height = _thumbBtnSize;
            _refreshAssetsBtnRef.style.borderTopLeftRadius = _thumbBtnRadius;
            _refreshAssetsBtnRef.style.borderTopRightRadius = _thumbBtnRadius;
            _refreshAssetsBtnRef.style.borderBottomLeftRadius = _thumbBtnRadius;
            _refreshAssetsBtnRef.style.borderBottomRightRadius = _thumbBtnRadius;
            _refreshAssetsBtnRef.style.backgroundColor = _assetOptionsThumbBg;
            _refreshAssetsBtnRef.style.justifyContent = Justify.Center;
            _refreshAssetsBtnRef.style.alignItems = Align.Center;
            
            var refreshIcon = new VisualElement();
            refreshIcon.name = "refresh-assets-icon";
            refreshIcon.pickingMode = PickingMode.Ignore;
            refreshIcon.style.width = _thumbBtnSize * 0.75f;
            refreshIcon.style.height = _thumbBtnSize * 0.75f;
            refreshIcon.style.alignSelf = Align.Center;
            refreshIcon.style.SetBackgroundScaleToFit();
            var refreshTex = LoadImage("Assets", "Update_Icon");
            if (refreshTex == null) refreshTex = LoadImage("Icons/Misc", "Update_Icon");
            if (refreshTex == null) refreshTex = LoadImage("Filter", "Update_Icon");
            if (refreshTex != null) refreshIcon.style.backgroundImage = new StyleBackground(refreshTex);
            _refreshAssetsBtnRef.Add(refreshIcon);
            
            _refreshAssetsBtnRef.tooltip = "Refresh owned assets";
            _refreshAssetsBtnRef.RegisterCallback<MouseEnterEvent>(_ => _refreshAssetsBtnRef.style.backgroundColor = thumbHoverBg);
            _refreshAssetsBtnRef.RegisterCallback<MouseLeaveEvent>(_ => _refreshAssetsBtnRef.style.backgroundColor = thumbBaseBg);
            ((Button)_refreshAssetsBtnRef).clicked += () => { _ = RefreshOwnedAssetsAsync(refreshIcon); };
            _refreshAssetsBtnRef.style.translate = new Translate(_refreshBtnX, _refreshBtnY);
            refreshGroup.Add(_refreshAssetsBtnRef);
        }
        
        private void UpdateGridIcon(VisualElement iconEl)
        {
            if (iconEl == null) return;
            Texture2D tex = null;
            switch (_thumbnailColumns)
            {
                case 5: tex = _gridIconSmall; break;
                case 4: tex = _gridIconMedium; break;
                default: tex = _gridIconBig; break;
            }
            if (tex != null)
                iconEl.style.backgroundImage = new StyleBackground(tex);
        }
        
        private void AddAssetSection(VisualElement parent)
        {
            var assetSection = new VisualElement();
            assetSection.name = "asset-section";
            assetSection.AddToClassList("asset-section");
            parent.Add(assetSection);
            
            // ── Asset count header (right-aligned "shown/total", above the grid) ──
            var assetCountHeader = new VisualElement();
            assetCountHeader.name = "asset-count-header";
            assetCountHeader.style.flexDirection = FlexDirection.Row;
            assetCountHeader.style.justifyContent = Justify.FlexEnd;
            assetCountHeader.style.alignItems = Align.Center;
            assetCountHeader.style.width = Length.Percent(100);
            assetCountHeader.pickingMode = PickingMode.Ignore;
            if (_assetCountHeight > 0f) assetCountHeader.style.height = _assetCountHeight;
            _assetCountHeader = assetCountHeader;
            _assetCountLabel = new Label("0/0");
            _assetCountLabel.name = "asset-count-label";
            _assetCountLabel.pickingMode = PickingMode.Ignore;
            _assetCountLabel.style.color = new Color(_assetCountColor.r, _assetCountColor.g, _assetCountColor.b, _assetCountOpacity);
            _assetCountLabel.style.fontSize = _assetCountFontSize;
            _assetCountLabel.style.unityFontStyleAndWeight = _assetCountBold ? FontStyle.Bold : FontStyle.Normal;
            _assetCountLabel.style.unityTextAlign = TextAnchor.MiddleRight;
            _assetCountLabel.style.translate = new Translate(_assetCountX, _assetCountY);
            assetCountHeader.Add(_assetCountLabel);
            assetSection.Add(assetCountHeader);
            
            var assetScroll = new ScrollView(ScrollViewMode.Vertical);
            assetScroll.name = "asset-scroll";
            _assetScrollView = assetScroll;
            // Continuously remember the scroll position so it can be restored after a re-sort or
            // a domain reload (install recompile). verticalScroller fires as the user scrolls.
            assetScroll.verticalScroller.valueChanged += (v) =>
            {
                if (_suppressScrollSave) return;
                _savedAssetScrollY = v;
                _hasSavedAssetScroll = true;
            };
            assetScroll.AddToClassList("asset-scroll");
            assetScroll.verticalScrollerVisibility = ScrollerVisibility.AlwaysVisible;
            // Never show a horizontal scrollbar in the asset area. Vertical mode alone does
            // not always prevent it - if any child is briefly wider than the viewport the
            // bar can flash in. Hiding the scroller plus clamping the content widths below
            // guarantees vertical-only scrolling at any window size.
            assetScroll.horizontalScrollerVisibility = ScrollerVisibility.Hidden;
            assetScroll.style.overflow = Overflow.Hidden;
            // The scroll viewport and its content container must not exceed the available
            // width, so the grid wraps instead of pushing sideways.
            assetScroll.contentContainer.style.maxWidth = Length.Percent(100);
            assetScroll.contentContainer.style.width = Length.Percent(100);
            assetSection.Add(assetScroll);

            // Settle veil — covers the grid briefly so the pass-verify flip (individually-owned →
            // full library, which lands a beat after the grid builds) is never seen. If the grid
            // already built with the pass on, it just reveals quickly. Bars added after this render
            // on top of it, so only the grid area is covered.
            _gridSettleVeil = new VisualElement { name = "grid-settle-veil" };
            _gridSettleVeil.pickingMode = PickingMode.Ignore;
            _gridSettleVeil.style.position = Position.Absolute;
            _gridSettleVeil.style.left = 0; _gridSettleVeil.style.right = 0;
            _gridSettleVeil.style.top = 0; _gridSettleVeil.style.bottom = 0;
            _gridSettleVeil.style.flexDirection = FlexDirection.Column; // transparent — cards below are hidden, so the tool background shows through
            _gridSettleVeil.style.transitionProperty = new StyleList<StylePropertyName>(new List<StylePropertyName> { new StylePropertyName("opacity") });
            _gridSettleVeil.style.transitionDuration = new StyleList<TimeValue>(new List<TimeValue> { new TimeValue(0.18f, TimeUnit.Second) });
            _gridSettleVeil.style.opacity = 1f;
            _gridSettling = true;
            // On a fresh open (not an install/uninstall reload, and not yet verified this session) the
            // verify triggers a catalog rebuild that briefly dips the counts — hold the veil until the
            // verify settles so that whole sequence happens behind it.
            _veilWaitVerify = !SessionState.GetBool(SESSION_SKIP_VERIFY, false)
                              && !SessionState.GetBool(SESSION_VERIFY_DONE, false);
            _gridSettleVeil.style.justifyContent = Justify.Center;
            _gridSettleVeil.style.alignItems = Align.Center;
            assetSection.Add(_gridSettleVeil);
            // Hide the grid cards while settling so the flip isn't seen, but keep the real tool
            // background visible (the veil itself is transparent). Restored in RevealGridVeil.
            if (_assetScrollView != null)
            {
                _assetScrollView.style.transitionProperty = new StyleList<StylePropertyName>(new List<StylePropertyName> { new StylePropertyName("opacity") });
                _assetScrollView.style.transitionDuration = new StyleList<TimeValue>(new List<TimeValue> { new TimeValue(0.18f, TimeUnit.Second) });
                _assetScrollView.style.opacity = 0f;
            }

            // Loading spinner (rotating ring with one bright accent quadrant) so the veil reads as a
            // brief loading state rather than a blank panel.
            var veilSpinner = new VisualElement { name = "grid-veil-spinner" };
            veilSpinner.pickingMode = PickingMode.Ignore;
            const float _svd = 34f;
            veilSpinner.style.width = _svd; veilSpinner.style.height = _svd;
            veilSpinner.style.borderTopWidth = 3; veilSpinner.style.borderBottomWidth = 3;
            veilSpinner.style.borderLeftWidth = 3; veilSpinner.style.borderRightWidth = 3;
            var _svBright = new Color(0f, 0.686f, 1f, 1f);       // accent #00AFFF
            var _svDim = new Color(1f, 1f, 1f, 0.12f);
            veilSpinner.style.borderTopColor = _svBright;
            veilSpinner.style.borderRightColor = _svDim;
            veilSpinner.style.borderBottomColor = _svDim;
            veilSpinner.style.borderLeftColor = _svDim;
            veilSpinner.style.borderTopLeftRadius = _svd * 0.5f;
            veilSpinner.style.borderTopRightRadius = _svd * 0.5f;
            veilSpinner.style.borderBottomLeftRadius = _svd * 0.5f;
            veilSpinner.style.borderBottomRightRadius = _svd * 0.5f;
            _gridSettleVeil.Add(veilSpinner);
            float _svAngle = 0f;
            var _svSpin = veilSpinner.schedule.Execute(() =>
            {
                if (_reloadingDomain || veilSpinner.panel == null) return;
                _svAngle = (_svAngle + 18f) % 360f;
                veilSpinner.style.rotate = new Rotate(new Angle(_svAngle, AngleUnit.Degree));
            }).Every(33);
            TrackScheduledItem(_svSpin);
            var veilLabel = new Label("Loading your library…");
            veilLabel.pickingMode = PickingMode.Ignore;
            veilLabel.style.marginTop = 14;
            veilLabel.style.color = new Color(1f, 1f, 1f, 0.55f);
            veilLabel.style.fontSize = 12;
            _gridSettleVeil.Add(veilLabel);
            {
                // Reveal when the grid has actually SETTLED, not on a fixed timer — a multi-install or
                // a slow verify flips the library several seconds after the grid builds, and a fixed
                // timeout lifts the veil too early. Watch the shown asset count: reveal once it's held
                // steady briefly AND (for pass-holders) the pass view is on. Hard safety at 12s.
                bool passHolder = SessionState.GetBool(SESSION_HAS_PASS, EditorPrefs.GetBool("SyntyStore_HasSyntyPass", false));
                int lastCount = -1;
                double stableSince = EditorApplication.timeSinceStartup;
                double startAt = EditorApplication.timeSinceStartup;
                IVisualElementScheduledItem mon = null;
                mon = _gridSettleVeil.schedule.Execute(() =>
                {
                    if (_gridSettleVeil == null) { SafePause(mon); return; }
                    double now = EditorApplication.timeSinceStartup;
                    if (now - startAt > 12.0) { RevealGridVeil(); SafePause(mon); return; } // hard safety
                    int c = _assetCountShown;
                    if (c != lastCount) { lastCount = c; stableSince = now; return; } // still changing
                    // "Ready" = the view is at its final state: not a pass-holder, or the pass view is
                    // on, or the user chose to keep it off (that IS the final state — don't wait for a
                    // flip that will never come).
                    bool passReady = !passHolder || _licenseSyntyPass || SessionState.GetBool(SESSION_PASS_TOGGLED_OFF, false);
                    if (passReady && !_veilWaitVerify && now - stableSince > 0.6) { RevealGridVeil(); SafePause(mon); }
                }).Every(50);
                TrackScheduledItem(mon);
            }
            SetupMarqueeSelect(assetScroll);
            
            // Exclusive deals container (pinned above the asset grid)
            _dealsContainer = new VisualElement();
            _dealsContainer.name = "deals-container";
            _dealsContainer.style.flexDirection = FlexDirection.Row;
            _dealsContainer.style.flexWrap = Wrap.Wrap;
            _dealsContainer.style.maxWidth = Length.Percent(100);
            _dealsContainer.style.display = DisplayStyle.None;
            assetScroll.Add(_dealsContainer);
            
            _assetContent = new VisualElement();
            _assetContent.name = "asset-content";
            _assetContent.AddToClassList("asset-content");
            _assetContent.style.maxWidth = Length.Percent(100);
            _assetContent.style.paddingTop = _assetGridTopPad;
            ApplyGridTopPad();
            assetScroll.Add(_assetContent);
            
            // Empty state container shown when filters produce no visible results
