                ApplyLibraryBtnColors(_statsNotInLibraryBtn, true, _libraryNotInOnColor, _libraryNotInOffColor);
                UpdateLibraryAllNoneButtons();
                
                // Turn on all price
                _priceFree = true;
                _pricePaid = true;
                UpdateStatsButtonState(_pricePaidBtn, true);
                UpdateStatsButtonState(_priceFreeBtn, true);
                UpdatePriceAllNoneButtons();
                
                // Turn on all installed
                _filterShowInstalled = true;
                _filterShowNotInstalled = true;
                UpdateInstalledFilterButtons();
                
                SaveFilterStates();
                FilterAssets();
            };
            _emptyStateContainer.Add(_clearFiltersBtn);
            
            assetScroll.Add(_emptyStateContainer);
            
            // SyntyPass promo panel (shown to non-pass users when they toggle the filter)
            BuildSyntyPassPromo(assetScroll);
            
            // Clear asset items list
            _assetItems.Clear();
            _productIcons.Clear();
            _iconSourceData.Clear();
