            // cache so the grid still populates instead of going blank.
            if (!SyntyCatalogBridge.IsLoaded || SyntyCatalogBridge.LoadedPacks.Count == 0)
                SyntyCatalogBridge.TryLoadFromDiskCache();
            
            if (SyntyCatalogBridge.IsLoaded && SyntyCatalogBridge.LoadedPacks.Count > 0)
            {
