            _downloadBar.style.left = _downloadBarPadding;
            _downloadBar.style.right = _downloadBarPadding;
            _downloadBar.style.bottom = -_downloadBarHeight - 24;
                UpdateBottomBarGradient();
            _downloadBar.style.height = _downloadBarHeight;
