            _downloadBarBtn.style.height = _downloadBarBtnHeight;
            _downloadBarBtn.style.backgroundColor = Color.clear;
            _downloadBarBtn.style.borderTopWidth = 0;
            _downloadBarBtn.style.borderBottomWidth = 0;
            _downloadBarBtn.style.borderLeftWidth = 0;
            _downloadBarBtn.style.borderRightWidth = 0;
            
            // Use 9-slice for the button background (same as Shop Now button)
            var btnBgTex = LoadImage("Buttons", "Button_ShopNow_BG");
            if (btnBgTex != null)
            {
                _downloadBarBtn.style.backgroundImage = new StyleBackground(btnBgTex);
                _downloadBarBtn.style.unityBackgroundImageTintColor = _downloadBarBtnColor;
                // 9-slice settings matching Shop Now button
                _downloadBarBtn.style.unitySliceLeft = 10;
                _downloadBarBtn.style.unitySliceRight = 10;
                _downloadBarBtn.style.unitySliceTop = 10;
                _downloadBarBtn.style.unitySliceBottom = 10;
            }
            
            _downloadBarBtn.clicked += () =>
            {
                var toDownload = _assetItems
                    .Where(item => item.getSelected() && item.getOwned()
                                   && item.button.style.display != DisplayStyle.None
                                   && !(item.btnVisual?.ClassListContains("asset-installed") ?? false))
                    .ToList();

                int selectedTotal = _assetItems.Count(i => i.getSelected());
                Dbg($"[Install] clicked. selected={selectedTotal}, ownedNotInstalled(toDownload)={toDownload.Count}");
                if (toDownload.Count == 0)
                {
                    EditorUtility.DisplayDialog("Nothing to Install",
                        "None of the selected assets need installing.\n\nOnly owned assets that aren't already installed can be installed. Not-owned assets and already-installed assets are skipped.",
                        "OK");
                    return;
                }
                
                // Sort by current visual order (top-left to bottom-right)
                if (_assetContent != null)
                    toDownload.Sort((a, b) => _assetContent.IndexOf(a.button).CompareTo(_assetContent.IndexOf(b.button)));
                
                // Track multi-install progress
                _multiInstallTotal = toDownload.Count;
                // Persist the original total so the "X of Y" count stays correct across any domain
                // reload during the batch (see ResumePendingDownloads).
                SessionState.SetInt(SESSION_BATCH_TOTAL, toDownload.Count);
                _multiInstallCurrent = 0;
                _multiInstallDone = 0;
                _downloadQueueFirstStarted = false;
                _advanceQueueOnComplete = false;
                
                // Lock assembly reloading for the whole batch so a scripted asset doesn't trigger a
                // domain reload mid-install (unlocked when every asset is done).
                if (toDownload.Count > 1)
                    LockAssemblyReloadForBatch();
                
                // Persist selection so it survives the install's domain reload (cards stay selected
                // and show their download progress; selection is restored after the reload).
                SaveSelectionToSession();
                UpdateSelectButtonStates();
                // Explicitly start the bars animating off screen now so the full transition
                // has run by the time the download begins (the StartingIn below waits for it).
                float barHideBottom = -_downloadBarHeight - 24;
                if (_downloadBar != null) _downloadBar.style.bottom = barHideBottom;
                if (_uninstallBar != null) _uninstallBar.style.bottom = barHideBottom;
                if (_updatesBar != null) _updatesBar.style.bottom = barHideBottom;
                if (_cartBar != null) _cartBar.style.bottom = barHideBottom;
                
                // Processing is delayed (see .StartingIn at the end of this block) until the
                // action bars have fully animated off screen, so they are completely gone
                // before the download visuals begin rather than being caught half cut off.
                var capturedToDownload = toDownload;
                rootVisualElement.schedule.Execute(() =>
                {
                    if (!this) return;
                    
                    // Set active download count and dimming
                    _activeDownloadCount = capturedToDownload.Count;
                    // Darken the whole grid up front; each asset is spotlighted bright in turn as it
                    // downloads/installs (SpotlightCard excludes the current card).
                    _spotlightCard = null;
                    SetDownloadingDimState(true);

                    // Build the pack list for this batch.
                    var packsToQueue = new List<AssetPackData>();
                    foreach (var item in capturedToDownload)
                    {
                        int idx = _assetItems.IndexOf(item);
                        if (_assetPackMapping.TryGetValue(idx, out var p) && p != null)
                            packsToQueue.Add(p);
                    }
                    Dbg($"[Install] packsToQueue built: {packsToQueue.Count}");

                    // Starts the manager processing the queued packs (they import from cache).
                    System.Action startInstallPass = () =>
                    {
                        if (!this) return;
                        if (_batchCancelled) { FinishCancelledBatch(); return; }
                        Dbg($"[Install] startInstallPass. packsToQueue={packsToQueue.Count}");
                        // Clear finished items left in the queue by any PREVIOUS batch, so this batch
                        // starts clean. Without this, a second consecutive multi-install numbers the
                        // whole (accumulated) queue and the counters/badges get thrown off — and
                        // re-installing a pack from the last batch would return its stale completed
                        // item instead of re-queuing it.
                        SyntyDownloadManager.Instance.ClearCompleted();
                        if (packsToQueue.Count > 0)
                            SyntyDownloadManager.Instance.AddToQueue(packsToQueue);
                        // Lock in a fixed 1-based number for each pack now, in processing order, so
                        // its "X of Y" never changes (survives focus changes and domain reloads).
                        {
                            int bi = 0;
                            foreach (var d in SyntyDownloadManager.Instance.Queue) d.batchIndex = ++bi;
                        }
                        _lastVisualizedHandle = null;

                        // Interleaved install: the manager processes the queue one pack at a time —
                        // download it (only if it isn't already cached), install it, then move to the
                        // next pack. (Previously this ran a DownloadOnlyMode phase that downloaded ALL
                        // packs to cache first, then installed them all after a "Downloads Complete"
                        // prompt.)
                        SyntyDownloadManager.Instance.StartProcessing();
                    };

                    // For a multi-pack batch, first confirm the total download size with the user
                    // (always shown for multi-installs). On confirm, packs are downloaded and installed
                    // one at a time (download if needed, then install, then the next). On cancel,
                    // nothing is downloaded (safe) and the UI restores. Single packs skip the prompt.
                    if (packsToQueue.Count > 1)
                    {
                        ConfirmMultiInstallSizeThenRun(packsToQueue, startInstallPass);
                    }
                    else
                    {
                        startInstallPass();
                    }
                }).StartingIn((long)(_actionBarTransitionDuration + 80));
            };
            
            // Hover effect for download bar button (lighten + slight scale up)
            var normalGreen = _downloadBarBtnColor;
            var hoverGreen = new Color(
                Mathf.Min(1f, _downloadBarBtnColor.r + (1f - _downloadBarBtnColor.r) * 0.18f),
                Mathf.Min(1f, _downloadBarBtnColor.g + (1f - _downloadBarBtnColor.g) * 0.18f),
                Mathf.Min(1f, _downloadBarBtnColor.b + (1f - _downloadBarBtnColor.b) * 0.18f),
                1f);
            
            _downloadBarBtn.style.transitionProperty = new List<StylePropertyName> { 
