            _downloadBarBtn.RegisterCallback<MouseLeaveEvent>(evt => {
                _downloadBarHovered = false;
                _downloadBarBtn.style.scale = new Scale(Vector3.one);
            });
            
            // Download bar label container (vertical stack for two lines)
