            _downloadBarSubtitleLabel.style.unityTextAlign = TextAnchor.MiddleCenter;
            _downloadBarSubtitleLabel.style.marginTop = _downloadBarSubtitleY;
            _downloadBarSubtitleLabel.style.marginLeft = _downloadBarSubtitleX;
            _downloadBarSubtitleLabel.pickingMode = PickingMode.Ignore;
            // Subtitle (asset name / count) uses the default editor font - same as the
