            RegisterTextAutoFit(_downloadBarTitleLabel);
            RegisterTextAutoFit(_downloadBarSubtitleLabel);
            
            _downloadBar.Add(_downloadBarBtn);
            AddActionBarHoverOutline(_downloadBarBtn, _actionBarHoverRadius);

            // Single shared gradient at bottom of tool — renders under all action bars
            _bottomBarGradient = new VisualElement();
            _bottomBarGradient.name = "bottom-bar-gradient";
            _bottomBarGradient.pickingMode = PickingMode.Position; // Block mouse events from reaching assets below
            _bottomBarGradient.style.position = Position.Absolute;
            _bottomBarGradient.style.left = 0;
            _bottomBarGradient.style.right = 0;
            _bottomBarGradient.style.bottom = _bottomBarGradientY;
            _bottomBarGradient.style.height = _bottomBarGradientHeight;
            _bottomBarGradient.style.scale = new Scale(new Vector3(1f, _bottomBarGradientScaleY, 1f));
            _bottomBarGradient.style.transformOrigin = new TransformOrigin(Length.Percent(50), Length.Percent(100));
            _bottomBarGradient.style.opacity = 0;
            _bottomBarGradient.style.transitionProperty = new List<StylePropertyName> { new StylePropertyName("opacity") };
            _bottomBarGradient.style.transitionDuration = new List<TimeValue> { new TimeValue(300, TimeUnit.Millisecond) };
            _bottomBarGradient.style.transitionTimingFunction = new List<EasingFunction> { new EasingFunction(EasingMode.EaseOut) };
            if (_btnGradient != null)
            {
                _bottomBarGradient.style.backgroundImage = new StyleBackground(_btnGradient);
                _bottomBarGradient.style.SetBackgroundStretchToFill();
                _bottomBarGradient.style.unityBackgroundImageTintColor = new Color(_bottomBarGradientColor.r, _bottomBarGradientColor.g, _bottomBarGradientColor.b, _bottomBarGradientOpacity);
            }
            // Unhover all asset buttons when mouse enters the gradient/action bar area
            _bottomBarGradient.RegisterCallback<MouseEnterEvent>(evt => {
