            assetSection.Add(_bottomBarGradient);
            assetSection.Add(_downloadBar);
            
            // Cart bar (for not-owned assets, similar structure to download bar)
            _cartBar = new VisualElement();
            _cartBar.name = "cart-bar";
            _cartBar.AddToClassList("cart-bar");
            _cartBar.style.position = Position.Absolute;
            _cartBar.style.left = _downloadBarPadding;
            _cartBar.style.right = _downloadBarPadding;
            _cartBar.style.bottom = -_downloadBarHeight - 24;
                UpdateBottomBarGradient();
