            {
                _cartBarBtn.style.backgroundImage = new StyleBackground(btnBgTex);
                _cartBarBtn.style.unityBackgroundImageTintColor = _cartBarBtnColor;
                _cartBarBtn.style.unitySliceLeft = 10;
