            _cartBarBtn.clicked += () => {
                var cartItems = _assetItems
                    .Select((item, idx) => (item, idx))
                    .Where(x => x.item.getSelected() && !x.item.getOwned()
                                && x.item.button.style.display != DisplayStyle.None)
                    .ToList();
                int count = cartItems.Count;
                
                // Deselect cart items
                foreach (var (item, idx) in cartItems)
                    item.setSelected(false);
                UpdateDownloadBar();
                
                // Add to cart via catalog bridge
                var packsForCart = cartItems
                    .Where(x => _assetPackMapping.ContainsKey(x.idx))
                    .Select(x => _assetPackMapping[x.idx])
                    .ToList();
                if (packsForCart.Count > 0)
                {
                    foreach (var p in packsForCart)
                        SyntyAnalytics.TrackAddToCart(p.packName ?? "", p.displayName ?? "", p.price, packsForCart.Count > 1, packsForCart.Count);
                    SyntyCatalogBridge.AddMultipleToCart(packsForCart);
                }
                else
                    Application.OpenURL(SyntyCatalogBridge.STORE_AFFILIATE_URL);
            };
            
            // Hover effect for cart bar button
            var normalBlue = _cartBarBtnColor;
            var hoverBlue = new Color(
                Mathf.Min(1f, _cartBarBtnColor.r + (1f - _cartBarBtnColor.r) * 0.18f),
                Mathf.Min(1f, _cartBarBtnColor.g + (1f - _cartBarBtnColor.g) * 0.18f),
                Mathf.Min(1f, _cartBarBtnColor.b + (1f - _cartBarBtnColor.b) * 0.18f),
