            _cartBarSubtitleLabel = new Label("0 ASSETS");
            _cartBarSubtitleLabel.style.color = _downloadBarSubtitleColor;
            _cartBarSubtitleLabel.style.fontSize = _downloadBarSubtitleFontSize;
            _cartBarSubtitleLabel.style.unityFontStyleAndWeight = _downloadBarSubtitleBold ? FontStyle.Bold : FontStyle.Normal;
            _cartBarSubtitleLabel.style.unityTextAlign = TextAnchor.MiddleCenter;
            _cartBarSubtitleLabel.style.marginTop = _downloadBarSubtitleY;
            _cartBarSubtitleLabel.style.marginLeft = _downloadBarSubtitleX;
            _cartBarSubtitleLabel.style.display = DisplayStyle.None;
