            _cartBarPriceContainer = new VisualElement();
            _cartBarPriceContainer.style.flexDirection = FlexDirection.Row;
            _cartBarPriceContainer.style.justifyContent = Justify.Center;
            _cartBarPriceContainer.style.alignItems = Align.Center;
            _cartBarPriceContainer.style.marginTop = _downloadBarSubtitleY;
            _cartBarPriceContainer.style.marginLeft = _downloadBarSubtitleX;
