            _cartBarPriceContainer.pickingMode = PickingMode.Ignore;
            // Subtitle uses the default editor font (matches asset card name line).
            cartLabelContainer.Add(_cartBarSubtitleLabel);
            cartLabelContainer.Add(_cartBarPriceContainer);

            // Third line: purchase disclaimer. Shows the full text when the button is wide enough,
            // and a shortened version when it's narrow (so it doesn't clip).
            _cartBarDisclaimerLabel = new Label(CART_DISCLAIMER_FULL);
            _cartBarDisclaimerLabel.style.color = _downloadBarSubtitleColor;
            _cartBarDisclaimerLabel.style.fontSize = Mathf.Max(8f, _downloadBarSubtitleFontSize - 3f);
            _cartBarDisclaimerLabel.style.unityTextAlign = TextAnchor.MiddleCenter;
            _cartBarDisclaimerLabel.style.marginTop = 1;
            _cartBarDisclaimerLabel.style.opacity = 0.7f;
            _cartBarDisclaimerLabel.style.unityFontStyleAndWeight = FontStyle.Bold;
