            _uninstallBarBtn.clicked += () =>
            {
                var toUninstall = _assetItems
                    .Select((item, idx) => (item, idx))
                    .Where(x => x.item.getSelected()
                                && x.item.button.style.display != DisplayStyle.None
                                && x.item.btnVisual?.ClassListContains("asset-installed") == true)
                    .ToList();
                
                // Sort by visual order (top-left to bottom-right)
                if (_assetContent != null)
                    toUninstall.Sort((a, b) => _assetContent.IndexOf(a.item.button).CompareTo(_assetContent.IndexOf(b.item.button)));
                
                if (toUninstall.Count == 0) return;
                
                string msg = toUninstall.Count == 1
                    ? $"Are you sure you want to uninstall {toUninstall[0].item.name}?"
                    : $"Are you sure you want to uninstall {toUninstall.Count} assets?";
                msg += "\n\nThis will remove the asset files from your project. You can always re-download them later.";
                
                if (!EditorUtility.DisplayDialog("Uninstall Assets", msg, "Uninstall", "Cancel"))
                    return;
                
                // Persist selection so it survives the uninstall domain reload, but exclude the
                // assets being uninstalled so they are NOT re-selected afterward.
                var uninstalledNames = new System.Collections.Generic.HashSet<string>();
                foreach (var (item, idx) in toUninstall) uninstalledNames.Add(item.name);
                SaveSelectionToSession(uninstalledNames);
                // Deselect the uninstalled assets now, and hide the uninstall bar.
                foreach (var (item, idx) in toUninstall)
                    item.setSelected(false);
                if (_uninstallBar != null) _uninstallBar.style.bottom = -_downloadBarHeight - 24;
                
                // Delay processing until bar has animated off screen
                var capturedUninstall = toUninstall;
                rootVisualElement.schedule.Execute(() =>
                {
                    if (!this) return;
                    
                    ShowToolWaiting();
                
                    foreach (var (item, idx) in capturedUninstall)
                    {
                    
                    if (!_assetPackMapping.TryGetValue(idx, out var pack)) continue;
                    
                    string handle = pack.packName;
                    if (string.IsNullOrEmpty(handle))
                        handle = SyntyStoreService.ExtractHandleFromUrl(pack.storeUrl);
                    
                    // Analytics: track uninstall
                    SyntyAnalytics.TrackUninstall(handle, pack.displayName ?? handle);
                    
                    // Delete folders
                    bool deleted = false;
                    if (SyntyInstallManifest.HasManifest(handle))
                    {
                        var entry = SyntyInstallManifest.GetEntry(handle);
                        if (entry != null && entry.installedFolders != null && entry.installedFolders.Count > 0)
                        {
                            MarkOwnershipUnchangedReload(); // ownership unchanged — skip verify on the reload this triggers
                            var result = SyntyInstallManifest.UninstallPack(handle);
                            deleted = result.deleted > 0;
                        }
                        else
                        {
                            SyntyInstallManifest.RemoveEntry(handle);
                        }
                    }
                    if (!deleted)
                    {
                        TryDeleteAssetFolder(handle, pack.GetDisplayName());
                    }
                    
                    SyntyImportTracker.ClearImport(handle);
                    CancelSyntyPassAutoOn(); // user is uninstalling: don't let the filter auto-on later
                    
                    // Remove from download queue
                    var queueItem = SyntyDownloadManager.Instance.Queue.Find(d => d.productHandle == handle);
                    if (queueItem != null) SyntyDownloadManager.Instance.Queue.Remove(queueItem);
                    
                    // Reset button visuals
                    var btn = item.button;
                    var btnVisual = btn.Q<VisualElement>("asset-btn-visual");
                    var dlBtn = btn.Q<VisualElement>("download-btn");
                    var dlIcon = dlBtn?.Q<VisualElement>("download-icon");
                    var selOvr = btn.Q<VisualElement>("asset-btn-selected");
                    
                    // Remove installed class from all possible elements
                    btnVisual?.RemoveFromClassList("asset-installed");
                    btn?.RemoveFromClassList("asset-installed");
                    RemoveInstalledBadge(btn);
                    
                    if (dlBtn != null)
                    {
                        var (themeColor, _) = GetAssetTypeColors(item.type);
                        dlBtn.style.unityBackgroundImageTintColor = _downloadBtnWhiteBg ? new Color(0.094f, 0.078f, 0.145f, 1f) : themeColor;
                        float dbs = GetDlBtnBaseScale();
                        dlBtn.style.scale = new Scale(new Vector3(dbs, dbs, 1f));
                        dlBtn.style.display = DisplayStyle.Flex;
                        
                        if (dlIcon != null && _downloadIcon != null)
                        {
                            dlIcon.style.backgroundImage = new StyleBackground(_downloadIcon);
                            dlIcon.style.unityBackgroundImageTintColor = _downloadBtnWhiteBg ? Color.white : Color.black;
                            dlIcon.style.scale = new Scale(Vector3.one);
                        }
                        
                        var pressedOvr = dlBtn.Q<VisualElement>("download-pressed-overlay");
                        if (pressedOvr != null) pressedOvr.style.display = DisplayStyle.None;
                        
                        if (dlBtn.userData is object[] refs && refs.Length >= 3)
                        {
                            if (refs[0] is Color[] btnColorRef) btnColorRef[0] = themeColor;
                            if (refs[1] is Color[] iconColorRef) iconColorRef[0] = Color.black;
                            if (refs[2] is bool[] installedRef) installedRef[0] = false;
                        }
                        
                        // Update tooltip to "Install"
                        Label uninstallTtLabel = null;
                        _downloadTooltipLabels.TryGetValue(dlBtn, out uninstallTtLabel);
                        if (uninstallTtLabel != null) uninstallTtLabel.text = "Install";
                    }
                    
                    if (selOvr != null)
                    {
                        selOvr.style.display = DisplayStyle.None;
                        selOvr.style.opacity = 0;
                        selOvr.style.unityBackgroundImageTintColor = Color.white;
                    }
                    
                    var gradOvr = btnVisual?.Q<VisualElement>("asset-btn-gradient");
                    if (gradOvr != null)
                    {
                        var (tc, _) = GetAssetTypeColors(item.type);
                        gradOvr.style.unityBackgroundImageTintColor = tc;
                    }
                    
                    // After uninstall, check if asset is individually owned
                    // If not (was only accessible via SyntyPass), revert to not-owned state
                    bool individuallyOwned = SyntyStoreService.Instance.OwnedProductHandles.Contains(pack.packName);
                    if (!individuallyOwned && !_licenseSyntyPass)
                    {
                        item.setOwned(false);
                    }

                    // Deselect the card now that it's uninstalled (the install flow does the same on
                    // completion), and drop it from the persisted selection so a reload/rebuild won't
                    // re-select it.
                    item.setSelected(false);
                    RemoveFromSessionSelection(item.name);
                }
                
                UpdateCollectionCounts();
                UpdateDownloadBar();
                UpdateSaleBadgeVisibility();
                FilterAssets(reSort: false);
                
                // Refresh immediately so Unity picks up the deleted asset scripts and starts the
                // recompile/assembly reload right away, instead of after a delayed tick.
                HideToolWaiting();
                AssetDatabase.Refresh();
                }).StartingIn((long)(_actionBarTransitionDuration + 80));
            };
            
            var hoverRed = new Color(0.65f, 0.15f, 0.15f, 1f);
            _uninstallBarBtn.style.transitionProperty = new List<StylePropertyName> { 
                new StylePropertyName("scale"),
                new StylePropertyName("-unity-background-image-tint-color")
            };
            _uninstallBarBtn.style.transitionDuration = new List<TimeValue> { 
                new TimeValue(100, TimeUnit.Millisecond),
                new TimeValue(100, TimeUnit.Millisecond)
            };
            _uninstallBarBtn.style.transitionTimingFunction = new List<EasingFunction> { 
                new EasingFunction(EasingMode.EaseOut),
                new EasingFunction(EasingMode.EaseOut)
            };
            
            _uninstallBarBtn.RegisterCallback<MouseEnterEvent>(evt => {
                _uninstallBarBtn.style.scale = new Scale(new Vector3(1.02f, 1.02f, 1f));
            });
            _uninstallBarBtn.RegisterCallback<MouseLeaveEvent>(evt => {
                _uninstallBarBtn.style.scale = new Scale(Vector3.one);
            });
            
            var uninstallLabelContainer = new VisualElement();
            uninstallLabelContainer.style.flexDirection = FlexDirection.Column;
            uninstallLabelContainer.style.alignItems = Align.Center;
            uninstallLabelContainer.style.justifyContent = Justify.Center;
            uninstallLabelContainer.style.flexGrow = 1;
            uninstallLabelContainer.pickingMode = PickingMode.Ignore;
            
            _uninstallBarTitleLabel = new Label("UNINSTALL");
            _uninstallBarTitleLabel.style.color = _downloadBarTitleColor;
            _uninstallBarTitleLabel.style.fontSize = _downloadBarTitleFontSize;
            _uninstallBarTitleLabel.style.unityFontStyleAndWeight = _downloadBarTitleBold ? FontStyle.Bold : FontStyle.Normal;
            _uninstallBarTitleLabel.style.unityTextAlign = TextAnchor.MiddleCenter;
            _uninstallBarTitleLabel.style.marginTop = _downloadBarTitleY;
            _uninstallBarTitleLabel.style.marginLeft = _downloadBarTitleX;
            _uninstallBarTitleLabel.pickingMode = PickingMode.Ignore;
            if (_newakeFont != null) _uninstallBarTitleLabel.style.unityFontDefinition = FontDefinition.FromFont(_newakeFont);
            uninstallLabelContainer.Add(_uninstallBarTitleLabel);
            
            _uninstallBarSubtitleLabel = new Label("0 ASSETS");
            _uninstallBarSubtitleLabel.style.color = _downloadBarSubtitleColor;
            _uninstallBarSubtitleLabel.style.fontSize = _downloadBarSubtitleFontSize;
            _uninstallBarSubtitleLabel.style.unityFontStyleAndWeight = _downloadBarSubtitleBold ? FontStyle.Bold : FontStyle.Normal;
            _uninstallBarSubtitleLabel.style.unityTextAlign = TextAnchor.MiddleCenter;
            _uninstallBarSubtitleLabel.style.marginTop = _downloadBarSubtitleY;
            _uninstallBarSubtitleLabel.style.marginLeft = _downloadBarSubtitleX;
            _uninstallBarSubtitleLabel.pickingMode = PickingMode.Ignore;
            // Subtitle uses the default editor font (matches asset card name line).
            uninstallLabelContainer.Add(_uninstallBarSubtitleLabel);
            
            _uninstallBarBtn.Add(uninstallLabelContainer);
            
            RegisterTextAutoFit(_uninstallBarTitleLabel);
            RegisterTextAutoFit(_uninstallBarSubtitleLabel);
            
            _uninstallBar.Add(_uninstallBarBtn);
            AddActionBarHoverOutline(_uninstallBarBtn, _actionBarHoverRadius);
            assetSection.Add(_uninstallBar);
            
            // Note: UpdateCollectionCounts is called by OnAllButtonsCreated after all buttons exist
            
            // Deferred: apply greyscale + tint to not-owned icons after layout resolves
            EditorApplication.delayCall += () => { if (this) RebuildNotOwnedIcons(); };
        }
        
        /// <summary>
        /// Creates a masked texture by applying a mask to an image.
        private void FilterAssets(bool reSort = true)
        {
            // Cancel any stuck marquee drag — the grid contents are about to change and a pointer-up
            // can be lost across the rebuild.
            ResetMarqueeState();
            string query = _searchQuery.ToLower().Trim();
            int shownCount = 0;
            
            foreach (var item in _assetItems)
            {
                // Search filter
                bool matchesSearch = string.IsNullOrEmpty(query) || 
                               item.name.ToLower().Contains(query) ||
                               item.type.ToLower().Contains(query);
                
                // Type filter
                bool matchesType = _selectedAssetTypes.Contains(item.type);
                
                // Theme filter — an asset can have several themes (comma-joined in item.theme);
                // it matches when ANY of them is selected.
                bool matchesTheme = ThemeMatches(item.theme);
                
                // Library filter
                bool isOwned = item.getOwned();
                bool matchesLibrary = false;
                bool anyLibraryEnabled = _statsInLibrary || _statsNotInLibrary;
                if (!anyLibraryEnabled)
                    matchesLibrary = false;
                else
                {
                    if (_statsInLibrary && isOwned) matchesLibrary = true;
                    if (_statsNotInLibrary && !isOwned) matchesLibrary = true;
                }
                
                // Price filter
                bool matchesPrice = (item.isFree && _priceFree) || (!item.isFree && _pricePaid);
                
                // Installed filter
                bool isInstalled = item.btnVisual?.ClassListContains("asset-installed") == true || 
                                   item.btnVisual?.ClassListContains("asset-has-update") == true;
                bool matchesInstalled = (_filterShowInstalled && isInstalled) || (_filterShowNotInstalled && !isInstalled);
                
                bool show = matchesSearch && matchesType && matchesTheme && matchesLibrary && matchesPrice && matchesInstalled;
                item.button.style.display = show ? DisplayStyle.Flex : DisplayStyle.None;
                if (show) shownCount++;
            }
            
            // Update the "shown/total" count header.
            _assetCountShown = shownCount;
            _assetCountTotal = _assetItems.Count;
            if (_assetCountLabel != null)
                _assetCountLabel.text = FormatAssetCount(shownCount, _assetItems.Count);
            
            // Re-sort when filters change (instant). The uninstall path passes reSort:false so
            // buttons keep their current visual position instead of jumping to a new sort order
            // (uninstalling clears the asset-installed class, which would otherwise reorder the
            // card under Updates/Installed sort, causing a visible flicker).
            if (reSort)
                ApplySortOrder();
            
            UpdateEmptyState();
            UpdateDownloadBar();
            UpdateSelectButtonStates();
            UpdateSortDropdownChoices();
        }
        
        private static string CleanEmptyMsg(string s) => s?.Replace("\r\n", " ").Replace("\n", " ").Replace("\r", "").Trim() ?? "";
        
        private void UpdateEmptyState()
        {
            if (_emptyStateLabel == null) return;
            
            bool noType    = _selectedAssetTypes.Count == 0;
            bool noTheme   = _selectedThemes.Count == 0;
            bool noLibrary = !_statsInLibrary && !_statsNotInLibrary;
            
            string message = null;
            
            if (!noType && !noTheme && !noLibrary)
            {
                bool anyVisible = _assetItems.Any(i => i.button.style.display != DisplayStyle.None);
                if (!anyVisible) message = _emptyMsgNoResults;
            }
            else if (noType && noTheme && noLibrary) message = _emptyMsgNoFilters;
            else if (noType && noTheme)              message = _emptyMsgNoTypeNoTheme;
            else if (noType && noLibrary)            message = _emptyMsgNoTypeNoLib;
            else if (noTheme && noLibrary)           message = _emptyMsgNoThemeNoLib;
            else if (noType)                         message = _emptyMsgNoTypeOnly;
            else if (noTheme)                        message = _emptyMsgNoThemeOnly;
            else                                     message = _emptyMsgNoLibOnly;
            
            if (message != null)
            {
                _emptyStateLabel.text = message;
                UpdateEmptyStateTop();
                _emptyStateContainer.style.display = DisplayStyle.Flex;
            }
            else
            {
                _emptyStateContainer.style.display = DisplayStyle.None;
            }
        }
        
        private void UpdateEmptyStateStyle()
        {
            if (_emptyStateLabel == null) return;
            _emptyStateLabel.style.paddingLeft  = _emptyStateX;
            _emptyStateLabel.style.paddingRight = _emptyStateX;
            _emptyStateLabel.style.marginTop    = _emptyStateY;
            _emptyStateLabel.style.fontSize     = _emptyStateFontSize;
            _emptyStateLabel.style.color        = _emptyStateColor;
        }
        
        private void ApplySortOrder()
        {
            var parent = _assetItems.FirstOrDefault().button?.parent;
            if (parent == null) return;
            
            var visible = _assetItems.Where(i => i.button.style.display != DisplayStyle.None).ToList();
            var hidden  = _assetItems.Where(i => i.button.style.display == DisplayStyle.None).ToList();
            
            IEnumerable<(VisualElement button, VisualElement btnVisual, string type, string name, string theme, System.Action<bool> setSelected, System.Func<bool> getSelected, System.Action<bool> setOwned, System.Func<bool> getOwned, bool isNew, bool isOnSale, bool isFree, float price, int sortOrder)> sorted;
            
            // Discount % per item (for On Sale sorting), derived from the pack's compare-at price
            var salePctByButton = new Dictionary<VisualElement, float>();
            for (int si = 0; si < _assetItems.Count; si++)
            {
                float pct = 0f;
                if (_assetPackMapping != null && _assetPackMapping.TryGetValue(si, out var spk) && spk != null &&
                    !string.IsNullOrEmpty(spk.compareAtPrice) &&
                    float.TryParse(spk.compareAtPrice, System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture, out float scmp) &&
                    scmp > 0f && _assetItems[si].price > 0f)
                {
                    pct = (scmp - _assetItems[si].price) / scmp * 100f;
                }
                if (_assetItems[si].button != null) salePctByButton[_assetItems[si].button] = pct;
            }
            
            switch (_sortMode)
            {
                case 1: // On Sale — not-owned sale assets first, by highest discount %, then price, then rest by release date
                    sorted = visible
                        .OrderByDescending(i => (i.isOnSale && !i.getOwned()) ? 1 : 0)
                        .ThenByDescending(i => (i.isOnSale && !i.getOwned()) ? (salePctByButton.TryGetValue(i.button, out var sp) ? sp : 0f) : 0f)
                        .ThenByDescending(i => (i.isOnSale && !i.getOwned()) ? i.price : 0f)
                        .ThenBy(i => (i.isOnSale && !i.getOwned()) ? 0 : i.sortOrder);
                    break;
                case 2: // Updates — updates first, then installed, then rest (all by release date)
                    sorted = visible
                        .OrderByDescending(i => {
                            var bv = i.btnVisual;
                            if (bv != null && bv.ClassListContains("asset-has-update")) return 2;
                            if (bv != null && bv.ClassListContains("asset-installed")) return 1;
                            return 0;
                        })
                        .ThenBy(i => i.sortOrder);
                    break;
                case 3: // Installed — installed first by release date, rest by release date
                    sorted = visible
                        .OrderByDescending(i => (i.getOwned() && i.btnVisual?.ClassListContains("asset-installed") == true) ? 1 : 0)
                        .ThenBy(i => i.sortOrder);
                    break;
                case 4: // Name
                    sorted = visible.OrderBy(i => i.name);
                    break;
                case 5: // Price (Low to High)
                    sorted = visible.OrderBy(i => i.price);
                    break;
                case 6: // Price (High to Low)
                    sorted = visible.OrderByDescending(i => i.price);
                    break;
                default: // Release Date (newest first — lower sortOrder = newer)
                    sorted = visible.OrderBy(i => i.sortOrder);
                    break;
            }
            
            // Re-inserting all buttons resets the ScrollView to the top. Capture the current
            // scroll offset first and restore it after, so a re-sort (e.g. from install/uninstall
            // that does NOT recompile) doesn't jump the list back to the top. The domain-reload
            // case is handled separately by RestoreAssetScrollPosition after the grid rebuilds.
            Vector2 savedOffset = _assetScrollView != null ? _assetScrollView.scrollOffset : Vector2.zero;
            
            int insertIdx = 0;
            foreach (var item in sorted)
                parent.Insert(insertIdx++, item.button);
            foreach (var item in hidden)
                parent.Insert(insertIdx++, item.button);
            
            if (_assetScrollView != null)
            {
                _suppressScrollSave = true;
                _assetScrollView.scrollOffset = savedOffset;
                _suppressScrollSave = false;
                _assetScrollView.schedule.Execute(() =>
                {
                    if (_reloadingDomain || _assetScrollView == null || _assetScrollView.panel == null) return;
                    _suppressScrollSave = true;
                    _assetScrollView.scrollOffset = savedOffset;
                    _suppressScrollSave = false;
                }).StartingIn(0);
            }
        }
        
        /// <summary>
        /// Show plain text in the cart subtitle (no price formatting).
        /// </summary>
        private void SetCartSubtitleText(string text)
        {
            if (_cartBarSubtitleLabel != null)
            {
                _cartBarSubtitleLabel.text = text;
                _cartBarSubtitleLabel.style.display = DisplayStyle.Flex;
            }
            if (_cartBarPriceContainer != null)
                _cartBarPriceContainer.style.display = DisplayStyle.None;
        }
        
        /// <summary>
        /// Show formatted price with comma separators and smaller cents in the cart subtitle.
        /// </summary>
        private void SetCartSubtitleWithPrice(string prefix, float price, string suffix)
        {
            if (_cartBarSubtitleLabel != null)
                _cartBarSubtitleLabel.style.display = DisplayStyle.None;
            if (_cartBarPriceContainer == null) return;
            
            _cartBarPriceContainer.Clear();
            _cartBarPriceContainer.style.display = DisplayStyle.Flex;
            
            // Convert the USD price to the user's display currency, and force the suffix +
            // symbol to match (callers pass USD + " USD"; we override both here so every cart
            // line follows the selected currency without each call site needing to know it).
            price = SyntyCurrency.Convert(price);
            suffix = SyntyCurrency.CodeSuffix;
            string curSymbol = SyntyCurrency.Symbol;
            
            // Format price: split into dollars and cents
            string formatted = price.ToString("N2", System.Globalization.CultureInfo.GetCultureInfo("en-US"));
            int dotIdx = formatted.LastIndexOf('.');
            string dollars = dotIdx >= 0 ? formatted.Substring(0, dotIdx) : formatted;
            string cents = dotIdx >= 0 ? formatted.Substring(dotIdx) : "";
            
            float mainSize = _downloadBarSubtitleFontSize;
            float centsSize = mainSize; // cents same size as dollars so the price line matches the other subtitles
            
            // Prefix label
            if (!string.IsNullOrEmpty(prefix))
            {
                var prefixLabel = new Label(prefix);
                prefixLabel.style.color = _downloadBarSubtitleColor;
                prefixLabel.style.fontSize = mainSize;
                prefixLabel.style.unityFontStyleAndWeight = _downloadBarSubtitleBold ? FontStyle.Bold : FontStyle.Normal;
                prefixLabel.pickingMode = PickingMode.Ignore;
                prefixLabel.style.paddingTop = 0; prefixLabel.style.paddingBottom = 0;
                prefixLabel.style.marginTop = 0; prefixLabel.style.marginBottom = 0;
                // default editor font - matches the rest of the cart line
                _cartBarPriceContainer.Add(prefixLabel);
            }
            
            // Dollar sign + whole dollars
            var dollarLabel = new Label($"{curSymbol}{dollars}");
            dollarLabel.style.color = _downloadBarSubtitleColor;
            dollarLabel.style.fontSize = mainSize;
            dollarLabel.style.unityFontStyleAndWeight = _downloadBarSubtitleBold ? FontStyle.Bold : FontStyle.Normal;
            dollarLabel.pickingMode = PickingMode.Ignore;
            dollarLabel.style.paddingTop = 0; dollarLabel.style.paddingBottom = 0;
            dollarLabel.style.marginTop = 0; dollarLabel.style.marginBottom = 0;
            // Zero the inner horizontal padding/margin so the cents sit flush after it.
            dollarLabel.style.paddingLeft = 0; dollarLabel.style.paddingRight = 0;
            dollarLabel.style.marginLeft = 0; dollarLabel.style.marginRight = 0;
            // default editor font
            _cartBarPriceContainer.Add(dollarLabel);
            
            // Cents (smaller)
            if (!string.IsNullOrEmpty(cents))
            {
                var centsLabel = new Label(cents);
                centsLabel.style.color = _downloadBarSubtitleColor;
                centsLabel.style.fontSize = centsSize;
                centsLabel.style.unityFontStyleAndWeight = _downloadBarSubtitleBold ? FontStyle.Bold : FontStyle.Normal;
                centsLabel.pickingMode = PickingMode.Ignore;
                centsLabel.style.paddingTop = 0; centsLabel.style.paddingBottom = 0;
                centsLabel.style.marginTop = 0; centsLabel.style.marginBottom = 0;
                // No left padding/margin so ".98" sits flush against "$49" (no gap).
                centsLabel.style.paddingLeft = 0; centsLabel.style.paddingRight = 0;
                centsLabel.style.marginLeft = 0; centsLabel.style.marginRight = 0;
                // default editor font
                _cartBarPriceContainer.Add(centsLabel);
            }
            
            // Suffix label (USD etc)
            if (!string.IsNullOrEmpty(suffix))
            {
                var suffixLabel = new Label(suffix);
                suffixLabel.style.color = _downloadBarSubtitleColor;
                suffixLabel.style.fontSize = mainSize;
                suffixLabel.style.unityFontStyleAndWeight = _downloadBarSubtitleBold ? FontStyle.Bold : FontStyle.Normal;
                suffixLabel.pickingMode = PickingMode.Ignore;
                suffixLabel.style.paddingTop = 0; suffixLabel.style.paddingBottom = 0;
                suffixLabel.style.marginTop = 0; suffixLabel.style.marginBottom = 0;
                // default editor font
                _cartBarPriceContainer.Add(suffixLabel);
            }
        }
        
        // Updates the bottom gradient: fades in and tints to the active bottom action's color.
        // Precedence when multiple actions are selectable: download/install > updates > uninstall > cart.
        private void UpdateBottomGradient(bool showDownload, bool showUpdates, bool showUninstall, bool showCart)
        {
            if (_bottomGradient == null) return;
            bool any = showDownload || showUpdates || showUninstall || showCart;
            if (!any)
            {
                if (!_bottomGradientForceVisible) _bottomGradient.style.opacity = 0f;
                return;
            }
            Color c = showDownload ? _bottomGradientDownloadColor
                    : showUpdates  ? _bottomGradientUpdatesColor
                    : showUninstall ? _bottomGradientUninstallColor
                    : _bottomGradientCartColor;
            _bottomGradient.style.unityBackgroundImageTintColor = c;
            bool wasHidden = _bottomGradient.resolvedStyle.opacity <= 0.01f && !_bottomGradientForceVisible;
            _bottomGradient.style.opacity = _bottomGradientOpacity;
            // Pop flourish when it first appears: scale Y up, then ease back to base.
            if (wasHidden) PlayBottomGradientPop();
        }
        
        // Eases the gradient's Y scale up then back, mirroring the top gradient's 100% pop.
        private void PlayBottomGradientPop()
        {
            if (_bottomGradient == null) return;
            float baseY = _bottomGradientFlipY ? -_bottomGradientScaleY : _bottomGradientScaleY;
            float popY = baseY * _bottomGradientPopScaleY;
            // ease up
            _bottomGradient.style.transitionDuration = new List<TimeValue> {
                new TimeValue((int)_bottomGradientPopMs, TimeUnit.Millisecond),
                new TimeValue((int)_bottomGradientEaseMs, TimeUnit.Millisecond),
                new TimeValue((int)_bottomGradientPopMs, TimeUnit.Millisecond)
            };
            _bottomGradient.style.scale = new Scale(new Vector3(
                _bottomGradientFlipX ? -_bottomGradientScaleX : _bottomGradientScaleX, popY, 1f));
            // ease back after pop
            _bottomGradient.schedule.Execute(() =>
            {
                if (_bottomGradient == null) return;
                _bottomGradient.style.transitionDuration = new List<TimeValue> {
                    new TimeValue((int)_bottomGradientReturnMs, TimeUnit.Millisecond),
                    new TimeValue((int)_bottomGradientEaseMs, TimeUnit.Millisecond),
                    new TimeValue((int)_bottomGradientReturnMs, TimeUnit.Millisecond)
                };
                _bottomGradient.style.scale = new Scale(new Vector3(
                    _bottomGradientFlipX ? -_bottomGradientScaleX : _bottomGradientScaleX, baseY, 1f));
            }).StartingIn((long)_bottomGradientPopMs);
        }
        
        // Applies bottom gradient position/scale live from the debug panel.
        private void ApplyBottomGradientLayout()
        {
            if (_bottomGradient == null) return;
            _bottomGradient.style.marginLeft = _bottomGradientX;
            _bottomGradient.style.marginBottom = _bottomGradientY;
            _bottomGradient.style.scale = new Scale(new Vector3(_bottomGradientFlipX ? -_bottomGradientScaleX : _bottomGradientScaleX, _bottomGradientFlipY ? -_bottomGradientScaleY : _bottomGradientScaleY, 1f));
            _bottomGradient.style.rotate = new Rotate(new Angle(_bottomGradientRotation, AngleUnit.Degree));
        }
        
        // Resolves the override color + text colors for a selected asset based on its action state.
        // States: not owned -> cart, owned+update -> update, owned+installed -> uninstall,
        // owned (installable) -> install.
        private void GetSelOverrideColors(bool isOwned, VisualElement btn, out Color overlay, out Color typeText, out Color nameText)
        {
            GetSelOverrideColors(isOwned, btn, out overlay, out typeText, out nameText, out _, out _);
        }

        private void GetSelOverrideColors(bool isOwned, VisualElement btn, out Color overlay, out Color typeText, out Color nameText, out Color iconColor, out Color btnColor)
        {
            if (!isOwned)
            {
                overlay = _selCartColor; typeText = _selCartTypeTextColor; nameText = _selCartNameTextColor; iconColor = _selCartIconColor; btnColor = _selCartBtnColor;
            }
            else if (btn.ClassListContains("asset-has-update"))
            {
                overlay = _selUpdateColor; typeText = _selUpdateTypeTextColor; nameText = _selUpdateNameTextColor; iconColor = _selUpdateIconColor; btnColor = _selUpdateBtnColor;
            }
            else if (btn.ClassListContains("asset-installed"))
            {
                overlay = _selUninstallColor; typeText = _selUninstallTypeTextColor; nameText = _selUninstallNameTextColor; iconColor = _selUninstallIconColor; btnColor = _selUninstallBtnColor;
            }
            else
            {
                overlay = _selInstallColor; typeText = _selInstallTypeTextColor; nameText = _selInstallNameTextColor; iconColor = _selInstallIconColor; btnColor = _selInstallBtnColor;
            }
        }

        // Re-applies selected-state styling to every currently-selected card. setSelected ignores a
        // no-op, so we flip off→on to force the visuals to rebuild with current override settings.
        private void RefreshSelectedVisuals()
        {
            if (_assetItems == null) return;
            foreach (var item in _assetItems)
            {
                if (item.getSelected())
                {
                    item.setSelected(false);
                    item.setSelected(true);
                }
            }
        }

        // Applies the grid top pad. Padding can't be negative in UI Toolkit, so a negative value
        // is applied as a negative marginTop (pulls the grid up); positive uses paddingTop.
        private void ApplyGridTopPad()
        {
            if (_assetContent == null) return;
            if (_assetGridTopPad >= 0f)
            {
                _assetContent.style.paddingTop = _assetGridTopPad;
                _assetContent.style.marginTop = 0;
            }
            else
            {
                _assetContent.style.paddingTop = 0;
                _assetContent.style.marginTop = _assetGridTopPad;
            }
        }

