        // Picks the full or shortened disclaimer text based on the cart button's current width, so
        // it never clips. Uses a rough character-width estimate against the available pixel width.
        private void UpdateCartDisclaimerText()
        {
            if (_cartBarDisclaimerLabel == null || _cartBarBtn == null) return;
            float width = _cartBarBtn.resolvedStyle.width;
            if (width <= 0f) return;
            float fontSize = _cartBarDisclaimerLabel.resolvedStyle.fontSize;
            if (fontSize <= 0f) fontSize = 9f;
            // Approx average glyph width ~0.52em; leave a little horizontal padding.
            float avgChar = fontSize * 0.52f;
            int fitsChars = Mathf.FloorToInt((width - 24f) / Mathf.Max(1f, avgChar));
            string desired = (CART_DISCLAIMER_FULL.Length <= fitsChars) ? CART_DISCLAIMER_FULL : CART_DISCLAIMER_SHORT;
            if (_cartBarDisclaimerLabel.text != desired)
                _cartBarDisclaimerLabel.text = desired;
        }

        private void UpdateDownloadBar()
        {
            // Can be called during startup (via RestoreSelectionFromSession) before the bars/labels
            // are built. Bail out until they exist to avoid a NullReference.
            if (_downloadBar == null || _downloadBarSubtitleLabel == null) return;
            // Count selected installed assets (for uninstall bar)
            var selectedInstalled = _assetItems.Where(item => 
                item.getSelected() && 
                item.button.style.display != DisplayStyle.None &&
                item.btnVisual?.ClassListContains("asset-installed") == true
            ).ToList();
            _selectedUninstallCount = selectedInstalled.Count;
            
            // Count selected owned NOT-installed assets (for download bar)
            var selectedDownload = _assetItems.Where(item => 
                item.getSelected() && item.getOwned() && 
                item.button.style.display != DisplayStyle.None &&
                item.btnVisual?.ClassListContains("asset-installed") != true &&
                item.btnVisual?.ClassListContains("asset-has-update") != true
            ).ToList();
            _selectedCount = selectedDownload.Count;
            
            // Count selected not-owned visible assets (for cart)
            var selectedNotOwned = _assetItems.Where(item => item.getSelected() && !item.getOwned() && item.button.style.display != DisplayStyle.None).ToList();
            _selectedCartCount = selectedNotOwned.Count;
            // Cart pulse: arm when at least one not-owned asset is selected, stop when none are.
            if (_selectedCartCount > 0)
            {
                if (_cartPulseSelectedAt < 0) ArmCartPulse();
                if (_cartBarPulseShownAt < 0) ArmCartBarPulse();
            }
            else
            {
                if (_cartPulseSelectedAt >= 0) StopCartPulse();
                if (_cartBarPulseShownAt >= 0) StopCartBarPulse();
            }
            
            // Count selected update visible assets (owned assets with update state)
            var selectedUpdates = _assetItems.Where(item => item.getSelected() && item.getOwned() && item.btnVisual?.ClassListContains("asset-has-update") == true && item.button.style.display != DisplayStyle.None).ToList();
            _selectedUpdatesCount = selectedUpdates.Count;
            
            // Update projected collection bar
            UpdateProjectedBar();
            
            bool showDownload = _selectedCount > 0;
            bool showCart = _selectedCartCount > 0;
            bool showUpdates = _selectedUpdatesCount > 0;
            bool showUninstall = _selectedUninstallCount > 0;
            UpdateBottomGradient(showDownload, showUpdates, showUninstall, showCart);
            
            // Count how many bars are visible
            int visibleBars = (showDownload ? 1 : 0) + (showCart ? 1 : 0) + (showUpdates ? 1 : 0) + (showUninstall ? 1 : 0);
            
            // The cart button's third disclaimer line needs room; hide it when the cart bar is
            // sharing space with 2+ other bars (3+ total), so the buttons don't overflow.
            if (_cartBarDisclaimerLabel != null)
                _cartBarDisclaimerLabel.style.display = (visibleBars >= 3) ? DisplayStyle.None : DisplayStyle.Flex;
            
            float hideBottom = -_downloadBarHeight - 24;
            
            // While a download/install is in progress, animate ALL action bars off screen
            // and keep them there until it completes. _downloadingActive is set true by
            // SetDownloadingDimState(true) at install start and false at the end; the
            // completion path calls UpdateDownloadBar() again, which brings the bars back.
            if (_downloadingActive)
            {
                if (_downloadBar != null) _downloadBar.style.bottom = hideBottom;
                if (_uninstallBar != null) _uninstallBar.style.bottom = hideBottom;
                if (_updatesBar != null) _updatesBar.style.bottom = hideBottom;
                if (_cartBar != null) _cartBar.style.bottom = hideBottom;
                UpdateBottomBarGradient();
                return;
            }
            
            // Collect all bars and their visibility
            var allBars = new List<(VisualElement bar, bool show)>
            {
                (_downloadBar, showDownload),
                (_uninstallBar, showUninstall),
                (_updatesBar, showUpdates),
                (_cartBar, showCart)
            };
            
            // Hide all bars first, reset margins
            foreach (var (bar, _) in allBars)
            {
                if (bar == null) continue;
                bar.style.marginLeft = 0;
            }
            
            // Get visible bars in order
            var visible = allBars.Where(x => x.show && x.bar != null).Select(x => x.bar).ToList();
            
            if (visible.Count == 0)
            {
                foreach (var (bar, _) in allBars)
                {
                    if (bar != null) bar.style.bottom = hideBottom;
                }
                UpdateBottomBarGradient();
            }
            else
            {
                int n = visible.Count;
                // Width per bar — uses the tunable values for 1/2/3 (so existing hand-tuned
                // layouts keep their look) and computes one that fits cleanly when 4+ are
                // visible.
                float widthPct = n == 1 ? _actionBar1Width 
                    : n == 2 ? _actionBar2Width 
                    : n == 3 ? _actionBar3Width 
                    : (96f - (n - 1) * 2f) / n;
                
                // Outer margin as a fixed percent on both sides. Using a percent (not the
                // pixel padding) keeps every bar on one consistent scale so gaps stay even
                // and bars never overlap regardless of panel width or layout timing.
                float outerMarginPct = 2f;
                
                // Total horizontal space = 100%. Subtract the two outer margins and the n bar
                // widths; whatever remains is split evenly across the (n-1) interior gaps so
                // the bars are perfectly evenly distributed edge to edge.
                float usable = 100f - (outerMarginPct * 2f);
                float gapPct = n > 1 ? Mathf.Max(0f, (usable - n * widthPct) / (n - 1)) : 0f;
                
                for (int i = 0; i < n; i++)
                {
                    var bar = visible[i];
                    bar.style.bottom = _actionBarBottom;
                    bar.style.width = new StyleLength(new Length(widthPct, LengthUnit.Percent));
                    bar.style.paddingLeft = 0;
                    bar.style.paddingRight = 0;
                    // Position every bar by its left edge on the same percent scale, and
                    // explicitly clear `right` so a stale right-pin from a previous layout
                    // cannot stretch/overlap the bar. Using one consistent scale for all
                    // bars (no mixing px-pinned edges with percent) is what keeps the gaps
                    // even and prevents the overlap seen with wide 2-bar widths.
                    float leftPct = outerMarginPct + (i * widthPct) + (i * gapPct);
                    bar.style.left = new StyleLength(new Length(leftPct, LengthUnit.Percent));
                    bar.style.right = StyleKeyword.Null;
                    bar.style.marginLeft = 0;
                    bar.style.marginRight = 0;
                }
                
                // Hide non-visible bars
                foreach (var (bar, show) in allBars)
                {
                    if (bar != null && !show)
                        bar.style.bottom = hideBottom;
                }
                
                UpdateBottomBarGradient();
            }
            
            // Update download bar subtitle
            if (_selectedCount == 1)
            {
                var item = selectedDownload[0];
                _downloadBarSubtitleLabel.text = $"{item.type} {item.name}";
            }
            else if (_selectedCount > 1)
            {
                _downloadBarSubtitleLabel.text = $"{_selectedCount} Selected Assets";
            }
            
            // Update cart bar subtitle with real prices
            if (_selectedCartCount == 1)
            {
                var item = selectedNotOwned[0];
                // Check if on sale via pack mapping
                int idx = _assetItems.IndexOf(item);
                AssetPackData singlePack = null;
                if (idx >= 0) _assetPackMapping.TryGetValue(idx, out singlePack);
                
                if (singlePack != null && singlePack.isOnSale && !string.IsNullOrEmpty(singlePack.compareAtPrice) && item.price > 0)
                {
                    SetCartSubtitleWithPrice($"{item.type} {item.name} - ", item.price, $" USD (was ${singlePack.compareAtPrice})");
                }
                else
                {
                    if (item.price > 0)
                        SetCartSubtitleWithPrice($"{item.type} {item.name} - ", item.price, " USD");
                    else
                        SetCartSubtitleText($"{item.type} {item.name}");
                }
            }
            else if (_selectedCartCount > 1)
            {
                float totalPrice = 0f;
                foreach (var item in selectedNotOwned) totalPrice += item.price;
                if (totalPrice > 0)
                    SetCartSubtitleWithPrice($"{_selectedCartCount} Assets - ", totalPrice, " USD");
                else
                    SetCartSubtitleText($"{_selectedCartCount} Selected Assets");
            }
            
            // Update updates bar subtitle
            if (_selectedUpdatesCount == 1)
            {
                var item = selectedUpdates[0];
                _updatesBarSubtitleLabel.text = $"{item.type} {item.name}";
            }
            else if (_selectedUpdatesCount > 1)
            {
                _updatesBarSubtitleLabel.text = $"{_selectedUpdatesCount} Selected Assets";
            }
            
            // Update uninstall bar subtitle
            if (_selectedUninstallCount == 1 && selectedInstalled.Count > 0)
            {
                var item = selectedInstalled[0];
                _uninstallBarSubtitleLabel.text = $"{item.type} {item.name}";
            }
            else if (_selectedUninstallCount > 1)
            {
                _uninstallBarSubtitleLabel.text = $"{_selectedUninstallCount} Selected Assets";
            }
            
            // Add bottom padding to scroll content so last row isn't hidden behind action bars
            if (_assetContent != null)
            {
                float barPad = visibleBars > 0 ? _downloadBarHeight + _actionBarBottom + 10 : 0;
                _assetContent.style.paddingBottom = barPad;
            }
        }
        
        private float GetCurrentButtonSize()
        {
            if (_thumbnailColumns == 5) return _assetButtonSize5Across;
            if (_thumbnailColumns == 4) return _assetButtonSize4Across;
            return _assetButtonSize3Across;
        }
        
        private float GetBtnBaseScale()
        {
            if (_thumbnailColumns >= 5) return _assetButtonSize5Across / _assetButtonSize3Across;
            if (_thumbnailColumns >= 4) return _assetButtonSize4Across / _assetButtonSize3Across;
            return 1f;
        }
        
        private float GetDlBtnBaseScale()
        {
            if (_thumbnailColumns >= 5) return _smallDlBtnScale;
            if (_thumbnailColumns >= 4) return _medDlBtnScale;
            return 1f;
        }
        
        private float GetProductBtnBaseScale()
        {
            if (_thumbnailColumns >= 5) return _smallProductBtnScale;
            if (_thumbnailColumns >= 4) return _medProductBtnScale;
            return 1f;
        }
        
        private float _lastRootWidth = -1f;
        private float _lastRootHeight = -1f;
        // Unity 6 can leave the whole panel non-uniformly scaled (vertical != horizontal) after the
        // window is maximized or restored. The tool sets no root scale, so this is a Unity panel
        // relayout glitch. When the root size changes meaningfully, force the panel to recompute its
        // layout the same way reopening the window does: clear any stray transform, mark the
        // hierarchy dirty, and repaint over the next couple of frames.
        private void OnRootGeometryChanged(GeometryChangedEvent evt)
        {
            float w = evt.newRect.width;
            float h = evt.newRect.height;
            if (Mathf.Abs(w - _lastRootWidth) < 2f && Mathf.Abs(h - _lastRootHeight) < 2f) return;
            _lastRootWidth = w;
            _lastRootHeight = h;
            ForcePanelRelayout();
        }

        // Resets any panel-level transform and forces a fresh layout pass + repaint, mimicking what
        // closing and reopening the window does to clear the Unity 6 maximize scaling glitch.
        private void ForcePanelRelayout()
        {
            var root = rootVisualElement;
            if (root == null) return;
            // Clear any non-uniform scale/transform that may have leaked onto the root.
            root.style.scale = new Scale(Vector3.one);
            root.style.translate = new Translate(0, 0);
            // Re-apply fixed card sizes and force a layout/repaint over the next frames so the
            // corrected panel size propagates everywhere, not just the grid.
            root.schedule.Execute(() =>
            {
                if (_assetItems != null && _assetItems.Count > 0) UpdateThumbnailSize();
                root.MarkDirtyRepaint();
                Repaint();
            }).StartingIn(0);
            root.schedule.Execute(() =>
            {
                root.MarkDirtyRepaint();
                Repaint();
            }).StartingIn(33); // one more pass after layout settles
        }

        private void UpdateThumbnailSize()
        {
            float buttonSize = GetCurrentButtonSize();
            bool isScaled = _thumbnailColumns >= 4;
            float baseSize = _assetButtonSize3Across;
            float scaleFactor = isScaled ? buttonSize / baseSize : 1f;
            
            foreach (var item in _assetItems)
            {
                item.button.style.width = buttonSize;
                item.button.style.height = buttonSize;
                
                var btn = item.btnVisual;
                if (btn == null) continue;
                
                // Disable transitions for instant size change
                btn.style.transitionDuration = new List<TimeValue> { new TimeValue(0, TimeUnit.Millisecond) };
                
                if (isScaled)
                {
                    btn.style.width = baseSize;
                    btn.style.height = baseSize;
                    float offset = (buttonSize - baseSize) / 2f;
                    btn.style.left = offset;
                    btn.style.top = offset;
                    btn.style.scale = new Scale(new Vector3(scaleFactor, scaleFactor, 1f));
                }
                else
                {
                    btn.style.width = buttonSize;
                    btn.style.height = buttonSize;
                    btn.style.left = 0;
                    btn.style.top = 0;
                    btn.style.scale = new Scale(Vector3.one);
                }
                
                var icon = item.button.Q<VisualElement>(className: "asset-btn-icon");
                if (icon != null && icon.style.backgroundImage.value.texture != null)
                {
                    var tex = icon.style.backgroundImage.value.texture;
                    float aspectRatio = (float)tex.height / tex.width;
                    icon.style.height = baseSize * aspectRatio;
                }
                
                if (_thumbnailColumns == 5)
                    ApplyScaledOverrides(btn, _smallTypeFontSize, _smallNameFontSize, _smallDlBtnScale, _smallDlBtnX, _smallDlBtnY, _smallProductBtnScale, _smallProductBtnX, _smallProductBtnY, scaleFactor);
                else if (_thumbnailColumns == 4)
                    ApplyScaledOverrides(btn, _medTypeFontSize, _medNameFontSize, _medDlBtnScale, _medDlBtnX, _medDlBtnY, _medProductBtnScale, _medProductBtnX, _medProductBtnY, scaleFactor);
                else
                    ResetScaledOverrides(btn);
                
                // Restore transitions after layout applies
                var capturedBtn = btn;
                btn.schedule.Execute(() => {
                    capturedBtn.style.transitionDuration = new List<TimeValue> { new TimeValue(_animDuration, TimeUnit.Millisecond) };
                }).StartingIn(50);
            }
            
            // Keep the exclusive-deal product button in step with the asset buttons
            if (_dealsContainer != null)
                _dealsContainer.Query<VisualElement>("deal-product-btn").ForEach(ApplyDealProductOffsets);
            
            // Scale the sale-amount images with the thumbnail size
            UpdateSaleAmount();
        }
        
        // Sets the name label to baseFontSize, then (once laid out) shrinks it proportionally if the
        // text is wider than the space available on the card — so long titles fit at ANY icon size.
        // Re-applied whenever the font is (re)set, because icon-size changes overwrite it otherwise.
        // Shrinks a filter group's title font so it doesn't overlap the All/None buttons + chevron
        // when the title is long (e.g. "INSTALLED"). Measured once after layout; self-unregistering.
        private void FitFilterTitle(Label titleLabel, VisualElement header, VisualElement allNoneContainer)
        {
            if (titleLabel == null || header == null) return;
            titleLabel.RegisterCallback<GeometryChangedEvent>(evt =>
            {
                float headerW = header.resolvedStyle.width;
                float titleW = titleLabel.resolvedStyle.width;
                float curFs = titleLabel.resolvedStyle.fontSize;
                float allNoneW = allNoneContainer != null ? allNoneContainer.resolvedStyle.width : 0f;
                if (headerW <= 1f || titleW <= 1f || curFs <= 0f) return;
                float maxW = headerW - allNoneW - 20f; // reserve tuned so the title is readable without crowding All
                // Only shrink (never grow) so it converges. Apply the change DEFERRED (next tick), not
                // during this layout pass — changing the font mid-layout re-triggers layout and Unity
                // warns about "recursive layout". Deferring keeps the self-heal without the recursion.
                if (maxW > 10f && titleW > maxW + 0.5f)
                {
                    float target = Mathf.Max(7f, curFs * (maxW / titleW));
                    titleLabel.schedule.Execute(() =>
                    {
                        if (titleLabel != null && Mathf.Abs(titleLabel.resolvedStyle.fontSize - target) > 0.25f)
                            titleLabel.style.fontSize = target;
                    }).ExecuteLater(1);
                }
            });
        }

        private void FitNameLabel(Label nameLabel, float baseFontSize)
        {
            if (nameLabel == null) return;
            nameLabel.style.fontSize = baseFontSize;
            EventCallback<GeometryChangedEvent> cb = null;
            cb = (evt) =>
            {
                nameLabel.UnregisterCallback(cb); // one-shot — avoids a relayout loop
                if (nameLabel.parent == null) return;
                float pw = nameLabel.parent.resolvedStyle.width;
                float textW = nameLabel.resolvedStyle.width;
                if (pw <= 1f || textW <= 1f) return;
                float maxW = pw - _nameLabelX - 40f; // reserve room for the download/link button
                if (maxW > 10f && textW > maxW)
                {
                    float target = Mathf.Max(6f, baseFontSize * (maxW / textW));
                    // Defer out of the layout pass — changing font mid-layout re-triggers layout, and
                    // with a full grid of cards Unity flags it as "recursive layout".
                    nameLabel.schedule.Execute(() => { if (nameLabel != null) nameLabel.style.fontSize = target; }).ExecuteLater(1);
                }
            };
            nameLabel.RegisterCallback(cb);
        }

        private void ApplyScaledOverrides(VisualElement btn, float typeFontSize, float nameFontSize,
            float dlScale, float dlX, float dlY, float prodScale, float prodX, float prodY, float globalScale)
        {
            var typeLabel = btn.Q<Label>("asset-type-label");
            if (typeLabel != null)
                typeLabel.style.fontSize = typeFontSize / globalScale;
            
            var nameLabel = btn.Q<Label>("asset-name-label");
            if (nameLabel != null)
                FitNameLabel(nameLabel, nameFontSize / globalScale);
            
            var dlBtn = btn.Q<VisualElement>("download-btn");
            if (dlBtn != null)
            {
                dlBtn.style.scale = new Scale(new Vector3(dlScale, dlScale, 1f));
                dlBtn.style.right = dlX;
                dlBtn.style.bottom = dlY;
            }
            
            var dlBtnBg = btn.Q<VisualElement>("download-btn-bg");
            if (dlBtnBg != null)
            {
                dlBtnBg.style.scale = new Scale(new Vector3(dlScale, dlScale, 1f));
                dlBtnBg.style.right = dlX;
                dlBtnBg.style.bottom = dlY;
            }
            
            var cartBtn = btn.Q<VisualElement>("cart-btn");
            if (cartBtn != null)
            {
                cartBtn.style.scale = new Scale(new Vector3(dlScale, dlScale, 1f));
                cartBtn.style.right = dlX;
                cartBtn.style.bottom = dlY;
            }
            
            var productBtn = btn.Q<VisualElement>("product-btn");
            if (productBtn != null)
            {
                productBtn.style.scale = new Scale(new Vector3(prodScale, prodScale, 1f));
                productBtn.style.left = prodX;
                productBtn.style.top = prodY;
            }
            
            var radialRing = btn.Q<VisualElement>("radial-ring");
            if (radialRing != null)
            {
                radialRing.style.right = dlX - 10;
                radialRing.style.bottom = dlY - 10;
            }
            var radialRingBg = btn.Q<VisualElement>("radial-ring-bg");
            if (radialRingBg != null)
            {
                radialRingBg.style.right = dlX - 10;
                radialRingBg.style.bottom = dlY - 10;
            }
        }
        
        private void ResetScaledOverrides(VisualElement btn)
        {
            var typeLabel = btn.Q<Label>("asset-type-label");
            if (typeLabel != null)
                typeLabel.style.fontSize = _typeFontSize;
            
            var nameLabel = btn.Q<Label>("asset-name-label");
            if (nameLabel != null)
                FitNameLabel(nameLabel, _nameFontSize);
            
            var dlBtn = btn.Q<VisualElement>("download-btn");
            if (dlBtn != null)
            {
                dlBtn.style.scale = new Scale(Vector3.one);
                dlBtn.style.right = _downloadBtnX;
                dlBtn.style.bottom = _downloadBtnY;
            }
            
            var dlBtnBg = btn.Q<VisualElement>("download-btn-bg");
            if (dlBtnBg != null)
            {
                dlBtnBg.style.scale = new Scale(Vector3.one);
                dlBtnBg.style.right = _downloadBtnX;
                dlBtnBg.style.bottom = _downloadBtnY;
            }
            
            var cartBtn = btn.Q<VisualElement>("cart-btn");
            if (cartBtn != null)
            {
                cartBtn.style.scale = new Scale(Vector3.one);
                cartBtn.style.right = _downloadBtnX;
                cartBtn.style.bottom = _downloadBtnY;
            }
            
            var productBtn = btn.Q<VisualElement>("product-btn");
            if (productBtn != null)
            {
                productBtn.style.scale = new Scale(Vector3.one);
                productBtn.style.left = _productBtnX;
                productBtn.style.top = _productBtnY;
            }
            
            var radialRing = btn.Q<VisualElement>("radial-ring");
            if (radialRing != null)
            {
                radialRing.style.right = _downloadBtnX - 10;
                radialRing.style.bottom = _downloadBtnY - 10;
            }
            var radialRingBg = btn.Q<VisualElement>("radial-ring-bg");
            if (radialRingBg != null)
            {
                radialRingBg.style.right = _downloadBtnX - 10;
                radialRingBg.style.bottom = _downloadBtnY - 10;
            }
        }
        
        private (VisualElement button, System.Action<bool> setSelected, System.Func<bool> getSelected, System.Action<bool> setOwned, System.Func<bool> getOwned) CreateAssetButton(string assetType, string assetName, string iconName, bool isNew = false, bool isOnSale = false, bool initiallyOwned = true, float price = 0f, string compareAtPrice = null)
        {
            // Get colors based on asset type
            var (themeColor, textColor) = GetAssetTypeColors(assetType);
            
            float initialSize = GetCurrentButtonSize();
            
            // Outer hit area container - fixed size, handles mouse events, doesn't scale
            var hitArea = new VisualElement();
            hitArea.AddToClassList("asset-btn-hitarea");
            hitArea.style.position = Position.Relative;
            hitArea.pickingMode = PickingMode.Position;
            hitArea.focusable = true;
            hitArea.style.width = initialSize;
            hitArea.style.height = initialSize;
            hitArea.style.marginLeft = _assetBtnMargin;
            hitArea.style.marginRight = _assetBtnMargin;
            hitArea.style.marginTop = _assetBtnMargin;
            hitArea.style.marginBottom = _assetBtnMargin;
            hitArea.style.alignItems = Align.Center;
            hitArea.style.justifyContent = Justify.Center;
            
            // Inner visual container - this is what actually scales
            var btn = new VisualElement();
            btn.name = "asset-btn-visual";
            btn.AddToClassList("asset-btn");
            btn.style.position = Position.Absolute;
            btn.style.top = 0;
            btn.style.left = 0;
            btn.pickingMode = PickingMode.Ignore; // Only hitArea handles main mouse events
            btn.style.width = initialSize;
            btn.style.height = initialSize;
            btn.style.transformOrigin = new TransformOrigin(Length.Percent(50), Length.Percent(50));
            btn.style.overflow = Overflow.Hidden; // Clip children to border-radius
            btn.style.borderTopLeftRadius = _assetBtnRadius;
            btn.style.borderTopRightRadius = _assetBtnRadius;
            btn.style.borderBottomLeftRadius = _assetBtnRadius;
            btn.style.borderBottomRightRadius = _assetBtnRadius;
            hitArea.Add(btn);
            
            // Background image (layer 1) - using Asset_Background like in mask test
            var assetBg = new VisualElement();
            assetBg.AddToClassList("asset-btn-bg");
            assetBg.pickingMode = PickingMode.Ignore;
            var bgTex = LoadImage("Assets", "Asset_Background");
            if (bgTex != null)
            {
                assetBg.style.backgroundImage = new StyleBackground(bgTex);
            }
            btn.Add(assetBg);
            
            // Gradient overlay (layer 2) - tinted gradient texture
            var gradientOverlay = new VisualElement();
            gradientOverlay.name = "asset-btn-gradient";
            gradientOverlay.AddToClassList("asset-btn-gradient");
            gradientOverlay.pickingMode = PickingMode.Ignore;
            var gradientTex = LoadImage("Assets", "Asset_Background_Gradient");
            if (gradientTex != null)
            {
                gradientOverlay.style.backgroundImage = new StyleBackground(gradientTex);
                // Set initial gradient color based on state
                if (_debugDownloadState == 1)
                    gradientOverlay.style.unityBackgroundImageTintColor = _installedBtnColor;
                else if (_debugDownloadState == 2)
                    gradientOverlay.style.unityBackgroundImageTintColor = _updateBtnColor;
                else if (isOnSale && !initiallyOwned)
                    gradientOverlay.style.unityBackgroundImageTintColor = _saleGradientColor;
                else
                    gradientOverlay.style.unityBackgroundImageTintColor = themeColor;
            }
            btn.Add(gradientOverlay);
            
            // Asset icon/image (layer 3) - masked with rounded corners
            var assetIcon = new VisualElement();
            assetIcon.name = "asset-icon";
            assetIcon.AddToClassList("asset-btn-icon");
            assetIcon.pickingMode = PickingMode.Ignore;
            assetIcon.style.backgroundColor = Color.clear;
            assetIcon.style.SetBackgroundScaleToFit();
            
            // Use explicit iconName if provided, otherwise pick from shuffled pool
            string actualIconName = !string.IsNullOrEmpty(iconName) ? iconName : NextAssetIconName();
            
            // Load icon from AssetIcons/ — both the colored original and the desaturated copy
            // ("<name>Desaturated"). The icon is shown DESATURATED by default, and COLORED when
            // the card is hovered or selected (manually or via Select All). Falls back to the
            // colored icon if the desaturated copy is missing.
            // Ensure the desaturated copy exists + is cached right here, so it is available the
            // first time the card paints regardless of which build path created it (otherwise
            // the icon would appear colored until a hover forced a fresh load).
            if (actualIconName != null) EnsureDesaturatedCopy("AssetIcons", actualIconName);
            var iconTex = actualIconName != null ? LoadImage("AssetIcons", actualIconName) : null;
            var iconTexDesat = actualIconName != null ? LoadImage("AssetIcons", actualIconName + "Desaturated") : null;
            if (iconTexDesat == null) iconTexDesat = iconTex; // fallback to colored if no desat copy
            
            Texture2D maskedTex = iconTex;
            
            if (maskedTex != null)
            {
                // Owned -> colored; not-owned -> desaturated (until hovered/selected).
                assetIcon.style.backgroundImage = new StyleBackground(initiallyOwned ? iconTex : iconTexDesat);
                _iconSourceData[assetIcon] = maskedTex;
                _iconColored[assetIcon] = iconTex;
                _iconDesaturated[assetIcon] = iconTexDesat;
            }
            btn.Add(assetIcon);
            
            // Track owned state (declared early so the icon-arrival spinner and child button
            // handlers can access it).
            bool isOwned = initiallyOwned;
            
            // Loading spinner shown in the center of the card while the icon image is not yet
            // available (e.g. it is still downloading from R2 on first run). It is a simple
            // rotating element; it hides itself as soon as an icon texture is present. If the
            // icon never arrives (e.g. not uploaded to R2) the card keeps whatever fallback
            // it has, and the spinner stops after a timeout so it does not spin forever.
            if (maskedTex == null)
            {
                var spinner = new VisualElement();
                spinner.name = "asset-loading-spinner";
                spinner.pickingMode = PickingMode.Ignore;
                spinner.style.position = Position.Absolute;
                spinner.style.width = 28;
                spinner.style.height = 28;
                spinner.style.left = Length.Percent(50);
                spinner.style.top = Length.Percent(50);
                spinner.style.marginLeft = -14;
                spinner.style.marginTop = -14;
                // Draw a ring with one lighter quadrant using borders, then rotate it.
                spinner.style.borderTopWidth = 3;
                spinner.style.borderBottomWidth = 3;
                spinner.style.borderLeftWidth = 3;
                spinner.style.borderRightWidth = 3;
                var dim = new Color(1f, 1f, 1f, 0.15f);
                var bright = new Color(1f, 1f, 1f, 0.85f);
                spinner.style.borderTopColor = bright;
                spinner.style.borderRightColor = dim;
                spinner.style.borderBottomColor = dim;
                spinner.style.borderLeftColor = dim;
                spinner.style.borderTopLeftRadius = 14;
                spinner.style.borderTopRightRadius = 14;
                spinner.style.borderBottomLeftRadius = 14;
                spinner.style.borderBottomRightRadius = 14;
                btn.Add(spinner);
                
                // Animate rotation and poll for the icon arriving. Uses scheduler (not a
                // geometry/layout callback) so it never recurses into layout. Stops when the
                // icon appears, the element leaves the panel, or after ~20s as a safety cap.
                float angle = 0f;
                double startedAt = EditorApplication.timeSinceStartup;
                var capturedIcon = assetIcon;
                var capturedName = actualIconName;
                IVisualElementScheduledItem spinTask = null;
                spinTask = spinner.schedule.Execute(() =>
                {
                    // Stop the recurring task outright on domain reload or when the spinner
                    // leaves the panel, so its scheduled-item handle isn't left dangling
                    // across a domain reload ("invalid GC handle" warning).
                    if (_reloadingDomain || spinner.panel == null)
                    {
                        SafePause(spinTask);
                        return;
                    }
                    // Icon arrived? (either already set, or now loadable from disk)
                    Texture2D nowTex = capturedIcon.resolvedStyle.backgroundImage.texture;
                    if (nowTex == null && capturedName != null)
                        nowTex = LoadImage("AssetIcons", capturedName);
                    bool timedOut = (EditorApplication.timeSinceStartup - startedAt) > 20.0;
                    if (nowTex != null || timedOut)
                    {
                        if (nowTex != null && capturedIcon.resolvedStyle.backgroundImage.texture == null)
                        {
                            // Populate the colored/desaturated pair now that the icon arrived,
                            // and show the right one for the current owned state.
                            var desatNow = LoadImage("AssetIcons", capturedName + "Desaturated");
                            if (desatNow == null) desatNow = nowTex;
                            _iconColored[capturedIcon] = nowTex;
                            _iconDesaturated[capturedIcon] = desatNow;
                            _iconSourceData[capturedIcon] = nowTex;
                            capturedIcon.style.backgroundImage = new StyleBackground(isOwned ? nowTex : desatNow);
                        }
                        spinner.style.display = DisplayStyle.None;
                        SafePause(spinTask); // done — stop the recurring tick
                        return;
                    }
                    angle = (angle + 12f) % 360f;
                    spinner.style.rotate = new Rotate(new Angle(angle, AngleUnit.Degree));
                }).Every(33); // ~30fps
                TrackScheduledItem(spinTask);
            }
            
            // Colored overlay for not-owned assets (layer 3.5) - fades in when selected
            var coloredOverlay = new VisualElement();
            coloredOverlay.name = "asset-colored-overlay";
            coloredOverlay.AddToClassList("asset-btn-icon");
            coloredOverlay.pickingMode = PickingMode.Ignore;
            coloredOverlay.style.position = Position.Absolute;
            coloredOverlay.style.top = 0;
            coloredOverlay.style.left = 0;
            coloredOverlay.style.right = 0;
            coloredOverlay.style.bottom = 0;
            coloredOverlay.style.opacity = 0; // Hidden by default
            if (maskedTex != null)
            {
                coloredOverlay.style.backgroundImage = new StyleBackground(maskedTex);
            }
            // Setup transition for fade effect
            coloredOverlay.style.transitionProperty = new List<StylePropertyName> { new StylePropertyName("opacity") };
            coloredOverlay.style.transitionDuration = new List<TimeValue> { new TimeValue(200, TimeUnit.Millisecond) };
            coloredOverlay.style.transitionTimingFunction = new List<EasingFunction> { new EasingFunction(EasingMode.EaseOut) };
            btn.Add(coloredOverlay);
            
            // Load round button texture for both buttons
            var roundTex = LoadImage("Buttons", "Button_Round");
            var roundPressedTex = LoadImage("Buttons", "Button_Round_Pressed");
            
            // Track if mouse is over a child button (to prevent parent scale)
            // Declared here so it's accessible by product/download button handlers and main button handlers
            bool isOverChildButton = false;
            
            // Track selected state (declared early so child button handlers can access it)
            bool isSelected = false;
            
            // Forward declare selectedOverlay so child button handlers can access it
            VisualElement selectedOverlay = null;
            // Forward declare isInstalledRef so child button handlers can access it
            bool[] isInstalledRef = { initiallyOwned && _debugDownloadState == 1 };
            // Forward declare setSelected ref so download button can deselect before declaration
            System.Action<bool>[] setSelectedRef = { null };
            // Forward declare downloadIcon so it's accessible inside the downloadBtnInteractive block
            VisualElement downloadIcon = null;
            
            // Forward declare hoverScheduledTask so child button handlers can cancel it
            IVisualElementScheduledItem hoverScheduledTask = null;
            
            // Product page button (top left)
            var productBtn = new Button();
            productBtn.name = "product-btn";
            productBtn.AddToClassList("product-btn");
            // Remove default Unity button styling
            productBtn.RemoveFromClassList("unity-button");
            productBtn.RemoveFromClassList("unity-text-element");
            productBtn.style.position = Position.Absolute;
            productBtn.style.top = _productBtnY;
            productBtn.style.left = _productBtnX;
            productBtn.style.width = 28;
            productBtn.style.height = 28;
            productBtn.style.backgroundColor = Color.clear;
            productBtn.style.borderTopWidth = 0;
            productBtn.style.borderBottomWidth = 0;
            productBtn.style.borderLeftWidth = 0;
            productBtn.style.borderRightWidth = 0;
            productBtn.style.opacity = 1; // Always visible
            if (roundTex != null)
            {
                productBtn.style.backgroundImage = new StyleBackground(roundTex);
            }
            // Use black for button background
            productBtn.style.unityBackgroundImageTintColor = Color.black;
            productBtn.clicked += () => {
                // Find pack data and open real product page
                int idx = _assetItems.FindIndex(x => x.button == hitArea);
                if (idx >= 0 && _assetPackMapping.TryGetValue(idx, out var pack))
                    SyntyCatalogBridge.OpenProductPage(pack);
                else
                    Application.OpenURL(SyntyCatalogBridge.STORE_AFFILIATE_URL);
            };
            
            // Setup transition for scale animation
            productBtn.style.transitionProperty = new List<StylePropertyName> { 
                new StylePropertyName("scale")
            };
            productBtn.style.transitionDuration = new List<TimeValue> { 
                new TimeValue(100, TimeUnit.Millisecond)
            };
            productBtn.style.transitionTimingFunction = new List<EasingFunction> { 
                new EasingFunction(EasingMode.EaseOut)
            };
            
            // Product page icon inside button
            var productIcon = new VisualElement();
            productIcon.name = "product-icon";
            productIcon.style.position = Position.Absolute;
            productIcon.style.top = _productIconPadding;
            productIcon.style.left = _productIconPadding;
            productIcon.style.right = _productIconPadding;
            productIcon.style.bottom = _productIconPadding;
            productIcon.pickingMode = PickingMode.Ignore;
            var prodTex = LoadImage("Assets", "Icon_ProductPage");
            if (prodTex != null)
            {
                productIcon.style.backgroundImage = new StyleBackground(prodTex);
                productIcon.style.SetBackgroundScaleToFit();
            }
            // Set icon tint to white
            productIcon.style.unityBackgroundImageTintColor = Color.white;
            productBtn.Add(productIcon);
            _productIcons.Add(productIcon);
            
            // Ensure tint is applied after element is rendered
            productBtn.RegisterCallback<GeometryChangedEvent>(evt => {
                productBtn.style.unityBackgroundImageTintColor = Color.black;
                productIcon.style.unityBackgroundImageTintColor = Color.white;
            });
            
            // Product button pressed overlay (shows on hover)
            var productPressedOverlay = new VisualElement();
            productPressedOverlay.name = "product-pressed-overlay";
            productPressedOverlay.style.position = Position.Absolute;
