                {
                    float progress = (radialRing.userData is float[] ud) ? ud[0] : progressRef[0];
                    if (progress <= 0f || _downloadRingTex == null) return;
                    
                    var rect = ctx.visualElement.contentRect;
                    float w = rect.width, h = rect.height;
                    // contentRect can read 0 on the first paints after the element flips from
                    // display:None to Flex (layout hasn't resolved yet). Fall back to the element's
                    // styled size, then a hard default, so the ring always has a radius to draw.
                    if (w <= 0f || float.IsNaN(w))
