                    if (h <= 0f || float.IsNaN(h))
                        h = ctx.visualElement.resolvedStyle.height > 0 ? ctx.visualElement.resolvedStyle.height : 48f;
                    float cx = w * 0.5f;
                    float cy = h * 0.5f;
                    float radius = Mathf.Min(cx, cy);
                    
                    float sweepAngle = 360f * Mathf.Clamp01(progress);
                    int segments = Mathf.Max(3, Mathf.CeilToInt(sweepAngle / 3f));
                    
                    int vertCount = segments + 2;
                    int idxCount  = segments * 3;
                    
                    var mesh = ctx.Allocate(vertCount, idxCount, _downloadRingTex);
                    
