                    mesh.SetNextVertex(new Vertex {
                        position = new Vector3(cx, cy, Vertex.nearZ),
                        uv = new Vector2(0.5f, 0.5f),
                        tint = green
                    });
                    
                    // Arc starts at top (-90°), sweeps clockwise
                    for (int i = 0; i <= segments; i++)
                    {
                        float angleDeg = -90f + sweepAngle * i / segments;
                        float rad = angleDeg * Mathf.Deg2Rad;
                        float x = cx + Mathf.Cos(rad) * radius;
                        float y = cy + Mathf.Sin(rad) * radius;
                        mesh.SetNextVertex(new Vertex {
                            position = new Vector3(x, y, Vertex.nearZ),
                            uv = new Vector2(x / w, y / h),
                            tint = green
                        });
                    }
                    
                    for (int i = 0; i < segments; i++)
                    {
                        mesh.SetNextIndex(0);
                        mesh.SetNextIndex((ushort)(i + 1));
                        mesh.SetNextIndex((ushort)(i + 2));
                    }
