                            uninstallBadge.style.unityFontStyleAndWeight = FontStyle.Bold;
                            uninstallBadge.style.paddingTop = 5;
                            uninstallBadge.style.paddingBottom = 5;
                            uninstallBadge.style.paddingLeft = 8;
                            uninstallBadge.style.paddingRight = 8;
                            uninstallBadge.style.letterSpacing = 1;
                            if (_titleFont != null) uninstallBadge.style.unityFontDefinition = FontDefinition.FromFont(_titleFont);
