                                else
                                {
                                    downloadBtn.style.unityBackgroundImageTintColor = Color.black;
                                    downloadIcon.style.unityBackgroundImageTintColor = selectionColor;
                                    gradientOverlay.style.unityBackgroundImageTintColor = themeColor;
                                }
                            }
                            else
                            {
                                cartBtn.style.unityBackgroundImageTintColor = Color.black;
                                // Get cart icon and set to cart color
                                var cartIconEl = cartBtn.Q<VisualElement>("cart-icon");
                                if (cartIconEl != null)
                                    cartIconEl.style.unityBackgroundImageTintColor = selectionColor;
                            }
                            productIcon.style.unityBackgroundImageTintColor = Color.white;
