            }, TrickleDown.TrickleDown);
            
            // Single consolidated MouseLeaveEvent handler
            hitArea.RegisterCallback<MouseLeaveEvent>(evt => {
                if (_activeDownloadCount > 0) return; // suppress hover cleanup while any download is active
                // Cancel any pending hover task
                if (hoverScheduledTask != null)
                {
                    SafePause(hoverScheduledTask);
                    hoverScheduledTask = null;
                }
                
                // Guarantee the card never gets stuck at the pressed (smaller) scale: whenever the
                // mouse leaves, snap the scale back to its correct resting value immediately. The
                // bounds-gated block below still handles overlay/colour cleanup with cooldown, but
                // scale restoration must not depend on it (a stale worldBound on the first card after
                // a refresh could otherwise skip the restore and leave it shrunk).
                if (!isSelected)
                {
                    float _bsImmediate = GetBtnBaseScale();
                    btn.style.scale = new Scale(new Vector3(_bsImmediate, _bsImmediate, 1f));
                }
                
                // Only process if actually leaving the hit area bounds
                if (!hitArea.worldBound.Contains(evt.mousePosition))
                {
                    // Use cooldown to delay the leave action
                    System.Action performLeave = () => {
                        isCurrentlyHovered = false;
                        lastHoverChangeTime = EditorApplication.timeSinceStartup * 1000;
                        updateIconColorState(); // back to desaturated unless still selected
                        
                        // Restore the sale-amount badge's base scale (hover release).
                        {
                            var saLeave = hitArea.Q<VisualElement>("sale-amount") ?? btn.Q<VisualElement>("sale-amount");
                            if (saLeave != null)
                            {
                                float baseScale = _saleAmountScale * GetThumbScaleFactor();
                                saLeave.style.scale = new Scale(new Vector3(baseScale, baseScale, 1f));
                            }
                        }
                        
                        if (isPressed)
                        {
                            isPressed = false;
                        }
                        
                        // Restore transition duration
                        btn.style.transitionDuration = new List<TimeValue> { new TimeValue(_animDuration, TimeUnit.Millisecond) };
                        
                        // Fade out colored overlay for not-owned assets
                        if (!isOwned)
                        {
                            if (!isSelected)
                            {
                                coloredOverlay.style.opacity = (isOnSale && _saleColorOverlayOpacity > 0f) ? _saleColorOverlayOpacity : 0f;
                                typeLabel.style.color = _notOwnedTypeTextColor;
                                nameLabel.style.color = _notOwnedNameTextColor;
                            }
                            else
                            {
                                // Selected but not owned: restore dimmed overlay, keep selected text colors
                                coloredOverlay.style.opacity = (isOnSale && _saleColorOverlayOpacity > 0f) ? _saleColorOverlayOpacity : 0f;
                                typeLabel.style.color = _notOwnedSelectedTypeTextColor;
                                nameLabel.style.color = _notOwnedSelectedNameTextColor;
                            }
                        }
                        
                        if (!isSelected)
                        {
                        if (btn.ClassListContains("asset-has-update"))
                        {
                            selectedOverlay.style.unityBackgroundImageTintColor = _updateBtnColor;
                            selectedOverlay.style.opacity = 1;
                        }
                        else if (btn.ClassListContains("asset-installed"))
                        {
                            selectedOverlay.style.unityBackgroundImageTintColor = _installedBtnColor;
                            selectedOverlay.style.opacity = 1;
                        }
                        else if (isOnSale && !isOwned && _showSaleBadges)
                        {
                            selectedOverlay.style.unityBackgroundImageTintColor = _saleOutlineColor;
                            selectedOverlay.style.opacity = _saleOutlineOpacity;
                        }
                        else
                            selectedOverlay.style.opacity = 0;
                            { float _bs = GetBtnBaseScale(); btn.style.scale = new Scale(new Vector3(_bs, _bs, 1f)); }
                        }
                        else
                        {
                            // Restore selection color overlay when leaving selected button
                            if (_selOverrideEnabled)
                            {
                                GetSelOverrideColors(isOwned, btn, out Color actionColor, out Color tType, out Color tName, out Color tIcon, out Color tBtn);
                                selectedOverlay.style.unityBackgroundImageTintColor = actionColor;
                                if (_selOverrideTintBg)
                                {
                                    assetBg.style.unityBackgroundImageTintColor = actionColor;
                                    gradientOverlay.style.unityBackgroundImageTintColor = actionColor;
                                    if (typeBgOverlayRef != null) typeBgOverlayRef.style.unityBackgroundImageTintColor = actionColor;
                                }
                                if (!isOwned)
                                {
                                    cartBtn.style.unityBackgroundImageTintColor = tBtn;
                                    var ci = cartBtn.Q<VisualElement>("cart-icon");
                                    if (ci != null) ci.style.unityBackgroundImageTintColor = tIcon;
                                }
                                else
                                {
                                    downloadBtn.style.unityBackgroundImageTintColor = tBtn;
                                    if (downloadIcon != null) downloadIcon.style.unityBackgroundImageTintColor = tIcon;
                                    var pOvr = downloadBtn.Q<VisualElement>("download-pressed-overlay");
                                    if (pOvr != null) pOvr.style.unityBackgroundImageTintColor = tBtn;
                                    // Installed asset selected -> show the uninstall icon.
                                    if (btn.ClassListContains("asset-installed") && _uninstallIcon != null && downloadIcon != null)
                                        downloadIcon.style.backgroundImage = new StyleBackground(_uninstallIcon);
                                }
                                typeLabel.style.color = tType;
                                nameLabel.style.color = tName;
                                { float _bs = GetBtnBaseScale(); btn.style.scale = new Scale(new Vector3(_selOverrideScale * _bs, _selOverrideScale * _bs, 1f)); }
                            }
                            else
                            {
                            var selectionColor = isOwned ? selectedColor : _cartBtnColor;
                            selectedOverlay.style.unityBackgroundImageTintColor = selectionColor;
                            { float _bs = GetBtnBaseScale(); btn.style.scale = new Scale(new Vector3(_selectedScale * _bs, _selectedScale * _bs, 1f)); }
                            }
                        }
                        leaveScheduledTask = null;
                    };
                    
                    if (_hoverCooldown > 0)
                    {
                        // Schedule leave with cooldown delay
                        leaveScheduledTask = hitArea.schedule.Execute(performLeave).StartingIn((long)_hoverCooldown);
                    }
                    else
                    {
                        performLeave();
                    }
                }
            });
            
            // External selection control function
            System.Action<bool> setSelected = (bool selected) => {
                if (selected == isSelected) return; // No change needed                
                isSelected = selected;
                updateIconColorState(); // colored when selected, desaturated when not
                if (isSelected)
                {
                    btn.AddToClassList("asset-btn--selected");
                    if (_selOverrideEnabled)
                    {
                        // Color the selected state by the ACTION that applies to this asset.
                        GetSelOverrideColors(isOwned, btn, out Color actionColor, out Color tType, out Color tName, out Color tIcon, out Color tBtn);
                        float _bs = GetBtnBaseScale();
                        btn.style.scale = new Scale(new Vector3(_selOverrideScale * _bs, _selOverrideScale * _bs, 1f));
                        selectedOverlay.style.opacity = _selOverrideOverlayOpacity;
                        selectedOverlay.style.unityBackgroundImageTintColor = actionColor;
                        if (_selOverrideTintBg)
                        {
                            assetBg.style.unityBackgroundImageTintColor = actionColor;
                            gradientOverlay.style.unityBackgroundImageTintColor = actionColor; // the visible footer color
                            if (typeBgOverlayRef != null) typeBgOverlayRef.style.unityBackgroundImageTintColor = actionColor;
                        }
                        if (!isOwned)
                        {
                            cartBtn.style.unityBackgroundImageTintColor = tBtn;
                            var ci = cartBtn.Q<VisualElement>("cart-icon");
                            if (ci != null) ci.style.unityBackgroundImageTintColor = tIcon;
                        }
                        else
                        {
                            downloadBtn.style.unityBackgroundImageTintColor = tBtn;
                            if (downloadIcon != null) downloadIcon.style.unityBackgroundImageTintColor = tIcon;
                            var pOvr = downloadBtn.Q<VisualElement>("download-pressed-overlay");
                            if (pOvr != null) pOvr.style.unityBackgroundImageTintColor = tBtn;
                            if (btn.ClassListContains("asset-installed") && _uninstallIcon != null && downloadIcon != null)
                                downloadIcon.style.backgroundImage = new StyleBackground(_uninstallIcon);
                        }
                        typeLabel.style.color = tType;
                        nameLabel.style.color = tName;
                        if (selectedShadow != null) selectedShadow.style.display = DisplayStyle.Flex;
                    }
                    else
                    {
                    { float _bs = GetBtnBaseScale(); btn.style.scale = new Scale(new Vector3(_selectedScale * _bs, _selectedScale * _bs, 1f)); }
                    var selOverlayColor = isOwned ? selectedColor : _cartBtnColor;
                    selectedOverlay.style.opacity = 1;
                    selectedOverlay.style.unityBackgroundImageTintColor = selOverlayColor;
                    assetBg.style.unityBackgroundImageTintColor = selOverlayColor;
                    typeLabel.style.color = textColor;
                    nameLabel.style.color = isOwned ? textColor : Color.white;
                    // Turn on the selected-shadow overlay (sits over the background element).
                    if (selectedShadow != null) selectedShadow.style.display = DisplayStyle.Flex;
                    }
                }
                else
                {
                    btn.RemoveFromClassList("asset-btn--selected");
                    { float _bs = GetBtnBaseScale(); btn.style.scale = new Scale(new Vector3(_bs, _bs, 1f)); }
                    // Sale assets: keep overlay visible in sale blue; installed: green; others: hide it
                    if (btn.ClassListContains("asset-has-update"))
                    {
                        selectedOverlay.style.unityBackgroundImageTintColor = _updateBtnColor;
                        selectedOverlay.style.opacity = 1;
                    }
                    else if (btn.ClassListContains("asset-installed"))
                    {
                        selectedOverlay.style.unityBackgroundImageTintColor = _installedBtnColor;
                        selectedOverlay.style.opacity = 1;
                    }
                    else if (isOnSale && !isOwned && _showSaleBadges)
                    {
                        selectedOverlay.style.unityBackgroundImageTintColor = _saleOutlineColor;
                        selectedOverlay.style.opacity = _saleOutlineOpacity;
                    }
                    else
                    {
                        selectedOverlay.style.opacity = 0;
                        selectedOverlay.style.unityBackgroundImageTintColor = Color.white;
                    }
                    assetBg.style.unityBackgroundImageTintColor = defaultBgColor;
                    if (typeBgOverlayRef != null) typeBgOverlayRef.style.unityBackgroundImageTintColor = themeColor;
                    // If override tinted the gradient overlay, restore it to its state/theme color.
                    if (_selOverrideEnabled)
                    {
                        if (btn.ClassListContains("asset-has-update")) gradientOverlay.style.unityBackgroundImageTintColor = _updateBtnColor;
                        else if (btn.ClassListContains("asset-installed")) gradientOverlay.style.unityBackgroundImageTintColor = _installedBtnColor;
                        else gradientOverlay.style.unityBackgroundImageTintColor = themeColor;
                    }
                    typeLabel.style.color = isOwned ? textColor : _notOwnedTypeTextColor;
                    nameLabel.style.color = isOwned ? Color.white : _notOwnedNameTextColor;
                    // Turn off the selected-shadow overlay.
                    if (selectedShadow != null) selectedShadow.style.display = DisplayStyle.None;
                    // Restore download button to correct color for current state
                    if (isOwned)
                    {
                        downloadBtn.style.unityBackgroundImageTintColor = downloadBtnColorRef[0];
                        downloadIcon.style.unityBackgroundImageTintColor = downloadIconColorRef[0];
                        gradientOverlay.style.unityBackgroundImageTintColor = downloadBtnColorRef[0];
                        if (btn.ClassListContains("asset-installed") && _installedIcon != null)
