            setSelectedRef[0] = setSelected;
            
            System.Func<bool> getSelected = () => isSelected;
            
            // Owned state setter
            System.Action<bool> setOwned = (owned) =>
            {
                isOwned = owned;
                
                // Show type background only when owned
                var typeBgEl = btn.Q<VisualElement>("asset-type-bg");
                if (typeBgEl != null)
                    typeBgEl.style.display = owned ? DisplayStyle.Flex : DisplayStyle.None;
                
                // Update sale badge visibility — hidden when owned or when Synty Pass is on
                var saleBadge = hitArea.Q<VisualElement>("sale-badge");
                if (saleBadge == null) saleBadge = btn.Q<VisualElement>("sale-badge");
                if (saleBadge != null)
                {
                    saleBadge.style.display = (!owned && !_licenseSyntyPass && _showSaleBadges) ? DisplayStyle.Flex : DisplayStyle.None;
                    // Offset sale badge down if installed badge is also showing
                    bool hasInstalledBadge = btn.Q<Label>("installed-badge") != null;
                    saleBadge.style.top = _saleBadgeY + (hasInstalledBadge ? _saleBadgeInstalledOffsetY : 0f);
                    saleBadge.style.right = _saleBadgeX + (hasInstalledBadge ? _saleBadgeInstalledOffsetX : 0f);
                }
                
                // Sale amount image mirrors the sale badge's visibility
                var saleAmountEl = hitArea.Q<VisualElement>("sale-amount") ?? btn.Q<VisualElement>("sale-amount");
                if (saleAmountEl != null)
                    saleAmountEl.style.display = (!owned && !_licenseSyntyPass && _showSaleAmount) ? DisplayStyle.Flex : DisplayStyle.None;
                
                if (owned)
                {
                    // Icon color is driven by hover/selected state, not owned state.
                    updateIconColorState();
                    assetIcon.style.unityBackgroundImageTintColor = Color.white;
                    assetIcon.style.opacity = 1f;
                    gradientOverlay.style.display = DisplayStyle.Flex;
                    downloadBtn.style.display = DisplayStyle.Flex;
                    cartBtn.style.display = DisplayStyle.None;
                    // Update gradient and download button color based on state
                    if (_debugDownloadState == 1) // Installed
                    {
                        gradientOverlay.style.unityBackgroundImageTintColor = _installedBtnColor;
                        downloadBtn.style.unityBackgroundImageTintColor = _installedBtnColor;
                    }
                    else if (_debugDownloadState == 2) // Update
                    {
                        gradientOverlay.style.unityBackgroundImageTintColor = _updateBtnColor;
                        downloadBtn.style.unityBackgroundImageTintColor = _updateBtnColor;
                    }
                    else // Download (0)
                    {
                        gradientOverlay.style.unityBackgroundImageTintColor = themeColor;
                        downloadBtn.style.unityBackgroundImageTintColor = _downloadBtnWhiteBg ? new Color(0.094f, 0.078f, 0.145f, 1f) : themeColor;
                    }
                    // Restore text colors — textColor is black for Interface/Polygon, white for others
                    typeLabel.style.color = textColor;
                    nameLabel.style.color = Color.white;
                    // Restore link cursor (clear inline style to use USS default)
                    hitArea.style.cursor = StyleKeyword.Null;
                    // Hide colored overlay when owned
                    coloredOverlay.style.opacity = 0f;
                    // Hide sale overlay when asset is owned (sale blue only shows when not owned)
                    // But show green overlay if installed
                    if (!isSelected)
                    {
                        if (btn.ClassListContains("asset-has-update"))
                        {
                            selectedOverlay.style.unityBackgroundImageTintColor = _updateBtnColor;
                            selectedOverlay.style.opacity = 1;
                        }
                        else if (btn.ClassListContains("asset-installed"))
                        {
                            selectedOverlay.style.unityBackgroundImageTintColor = _installedBtnColor;
                            selectedOverlay.style.opacity = 1;
                        }
                        else
