                    }
                }
                else
                {
                    // Icon color is driven by hover/selected state, not owned state.
                    // updateIconColorState also applies the not-owned tint to the desaturated icon.
                    updateIconColorState();
                    assetIcon.style.opacity = 1f;
                    gradientOverlay.style.display = DisplayStyle.Flex;
                    gradientOverlay.style.unityBackgroundImageTintColor = 
                        (isOnSale && _showSaleBadges) ? _saleGradientColor : _cartBtnColor;
                    downloadBtn.style.display = DisplayStyle.None;
                    cartBtn.style.display = DisplayStyle.Flex;
                    typeLabel.style.color = _notOwnedTypeTextColor;
                    nameLabel.style.color = _notOwnedNameTextColor;
                    hitArea.style.cursor = StyleKeyword.Null;
                    coloredOverlay.style.opacity = (isOnSale && _saleColorOverlayOpacity > 0f) ? _saleColorOverlayOpacity : 0f;
                    // Show sale overlay in blue when not owned and on sale
                    if (isOnSale && !isSelected)
