            System.Func<bool> getOwned = () => isOwned;
            
            // Price tooltip — always created, shown on hover only when not owned
            {
                float tooltipGap = _tooltipSaleOffsetY;
                float tooltipTop  = isOnSale ? (_tooltipSaleY != 0f ? _tooltipSaleY : _saleBadgeY + _saleBadgeHeight + tooltipGap) : _tooltipNoSaleY;
                float tooltipRight = isOnSale ? _tooltipSaleX : _tooltipNoSaleX;
                Color tooltipBg   = isOnSale ? _tooltipSaleBgColor   : _tooltipBgColor;
                Color tooltipText = isOnSale ? _tooltipSaleTextColor  : _tooltipTextColor;
                
                var priceTooltip = new VisualElement();
                priceTooltip.name = "price-tooltip";
                priceTooltip.style.position = Position.Absolute;
                priceTooltip.style.top = tooltipTop;
                priceTooltip.style.right = tooltipRight;
                priceTooltip.style.paddingLeft = 8;
                priceTooltip.style.paddingRight = 8;
                priceTooltip.style.paddingTop = 4;
                priceTooltip.style.paddingBottom = 4;
                priceTooltip.style.backgroundColor = tooltipBg;
                priceTooltip.style.borderTopLeftRadius = 4;
                priceTooltip.style.borderTopRightRadius = 4;
                priceTooltip.style.borderBottomLeftRadius = 4;
                priceTooltip.style.borderBottomRightRadius = 4;
                priceTooltip.style.display = DisplayStyle.None;
                priceTooltip.pickingMode = PickingMode.Ignore;
                
                var priceLabel = new Label(price > 0f ? SyntyCurrency.Format(price) : "FREE");
                if (price > 0f) { _priceLabelUsd[priceLabel] = price; _priceLabelHasCode[priceLabel] = true; }
                priceLabel.style.color = tooltipText;
                priceLabel.style.fontSize = _tooltipFontSize;
                priceLabel.style.unityFontStyleAndWeight = _tooltipBold ? FontStyle.Bold : FontStyle.Normal;
                priceLabel.style.unityTextAlign = TextAnchor.MiddleCenter;
                priceLabel.pickingMode = PickingMode.Ignore;
                
                // Show compare-at price with strikethrough when on sale
                if (!string.IsNullOrEmpty(compareAtPrice) && price > 0f)
                {
                    float cap;
                    float.TryParse(compareAtPrice, System.Globalization.NumberStyles.Float, 
                        System.Globalization.CultureInfo.InvariantCulture, out cap);
                    if (cap > 0f)
                    {
                        float saleFontSize = _salePriceFontSize > 0f ? _salePriceFontSize : _tooltipFontSize;
                        
                        priceTooltip.style.flexDirection = FlexDirection.Column;
                        priceTooltip.style.alignItems = Align.Center;
                        
                        // Original price with strikethrough (top line)
                        var origContainer = new VisualElement();
                        origContainer.style.position = Position.Relative;
                        origContainer.style.alignSelf = Align.Center;
                        origContainer.pickingMode = PickingMode.Ignore;
                        
                        var origLabel = new Label(SyntyCurrency.Format(cap, false));
                        _priceLabelUsd[origLabel] = cap; _priceLabelHasCode[origLabel] = false;
                        origLabel.style.color = _saleOriginalPriceColor;
                        origLabel.style.fontSize = saleFontSize;
                        origLabel.style.unityTextAlign = TextAnchor.MiddleCenter;
                        origLabel.pickingMode = PickingMode.Ignore;
                        origContainer.Add(origLabel);
                        
                        // Strikethrough line
                        var strikeLine = new VisualElement();
                        strikeLine.style.position = Position.Absolute;
                        strikeLine.style.top = Length.Percent(50);
                        strikeLine.style.left = 0;
                        strikeLine.style.right = 0;
                        strikeLine.style.height = 1;
                        strikeLine.style.backgroundColor = _saleStrikeColor;
                        strikeLine.pickingMode = PickingMode.Ignore;
                        origContainer.Add(strikeLine);
                        
                        priceTooltip.Add(origContainer);
                        
                        // Sale price (bottom line)
                        priceLabel.text = SyntyCurrency.Format(price);
                        priceLabel.style.color = _salePriceColor;
                        priceLabel.style.fontSize = saleFontSize;
                        priceLabel.style.unityFontStyleAndWeight = _salePriceBold ? FontStyle.Bold : FontStyle.Normal;
                    }
                }
                priceTooltip.Add(priceLabel);
                hitArea.Add(priceTooltip);
                
                hitArea.RegisterCallback<MouseEnterEvent>(evt => {
                    if (!isOwned && _showPrices)
                    {
                        // Adjust position if installed badge is present
                        bool hasInstalledBadge = btn.Q<Label>("installed-badge") != null;
                        float offset = hasInstalledBadge ? _salePriceInstalledOffsetY : 0f;
                        float offsetX = hasInstalledBadge ? _salePriceInstalledOffsetX : 0f;
                        float top = isOnSale ? (_tooltipSaleY != 0f ? _tooltipSaleY + offset : _saleBadgeY + offset + _saleBadgeHeight + _tooltipSaleOffsetY) : _tooltipNoSaleY;
                        priceTooltip.style.top = top;
                        priceTooltip.style.right = (isOnSale ? _tooltipSaleX : _tooltipNoSaleX) + offsetX;
                        priceTooltip.style.display = DisplayStyle.Flex;
                    }
                });
                hitArea.RegisterCallback<MouseLeaveEvent>(evt => {
                    priceTooltip.style.display = DisplayStyle.None;
                });
            }
            
            // Apply initial owned state — sets badge, icon, gradient, buttons correctly
            if (!initiallyOwned)
                setOwned(false);
            
            // Selected-shadow overlay: fills the tile (inside the clipped visual container).
            // Added last + brought to front so it renders above the gradient, icon, type-bg,
            // buttons and labels. The four elements below are then brought back above it.
            selectedShadow = new VisualElement();
            selectedShadow.name = "asset-selected-shadow";
            selectedShadow.pickingMode = PickingMode.Ignore;
            selectedShadow.style.position = Position.Absolute;
            selectedShadow.style.left = 0;
            selectedShadow.style.top = 0;
            selectedShadow.style.right = 0;
            selectedShadow.style.bottom = 0;
            selectedShadow.style.SetBackgroundStretchToFill();
            selectedShadow.style.unityBackgroundImageTintColor = Color.white; // render image as-is
            var selShadowTex = LoadImage("Assets", "Asset_Shadow_Selected");
            if (selShadowTex != null)
                selectedShadow.style.backgroundImage = new StyleBackground(selShadowTex);
            selectedShadow.style.display = DisplayStyle.None;
            btn.Add(selectedShadow);
            // Hover/selection visual on top: the selected overlay (Asset_Selected outline) is shown
            // on hover and when selected. Bring it to the front so the hover outline always renders
            // above the card's other layers (type bar, labels, buttons). It's pickingMode Ignore, so
            // sitting on top doesn't block clicks on the action buttons.
            selectedOverlay.BringToFront();
            
            // Keep these above the shadow (children of btn, brought to front in add-order):
            // product link, new badge, sale badge. The price tooltip + sale amount live on the
            // unclipped hitArea (a different parent), so they are already above btn's children.
            btn.Q<VisualElement>("product-btn")?.BringToFront();
            btn.Q<VisualElement>("new-badge")?.BringToFront();
            btn.Q<VisualElement>("sale-badge")?.BringToFront();
            
            return (hitArea, setSelected, getSelected, setOwned, getOwned);
        }
        
        // Get theme color and text color based on asset type
        private (Color themeColor, Color textColor) GetAssetTypeColors(string assetType)
        {
            switch (assetType.ToUpper())
            {
                case "POLYGON":
                    return (_polygonColor, Color.black); // yellow, black text
                case "INTERFACE":
                    return (_interfaceColor, Color.black); // cyan, black text
                case "ANIMATION":
                    return (_animationColor, Color.black); // purple, black text
                case "SIMPLE":
                    return (_simpleColor, Color.white); // pink, white text
                case "SIDEKICK":
                default:
                    return (_sidekickColor, Color.white); // red, white text
            }
        }
        
        // Get filter button colors based on asset type (ON bg, OFF bg, ON text, OFF text)
        private (Color onBg, Color offBg, Color onText, Color offText) GetAssetFilterColors(string assetType)
        {
            switch (assetType.ToUpper())
            {
                case "POLYGON":
                    return (_polygonColor, _polygonOffBgColor, _polygonOnTextColor, _polygonOffTextColor);
                case "INTERFACE":
                    return (_interfaceColor, _interfaceOffBgColor, _interfaceOnTextColor, _interfaceOffTextColor);
                case "ANIMATION":
                    return (_animationColor, _animationOffBgColor, _animationOnTextColor, _animationOffTextColor);
                case "SIMPLE":
                    return (_simpleColor, _simpleOffBgColor, _simpleOnTextColor, _simpleOffTextColor);
                case "SIDEKICK":
                default:
                    return (_sidekickColor, _sidekickOffBgColor, _sidekickOnTextColor, _sidekickOffTextColor);
            }
        }
        
        private string GetAssetIconName(string assetType)
        {
            switch (assetType.ToUpper())
            {
                case "INTERFACE":
                    return "Asset_Image_Interface";
                case "POLYGON":
                    return "Asset_Image_ScifiHorror";
                case "ANIMATION":
                case "SIMPLE":
                case "SIDEKICK":
                default:
                    return "Asset_Icon";
            }
        }
        
        private void AddOptionsPanel(VisualElement parent)
        {
            _optionsPanel = new VisualElement();
            _optionsPanel.name = "options-panel";
            _optionsPanel.style.width = _optionsPanelWidth;
            _optionsPanel.style.backgroundColor = new Color(0.15f, 0.15f, 0.15f, 1f);
            _optionsPanel.style.flexShrink = 0;
            _optionsPanel.style.overflow = Overflow.Hidden;
            _optionsPanel.style.display = _optionsPanelVisible ? DisplayStyle.Flex : DisplayStyle.None;
            parent.Add(_optionsPanel);
            
            // Scrollable content
            var scrollView = new ScrollView(ScrollViewMode.Vertical);
            scrollView.style.flexGrow = 1;
            scrollView.horizontalScrollerVisibility = ScrollerVisibility.Hidden;
            _optionsPanel.Add(scrollView);
            
            var optionsContent = new VisualElement();
            optionsContent.style.paddingLeft = 6;
            optionsContent.style.paddingRight = 6;
            optionsContent.style.paddingTop = 6;
            optionsContent.style.paddingBottom = 6;
            optionsContent.style.overflow = Overflow.Hidden;
            scrollView.Add(optionsContent);
            
            // Title
            var title = new Label("VISUAL OPTIONS");
            title.style.fontSize = 12;
            title.style.unityFontStyleAndWeight = FontStyle.Bold;
            title.style.color = Color.white;
            title.style.marginBottom = 6;
            title.style.unityTextAlign = TextAnchor.MiddleCenter;
            optionsContent.Add(title);
            
            // === ELEMENT VISIBILITY (Debug) ===
            AddOptionsFoldout(optionsContent, "[Window]", foldout => {
                AddSliderOption(foldout, "Min Width", 400f, 1600f, _minWidthNoOptions, v => {
                    _minWidthNoOptions = v;
                    // Apply immediately to the live window minimum (only meaningful when the
                    // options panel is closed; ApplyOptionsPanelState recomputes either way).
                    if (!_optionsPanelVisible) minSize = new Vector2(_minWidthNoOptions, _minHeight);
                });
                AddSliderOption(foldout, "Min Height", 300f, 1600f, _minHeight, v => {
                    _minHeight = v;
                    var ms = minSize; ms.y = _minHeight; minSize = ms;
                });
                // Live readout of the window's actual current size, updated ~3x/sec so it
                // tracks as the user resizes the window by hand.
                var curSizeLabel = new Label();
                curSizeLabel.style.fontSize = 11;
                curSizeLabel.style.color = new Color(0.7f, 0.7f, 0.7f, 1f);
                curSizeLabel.style.marginTop = 4;
                curSizeLabel.style.marginLeft = 4;
                curSizeLabel.style.whiteSpace = WhiteSpace.NoWrap;
                foldout.Add(curSizeLabel);
                IVisualElementScheduledItem sizeTask = null;
                sizeTask = curSizeLabel.schedule.Execute(() =>
                {
                    if (_reloadingDomain || curSizeLabel.panel == null) { SafePause(sizeTask); return; }
                    var p = position;
                    curSizeLabel.text = $"Current: {Mathf.Round(p.width)} x {Mathf.Round(p.height)}";
                }).Every(300);
                TrackScheduledItem(sizeTask);
            }, GetWindowSettings);
            
            AddOptionsFoldout(optionsContent, "[Toolbar]", foldout => {
                AddToggleOption(foldout, "Notifications", _hasNotifications, v => {
                    _hasNotifications = v;
                    SaveFilterStates();
                    SyntyToolbarButton.SetNotifications(v);
                });
                AddTextOption(foldout, "Label", SyntyToolbarButton.LabelText, v => {
                    ApplyToolbarSettings(label: v);
                });
                AddSliderOption(foldout, "Font Size", 8f, 20f, SyntyToolbarButton.FontSize, v => {
                    ApplyToolbarSettings(fontSize: v);
                });
                AddSliderOption(foldout, "Height", 14f, 40f, SyntyToolbarButton.BtnHeight, v => {
                    ApplyToolbarSettings(height: v);
                });
                AddSliderOption(foldout, "Radius", 0f, 20f, SyntyToolbarButton.BorderRadius, v => {
                    ApplyToolbarSettings(radius: v);
                });
                AddSliderOption(foldout, "Padding H", 0f, 30f, SyntyToolbarButton.PaddingH, v => {
                    ApplyToolbarSettings(paddingH: v);
                });
                AddSliderOption(foldout, "Badge Size", 4f, 20f, SyntyToolbarButton.BadgeSize, v => {
                    ApplyToolbarSettings(badgeSize: v);
                });
                AddToggleOption(foldout, "Show Icon", SyntyToolbarButton.ShowIcon, v => {
                    ApplyToolbarSettings(showIcon: v);
                });
                AddSliderOption(foldout, "Icon Size", 8f, 40f, SyntyToolbarButton.IconSize, v => {
                    ApplyToolbarSettings(iconSize: v);
                });
                AddSliderOption(foldout, "Icon X", -20f, 20f, SyntyToolbarButton.IconX, v => {
                    ApplyToolbarSettings(iconX: v);
                });
                AddSliderOption(foldout, "Label X", -20f, 20f, SyntyToolbarButton.LabelX, v => {
                    ApplyToolbarSettings(labelX: v);
                });
                AddColorOption(foldout, "Bg", SyntyToolbarButton.DefaultBgColor, v => {
                    ApplyToolbarSettings(defaultBg: v);
                });
                AddColorOption(foldout, "Hover", SyntyToolbarButton.DefaultHoverColor, v => {
                    ApplyToolbarSettings(defaultHover: v);
                });
                AddColorOption(foldout, "Press", SyntyToolbarButton.DefaultPressColor, v => {
                    ApplyToolbarSettings(defaultPress: v);
                });
                AddColorOption(foldout, "Text", SyntyToolbarButton.DefaultTextColor, v => {
                    ApplyToolbarSettings(defaultText: v);
                });
                AddColorOption(foldout, "Notif Bg", SyntyToolbarButton.NotifBgColor, v => {
                    ApplyToolbarSettings(notifBg: v);
                });
                AddColorOption(foldout, "Notif Hover", SyntyToolbarButton.NotifHoverColor, v => {
                    ApplyToolbarSettings(notifHover: v);
                });
                AddColorOption(foldout, "Notif Press", SyntyToolbarButton.NotifPressColor, v => {
                    ApplyToolbarSettings(notifPress: v);
                });
                AddColorOption(foldout, "Notif Text", SyntyToolbarButton.NotifTextColor, v => {
                    ApplyToolbarSettings(notifText: v);
                });
                AddColorOption(foldout, "Badge", SyntyToolbarButton.BadgeColor, v => {
                    ApplyToolbarSettings(badge: v);
                });
            }, () => $"--- TOOLBAR ---\nNotifications: {_hasNotifications}\n" + GetToolbarButtonSettings());
            
            AddOptionsFoldout(optionsContent, "[Bg Gradient]", foldout => {
                AddSliderOption(foldout, "X", -500f, 500f, _bgGradientX, v => {
                    _bgGradientX = v;
                    if (_bgGradient != null) _bgGradient.style.marginLeft = v;
                });
                AddSliderOption(foldout, "Y", -500f, 500f, _bgGradientY, v => {
                    _bgGradientY = v;
                    if (_bgGradient != null) _bgGradient.style.marginTop = v;
                });
                AddSliderOption(foldout, "Scale X", 0.1f, 3f, _bgGradientScaleX, v => {
                    _bgGradientScaleX = v;
                    if (_bgGradient != null) _bgGradient.style.scale = new Scale(new Vector3(_bgGradientScaleX, _bgGradientScaleY, 1f));
                });
                AddSliderOption(foldout, "Scale Y", 0.1f, 3f, _bgGradientScaleY, v => {
                    _bgGradientScaleY = v;
                    if (_bgGradient != null) _bgGradient.style.scale = new Scale(new Vector3(_bgGradientScaleX, _bgGradientScaleY, 1f));
                });
                AddSliderOption(foldout, "Ease ms", 100f, 2000f, _bgGradientEaseMs, v => {
                    _bgGradientEaseMs = v;
                    if (_bgGradient != null)
                    {
                        _bgGradient.style.transitionDuration = new List<TimeValue> {
                            new TimeValue((int)v, TimeUnit.Millisecond),
                            new TimeValue((int)v, TimeUnit.Millisecond)
                        };
                    }
                });
                // ON state (Synty Pass active)
                AddColorOption(foldout, "ON Color", _bgGradientOnColor, v => {
                    _bgGradientOnColor = v;
                    if (_licenseSyntyPass) SetBgGradientState(v, _bgGradientOnOpacity);
                });
                AddSliderOption(foldout, "ON Opacity", 0f, 1f, _bgGradientOnOpacity, v => {
                    _bgGradientOnOpacity = v;
                    if (_licenseSyntyPass) SetBgGradientState(_bgGradientOnColor, v);
                });
                // OFF state (Synty Pass inactive)
                AddColorOption(foldout, "OFF Color", _bgGradientOffColor, v => {
                    _bgGradientOffColor = v;
                    if (!_licenseSyntyPass) SetBgGradientState(v, _bgGradientOffOpacity);
                });
                AddSliderOption(foldout, "OFF Opacity", 0f, 1f, _bgGradientOffOpacity, v => {
                    _bgGradientOffOpacity = v;
                    if (!_licenseSyntyPass) SetBgGradientState(_bgGradientOffColor, v);
                });
                // 100% celebration state
                AddColorOption(foldout, "100% Color", _bgGradient100Color, v => {
                    _bgGradient100Color = v;
                });
                AddSliderOption(foldout, "100% Opacity", 0f, 1f, _bgGradient100Opacity, v => {
                    _bgGradient100Opacity = v;
                });
                AddSliderOption(foldout, "100% Scale Y", 0.1f, 1.5f, _bgGradient100ScaleY, v => {
                    _bgGradient100ScaleY = v;
                });
                AddSliderOption(foldout, "100% Pop ms", 100f, 2000f, _bgGradient100PopMs, v => {
                    _bgGradient100PopMs = v;
                });
                AddSliderOption(foldout, "100% Return ms", 100f, 2000f, _bgGradient100ReturnMs, v => {
                    _bgGradient100ReturnMs = v;
                });
            }, GetBgGradientSettings);
            
            AddOptionsFoldout(optionsContent, "[Visibility]", foldout => {
                AddToggleOption(foldout, "Corner TL", true, v => SetFrameElementVisible("corner-tl", v));
                AddToggleOption(foldout, "Corner TR", true, v => SetFrameElementVisible("corner-tr", v));
                AddToggleOption(foldout, "Corner BL", true, v => SetFrameElementVisible("corner-bl", v));
                AddToggleOption(foldout, "Corner BR", true, v => SetFrameElementVisible("corner-br", v));
                AddToggleOption(foldout, "Edge Top", true, v => SetFrameElementVisible("edge-top", v));
                AddToggleOption(foldout, "Edge Bottom", true, v => SetFrameElementVisible("edge-bottom", v));
                AddToggleOption(foldout, "Edge Left", true, v => SetFrameElementVisible("edge-left", v));
                AddToggleOption(foldout, "Edge Right", true, v => SetFrameElementVisible("edge-right", v));
                AddToggleOption(foldout, "Center Fill", true, v => SetFrameElementVisible("center-fill", v));
                AddToggleOption(foldout, "Bg Gradient", true, v => {
                    if (_bgGradient != null) _bgGradient.style.display = v ? DisplayStyle.Flex : DisplayStyle.None;
                });
                AddToggleOption(foldout, "Banner", true, v => SetElementVisible("banner-button", v));
                AddToggleOption(foldout, "Logo", true, v => SetElementVisible("logo", v));
                AddToggleOption(foldout, "Filters", true, v => SetElementVisible("filter-section", v));
                AddToggleOption(foldout, "Collection", true, v => SetElementVisible("collection-section", v));
                AddToggleOption(foldout, "Asset Options", true, v => SetElementVisible("asset-options-section", v));
                AddToggleOption(foldout, "Asset Grid", true, v => SetElementVisible("asset-scroll", v));
            }, () => "--- VISIBILITY ---\n(Toggle states not persisted)");
            
            // === DEBUG / TESTING ===
            AddOptionsFoldout(optionsContent, "[Debug]", foldout => {
                AddToggleOption(foldout, "Show Sale Badges", _showSaleBadges, v => {
                    _showSaleBadges = v;
                    UpdateSaleBadgeVisibility();
                });
                
                AddToggleOption(foldout, "Show Prices", _showPrices, v => {
                    _showPrices = v;
                    // Hide any currently-visible price tooltips immediately
                    foreach (var item in _assetItems)
                    {
                        var tooltip = item.button.Q("price-tooltip");
                        if (tooltip != null && !v) tooltip.style.display = DisplayStyle.None;
                    }
                });
                
                // Download button state dropdown
                var stateLabel = new Label("Download Btn State");
                stateLabel.style.color = Color.white;
                stateLabel.style.marginTop = 5;
                stateLabel.style.marginBottom = 2;
                foldout.Add(stateLabel);
                
                var stateDropdown = new DropdownField(new List<string> { "Download", "Installed", "Update" }, _debugDownloadState);
                stateDropdown.AddToClassList("debug-dropdown");
                stateDropdown.RegisterValueChangedCallback(evt => {
                    _debugDownloadState = stateDropdown.index;
                    // Deselect all buttons when transitioning to Installed or Update state
                    if (_debugDownloadState == 1 || _debugDownloadState == 2)
                    {
                        foreach (var item in _assetItems)
                            if (item.getSelected()) item.setSelected(false);
                        UpdateDownloadBar();
                        FilterAssets();
                    }
                    UpdateDownloadButtonStates();
                });
                foldout.Add(stateDropdown);
                
                // Installed button color
                AddColorOption(foldout, "Installed Color", _installedBtnColor, v => { _installedBtnColor = v; UpdateDownloadButtonStates(); });
                
                // Update button color
                AddColorOption(foldout, "Update Color", _updateBtnColor, v => { _updateBtnColor = v; UpdateDownloadButtonStates(); });
                
                // Update button pop animation
                AddSliderOption(foldout, "Pop Scale", 1.0f, 1.5f, _updateBtnPopScale, v => _updateBtnPopScale = v);
                AddSliderOption(foldout, "Pop Duration", 0f, 1f, _updateBtnPopDuration, v => _updateBtnPopDuration = v);
                AddSliderOption(foldout, "Pop Return", 0f, 1.5f, _updateBtnPopReturnDuration, v => _updateBtnPopReturnDuration = v);
                AddToggleOption(foldout, "Pop Loop", _updateBtnPopLoop, v => _updateBtnPopLoop = v);
                AddSliderOption(foldout, "Pop Loop Delay", 0f, 5f, _updateBtnPopLoopDelay, v => _updateBtnPopLoopDelay = v);
                
                // NotOwned button color (grey)
                AddColorOption(foldout, "NotOwned Color", _notOwnedBtnColor, v => { _notOwnedBtnColor = v; UpdateNotOwnedButtonColors(); });
                
                // White download button background
                AddToggleOption(foldout, "Dark Btn Bg", _downloadBtnWhiteBg, v => { _downloadBtnWhiteBg = v; var r = rootVisualElement; r.Clear(); if (_styleSheet != null) r.styleSheets.Add(_styleSheet); BuildUI(r); });
                
                // Cart button color (blue)
                AddColorOption(foldout, "Cart Color", _cartBtnColor, v => { _cartBtnColor = v; UpdateCartButtonColors(); });
                
                AddToggleOption(foldout, "Set Random Assets Not Owned", false, value => {
                    if (value)
                    {
                        var random = new System.Random();
                        var indices = Enumerable.Range(0, _assetItems.Count).OrderBy(x => random.Next()).Take(_assetItems.Count / 2).ToList();
                        for (int i = 0; i < _assetItems.Count; i++)
                            _assetItems[i].setOwned(!indices.Contains(i));
                    }
                    else
                    {
                        foreach (var item in _assetItems)
                            item.setOwned(true);
                    }
                    UpdateCollectionCounts();
                    UpdateDownloadBar();
                });
                
                // Debug: Add one random asset as owned
                var addOwnedBtn = new Button(() => {
                    var notOwned = _assetItems.Where(item => !item.getOwned()).ToList();
                    if (notOwned.Count == 0) { return; }
                    var rng = new System.Random();
                    var pick = notOwned[rng.Next(notOwned.Count)];
                    pick.setOwned(true);
                    UpdateCollectionCounts();
                    UpdateDownloadBar();
                    FilterAssets();
                });
                addOwnedBtn.text = "Add Random Owned";
                addOwnedBtn.style.marginTop = 8;
                addOwnedBtn.style.backgroundColor = new Color(0.17f, 0.53f, 0.36f, 1f);
                addOwnedBtn.style.color = Color.white;
                addOwnedBtn.style.borderTopWidth = 0; addOwnedBtn.style.borderBottomWidth = 0;
                addOwnedBtn.style.borderLeftWidth = 0; addOwnedBtn.style.borderRightWidth = 0;
                addOwnedBtn.style.borderTopLeftRadius = 4; addOwnedBtn.style.borderTopRightRadius = 4;
                addOwnedBtn.style.borderBottomLeftRadius = 4; addOwnedBtn.style.borderBottomRightRadius = 4;
                foldout.Add(addOwnedBtn);
                
                // Debug: Remove all owned
                var clearOwnedBtn = new Button(() => {
                    foreach (var item in _assetItems) item.setOwned(false);
                    UpdateCollectionCounts();
                    UpdateDownloadBar();
                    FilterAssets();
                });
                clearOwnedBtn.text = "Clear All Owned";
                clearOwnedBtn.style.marginTop = 4;
                clearOwnedBtn.style.backgroundColor = new Color(0.5f, 0.15f, 0.15f, 1f);
                clearOwnedBtn.style.color = Color.white;
                clearOwnedBtn.style.borderTopWidth = 0; clearOwnedBtn.style.borderBottomWidth = 0;
                clearOwnedBtn.style.borderLeftWidth = 0; clearOwnedBtn.style.borderRightWidth = 0;
                clearOwnedBtn.style.borderTopLeftRadius = 4; clearOwnedBtn.style.borderTopRightRadius = 4;
                clearOwnedBtn.style.borderBottomLeftRadius = 4; clearOwnedBtn.style.borderBottomRightRadius = 4;
                foldout.Add(clearOwnedBtn);
            }, GetDebugSettings);
            
            // === BANNER ===
            AddOptionsFoldout(optionsContent, "[Banner]", foldout => {
                AddColorOption(foldout, "Tint Color", _bannerTintColor, v => { 
                    _bannerTintColor = v; 
                    // "Banner Tint" recolors the banner art itself (left/center/right images).
                    ApplyBannerTintToElements();
                });
                AddSliderOption(foldout, "Height", 30f, 80f, _bannerHeight, v => { _bannerHeight = v; UpdateBannerHeight(); });
                AddSliderOption(foldout, "Left Gap", 100f, 200f, _bannerLeftGap, v => { _bannerLeftGap = v; if (_bannerButton != null) _bannerButton.style.left = v; });
                AddSliderOption(foldout, "Right Gap", 20f, 80f, _bannerRightGap, v => { _bannerRightGap = v; if (_bannerButton != null) _bannerButton.style.right = v; });
                // Per-element show/hide toggles (all on by default).
                AddToggleOption(foldout, "Show Background", false, v => {
                    _bannerShowBackground = v;
                    if (_bannerButton != null)
                        _bannerButton.style.backgroundColor = v ? _bannerTintColor : Color.clear;
                });
                AddToggleOption(foldout, "Show Left Image", true, v => SetElementVisible("banner-left", v));
                AddToggleOption(foldout, "Show Center Image", true, v => SetElementVisible("banner-center", v));
                AddToggleOption(foldout, "Show Right Image", true, v => SetElementVisible("banner-right", v));
                AddToggleOption(foldout, "Show Right Overlay", true, v => SetElementVisible("banner-overlay-right", v));
                AddToggleOption(foldout, "Show Line 1 Text", true, v => SetElementVisible("banner-text-container", v));
                AddToggleOption(foldout, "Show Shop-Now Pill", true, v => SetElementVisible("shop-now-container", v));
                AddToggleOption(foldout, "Show Line 2 Text", true, v => SetElementVisible("banner-subtitle", v));
                AddToggleOption(foldout, "Show Icon", true, v => SetElementVisible("shop-now-icon", v));
            }, GetBannerSettings);
            
            // === BANNER TEXT ===
            AddOptionsFoldout(optionsContent, "[Banner Line 1]", foldout => {
                AddTextOption(foldout, "Text", _bannerTitleText, v => { _bannerTitleText = v; if (_bannerTitle != null) _bannerTitle.text = v; });
                AddSliderOption(foldout, "Title Font", 10f, 36f, _bannerTitleFontSize, v => { _bannerTitleFontSize = v; if (_bannerTitle != null) _bannerTitle.style.fontSize = v; });
                AddSliderOption(foldout, "Title X", -200f, 200f, _bannerTitleX, v => { _bannerTitleX = v; if (_bannerTitle != null) _bannerTitle.style.translate = new Translate(v, 0); });
                AddSliderOption(foldout, "Title Y (Top)", 0f, 20f, _bannerTitleY, v => { _bannerTitleY = v; if (_bannerTitle != null) _bannerTitle.style.top = v; });
                AddToggleOption(foldout, "Bold", _bannerLine1Bold, v => { _bannerLine1Bold = v; if (_bannerTitle != null) _bannerTitle.style.unityFontStyleAndWeight = v ? FontStyle.Bold : FontStyle.Normal; });
                AddColorOption(foldout, "Title Color", _bannerTextColor, v => { 
                    _bannerTextColor = v; 
                    if (_bannerTitle != null) _bannerTitle.style.color = v;
                });
            }, GetBannerLine1Settings);
            
            // === BANNER LINE 2 (Shop Now Button) ===
            AddOptionsFoldout(optionsContent, "[Banner Line 2]", foldout => {
                AddTextOption(foldout, "Text", _bannerSubtitleText, v => { _bannerSubtitleText = v; if (_bannerSubtitle != null) _bannerSubtitle.text = v; });
                AddSliderOption(foldout, "Y (Bottom)", -20f, 60f, _shopNowY, v => { _shopNowY = v; if (_shopNowContainer != null) _shopNowContainer.style.bottom = v; });
                AddSliderOption(foldout, "X", -200f, 200f, _shopNowXOffset, v => { _shopNowXOffset = v; if (_shopNowContainer != null) _shopNowContainer.style.marginLeft = v; });
                AddSliderOption(foldout, "Height", 20f, 40f, _shopNowHeight, v => { _shopNowHeight = v; if (_shopNowContainer != null) _shopNowContainer.style.height = v; });
                AddSliderOption(foldout, "Padding H", 4f, 20f, _shopNowPaddingH, v => { 
                    _shopNowPaddingH = v; 
                    if (_shopNowContainer != null) { 
                        _shopNowContainer.style.paddingLeft = v; 
                        _shopNowContainer.style.paddingRight = v - 2; 
                    } 
                });
                AddSliderOption(foldout, "Font Size", 8f, 28f, _bannerSubtitleFontSize, v => { _bannerSubtitleFontSize = v; if (_bannerSubtitle != null) _bannerSubtitle.style.fontSize = v; });
                AddSliderOption(foldout, "Text Y", -10f, 10f, _shopNowTextY, v => { _shopNowTextY = v; if (_bannerSubtitle != null) _bannerSubtitle.style.marginTop = v; });
