        private void AddOptionsFoldout(VisualElement parent, string title, System.Action<VisualElement> addContent, System.Func<string> getSettings = null)
        {
            var foldout = new Foldout();
            foldout.text = title;
            foldout.value = false; // Start collapsed
            foldout.style.marginBottom = 3;
            foldout.style.backgroundColor = new Color(0.2f, 0.2f, 0.2f, 1f);
            foldout.style.borderTopLeftRadius = 3;
            foldout.style.borderTopRightRadius = 3;
            foldout.style.borderBottomLeftRadius = 3;
            foldout.style.borderBottomRightRadius = 3;
            foldout.style.paddingLeft = 2;
            foldout.style.paddingRight = 2;
            foldout.style.paddingTop = 1;
            foldout.style.paddingBottom = 1;
            foldout.style.overflow = Overflow.Hidden;
            
            // Style the toggle label
            var toggle = foldout.Q<Toggle>();
            if (toggle != null)
            {
                var label = toggle.Q<Label>();
                if (label != null) label.style.fontSize = 10;
            }
            
            var content = new VisualElement();
            content.style.paddingLeft = 2;
            content.style.paddingRight = 2;
            content.style.paddingTop = 3;
            content.style.paddingBottom = 3;
            content.style.overflow = Overflow.Hidden;
            foldout.Add(content);
            
            addContent(content);
            
            // Add copy button if getSettings is provided
            if (getSettings != null)
            {
                var copyBtn = new Button(() => {
                    string settings = getSettings();
                    EditorGUIUtility.systemCopyBuffer = settings;
                });
                copyBtn.text = "📋 Copy Settings";
                copyBtn.style.marginTop = 6;
                copyBtn.style.height = 18;
                copyBtn.style.fontSize = 9;
                content.Add(copyBtn);
            }
            
            parent.Add(foldout);
        }
        
        private void ApplyToolbarSettings(
            Color? defaultBg = null, Color? defaultHover = null, Color? defaultPress = null, Color? defaultText = null,
            Color? notifBg = null, Color? notifHover = null, Color? notifPress = null, Color? notifText = null,
            Color? badge = null, string label = null, float? fontSize = null, float? height = null,
            float? radius = null, float? paddingH = null, float? badgeSize = null,
            bool? showIcon = null, float? iconSize = null, float? iconX = null, float? labelX = null)
        {
            SyntyToolbarButton.ApplySettings(
                defaultBg    ?? SyntyToolbarButton.DefaultBgColor,
                defaultHover ?? SyntyToolbarButton.DefaultHoverColor,
                defaultPress ?? SyntyToolbarButton.DefaultPressColor,
                defaultText  ?? SyntyToolbarButton.DefaultTextColor,
                notifBg      ?? SyntyToolbarButton.NotifBgColor,
                notifHover   ?? SyntyToolbarButton.NotifHoverColor,
                notifPress   ?? SyntyToolbarButton.NotifPressColor,
                notifText    ?? SyntyToolbarButton.NotifTextColor,
                badge        ?? SyntyToolbarButton.BadgeColor,
                label        ?? SyntyToolbarButton.LabelText,
                fontSize     ?? SyntyToolbarButton.FontSize,
                height       ?? SyntyToolbarButton.BtnHeight,
                radius       ?? SyntyToolbarButton.BorderRadius,
                paddingH     ?? SyntyToolbarButton.PaddingH,
                badgeSize    ?? SyntyToolbarButton.BadgeSize,
                showIcon     ?? SyntyToolbarButton.ShowIcon,
                iconSize     ?? SyntyToolbarButton.IconSize,
                iconX        ?? SyntyToolbarButton.IconX,
                labelX       ?? SyntyToolbarButton.LabelX
            );
        }
        
        private void AddTextOption(VisualElement parent, string label, string value, System.Action<string> onChange)
        {
            var row = new VisualElement();
            row.style.flexDirection = FlexDirection.Row;
            row.style.alignItems = Align.Center;
            row.style.marginBottom = 2;
            row.style.height = 18;

            var lbl = new Label(label);
            lbl.style.width = 80;
            lbl.style.fontSize = 10;
            lbl.style.color = Color.white;
            lbl.style.unityTextAlign = TextAnchor.MiddleLeft;
            row.Add(lbl);

            var field = new TextField();
            field.value = value;
            field.style.flexGrow = 1;
            field.style.fontSize = 10;
            field.RegisterValueChangedCallback(evt => onChange(evt.newValue));
            row.Add(field);

            parent.Add(row);
        }

        private void AddSliderOption(VisualElement parent, string label, float min, float max, float value, System.Action<float> onChange)
        {
            var row = new VisualElement();
            row.style.flexDirection = FlexDirection.Row;
            row.style.alignItems = Align.Center;
            row.style.marginBottom = 2;
            row.style.height = 20;
            row.style.overflow = Overflow.Hidden;
            row.style.flexShrink = 0;
            
            var lbl = new Label(label);
            lbl.style.width = 80;
            lbl.style.minWidth = 80;
            lbl.style.fontSize = 9;
            lbl.style.color = new Color(0.75f, 0.75f, 0.75f, 1f);
            lbl.style.overflow = Overflow.Hidden;
            lbl.style.textOverflow = TextOverflow.Ellipsis;
            lbl.style.flexShrink = 0;
            row.Add(lbl);
            
            var slider = new Slider(min, max);
            slider.value = value;
            slider.style.flexGrow = 1;
            slider.style.flexShrink = 1;
            slider.style.minWidth = 50;
            slider.style.marginLeft = 4;
            slider.style.marginRight = 4;
            row.Add(slider);
            
            var field = new FloatField();
            field.value = value;
            field.style.width = 50;
            field.style.minWidth = 50;
            field.style.flexShrink = 0;
            field.style.marginRight = 4;
            row.Add(field);
            
            slider.RegisterValueChangedCallback(evt => {
                field.SetValueWithoutNotify(evt.newValue);
                onChange(evt.newValue);
            });
            
            field.RegisterValueChangedCallback(evt => {
                var clamped = Mathf.Clamp(evt.newValue, min, max);
                slider.SetValueWithoutNotify(clamped);
                onChange(clamped);
            });
            
            // One-click copy of the current value to the clipboard.
            var copyBtn = new Button(() => {
                EditorGUIUtility.systemCopyBuffer = field.value.ToString("0.###");
            });
            copyBtn.text = "Copy";
            copyBtn.style.width = 38;
            copyBtn.style.minWidth = 38;
            copyBtn.style.height = 16;
            copyBtn.style.fontSize = 8;
            copyBtn.style.flexShrink = 0;
            copyBtn.style.marginLeft = 0;
            copyBtn.style.marginRight = 0;
            copyBtn.style.marginTop = 0;
            copyBtn.style.marginBottom = 0;
            copyBtn.style.paddingLeft = 2;
            copyBtn.style.paddingRight = 2;
            copyBtn.style.paddingTop = 0;
            copyBtn.style.paddingBottom = 0;
            copyBtn.tooltip = "Copy this value to the clipboard";
            row.Add(copyBtn);
            
            parent.Add(row);
        }
        
        private void AddToggleOption(VisualElement parent, string label, bool value, System.Action<bool> onChange)
        {
            var row = new VisualElement();
            row.style.flexDirection = FlexDirection.Row;
            row.style.alignItems = Align.Center;
            row.style.marginBottom = 2;
            row.style.overflow = Overflow.Hidden;
            row.style.flexShrink = 0;
            
            var toggle = new Toggle(label);
            toggle.value = value;
            toggle.style.flexGrow = 1;
            toggle.style.fontSize = 9;
            toggle.style.marginRight = 4;
            toggle.RegisterValueChangedCallback(evt => onChange(evt.newValue));
            row.Add(toggle);
            
            parent.Add(row);
        }
        
        private void AddTextAreaOption(VisualElement parent, string label, string value, System.Action<string> onChange)
        {
            var lbl = new Label(label);
            lbl.style.fontSize = 9;
            lbl.style.color = new Color(0.75f, 0.75f, 0.75f, 1f);
            lbl.style.marginTop = 4;
            lbl.style.marginBottom = 1;
            parent.Add(lbl);
            
            // Single-line — strip any embedded newlines so old corrupted values don't carry forward
            var cleanValue = value?.Replace("\n", " ").Replace("\r", "") ?? "";
            
            var field = new TextField();
            field.value = cleanValue;
            field.multiline = false;
            field.style.flexGrow = 1;
            field.style.fontSize = 9;
            field.style.marginRight = 4;
            field.style.marginBottom = 2;
            field.RegisterValueChangedCallback(evt => {
                // Strip any newlines that slip through paste
                var clean = evt.newValue?.Replace("\n", " ").Replace("\r", "") ?? "";
                onChange(clean);
            });
            parent.Add(field);
        }
        
        private void AddColorOption(VisualElement parent, string label, Color value, System.Action<Color> onChange)
        {
            var row = new VisualElement();
            row.style.flexDirection = FlexDirection.Row;
            row.style.alignItems = Align.Center;
            row.style.marginBottom = 2;
            row.style.height = 18;
            row.style.overflow = Overflow.Hidden;
            row.style.flexShrink = 0;
            
            var lbl = new Label(label);
            lbl.style.width = 80;
            lbl.style.minWidth = 80;
            lbl.style.fontSize = 9;
            lbl.style.color = new Color(0.75f, 0.75f, 0.75f, 1f);
            lbl.style.overflow = Overflow.Hidden;
            lbl.style.textOverflow = TextOverflow.Ellipsis;
            lbl.style.flexShrink = 0;
            row.Add(lbl);
            
            var colorField = new ColorField();
            colorField.value = value;
            colorField.style.flexGrow = 1;
            colorField.style.flexShrink = 1;
            colorField.style.height = 16;
            colorField.style.marginRight = 4;
            colorField.RegisterValueChangedCallback(evt => onChange(evt.newValue));
            row.Add(colorField);
            
            parent.Add(row);
        }
        
        private string ColorToHex(Color c)
        {
            string hex = $"#{(int)(c.r * 255):X2}{(int)(c.g * 255):X2}{(int)(c.b * 255):X2}";
            if (c.a < 0.999f)
                hex += $"/{c.a:F2}";
            return hex;
        }
        
        /// <summary>
        /// Append UTM tracking parameters to a URL for Shopify/GA attribution.
        /// </summary>
        private static string AppendUtm(string url, string content = null)
        {
            if (string.IsNullOrEmpty(url)) return url;
            string sep = url.Contains("?") ? "&" : "?";
            string utm = $"{sep}utm_source=synty_passport&utm_medium=unity_editor&utm_campaign=passport_v2";
            if (!string.IsNullOrEmpty(content))
                utm += $"&utm_content={content}";
            string sid = SyntyAnalytics.InstallId;
            if (!string.IsNullOrEmpty(sid))
                utm += $"&sid={sid}";
            return url + utm;
        }
        
