        private string GetEmptyStateSettings()
        {
            // Strip embedded newlines — these are single-line messages; newlines are corrupted data
            string S(string s) => s?.Replace("\r\n", " ").Replace("\n", " ").Replace("\r", "").Trim() ?? "";
            var sb = new System.Text.StringBuilder();
            sb.AppendLine("--- EMPTY STATE ---");
            sb.AppendLine($"Horiz Pad: {_emptyStateX}");
            sb.AppendLine($"Y Offset: {_emptyStateY}");
            sb.AppendLine($"Font Size: {_emptyStateFontSize}");
            sb.AppendLine($"Color: {ColorToHex(_emptyStateColor)}");
            sb.AppendLine($"No Filters: {S(_emptyMsgNoFilters)}");
            sb.AppendLine($"No Type+Theme: {S(_emptyMsgNoTypeNoTheme)}");
            sb.AppendLine($"No Type+Lib: {S(_emptyMsgNoTypeNoLib)}");
            sb.AppendLine($"No Theme+Lib: {S(_emptyMsgNoThemeNoLib)}");
            sb.AppendLine($"No Type Only: {S(_emptyMsgNoTypeOnly)}");
            sb.AppendLine($"No Theme Only: {S(_emptyMsgNoThemeOnly)}");
            sb.AppendLine($"No Lib Only: {S(_emptyMsgNoLibOnly)}");
            sb.Append($"No Results: {S(_emptyMsgNoResults)}");
            return sb.ToString();
        }
        
