        private string GetThemeBtnSettings()
        {
            var sb = new System.Text.StringBuilder();
            sb.AppendLine("--- THEME BUTTON ---");
            sb.AppendLine($"ON Bg: {ColorToHex(_themeBtnOnBgColor)}");
            sb.AppendLine($"OFF Bg: {ColorToHex(_themeBtnOffBgColor)}");
            sb.AppendLine($"ON Text: {ColorToHex(_themeBtnOnTextColor)}");
            sb.AppendLine($"OFF Text: {ColorToHex(_themeBtnOffTextColor)}");
            foreach (var (themeName, _) in Themes)
            {
                Color onCol = GetThemeOnColor(themeName);
                Color offCol = GetThemeOffColor(themeName);
                sb.AppendLine($"{themeName} ON: {ColorToHex(onCol)}");
                sb.AppendLine($"{themeName} OFF: {ColorToHex(offCol)}");
            }
            return sb.ToString().TrimEnd();
        }
        
