        // ── Debug: asset counts on filter buttons ──
        private int CountPacks(System.Func<AssetPackData, bool> predicate)
        {
            var packs = SyntyCatalogBridge.LoadedPacks;
            if (packs == null) return 0;
            int n = 0;
            foreach (var p in packs) { try { if (predicate(p)) n++; } catch { } }
            return n;
        }

        private bool IsOwnedPack(AssetPackData p)
        {
            if (p == null) return false;
            var owned = SyntyStoreService.Instance?.OwnedProductHandles;
            if (owned == null) return false;
            if (!string.IsNullOrEmpty(p.packName) && owned.Contains(p.packName)) return true;
            string h = SyntyStoreService.ExtractHandleFromUrl(p.storeUrl);
            return !string.IsNullOrEmpty(h) && owned.Contains(h);
        }

        // Sets a filter button's label to "BaseName (count)" when count >= 0, or just "BaseName" when
        // count < 0 (debug off). The 3-part button background auto-follows the label width.
        private void SetFilterCountLabel(Button btn, string baseName, int count)
        {
            if (btn == null) return;
            var label = btn.Q<Label>(className: "filter-btn-label");
            if (label == null) return;
            label.text = count >= 0 ? $"{baseName} ({count})" : baseName;
        }

        // Re-applies (or removes) the per-filter asset counts across all filter buttons based on the
        // _debugFilterCounts flag. Called when the toggle changes and after the filters are built.
        private void ApplyFilterCounts()
        {
            bool on = _debugFilterCounts;
            // Asset type buttons (keyed by type name).
            foreach (var kv in _assetButtons)
            {
                string type = kv.Key;
                SetFilterCountLabel(kv.Value, type,
                    on ? CountPacks(p => string.Equals(SyntyCatalogBridge.GetAssetType(p), type, System.StringComparison.OrdinalIgnoreCase)) : -1);
            }
            // Theme buttons (keyed by theme name).
            foreach (var kv in _themeButtons)
            {
                string theme = kv.Key;
                SetFilterCountLabel(kv.Value, theme,
                    on ? CountPacks(p => SyntyCatalogBridge.GetThemes(p).Contains(theme)) : -1);
            }
            // Library.
            SetFilterCountLabel(_statsInLibraryBtn, "In Library", on ? CountPacks(IsOwnedPack) : -1);
            SetFilterCountLabel(_statsNotInLibraryBtn, "Not in Library", on ? CountPacks(p => !IsOwnedPack(p)) : -1);
            // Installed.
            SetFilterCountLabel(_installedFilterBtn, "Installed", on ? CountPacks(p => SyntyCatalogBridge.IsInstalled(p)) : -1);
            SetFilterCountLabel(_notInstalledFilterBtn, "Not Installed", on ? CountPacks(p => !SyntyCatalogBridge.IsInstalled(p)) : -1);
        }

