        // Adds a hover visual to the Select All/None buttons matching the filter buttons:
        // lightens the background on mouse-over, and restores the correct state colour on
        // leave (the buttons show an "active" look when their state is already current).
        private void AddSelectBtnHover(Button btn)
        {
            btn.AddToClassList("link-cursor");
            btn.RegisterCallback<MouseEnterEvent>(_ =>
            {
                // Only react when not in the active/disabled state (opacity < 1 means active).
                if (btn.resolvedStyle.opacity >= 0.99f)
                    btn.style.backgroundColor = _selectBtnHoverBg;
            });
            btn.RegisterCallback<MouseLeaveEvent>(_ => UpdateSelectButtonStates());
        }
        
        private void UpdateSelectButtonStates()
        {
            if (_selectAllBtn == null || _selectNoneBtn == null) return;
            
            // Always "on" — don't dim/disable-style these based on whether the action is currently a
            // no-op (All when everything's selected, None when nothing is). Clicking a no-op is harmless.
            _selectAllBtn.style.backgroundColor = _assetOptionsSelectBtnBg;
            _selectAllBtn.style.color = _assetOptionsSelectBtnText;
            _selectAllBtn.style.opacity = 1f;
            
            _selectNoneBtn.style.backgroundColor = _assetOptionsSelectBtnBg;
            _selectNoneBtn.style.color = _assetOptionsSelectBtnText;
            _selectNoneBtn.style.opacity = 1f;
        }
        
        private void UpdateSortDropdownChoices()
        {
            if (_sortDropdown == null) return;
            
            bool hasOnSale = _assetItems.Any(i => i.isOnSale && !i.getOwned());
            bool hasUpdates = _assetItems.Any(i => i.btnVisual?.ClassListContains("asset-has-update") == true);
            bool hasInstalled = _assetItems.Any(i => i.getOwned() && i.btnVisual?.ClassListContains("asset-installed") == true);
            
            var choices = new List<string> { "Release Date" };
            if (hasOnSale) choices.Add("On Sale");
            if (hasUpdates) choices.Add("Updates");
            if (hasInstalled) choices.Add("Installed");
            choices.Add("Name");
            choices.Add("Price (Low to High)");
            choices.Add("Price (High to Low)");
            
            string currentValue = _sortDropdown.value;
            _sortDropdown.choices = choices;
            
            // If current selection is still available, keep it; otherwise reset to Release Date
            if (choices.Contains(currentValue))
                _sortDropdown.value = currentValue;
            else
            {
                _sortDropdown.value = "Release Date";
                _sortMode = 0;
                _sortDirty = true;
            }
        }
        
