        private void UpdateBackgroundFrame()
        {
            // Update all corners and edges with single border scale
            foreach (var border in _frameBorders)
            {
                if (border.name.StartsWith("corner"))
                {
                    // All corners use same size
                    border.style.width = _borderScale;
                    border.style.height = _borderScale;
                }
                else if (border.name == "edge-top" || border.name == "edge-bottom")
                {
                    // Horizontal edges stretch between corners
                    border.style.left = _borderScale;
                    border.style.right = _borderScale;
                    border.style.height = _borderScale;
                }
                else if (border.name == "edge-left" || border.name == "edge-right")
                {
                    // Vertical edges stretch between corners
                    border.style.top = _borderScale;
                    border.style.bottom = _borderScale;
                    border.style.width = _borderScale;
                }
                else if (border.name == "center-fill")
                {
                    // Center fill stretches to fill gap between all edges
                    border.style.top = _borderScale;
                    border.style.bottom = _borderScale;
                    border.style.left = _borderScale;
                    border.style.right = _borderScale;
                }
            }
        }
        
        private void SetFrameElementVisible(string elementName, bool visible)
        {
            foreach (var border in _frameBorders)
            {
                if (border.name == elementName)
                {
                    border.style.display = visible ? DisplayStyle.Flex : DisplayStyle.None;
                    break;
                }
            }
        }
        
        private void SetElementVisible(string elementName, bool visible)
        {
            var element = _mainFrame?.Q(elementName);
            if (element != null)
            {
                element.style.display = visible ? DisplayStyle.Flex : DisplayStyle.None;
            }
        }
        
        private void UpdateAccentColor()
        {
            // Update download bar button (keep the hover tint if currently hovered)
            if (_downloadBarBtn != null && !_downloadBarHovered)
                _downloadBarBtn.style.unityBackgroundImageTintColor = _downloadBarBtnColor;
            
            // Update progress bar fill (when not in Synty Pass mode)
            if (_progressBarFill != null && !_licenseSyntyPass)
            {
                if (_barGradientEnabled)
                    UpdateBarGradientForState(false, false);
                else
                    SetBarFillTint(_progressBarFillLeft, _progressBarFillMid, _progressBarFillRight, _accentColor);
            }
        }
        
