        /// <summary>Creates a 3-part bar fill (left cap / stretch middle / right cap) that avoids
        /// cap distortion. The returned container animates its width; tint is applied to all parts.</summary>
        private (VisualElement container, VisualElement left, VisualElement mid, VisualElement right)
            BuildBarFill(Texture2D capLeft, Texture2D capMid, Texture2D capRight,
                         float widthPercent, Color tint, bool absolutePos)
        {
            var container = new VisualElement();
            container.style.flexDirection = FlexDirection.Row;
            container.style.alignItems = Align.Stretch;
            container.style.width = Length.Percent(widthPercent);
            if (absolutePos)
            {
                container.style.position = Position.Absolute;
                container.style.top = 0; container.style.left = 0; container.style.bottom = 0;
            }
            else
            {
                container.style.height = Length.Percent(100);
            }
            container.pickingMode = PickingMode.Ignore;
            
            // Left cap
            var left = new VisualElement();
            left.style.flexShrink = 0;
            left.style.width = (_progressBarHeight / 2f) * _progressBarCapWidth;
            left.style.marginRight = -1;
            left.style.scale = new Scale(new Vector3(_progressBarCapScaleX, _progressBarCapScaleY, 1f));
            left.style.transformOrigin = new TransformOrigin(Length.Percent(100), Length.Percent(50));
            left.style.SetBackgroundStretchToFill();
            left.style.unityBackgroundImageTintColor = tint;
            if (capLeft != null) left.style.backgroundImage = new StyleBackground(capLeft);
            left.pickingMode = PickingMode.Ignore;
            container.Add(left);
            
            // Middle — stretches
            var mid = new VisualElement();
            mid.style.flexGrow = 1;
            mid.style.flexShrink = 0;
            mid.style.overflow = Overflow.Hidden;
            mid.style.SetBackgroundStretchToFill();
            mid.style.unityBackgroundImageTintColor = tint;
            if (capMid != null) mid.style.backgroundImage = new StyleBackground(capMid);
            mid.pickingMode = PickingMode.Ignore;
            container.Add(mid);
            
            // Right cap
            var right = new VisualElement();
            right.style.flexShrink = 0;
            right.style.width = (_progressBarHeight / 2f) * _progressBarCapWidth;
            right.style.marginLeft = -1;
            right.style.scale = new Scale(new Vector3(_progressBarCapScaleX, _progressBarCapScaleY, 1f));
            right.style.transformOrigin = new TransformOrigin(Length.Percent(0), Length.Percent(50));
            right.style.SetBackgroundStretchToFill();
            right.style.unityBackgroundImageTintColor = tint;
            if (capRight != null) right.style.backgroundImage = new StyleBackground(capRight);
            right.pickingMode = PickingMode.Ignore;
            container.Add(right);
            
            // Keep cap width synced with actual resolved height
            container.RegisterCallback<GeometryChangedEvent>(evt => {
                float h = evt.newRect.height;
                if (h <= 0) return;
                float capW = (h / 2f) * _progressBarCapWidth;
                left.style.width = capW;
                right.style.width = capW;
            });
            
            return (container, left, mid, right);
        }
        
        private void SetBarFillTint(VisualElement left, VisualElement mid, VisualElement right, Color tint)
        {
            if (left  != null) left.style.unityBackgroundImageTintColor  = tint;
            if (mid   != null) mid.style.unityBackgroundImageTintColor   = tint;
            if (right != null) right.style.unityBackgroundImageTintColor = tint;
        }
        
        private VisualElement CreateBarGradientOverlay(VisualElement fillContainer, Color[] leftColorRef, Color[] rightColorRef)
        {
            var overlay = new VisualElement();
            overlay.name = "bar-gradient-overlay";
            overlay.pickingMode = PickingMode.Ignore;
            overlay.style.position = Position.Absolute;
            overlay.style.top = 0;
            overlay.style.left = 0;
            overlay.style.right = 0;
            overlay.style.bottom = 0;
            overlay.generateVisualContent = (MeshGenerationContext mgc) =>
            {
                if (!_barGradientEnabled) return;
                var r = overlay.contentRect;
                if (r.width < 1 || r.height < 1) return;
                
                var mesh = mgc.Allocate(4, 6);
                if (mesh.vertexCount == 0) return;
                
                var verts = new Vertex[4];
                Color32 lc = leftColorRef[0];
                Color32 rc = rightColorRef[0];
                
                verts[0].position = new Vector3(0, 0, Vertex.nearZ);
                verts[0].tint = lc;
                verts[1].position = new Vector3(r.width, 0, Vertex.nearZ);
                verts[1].tint = rc;
                verts[2].position = new Vector3(r.width, r.height, Vertex.nearZ);
                verts[2].tint = rc;
                verts[3].position = new Vector3(0, r.height, Vertex.nearZ);
                verts[3].tint = lc;
                
                mesh.SetAllVertices(verts);
                mesh.SetAllIndices(new ushort[] { 0, 1, 2, 0, 2, 3 });
            };
            
            fillContainer.Add(overlay);
            overlay.BringToFront();
            // Repaint gradient when container resizes
            overlay.RegisterCallback<GeometryChangedEvent>(evt => overlay.MarkDirtyRepaint());
            fillContainer.RegisterCallback<GeometryChangedEvent>(evt => overlay.MarkDirtyRepaint());
            return overlay;
        }
        
        private void SetBarGradientColors(VisualElement overlay, Color[] leftRef, Color[] rightRef, Color left, Color right)
        {
            if (overlay == null) return;
            leftRef[0] = left;
            rightRef[0] = right;
            overlay.MarkDirtyRepaint();
        }
        
        private void UpdateBarGradientForState(bool syntyPassOn, bool is100)
        {
            if (!_barGradientEnabled) return;
            
            Color leftColor, rightColor;
            if (is100)
            {
                leftColor = _barGrad100LeftColor;
                rightColor = _barGrad100RightColor;
            }
            else if (syntyPassOn)
            {
                leftColor = _barGradSPLeftColor;
                rightColor = _barGradSPRightColor;
            }
            else
            {
                // Blue → Green gradient that eases in based on bar width
                // At low %, the bar is all blue. As it grows, green fades in on the right.
                leftColor = _barGradLeftColor; // always blue
                
                // Smoothstep: green starts appearing at ~15% and is fully green by ~60%
                float t = Mathf.Clamp01((_currentPercentage - 15f) / 45f);
                t = t * t * (3f - 2f * t); // smoothstep
                rightColor = Color.Lerp(_barGradLeftColor, _barGradRightColor, t);
            }
            
            SetBarGradientColors(_barGradientOverlay, _barGradCurrentLeft, _barGradCurrentRight, leftColor, rightColor);
            if (_progressBarFillLeft != null) _progressBarFillLeft.style.unityBackgroundImageTintColor = leftColor;
            if (_progressBarFillMid != null) _progressBarFillMid.style.unityBackgroundImageTintColor = Color.clear;
            if (_progressBarFillRight != null) _progressBarFillRight.style.unityBackgroundImageTintColor = rightColor;
        }
        
        private void UpdateProjectedBarGradient()
        {
            if (!_barGradientEnabled || _projectedGradientOverlay == null) return;
            
            // Match the smoothstep used by the main fill bar — at low projected percentages
            // (caps touching) the right cap matches the left so there's no visible seam, and
            // as the bar widens the right transitions to its configured colour.
            int selectedNotOwned = _assetItems.Count(i => i.getSelected() && !i.getOwned() && i.button.style.display != DisplayStyle.None);
            int totalCount = _assetItems.Count;
            int ownedCount = _assetItems.Count(i => i.getOwned());
            float projectedPct = totalCount > 0 ? Mathf.Min((float)(ownedCount + selectedNotOwned) / totalCount * 100f, 100f) : 0f;
            float t = Mathf.Clamp01((projectedPct - 15f) / 45f);
            t = t * t * (3f - 2f * t); // smoothstep
            Color leftColor = _barGradProjectedLeftColor;
            Color rightColor = Color.Lerp(_barGradProjectedLeftColor, _barGradProjectedRightColor, t);
            
            SetBarGradientColors(_projectedGradientOverlay, _projGradCurrentLeft, _projGradCurrentRight, leftColor, rightColor);
            if (_projectedBarFillLeft != null) _projectedBarFillLeft.style.unityBackgroundImageTintColor = leftColor;
            if (_projectedBarFillMid != null) _projectedBarFillMid.style.unityBackgroundImageTintColor = Color.clear;
            if (_projectedBarFillRight != null) _projectedBarFillRight.style.unityBackgroundImageTintColor = rightColor;
        }
        
        private void SetBarFillTransitions(VisualElement left, VisualElement mid, VisualElement right, int durationMs, EasingMode easing)
        {
            var prop = new List<StylePropertyName> { new StylePropertyName("unity-background-image-tint-color") };
            var dur = new List<TimeValue> { new TimeValue(durationMs, TimeUnit.Millisecond) };
            var ease = new List<EasingFunction> { new EasingFunction(easing) };
            foreach (var el in new[] { left, mid, right })
            {
                if (el == null) continue;
                el.style.transitionProperty = prop;
                el.style.transitionDuration = dur;
                el.style.transitionTimingFunction = ease;
            }
        }
        
