        private void UpdateProjectedBarStyle()
        {
            if (_projectedBarFill == null) return;
            int durationMs = Mathf.Max(1, Mathf.RoundToInt(_projectedBarEaseDuration));
            _projectedBarFill.style.transitionDuration = new List<TimeValue> { new TimeValue(durationMs, TimeUnit.Millisecond) };
            if (_barGradientEnabled)
            {
                SetBarFillTint(_projectedBarFillLeft, _projectedBarFillMid, _projectedBarFillRight, Color.clear);
                UpdateProjectedBarGradient();
            }
            else
                SetBarFillTint(_projectedBarFillLeft, _projectedBarFillMid, _projectedBarFillRight, _cartBtnColor);
            UpdateProjectedBar();
        }
        
        /// <summary>
        /// Sets the progress bar fill width. Hides the entire bar at 0%.
        /// </summary>
        private void SetProgressBarPercent(float percent)
        {
            if (_progressBarFill == null) return;
            
            if (percent <= 0f)
            {
                // 0% — keep the empty bar background visible (collection bar still shows the
                // capacity even with nothing owned), hide just the fill itself.
                if (_progressBarContainer != null) _progressBarContainer.style.display = DisplayStyle.Flex;
                if (_progressBarBgTrack != null) _progressBarBgTrack.style.display = DisplayStyle.Flex;
                _progressBarFill.style.display = DisplayStyle.None;
                if (_percentageTextContainer != null) _percentageTextContainer.style.display = DisplayStyle.Flex;
                if (_progressBarFillRight != null) _progressBarFillRight.style.display = DisplayStyle.None;
                if (_emptyCollectionLabel != null) _emptyCollectionLabel.style.display = DisplayStyle.Flex;
            }
            else
            {
                // Show everything
                if (_progressBarContainer != null) _progressBarContainer.style.display = DisplayStyle.Flex;
                if (_progressBarBgTrack != null) _progressBarBgTrack.style.display = DisplayStyle.Flex;
                _progressBarFill.style.display = DisplayStyle.Flex;
                if (_percentageTextContainer != null) _percentageTextContainer.style.display = DisplayStyle.Flex;
                if (_progressBarFillRight != null)
                    _progressBarFillRight.style.display = DisplayStyle.Flex;
                if (_emptyCollectionLabel != null) _emptyCollectionLabel.style.display = DisplayStyle.None;
                
                _progressBarFill.style.width = Length.Percent(percent);
                
                // Ensure minimum pixel width so caps + mid section have room to render
                float minCapWidth = (_progressBarHeight / 2f) * _progressBarCapWidth * 2f + 4f; // both caps + 4px mid
                _progressBarFill.style.minWidth = minCapWidth;
                
                // Update gradient colors based on new bar width
                if (_barGradientEnabled && !_licenseSyntyPass)
                    UpdateBarGradientForState(false, false);
            }
        }
        
        /// <summary>
        /// Registers hover handlers on an installed download button to show uninstall icon.
        /// </summary>
        // Applies font size + position to the asset count label live from the debug panel.
        // Builds the "shown/total" text with configurable spacing around the slash.
        private string FormatAssetCount(int shown, int total)
        {
            string pad = new string(' ', Mathf.Max(0, _assetCountSlashSpacing));
            return $"{shown}{pad}/{pad}{total}";
        }
        
        private void ApplyAssetCountStyle()
        {
            if (_assetCountLabel != null)
            {
                _assetCountLabel.style.fontSize = _assetCountFontSize;
                _assetCountLabel.style.unityFontStyleAndWeight = _assetCountBold ? FontStyle.Bold : FontStyle.Normal;
                _assetCountLabel.style.translate = new Translate(_assetCountX, _assetCountY);
                _assetCountLabel.style.color = new Color(_assetCountColor.r, _assetCountColor.g, _assetCountColor.b, _assetCountOpacity);
                _assetCountLabel.text = FormatAssetCount(_assetCountShown, _assetCountTotal);
            }
            if (_assetCountHeader != null)
            {
                if (_assetCountHeight > 0f) _assetCountHeader.style.height = _assetCountHeight;
                else _assetCountHeader.style.height = StyleKeyword.Auto;
            }
        }
        
        private string GetAssetCountSettings()
        {
            return $"--- ASSET COUNT ---\nFont Size: {_assetCountFontSize}\nBold: {_assetCountBold}\nX: {_assetCountX}\nY: {_assetCountY}\nHeight: {_assetCountHeight}\nColor: #{ColorUtility.ToHtmlStringRGB(_assetCountColor)}\nOpacity: {_assetCountOpacity}\nSlash Spacing: {_assetCountSlashSpacing}\nGrid Top Pad: {_assetGridTopPad}";
        }
        
        // Applies the current version font size + bold to every existing per-asset version label
        // (the "v1.0.0" under each installed/update badge), live without a rebuild.
        private void ApplyAssetVersionFont()
        {
            if (_versionTooltips == null) return;
            foreach (var kvp in _versionTooltips)
            {
                var tooltip = kvp.Value;
                if (tooltip == null) continue;
                tooltip.Query<Label>().ForEach(lbl =>
                {
                    if (lbl.text != null && lbl.text.StartsWith("v"))
                    {
                        lbl.style.fontSize = _assetVersionFontSize;
                        lbl.style.unityFontStyleAndWeight = _assetVersionBold ? FontStyle.Bold : FontStyle.Normal;
                    }
                });
            }
        }

        private void ShowInstalledBadge(VisualElement btn)
        {
            var btnVisual = btn.Q<VisualElement>("asset-btn-visual");
            if (btnVisual == null) return;
            
            // Don't add duplicate
            if (btnVisual.Q<Label>("installed-badge") != null) return;
            
            // Ensure green installed overlay is visible
            var selOverlay = btn.Q<VisualElement>("asset-btn-selected");
            if (selOverlay != null)
            {
                selOverlay.style.unityBackgroundImageTintColor = _installedBtnColor;
                selOverlay.style.opacity = 1;
            }
            
            // Shadow badge (behind the green one)
            var shadow = new Label("INSTALLED");
            shadow.name = "installed-badge-shadow";
            shadow.pickingMode = PickingMode.Ignore;
            shadow.style.position = Position.Absolute;
            shadow.style.top = _installedBadgeTop + _installedBadgeShadowOffY;
            shadow.style.right = _installedBadgeRight + _installedBadgeShadowOffX;
            shadow.style.backgroundColor = new Color(0f, 0f, 0f, _installedBadgeShadowOpacity);
            shadow.style.color = new Color(0f, 0f, 0f, 0f);
            shadow.style.fontSize = _installedBadgeFontSize;
            shadow.style.unityFontStyleAndWeight = FontStyle.Bold;
            shadow.style.paddingTop = _installedBadgePadV + _installedBadgeShadowPadV;
            shadow.style.paddingBottom = _installedBadgePadV + _installedBadgeShadowPadV;
            shadow.style.paddingLeft = _installedBadgePadH + _installedBadgeShadowPadH;
            shadow.style.paddingRight = _installedBadgePadH + _installedBadgeShadowPadH;
            shadow.style.borderTopLeftRadius = 0;
            shadow.style.borderTopRightRadius = _installedBadgeShadowRadius;
            shadow.style.borderBottomLeftRadius = _installedBadgeShadowRadius;
            shadow.style.borderBottomRightRadius = 0;
            shadow.style.letterSpacing = 1f;
            shadow.style.unityTextAlign = TextAnchor.MiddleCenter;
            if (_titleFont != null) shadow.style.unityFontDefinition = FontDefinition.FromFont(_titleFont);
            btnVisual.Add(shadow);
            
            var badge = new Label("INSTALLED");
            badge.name = "installed-badge";
            badge.pickingMode = PickingMode.Ignore;
            badge.style.position = Position.Absolute;
            badge.style.top = _installedBadgeTop;
            badge.style.right = _installedBadgeRight;
            badge.style.backgroundColor = _installedBadgeBgColor;
            badge.style.color = _installedBadgeTextColor;
            badge.style.fontSize = _installedBadgeFontSize;
            badge.style.unityFontStyleAndWeight = FontStyle.Bold;
            badge.style.paddingTop = _installedBadgePadV;
            badge.style.paddingBottom = _installedBadgePadV;
            badge.style.paddingLeft = _installedBadgePadH;
            badge.style.paddingRight = _installedBadgePadH;
            badge.style.borderTopLeftRadius = 0;
            badge.style.borderTopRightRadius = _installedBadgeRadius;
            badge.style.borderBottomLeftRadius = _installedBadgeRadius;
            badge.style.borderBottomRightRadius = 0;
            badge.style.letterSpacing = 1f;
            badge.style.unityTextAlign = TextAnchor.MiddleCenter;
            if (_titleFont != null) badge.style.unityFontDefinition = FontDefinition.FromFont(_titleFont);
            btnVisual.Add(badge);
            // Keep the darken overlay above the installed badge, so the badge dims with the card.
            {
                var dimAbove = btnVisual.Q<VisualElement>("download-dim-overlay");
                if (dimAbove != null && dimAbove.resolvedStyle.display != DisplayStyle.None)
                    dimAbove.BringToFront();
            }
            
            // Version tooltip — shown on hover of the asset button when installed
            string version = null;
            int itemIdx = _assetItems.FindIndex(x => x.button == btn);
            if (itemIdx >= 0 && _assetPackMapping.TryGetValue(itemIdx, out var vPack))
            {
                string handle = vPack.packName;
                if (string.IsNullOrEmpty(handle))
                    handle = SyntyStoreService.ExtractHandleFromUrl(vPack.storeUrl);
                var entry = SyntyInstallManifest.GetEntry(handle);
                version = entry != null && !string.IsNullOrEmpty(entry.installedVersion) 
                    ? entry.installedVersion 
                    : vPack.version;
            }
            
            if (!string.IsNullOrEmpty(version))
            {
                var versionTooltip = new VisualElement();
                versionTooltip.name = "version-tooltip";
                versionTooltip.pickingMode = PickingMode.Ignore;
                versionTooltip.style.position = Position.Absolute;
                versionTooltip.style.top = _installedBadgeTop + _installedBadgePadV * 2 + _installedBadgeFontSize + _versionTooltipOffsetY;
                versionTooltip.style.right = _installedBadgeRight + _versionTooltipOffsetX;
                versionTooltip.style.paddingLeft = 6;
                versionTooltip.style.paddingRight = 6;
                versionTooltip.style.paddingTop = 2;
                versionTooltip.style.paddingBottom = 2;
                versionTooltip.style.backgroundColor = _tooltipBgColor;
                versionTooltip.style.borderTopLeftRadius = 4;
                versionTooltip.style.borderTopRightRadius = 4;
                versionTooltip.style.borderBottomLeftRadius = 4;
                versionTooltip.style.borderBottomRightRadius = 4;
                versionTooltip.style.opacity = 0;
                versionTooltip.style.display = DisplayStyle.None;
                versionTooltip.style.whiteSpace = WhiteSpace.NoWrap;
                versionTooltip.style.transitionProperty = new List<StylePropertyName> { new StylePropertyName("opacity") };
                versionTooltip.style.transitionDuration = new List<TimeValue> { new TimeValue(150, TimeUnit.Millisecond) };
                versionTooltip.style.transitionTimingFunction = new List<EasingFunction> { new EasingFunction(EasingMode.EaseOut) };
                
                var vLabel = new Label($"v{version}");
                vLabel.style.color = _tooltipTextColor;
                vLabel.style.fontSize = _assetVersionFontSize;
                vLabel.style.unityFontStyleAndWeight = _assetVersionBold ? FontStyle.Bold : FontStyle.Normal;
                vLabel.style.unityTextAlign = TextAnchor.MiddleCenter;
                vLabel.pickingMode = PickingMode.Ignore;
                versionTooltip.Add(vLabel);
                btnVisual.Add(versionTooltip);
                
                _versionTooltips[btn] = versionTooltip;
                
                // Show/hide on hitArea hover. Shows for owned assets (or SyntyPass), whether
                // installed OR downloadable-but-not-installed. For not-installed (downloadable)
                // assets the tooltip is nudged up by _versionTooltipDownloadableOffsetY.
                btn.RegisterCallback<MouseEnterEvent>(evt => {
                    int vIdx = _assetItems.FindIndex(x => x.button == btn);
                    bool isOwned = vIdx >= 0 && _assetItems[vIdx].getOwned();
                    if (!isOwned && !_licenseSyntyPass) return; // not owned -> price shown, skip
                    
                    bool installed = btnVisual.ClassListContains("asset-installed");
                    // Reposition: base position plus an extra upward offset when not installed.
                    float extraY = installed ? 0f : _versionTooltipDownloadableOffsetY;
                    versionTooltip.style.top = _installedBadgeTop + _installedBadgePadV * 2 + _installedBadgeFontSize + _versionTooltipOffsetY + extraY;
                    
                    versionTooltip.style.display = DisplayStyle.Flex;
                    versionTooltip.schedule.Execute(() => {
                        versionTooltip.style.opacity = 1;
                    }).StartingIn(10);
                });
                btn.RegisterCallback<MouseLeaveEvent>(evt => {
                    versionTooltip.style.opacity = 0;
                    versionTooltip.schedule.Execute(() => {
                        if (versionTooltip.style.opacity.value < 0.1f)
                            versionTooltip.style.display = DisplayStyle.None;
                    }).StartingIn(200);
                });
            }
        }
        
