            badge.style.borderTopLeftRadius = 0;
            badge.style.borderTopRightRadius = _installedBadgeRadius;
            badge.style.borderBottomLeftRadius = _installedBadgeRadius;
            badge.style.borderBottomRightRadius = 0;
            badge.style.letterSpacing = 1f;
            badge.style.unityTextAlign = TextAnchor.MiddleCenter;
            if (_titleFont != null) badge.style.unityFontDefinition = FontDefinition.FromFont(_titleFont);
            btnVisual.Add(badge);
            // Keep the darken overlay above the installed badge, so the badge dims with the card.
            {
                var dimAbove = btnVisual.Q<VisualElement>("download-dim-overlay");
                if (dimAbove != null && dimAbove.resolvedStyle.display != DisplayStyle.None)
                    dimAbove.BringToFront();
            }
            
            // Version tooltip for update badge
            string version = null;
            int itemIdx = _assetItems.FindIndex(x => x.button == btn);
            if (itemIdx >= 0 && _assetPackMapping.TryGetValue(itemIdx, out var vPack))
            {
                version = vPack.version;
            }
            
            if (!string.IsNullOrEmpty(version))
            {
                var versionTooltip = new VisualElement();
                versionTooltip.name = "version-tooltip";
                versionTooltip.pickingMode = PickingMode.Ignore;
                versionTooltip.style.position = Position.Absolute;
                versionTooltip.style.top = _installedBadgeTop + _installedBadgePadV * 2 + _installedBadgeFontSize + _versionTooltipOffsetY;
                versionTooltip.style.right = _installedBadgeRight + _versionTooltipOffsetX;
                versionTooltip.style.paddingLeft = 6;
                versionTooltip.style.paddingRight = 6;
                versionTooltip.style.paddingTop = 2;
                versionTooltip.style.paddingBottom = 2;
                versionTooltip.style.backgroundColor = _tooltipBgColor;
                versionTooltip.style.borderTopLeftRadius = 4;
                versionTooltip.style.borderTopRightRadius = 4;
                versionTooltip.style.borderBottomLeftRadius = 4;
                versionTooltip.style.borderBottomRightRadius = 4;
                versionTooltip.style.opacity = 0;
                versionTooltip.style.display = DisplayStyle.None;
                versionTooltip.style.whiteSpace = WhiteSpace.NoWrap;
                versionTooltip.style.transitionProperty = new List<StylePropertyName> { new StylePropertyName("opacity") };
                versionTooltip.style.transitionDuration = new List<TimeValue> { new TimeValue(150, TimeUnit.Millisecond) };
                versionTooltip.style.transitionTimingFunction = new List<EasingFunction> { new EasingFunction(EasingMode.EaseOut) };
                
                var vLabel = new Label($"v{version}");
                vLabel.style.color = _tooltipTextColor;
                vLabel.style.fontSize = _assetVersionFontSize;
                vLabel.style.unityFontStyleAndWeight = _assetVersionBold ? FontStyle.Bold : FontStyle.Normal;
                vLabel.style.unityTextAlign = TextAnchor.MiddleCenter;
                vLabel.pickingMode = PickingMode.Ignore;
                versionTooltip.Add(vLabel);
                btnVisual.Add(versionTooltip);
                
                _versionTooltips[btn] = versionTooltip;
                
                btn.RegisterCallback<MouseEnterEvent>(evt => {
                    int vIdx2 = _assetItems.FindIndex(x => x.button == btn);
                    bool isOwned2 = vIdx2 >= 0 && _assetItems[vIdx2].getOwned();
                    if (!isOwned2 && !_licenseSyntyPass) return;
                    
                    versionTooltip.style.display = DisplayStyle.Flex;
                    versionTooltip.schedule.Execute(() => {
                        versionTooltip.style.opacity = 1;
                    }).StartingIn(10);
                });
                btn.RegisterCallback<MouseLeaveEvent>(evt => {
                    versionTooltip.style.opacity = 0;
                    versionTooltip.schedule.Execute(() => {
                        if (versionTooltip.style.opacity.value < 0.1f)
                            versionTooltip.style.display = DisplayStyle.None;
                    }).StartingIn(200);
                });
            }
        }
        
        private void RemoveInstalledBadge(VisualElement btn)
        {
            var badge = btn.Q<Label>("installed-badge");
            if (badge != null) badge.RemoveFromHierarchy();
            var shadow = btn.Q<Label>("installed-badge-shadow");
            if (shadow != null) shadow.RemoveFromHierarchy();
            
            // Remove version tooltip
            if (_versionTooltips.TryGetValue(btn, out var vTooltip))
            {
                vTooltip.RemoveFromHierarchy();
                _versionTooltips.Remove(btn);
            }
        }
        
        private static bool IsInstalledButton(VisualElement el)
        {
            var current = el;
            while (current != null)
            {
                if (current.ClassListContains("asset-installed")) return true;
                current = current.parent;
            }
            return false;
        }
        
        private void RegisterUninstallHover(VisualElement dlBtn, VisualElement dlIcon, Label tooltipLabel = null)
        {
            var pressedOvr = dlBtn.Q<VisualElement>("download-pressed-overlay");
            dlBtn.RegisterCallback<MouseEnterEvent>(evt => {
                if (_activeDownloadCount > 0) return;
                if (!IsInstalledButton(dlBtn)) return;
                if (_uninstallIcon != null)
                    dlIcon.style.backgroundImage = new StyleBackground(_uninstallIcon);
                dlBtn.style.unityBackgroundImageTintColor = new Color(0.8f, 0.2f, 0.2f, 1f);
                if (pressedOvr != null) pressedOvr.style.unityBackgroundImageTintColor = new Color(0.8f, 0.2f, 0.2f, 1f);
                dlIcon.style.unityBackgroundImageTintColor = Color.white;
                // Update tooltip to "Uninstall"
                if (tooltipLabel != null) tooltipLabel.text = "Uninstall";
                evt.StopPropagation();
            });
            dlBtn.RegisterCallback<MouseLeaveEvent>(evt => {
                if (!IsInstalledButton(dlBtn)) return;
                if (_installedIcon != null)
                    dlIcon.style.backgroundImage = new StyleBackground(_installedIcon);
                dlBtn.style.unityBackgroundImageTintColor = _installedBtnColor;
                if (pressedOvr != null) pressedOvr.style.unityBackgroundImageTintColor = _installedBtnColor;
                dlIcon.style.unityBackgroundImageTintColor = Color.white;
                // Restore tooltip to "Installed"
                if (tooltipLabel != null) tooltipLabel.text = "Installed";
            });
        }
        
        private void UpdateProgressBarCapScale()
        {
            var capS = new Scale(new Vector3(_progressBarCapScaleX, _progressBarCapScaleY, 1f));
            float capW = (_progressBarHeight / 2f) * _progressBarCapWidth;
            if (_progressBarFillLeft != null) { _progressBarFillLeft.style.scale = capS; _progressBarFillLeft.style.width = capW; }
            if (_progressBarFillRight != null) { _progressBarFillRight.style.scale = capS; _progressBarFillRight.style.width = capW; }
            if (_projectedBarFillLeft != null) { _projectedBarFillLeft.style.scale = capS; _projectedBarFillLeft.style.width = capW; }
            if (_projectedBarFillRight != null) { _projectedBarFillRight.style.scale = capS; _projectedBarFillRight.style.width = capW; }
            // Update bg track to match scaled cap height
            if (_progressBarBgTrack != null)
            {
                float bgH = _progressBarHeight * _progressBarCapScaleY;
                float bgOff = (_progressBarHeight - bgH) / 2f;
                _progressBarBgTrack.style.height = bgH;
                _progressBarBgTrack.style.top = bgOff;
                float r = bgH / 2f;
                _progressBarBgTrack.style.borderTopLeftRadius = r;
                _progressBarBgTrack.style.borderTopRightRadius = r;
                _progressBarBgTrack.style.borderBottomLeftRadius = r;
                _progressBarBgTrack.style.borderBottomRightRadius = r;
            }
        }
        
