        private void UpdateDownloadBarStyle()
        {
            // Download bar
            if (_downloadBarBtn != null)
                _downloadBarBtn.style.height = _downloadBarBtnHeight;
            if (_downloadBarTitleLabel != null)
            {
                _downloadBarTitleLabel.style.fontSize = _downloadBarTitleFontSize;
                _downloadBarTitleLabel.style.color = _downloadBarTitleColor;
                _downloadBarTitleLabel.style.unityFontStyleAndWeight = _downloadBarTitleBold ? FontStyle.Bold : FontStyle.Normal;
                _downloadBarTitleLabel.style.marginTop = _downloadBarTitleY;
                _downloadBarTitleLabel.style.marginLeft = _downloadBarTitleX;
            }
            if (_downloadBarSubtitleLabel != null)
            {
                _downloadBarSubtitleLabel.style.fontSize = _downloadBarSubtitleFontSize;
                _downloadBarSubtitleLabel.style.color = _downloadBarSubtitleColor;
                _downloadBarSubtitleLabel.style.unityFontStyleAndWeight = _downloadBarSubtitleBold ? FontStyle.Bold : FontStyle.Normal;
                _downloadBarSubtitleLabel.style.marginTop = _downloadBarSubtitleY;
                _downloadBarSubtitleLabel.style.marginLeft = _downloadBarSubtitleX;
            }
            // Cart bar
            if (_cartBarBtn != null)
                _cartBarBtn.style.height = _downloadBarBtnHeight;
            if (_cartBarTitleLabel != null)
            {
                _cartBarTitleLabel.style.fontSize = _downloadBarTitleFontSize;
                _cartBarTitleLabel.style.color = _downloadBarTitleColor;
                _cartBarTitleLabel.style.unityFontStyleAndWeight = _downloadBarTitleBold ? FontStyle.Bold : FontStyle.Normal;
                _cartBarTitleLabel.style.marginTop = _downloadBarTitleY;
                _cartBarTitleLabel.style.marginLeft = _downloadBarTitleX;
            }
            if (_cartBarSubtitleLabel != null)
            {
                _cartBarSubtitleLabel.style.fontSize = _downloadBarSubtitleFontSize;
                _cartBarSubtitleLabel.style.color = _downloadBarSubtitleColor;
                _cartBarSubtitleLabel.style.unityFontStyleAndWeight = _downloadBarSubtitleBold ? FontStyle.Bold : FontStyle.Normal;
                _cartBarSubtitleLabel.style.marginTop = _downloadBarSubtitleY;
                _cartBarSubtitleLabel.style.marginLeft = _downloadBarSubtitleX;
            }
            // When a price is showing, the cart subtitle is drawn by the separate price
            // container (prefix / $dollars / cents / suffix), not _cartBarSubtitleLabel.
            // Resize those labels too so the Sub Font slider affects the price line. The
            // cents stay proportionally smaller (0.7x) and we clear the auto-fit stored max
            // so it re-measures against the new size.
            if (_cartBarPriceContainer != null && _cartBarPriceContainer.style.display == DisplayStyle.Flex)
            {
                float mainSize = _downloadBarSubtitleFontSize;
                var priceLabels = _cartBarPriceContainer.Query<Label>().ToList();
                for (int i = 0; i < priceLabels.Count; i++)
                {
                    var lbl = priceLabels[i];
                    lbl.userData = mainSize; // reset auto-fit max to the new design size
                    lbl.style.fontSize = mainSize;
                    lbl.style.color = _downloadBarSubtitleColor;
                    lbl.style.unityFontStyleAndWeight = _downloadBarSubtitleBold ? FontStyle.Bold : FontStyle.Normal;
                }
            }
            // Updates bar
            if (_updatesBarBtn != null)
                _updatesBarBtn.style.height = _downloadBarBtnHeight;
            if (_updatesBarTitleLabel != null)
            {
                _updatesBarTitleLabel.style.fontSize = _downloadBarTitleFontSize;
                _updatesBarTitleLabel.style.color = _downloadBarTitleColor;
                _updatesBarTitleLabel.style.unityFontStyleAndWeight = _downloadBarTitleBold ? FontStyle.Bold : FontStyle.Normal;
                _updatesBarTitleLabel.style.marginTop = _downloadBarTitleY;
                _updatesBarTitleLabel.style.marginLeft = _downloadBarTitleX;
            }
            if (_updatesBarSubtitleLabel != null)
            {
                _updatesBarSubtitleLabel.style.fontSize = _downloadBarSubtitleFontSize;
                _updatesBarSubtitleLabel.style.color = _downloadBarSubtitleColor;
                _updatesBarSubtitleLabel.style.unityFontStyleAndWeight = _downloadBarSubtitleBold ? FontStyle.Bold : FontStyle.Normal;
                _updatesBarSubtitleLabel.style.marginTop = _downloadBarSubtitleY;
                _updatesBarSubtitleLabel.style.marginLeft = _downloadBarSubtitleX;
            }
            // Shadow gradient
            if (_bottomBarGradient != null)
            {
                _bottomBarGradient.style.height = _bottomBarGradientHeight;
                _bottomBarGradient.style.bottom = _bottomBarGradientY;
                _bottomBarGradient.style.scale = new Scale(new Vector3(1f, _bottomBarGradientScaleY, 1f));
                _bottomBarGradient.style.unityBackgroundImageTintColor = new Color(_bottomBarGradientColor.r, _bottomBarGradientColor.g, _bottomBarGradientColor.b, _bottomBarGradientOpacity);
            }
        }
        
        private EasingMode GetActionBarEasing()
        {
            return _actionBarEasingMode switch {
                0 => EasingMode.Ease,
                1 => EasingMode.EaseIn,
                2 => EasingMode.EaseOut,
                3 => EasingMode.EaseInOut,
                4 => EasingMode.Linear,
                _ => EasingMode.EaseOut
            };
        }
        
        private void UpdateActionBarTransitions()
        {
            var easing = new EasingFunction(GetActionBarEasing());
            var duration = new TimeValue(_actionBarTransitionDuration, TimeUnit.Millisecond);
            var durations = new List<TimeValue> { duration, duration, duration, duration, duration };
            var easings = new List<EasingFunction> { easing, easing, easing, easing, easing };
            
            if (_downloadBar != null)
            {
                _downloadBar.style.transitionDuration = durations;
                _downloadBar.style.transitionTimingFunction = easings;
            }
            if (_cartBar != null)
            {
                _cartBar.style.transitionDuration = durations;
                _cartBar.style.transitionTimingFunction = easings;
            }
            if (_updatesBar != null)
            {
                _updatesBar.style.transitionDuration = durations;
                _updatesBar.style.transitionTimingFunction = easings;
            }
        }
        
