        {
            if (_downloadBarBtn != null && !_downloadBarHovered)
                _downloadBarBtn.style.unityBackgroundImageTintColor = _downloadBarBtnColor;
            if (_cartBarBtn != null && !_cartBarHovered)
                _cartBarBtn.style.unityBackgroundImageTintColor = _cartBarBtnColor;
            if (_updatesBarBtn != null && !_updatesBarHovered)
                _updatesBarBtn.style.unityBackgroundImageTintColor = _updatesBarBtnColor;
            if (_uninstallBarBtn != null)
                _uninstallBarBtn.style.unityBackgroundImageTintColor = _uninstallBarBtnColor;
        }
        
        private VisualElement CreateAssetBtnTooltip(VisualElement parent, VisualElement hoverTarget, string text)
        {
            var tooltip = new VisualElement();
            tooltip.name = "asset-btn-tooltip";
            tooltip.pickingMode = PickingMode.Ignore;
            tooltip.style.position = Position.Absolute;
            tooltip.style.paddingLeft = 8;
            tooltip.style.paddingRight = 8;
            tooltip.style.paddingTop = 4;
            tooltip.style.paddingBottom = 4;
            tooltip.style.backgroundColor = _tooltipBgColor;
            tooltip.style.borderTopLeftRadius = 4;
            tooltip.style.borderTopRightRadius = 4;
            tooltip.style.borderBottomLeftRadius = 4;
            tooltip.style.borderBottomRightRadius = 4;
            tooltip.style.opacity = 0;
            tooltip.style.scale = new Scale(new Vector3(0.9f, 0.9f, 1f));
            tooltip.style.transitionProperty = new List<StylePropertyName> { 
                new StylePropertyName("opacity"),
                new StylePropertyName("scale")
            };
            tooltip.style.transitionDuration = new List<TimeValue> { 
                new TimeValue(150, TimeUnit.Millisecond),
                new TimeValue(150, TimeUnit.Millisecond)
            };
            tooltip.style.transitionTimingFunction = new List<EasingFunction> { 
                new EasingFunction(EasingMode.EaseOut),
                new EasingFunction(EasingMode.EaseOut)
            };
            tooltip.style.whiteSpace = WhiteSpace.NoWrap;
            tooltip.style.display = DisplayStyle.None;
            
            var label = new Label(text);
            label.style.color = _tooltipTextColor;
            label.style.fontSize = _tooltipFontSize;
            label.style.unityFontStyleAndWeight = _tooltipBold ? FontStyle.Bold : FontStyle.Normal;
            label.style.unityTextAlign = TextAnchor.MiddleCenter;
            label.pickingMode = PickingMode.Ignore;
            tooltip.Add(label);
            
            // Add to overlay layer so tooltip renders above all buttons
            if (_tooltipOverlay != null)
                _tooltipOverlay.Add(tooltip);
            else
                parent.Add(tooltip); // fallback
            
            IVisualElementScheduledItem delayedShow = null;
            
            hoverTarget.RegisterCallback<MouseEnterEvent>(evt => {
                tooltip.style.display = DisplayStyle.Flex;
                
                // Position tooltip relative to the hoverTarget's world position
                var targetBounds = hoverTarget.worldBound;
                var overlayBounds = _tooltipOverlay != null ? _tooltipOverlay.worldBound : parent.worldBound;
                float targetRight = targetBounds.x - overlayBounds.x;
                float targetBottom = targetBounds.y - overlayBounds.y + targetBounds.height * 0.5f;
                tooltip.style.top = targetBottom - 12;
                tooltip.style.left = targetRight - 8;
                // Nudge left by tooltip width after layout
                EventCallback<GeometryChangedEvent> onLayout = null;
                onLayout = (ge) => {
                    tooltip.style.left = targetRight - ge.newRect.width - 4;
                    tooltip.UnregisterCallback(onLayout);
                };
                tooltip.RegisterCallback(onLayout);
                
                // Start hidden, then fade in after delay
                tooltip.style.opacity = 0;
                tooltip.style.scale = new Scale(new Vector3(0.9f, 0.9f, 1f));
                delayedShow = hoverTarget.schedule.Execute(() => {
                    tooltip.style.opacity = 1;
                    tooltip.style.scale = new Scale(Vector3.one);
                }).StartingIn(500);
            });
            hoverTarget.RegisterCallback<MouseLeaveEvent>(evt => {
                if (delayedShow != null)
                {
                    SafePause(delayedShow);
                    delayedShow = null;
                }
                tooltip.style.opacity = 0;
                tooltip.style.scale = new Scale(new Vector3(0.9f, 0.9f, 1f));
                // Hide after fade out
                hoverTarget.schedule.Execute(() => {
                    if (tooltip.style.opacity.value < 0.1f)
                        tooltip.style.display = DisplayStyle.None;
                }).StartingIn(200);
            });
            
            return tooltip;
        }
        
        // Adds a white outline that draws over the button on hover (same look as the card buttons).
        // The outline is an absolutely-positioned bordered overlay, shown on MouseEnter, hidden on leave.
        private void AddActionBarHoverOutline(VisualElement btn, float cornerRadius)
        {
            if (btn == null) return;
            var outline = new VisualElement();
            outline.name = "action-bar-hover";
            outline.style.position = Position.Absolute;
            outline.style.left = 1; outline.style.right = 1;
            outline.style.top = 1; outline.style.bottom = 1;
            outline.style.borderTopLeftRadius = cornerRadius;
            outline.style.borderTopRightRadius = cornerRadius;
            outline.style.borderBottomLeftRadius = cornerRadius;
            outline.style.borderBottomRightRadius = cornerRadius;
            outline.style.borderTopWidth = 2f;
            outline.style.borderBottomWidth = 2f;
            outline.style.borderLeftWidth = 2f;
            outline.style.borderRightWidth = 2f;
            outline.style.borderTopColor = Color.white;
            outline.style.borderBottomColor = Color.white;
            outline.style.borderLeftColor = Color.white;
            outline.style.borderRightColor = Color.white;
            outline.style.display = DisplayStyle.None;
            outline.pickingMode = PickingMode.Ignore;
            btn.Add(outline);
            btn.RegisterCallback<MouseEnterEvent>(evt => outline.style.display = DisplayStyle.Flex);
            btn.RegisterCallback<MouseLeaveEvent>(evt => outline.style.display = DisplayStyle.None);
        }

