        // Snap a sale percentage to a 10-90 bucket. Use the nearest bucket only when within 2%,
        // otherwise round down to the lower bucket. Clamped to the available 10..90 images.
        private int ComputeSaleBucket(float pct)
        {
            int nearest = Mathf.RoundToInt(pct / 10f) * 10;
            int bucket = (Mathf.Abs(pct - nearest) <= 2f) ? nearest : (Mathf.FloorToInt(pct / 10f) * 10);
            return Mathf.Clamp(bucket, 10, 90);
        }
        
        // Live-apply sale-amount position/size + visibility (mirrors the sale badge), for the options panel.
        private void UpdateSaleAmount()
        {
            float gf = GetThumbScaleFactor();
            GetSaleAmountScaleOffset(out float offX, out float offY);
            foreach (var item in _assetItems)
            {
                var sa = item.button.Q<VisualElement>("sale-amount") ?? item.btnVisual?.Q<VisualElement>("sale-amount");
                if (sa == null) continue;
                sa.style.left = _saleAmountX * gf + offX;
                sa.style.top = _saleAmountY * gf + offY;
                sa.style.width = _saleAmountWidth;
                sa.style.height = _saleAmountHeight;
                sa.style.scale = new Scale(new Vector3(_saleAmountScale * gf, _saleAmountScale * gf, 1f));
                sa.style.transformOrigin = new TransformOrigin(
                    Length.Percent(_saleAmountHoverPivotX),
                    Length.Percent(_saleAmountHoverPivotY), 0);
                sa.style.transitionDuration = new List<TimeValue> { new TimeValue(_saleAmountHoverDurationMs, TimeUnit.Millisecond) };
                var sb = item.button.Q<VisualElement>("sale-badge") ?? item.btnVisual?.Q<VisualElement>("sale-badge");
                bool badgeVisible = sb != null && sb.resolvedStyle.display == DisplayStyle.Flex;
                // Never show the sale-amount while a download is dimming the grid - it would
                // paint above the dim. _downloadingActive is cleared when the download ends,
                // and this method runs again on the next refresh to restore it.
                sa.style.display = (!_downloadingActive && _showSaleAmount && badgeVisible) ? DisplayStyle.Flex : DisplayStyle.None;
            }
        }
        
        // Scale factor of the current thumbnail size relative to the largest (3-across) buttons.
        private float GetThumbScaleFactor()
        {
            float curSize = _thumbnailColumns == 5 ? _assetButtonSize5Across
                          : _thumbnailColumns == 4 ? _assetButtonSize4Across
                          : _assetButtonSize3Across;
            return (_assetButtonSize3Across > 0f) ? curSize / _assetButtonSize3Across : 1f;
        }
        
        // Extra sale-amount offset for the current thumbnail scale (medium/small).
        private void GetSaleAmountScaleOffset(out float offX, out float offY)
        {
            if (_thumbnailColumns >= 5) { offX = _saleAmountSmallOffsetX; offY = _saleAmountSmallOffsetY; }
            else if (_thumbnailColumns >= 4) { offX = _saleAmountMedOffsetX; offY = _saleAmountMedOffsetY; }
            else { offX = 0f; offY = 0f; }
        }
        
