        // ── Synty Pass button attention pulse ────────────────────────────
        // Arms the delay timer. After PASS_PULSE_DELAY_SEC with no click, the button pulses.
        // Restarts the pass-button pulse with current settings. Called when a debug option changes
        // so the effect is visible immediately without reopening the tool.
        private void ReArmPassPulse()
        {
            StopPassButtonPulse();
            _passPulseArmedAt = -1;
            if (_syntyPassBtn != null) ArmPassButtonPulse();
        }

        // Arms the cart ACTION BAR button pulse: records when the bar became visible and starts the
        // ticker. Called when the cart action bar is shown.
        private void ArmCartBarPulse()
        {
            if (!_cartBarPulseEnabled || _cartBarBtn == null) return;
            _cartBarPulseShownAt = EditorApplication.timeSinceStartup;
            EditorApplication.update -= CartBarPulseTick;
            EditorApplication.update += CartBarPulseTick;
        }

        // Stops the cart bar pulse and resets the bar button scale.
        private void StopCartBarPulse()
        {
            EditorApplication.update -= CartBarPulseTick;
            _cartBarPulseShownAt = -1;
            if (_cartBarBtn != null) _cartBarBtn.style.scale = new Scale(Vector3.one);
        }

        // Per-frame: after the delay, scales the cart bar button up and down in a ping-pong while the
        // cart bar is visible. Stops when the bar is hidden.
        private void CartBarPulseTick()
        {
            if (!_cartBarPulseEnabled || _cartBarBtn == null) { StopCartBarPulse(); return; }
            bool visible = _cartBar != null && _cartBar.style.bottom.value.value >= 0;
            if (!visible) { StopCartBarPulse(); return; }
            double elapsed = EditorApplication.timeSinceStartup - _cartBarPulseShownAt;
            if (elapsed < _cartBarPulseDelaySec) return;
            double t = ((elapsed - _cartBarPulseDelaySec) % _cartBarPulsePeriodSec) / _cartBarPulsePeriodSec;
            float pp = 1f - Mathf.Abs((float)t * 2f - 1f);
            float scale = Mathf.Lerp(1f, _cartBarPulseScale, pp);
            _cartBarBtn.style.scale = new Scale(new Vector3(scale, scale, 1f));
        }

        // Arms the cart pulse: records when a cart selection began and starts the ticker. Called
        // whenever a not-owned asset becomes selected.
        private void ArmCartPulse()
        {
            if (!_cartPulseEnabled) return;
            _cartPulseSelectedAt = EditorApplication.timeSinceStartup;
            EditorApplication.update -= CartPulseTick;
            EditorApplication.update += CartPulseTick;
        }

        // Stops the cart pulse and resets any pulsed cart buttons back to base scale.
        private void StopCartPulse()
        {
            EditorApplication.update -= CartPulseTick;
            _cartPulseSelectedAt = -1;
            if (_assetItems == null) return;
            foreach (var it in _assetItems)
            {
                var cb = it.button?.Q<Button>("cart-btn") ?? it.button?.Q<VisualElement>("cart-btn") as VisualElement;
                if (cb != null) cb.style.scale = new Scale(Vector3.one);
            }
        }

        // Per-frame: after the delay, scales the cart button of every selected not-owned card up and
        // down in a ping-pong. If no not-owned card is selected, stops.
        private void CartPulseTick()
        {
            if (!_cartPulseEnabled || _assetItems == null) { StopCartPulse(); return; }
            bool anyCartSelected = false;
            foreach (var it in _assetItems)
                if (it.getSelected() && !it.getOwned()) { anyCartSelected = true; break; }
            if (!anyCartSelected) { StopCartPulse(); return; }
            double elapsed = EditorApplication.timeSinceStartup - _cartPulseSelectedAt;
            if (elapsed < _cartPulseDelaySec) return;
            // Ping-pong 0..1..0 over the period.
            double t = ((elapsed - _cartPulseDelaySec) % _cartPulsePeriodSec) / _cartPulsePeriodSec;
            float pp = 1f - Mathf.Abs((float)t * 2f - 1f); // 0 at ends, 1 at middle
            float scale = Mathf.Lerp(1f, _cartPulseScale, pp);
            foreach (var it in _assetItems)
            {
                if (!it.getSelected() || it.getOwned()) continue;
                var cb = it.button?.Q<VisualElement>("cart-btn");
                if (cb != null) cb.style.scale = new Scale(new Vector3(scale, scale, 1f));
            }
        }

        private void ArmPassButtonPulse()
        {
            if (!_passPulseEnabled) return;
            // Respect the per-audience toggles so QA can target pass vs non-pass users.
            bool hasPass = _licenseSyntyPass;
            if (hasPass && !_passPulseForPassUsers) return;
            if (!hasPass && !_passPulseForNonPassUsers) return;
            _passBtnEverClicked = EditorPrefs.GetBool(PREFS_PREFIX + "PassBtnClicked", false);
            if (_passBtnEverClicked) return; // already discovered — never nag again
            _passPulseArmedAt = EditorApplication.timeSinceStartup;
            EditorApplication.update -= PassButtonPulseTick;
            EditorApplication.update += PassButtonPulseTick;
        }

        // Call when the pass button is clicked. Stops the pulse for good.
        private void MarkPassButtonClicked()
        {
            _passBtnEverClicked = true;
            EditorPrefs.SetBool(PREFS_PREFIX + "PassBtnClicked", true);
            _passPulseActive = false;
            _passPulseArmedAt = -1;
            EditorApplication.update -= PassButtonPulseTick;
            if (_syntyPassBtn != null) { _syntyPassBtn.style.scale = new Scale(Vector3.one); ResetPassPulseTint(); }
        }

        private void StopPassButtonPulse()
        {
            EditorApplication.update -= PassButtonPulseTick;
            if (_passPulseActive && _syntyPassBtn != null)
            {
                _syntyPassBtn.style.scale = new Scale(Vector3.one);
                ResetPassPulseTint();
            }
            _passPulseActive = false;
        }

        // Restores the glow bar (and its fade transition) and the button caps to their on/off base.
        private void ResetPassPulseTint()
        {
            if (_syntyPassGlowBar != null)
            {
                _syntyPassGlowBar.style.transitionDuration =
                    new StyleList<TimeValue>(new List<TimeValue> { new TimeValue(1f, TimeUnit.Second) });
                _syntyPassGlowBar.style.opacity = _licenseSyntyPass ? 1f : 0f;
            }
            if (_syntyPassBtn != null)
            {
                Color baseCol = _licenseSyntyPass ? _licenseBtnOnBgColor : _licenseBtnOffBgColor;
                var bg = _syntyPassBtn.Q<VisualElement>("filter-btn-bg");
                if (bg != null)
                {
                    var l = bg.Q<VisualElement>("filter-btn-left");
                    var m = bg.Q<VisualElement>("filter-btn-middle");
                    var r = bg.Q<VisualElement>("filter-btn-right");
                    if (l != null) l.style.unityBackgroundImageTintColor = baseCol;
                    if (m != null) m.style.unityBackgroundImageTintColor = baseCol;
                    if (r != null) r.style.unityBackgroundImageTintColor = baseCol;
                }
            }
        }

        private void PassButtonPulseTick()
        {
            if (_reloadingDomain || !this) return;
            if (_passBtnEverClicked || _passPulseArmedAt < 0 || _syntyPassBtn == null) return;

            double now = EditorApplication.timeSinceStartup;
            if (!_passPulseActive)
            {
                if (now - _passPulseArmedAt < _passPulseDelaySec) return;
                _passPulseActive = true;
                _passPulseArmedAt = now; // reuse as the animation start time
                _syntyPassBtn.style.transformOrigin = new TransformOrigin(Length.Percent(50), Length.Percent(50));
            }

            float period = Mathf.Max(0.2f, _passPulsePeriodSec);
            double elapsed = now - _passPulseArmedAt;
            float t = (float)(elapsed / period) % 2f;
            if (t > 1f) t = 2f - t;
            t = t * t * (3f - 2f * t); // smoothstep

            // Pulse DOWNWARD from full size so the button never grows wider than the filter area
            // (which would clip against the frame). _passPulseScale>1 is read as the shrink depth.
            float dip = Mathf.Max(0f, _passPulseScale - 1f);
            float scale = Mathf.Lerp(1f, 1f - dip, t);
            _syntyPassBtn.style.scale = new Scale(new Vector3(scale, scale, 1f));

            // Orange-glow ease synced to the pulse.
            if (_passPulseColorEnabled && _syntyPassGlowBar != null)
            {
                bool on = _licenseSyntyPass;
                _syntyPassGlowBar.style.transitionDuration =
                    new StyleList<TimeValue>(new List<TimeValue> { new TimeValue(0f, TimeUnit.Second) });
                float target = on ? (1f - t * _passPulseColorAmount) : (t * _passPulseColorAmount);
                _syntyPassGlowBar.style.opacity = target;
            }

            // Button-colour ease: OFF eases the black button toward orange; ON eases orange toward black.
            if (_passPulseBtnColorEnabled)
            {
                bool on = _licenseSyntyPass;
                Color baseCol   = on ? _licenseBtnOnBgColor : _licenseBtnOffBgColor;
                Color targetCol = on ? _passPulseBtnOnColor : _passPulseBtnOffColor;
                Color c = Color.Lerp(baseCol, targetCol, t * _passPulseBtnColorAmount);
                var bg = _syntyPassBtn.Q<VisualElement>("filter-btn-bg");
                if (bg != null)
                {
                    var l = bg.Q<VisualElement>("filter-btn-left");
                    var m = bg.Q<VisualElement>("filter-btn-middle");
                    var r = bg.Q<VisualElement>("filter-btn-right");
                    if (l != null) l.style.unityBackgroundImageTintColor = c;
                    if (m != null) m.style.unityBackgroundImageTintColor = c;
                    if (r != null) r.style.unityBackgroundImageTintColor = c;
                }
            }
        }

        private void StartSaleBadgePulse()
        {
            _saleBadgePulseStartTime = EditorApplication.timeSinceStartup;
            EditorApplication.update -= SaleBadgePulseTick;
            EditorApplication.update += SaleBadgePulseTick;
        }
        
        private void StopSaleBadgePulse()
        {
            EditorApplication.update -= SaleBadgePulseTick;
        }
        
        private void SaleBadgePulseTick()
        {
            if (_reloadingDomain || !this || !_saleBadgePulseEnabled) return;
            
            double elapsed = EditorApplication.timeSinceStartup - _saleBadgePulseStartTime;
            float durationSec = Mathf.Max(0.1f, _saleBadgePulseMs / 1000f);
            // Ping-pong: 0→1→0→1...
            float t = (float)(elapsed / durationSec) % 2f;
            if (t > 1f) t = 2f - t;
            // Smooth ease in-out
            t = t * t * (3f - 2f * t);
            
            Color c = Color.Lerp(_saleBadgeColor, _saleBadgeColor2, t);
            
            foreach (var item in _assetItems)
            {
                var saleBadge = item.button.Q<VisualElement>("sale-badge");
                if (saleBadge != null && saleBadge.style.display == DisplayStyle.Flex)
                    saleBadge.style.backgroundColor = c;
            }
            
            Repaint();
        }
        
        private void UpdateSaleBadgePulseState()
        {
            if (_saleBadgePulseEnabled)
                StartSaleBadgePulse();
            else
            {
                StopSaleBadgePulse();
                UpdateSaleBadgeColor(); // reset to static color
            }
        }
        
