        private void UpdateThemeButtonColors()
        {
            foreach (var kvp in _themeButtons)
            {
                string themeName = kvp.Key;
                var btn = kvp.Value;
                bool isOn = _selectedThemes.Contains(themeName);
                
                var label = btn.Q<Label>(className: "filter-btn-label");
                var icon = btn.Q<VisualElement>(className: "filter-btn-icon");
                
                if (isOn)
                {
                    btn.AddToClassList("filter-toggle-btn--active");
                    SetFilterBgVisible(btn, true);
                    UpdateFilterButtonBgColor(btn, _themeBtnOnBgColor);
                    Color onCol = GetThemeOnColor(themeName);
                    if (label != null) label.style.color = onCol;
                    if (icon != null) icon.style.unityBackgroundImageTintColor = onCol;
                    UpdateFilterRemoveIcon(btn, true, onCol);
                }
                else
                {
                    btn.RemoveFromClassList("filter-toggle-btn--active");
                    SetFilterBgVisible(btn, false);
                    UpdateFilterButtonBgColor(btn, _themeBtnOffBgColor);
                    Color offCol = GetThemeOffColor(themeName);
                    if (label != null) label.style.color = offCol;
                    if (icon != null) icon.style.unityBackgroundImageTintColor = offCol;
                    UpdateFilterRemoveIcon(btn, false, offCol);
                }
            }
        }
        
        private void ApplyLibraryBtnColors(Button btn, bool isOn, Color onColor, Color offColor)
        {
            if (btn == null) return;
            var label = btn.Q<Label>(className: "filter-btn-label");
            var icon = btn.Q<VisualElement>(className: "filter-btn-icon");
            if (isOn)
            {
                btn.AddToClassList("filter-toggle-btn--active");
                SetFilterBgVisible(btn, true);
                UpdateFilterButtonBgColor(btn, _themeBtnOnBgColor);
                if (label != null) label.style.color = onColor;
                if (icon != null) icon.style.unityBackgroundImageTintColor = onColor;
                UpdateFilterRemoveIcon(btn, true, onColor);
            }
            else
            {
                btn.RemoveFromClassList("filter-toggle-btn--active");
                SetFilterBgVisible(btn, false);
                UpdateFilterButtonBgColor(btn, _themeBtnOffBgColor);
                if (label != null) label.style.color = offColor;
                if (icon != null) icon.style.unityBackgroundImageTintColor = offColor;
                UpdateFilterRemoveIcon(btn, false, offColor);
            }
        }
        
