        private void TriggerUpdateBtnPop(VisualElement downloadBtn)
        {
            if (downloadBtn == null) return;
            int upMs   = Mathf.Max(1, Mathf.RoundToInt(_updateBtnPopDuration * 1000f));
            int downMs = Mathf.Max(1, Mathf.RoundToInt(_updateBtnPopReturnDuration * 1000f));
            int delayMs = Mathf.Max(0, Mathf.RoundToInt(_updateBtnPopLoopDelay * 1000f));
            
            // Phase 1: ease up to pop scale
            downloadBtn.style.transitionDuration = new List<TimeValue> { new TimeValue(upMs, TimeUnit.Millisecond) };
            downloadBtn.style.transitionTimingFunction = new List<EasingFunction> { new EasingFunction(EasingMode.EaseOut) };
            { float _dbs = GetDlBtnBaseScale(); downloadBtn.style.scale = new Scale(new Vector3(_updateBtnPopScale * _dbs, _updateBtnPopScale * _dbs, 1f)); }
            
            // Phase 2: after ease-up, ease back down
            downloadBtn.schedule.Execute(() => {
                downloadBtn.style.transitionDuration = new List<TimeValue> { new TimeValue(downMs, TimeUnit.Millisecond) };
                downloadBtn.style.transitionTimingFunction = new List<EasingFunction> { new EasingFunction(EasingMode.EaseIn) };
                { float _dbs = GetDlBtnBaseScale(); downloadBtn.style.scale = new Scale(new Vector3(_dbs, _dbs, 1f)); }
                
                // Phase 3: if looping, schedule next pop after return + delay
                if (_updateBtnPopLoop)
                {
                    downloadBtn.schedule.Execute(() => {
                        // Only re-trigger if still in update state (check CSS class on parent btn-visual)
                        var parentBtnVisual = downloadBtn.parent;
                        if (downloadBtn.panel != null && parentBtnVisual != null && parentBtnVisual.ClassListContains("asset-has-update"))
                            TriggerUpdateBtnPop(downloadBtn);
                    }).StartingIn(downMs + delayMs);
                }
            }).StartingIn(upMs);
        }
        
        private void UpdateDownloadButtonStates()
        {
            foreach (var item in _assetItems)
            {
                var downloadBtn = item.button.Q<VisualElement>("download-btn");
                if (downloadBtn == null) continue;
                
                var downloadIcon = downloadBtn.Q<VisualElement>("download-icon");
                var downloadPressedOverlay = downloadBtn.Q<VisualElement>("download-pressed-overlay");
                var gradientOverlay = item.button.Q<VisualElement>("asset-btn-gradient");
                
                // Get the type color for download state
                var (themeColor, _) = GetAssetTypeColors(item.type);
                
                switch (_debugDownloadState)
                {
                    case 0: // Download
                        downloadBtn.style.transitionDuration = new List<TimeValue> { new TimeValue(150, TimeUnit.Millisecond) };
                        { float _dbs = GetDlBtnBaseScale(); downloadBtn.style.scale = new Scale(new Vector3(_dbs, _dbs, 1f)); }
                        // Use grey color if not owned, otherwise type color
                        if (item.getOwned())
                        {
                            downloadBtn.style.unityBackgroundImageTintColor = _downloadBtnWhiteBg ? new Color(0.094f, 0.078f, 0.145f, 1f) : themeColor;
                            if (gradientOverlay != null)
                                gradientOverlay.style.unityBackgroundImageTintColor = themeColor;
                        }
                        else
                        {
                            downloadBtn.style.unityBackgroundImageTintColor = _notOwnedBtnColor;
                            if (gradientOverlay != null)
                                gradientOverlay.style.unityBackgroundImageTintColor = 
                                    (item.isOnSale && _showSaleBadges) ? _saleGradientColor : _cartBtnColor;
                        }
                        if (downloadIcon != null)
                        {
                            if (_downloadIcon != null)
                                downloadIcon.style.backgroundImage = new StyleBackground(_downloadIcon);
                            downloadIcon.style.unityBackgroundImageTintColor = _downloadBtnWhiteBg ? Color.white : Color.black;
                        }
                        downloadBtn.pickingMode = PickingMode.Position;
                        break;
                        
                    case 1: // Installed
                        downloadBtn.style.transitionDuration = new List<TimeValue> { new TimeValue(150, TimeUnit.Millisecond) };
                        { float _dbs = GetDlBtnBaseScale(); downloadBtn.style.scale = new Scale(new Vector3(_dbs, _dbs, 1f)); }
                        downloadBtn.style.unityBackgroundImageTintColor = _installedBtnColor;
                        if (gradientOverlay != null && item.getOwned())
                            gradientOverlay.style.unityBackgroundImageTintColor = _installedBtnColor;
                        else if (gradientOverlay != null)
                            gradientOverlay.style.unityBackgroundImageTintColor = 
                                (item.isOnSale && _showSaleBadges) ? _saleGradientColor : _cartBtnColor;
                        if (downloadIcon != null)
                        {
                            if (_installedIcon != null)
                                downloadIcon.style.backgroundImage = new StyleBackground(_installedIcon);
                            downloadIcon.style.unityBackgroundImageTintColor = Color.white;
                        }
                        // Show pressed overlay green for installed resting state
                        if (downloadPressedOverlay != null)
                        {
                            downloadPressedOverlay.style.display = DisplayStyle.Flex;
                            downloadPressedOverlay.style.unityBackgroundImageTintColor = _installedBtnColor;
                        }
                        // Non-interactive
                        downloadBtn.pickingMode = PickingMode.Position; // Keep clickable for uninstall
                        break;
                        
                    case 2: // Update
                        downloadBtn.style.unityBackgroundImageTintColor = _updateBtnColor;
                        if (gradientOverlay != null && item.getOwned())
                            gradientOverlay.style.unityBackgroundImageTintColor = _updateBtnColor;
                        else if (gradientOverlay != null)
                            gradientOverlay.style.unityBackgroundImageTintColor = 
                                (item.isOnSale && _showSaleBadges) ? _saleGradientColor : _cartBtnColor;
                        if (downloadIcon != null)
                        {
                            if (_updateIcon != null)
                                downloadIcon.style.backgroundImage = new StyleBackground(_updateIcon);
                            downloadIcon.style.unityBackgroundImageTintColor = _downloadBtnWhiteBg ? Color.white : Color.black;
                        }
                        downloadBtn.pickingMode = PickingMode.Position;
                        TriggerUpdateBtnPop(downloadBtn);
                        break;
                }
                
                // If this button is currently selected, refresh its selected overlay and bg to match the new state
                if (item.getSelected())
                {
                    var assetBg = item.btnVisual;
                    var selOverlay = item.button.Q<VisualElement>("asset-btn-selected");
                    if (item.getOwned())
                    {
                        Color selColor = themeColor;
                        if (assetBg  != null) assetBg.style.unityBackgroundImageTintColor  = selColor;
                        if (selOverlay != null) selOverlay.style.unityBackgroundImageTintColor = selColor;
                    }
                    // Not-owned stays cart color — already set correctly at selection time
                }
            }
        }
        
        private void RebuildNotOwnedIcons()
        {
            foreach (var item in _assetItems)
            {
                if (item.getOwned()) continue;
                var assetIcon = item.button.Q<VisualElement>("asset-icon");
                if (assetIcon == null) continue;
                // Not-owned icons show the desaturated copy (no colour tint). Fall back to the
                // colored source only if no desaturated copy is available.
                Texture2D showTex = null;
                if (_iconDesaturated.TryGetValue(assetIcon, out var dt) && dt != null) showTex = dt;
                else if (_iconSourceData.TryGetValue(assetIcon, out var srcTex) && srcTex != null) showTex = srcTex;
                if (showTex == null) continue;
                
                assetIcon.style.backgroundImage = new StyleBackground(showTex);
                assetIcon.style.opacity = _notOwnedIconOpacity;
                assetIcon.style.unityBackgroundImageTintColor = _notOwnedIconTint;
                assetIcon.MarkDirtyRepaint();
            }
        }
        
        private void UpdateNotOwnedButtonColors()
        {
            foreach (var item in _assetItems)
            {
                // Only update if not owned
                if (!item.getOwned())
                {
                    var downloadBtn = item.button.Q<VisualElement>("download-btn");
                    if (downloadBtn != null)
                    {
                        downloadBtn.style.unityBackgroundImageTintColor = _notOwnedBtnColor;
                    }
                    // Update gradient color for not owned
                    var gradientOverlay = item.button.Q<VisualElement>("asset-btn-gradient");
                    if (gradientOverlay != null)
                    {
                        gradientOverlay.style.unityBackgroundImageTintColor = 
                            (item.isOnSale && _showSaleBadges) ? _saleGradientColor : _cartBtnColor;
                    }
                }
            }
        }
        
        private void UpdateCartButtonColors()
        {
            foreach (var item in _assetItems)
            {
                var cartBtn = item.button.Q<Button>("cart-btn");
                if (cartBtn != null)
                {
                    cartBtn.style.unityBackgroundImageTintColor = _cartBtnColor;
                }
                // Also update gradient and icon tint for not-owned assets
                if (!item.getOwned())
                {
                    var gradientOverlay = item.button.Q<VisualElement>("asset-btn-gradient");
                    if (gradientOverlay != null)
                        gradientOverlay.style.unityBackgroundImageTintColor = 
                            (item.isOnSale && _showSaleBadges) ? _saleGradientColor : _cartBtnColor;
                    
                    var assetIcon = item.button.Q<VisualElement>("asset-icon");
                    if (assetIcon != null)
                    {
                        // Apply the configurable not-owned tint to the desaturated icon.
                        assetIcon.style.unityBackgroundImageTintColor = _notOwnedIconTint;
                        assetIcon.style.opacity = _notOwnedIconOpacity;
                    }
                }
            }
        }
        
        private void UpdateButtonTransitions()
        {
            var easingFunc = _easingType switch
            {
                1 => EasingMode.EaseOut,
                2 => EasingMode.EaseIn,
                3 => EasingMode.EaseInOut,
                _ => EasingMode.Linear
            };
            
            foreach (var item in _assetItems)
            {
                item.button.style.transitionDuration = new List<TimeValue> { new TimeValue(_animDuration, TimeUnit.Millisecond) };
                item.button.style.transitionTimingFunction = new List<EasingFunction> { new EasingFunction(easingFunc) };
                item.button.style.transitionProperty = new List<StylePropertyName> { new StylePropertyName("scale") };
            }
        }
        
        private void UpdateIconScale()
        {
            foreach (var item in _assetItems)
            {
                var icon = item.button.Q<VisualElement>(className: "asset-btn-icon");
                if (icon != null)
                {
                    // Scale from center using percentage positioning
                    float offset = (1f - _assetIconScale) * 50f; // 50% offset for centering
                    float size = _assetIconScale * 100f;
                    icon.style.left = new Length(offset, LengthUnit.Percent);
                    icon.style.top = new Length(offset, LengthUnit.Percent);
                    icon.style.right = new Length(offset, LengthUnit.Percent);
                    icon.style.bottom = new Length(offset, LengthUnit.Percent);
                }
            }
        }
        
        private void AddBanner(VisualElement parent)
        {
            _bannerButton = new VisualElement();
            _bannerButton.name = "banner-button";
            _bannerButton.AddToClassList("banner-button");
            _bannerButton.style.height = _bannerHeight;
            _bannerButton.style.left = _bannerLeftGap;
            _bannerButton.style.right = _bannerRightGap;
            // "Banner Tint" is the banner's background color (behind the banner images).
            // Default OFF (transparent); the "Show Background" debug toggle turns it on.
            _bannerButton.style.backgroundColor = Color.clear;
            _bannerButton.RegisterCallback<ClickEvent>(evt => OnBannerClicked());
            _bannerButton.RegisterCallback<MouseDownEvent>(evt => _bannerButton.AddToClassList("banner-button--active"));
            _bannerButton.RegisterCallback<MouseUpEvent>(evt => _bannerButton.RemoveFromClassList("banner-button--active"));
            _bannerButton.RegisterCallback<MouseLeaveEvent>(evt => {
                _bannerButton.RemoveFromClassList("banner-button--active");
                // Restore icon color on mouse leave
                if (_shopNowIcon != null)
                    _shopNowIcon.style.unityBackgroundImageTintColor = _shopNowIconColor;
            });
            _bannerButton.RegisterCallback<MouseEnterEvent>(evt => {
                // Make icon white on hover
                if (_shopNowIcon != null)
                    _shopNowIcon.style.unityBackgroundImageTintColor = Color.white;
            });
            parent.Add(_bannerButton);
            
            _bannerLeft = new VisualElement();
            _bannerLeft.name = "banner-left";
            _bannerLeft.AddToClassList("banner-left");
            _bannerLeft.style.height = _bannerHeight;
            _bannerLeft.style.width = _bannerHeight * (52f / 42f);
            _bannerLeft.pickingMode = PickingMode.Ignore;
            var leftTex = LoadImage("Banner", "Banner_Left");
            if (leftTex != null) _bannerLeft.style.backgroundImage = new StyleBackground(leftTex);
            _bannerLeft.style.unityBackgroundImageTintColor = _bannerTintColor;
            _bannerButton.Add(_bannerLeft);
            
            _bannerCenter = new VisualElement();
            _bannerCenter.name = "banner-center";
            _bannerCenter.AddToClassList("banner-center");
            _bannerCenter.style.height = _bannerHeight;
            _bannerCenter.pickingMode = PickingMode.Ignore;
            var centerTex = LoadImage("Banner", "Banner_Center");
            if (centerTex != null) _bannerCenter.style.backgroundImage = new StyleBackground(centerTex);
            _bannerCenter.style.unityBackgroundImageTintColor = _bannerTintColor;
            _bannerButton.Add(_bannerCenter);
            
            _bannerTextContainer = new VisualElement();
            _bannerTextContainer.name = "banner-text-container";
            _bannerTextContainer.AddToClassList("banner-text-container");
            _bannerTextContainer.style.position = Position.Absolute;
            _bannerTextContainer.style.top = 0;
            _bannerTextContainer.style.left = 0;
            _bannerTextContainer.style.right = 0;
            _bannerTextContainer.style.bottom = 0;
            _bannerTextContainer.pickingMode = PickingMode.Ignore;
            // Parented to the banner button (not the center image) so it can be layered above
            // all banner images and the overlay. The title is center-aligned, so spanning the
            // full banner width keeps it centered the same as before.
            _bannerButton.Add(_bannerTextContainer);
            
            _bannerTitle = new Label(_bannerTitleText);
            _bannerTitle.name = "banner-title";
            _bannerTitle.AddToClassList("banner-title");
            _bannerTitle.style.position = Position.Absolute;
            _bannerTitle.style.top = _bannerTitleY;
            _bannerTitle.style.left = 0;
            _bannerTitle.style.right = 0;
            _bannerTitle.style.translate = new Translate(_bannerTitleX, 0);
            _bannerTitle.style.fontSize = _bannerTitleFontSize;
            _bannerTitle.style.color = _bannerTextColor;
            _bannerTitle.style.unityTextAlign = TextAnchor.MiddleCenter;
            _bannerTitle.style.unityFontStyleAndWeight = _bannerLine1Bold ? FontStyle.Bold : FontStyle.Normal;
            _bannerTitle.pickingMode = PickingMode.Ignore;
            if (_titleFont != null)
                _bannerTitle.style.unityFontDefinition = FontDefinition.FromFont(_titleFont);
            _bannerTextContainer.Add(_bannerTitle);
            
            _bannerRight = new VisualElement();
            _bannerRight.name = "banner-right";
            _bannerRight.AddToClassList("banner-right");
            _bannerRight.style.height = _bannerHeight;
            _bannerRight.style.width = _bannerHeight * (52f / 42f);
            _bannerRight.pickingMode = PickingMode.Ignore;
            var rightTex = LoadImage("Banner", "Banner_Right");
            if (rightTex != null) _bannerRight.style.backgroundImage = new StyleBackground(rightTex);
            _bannerRight.style.unityBackgroundImageTintColor = _bannerTintColor;
            _bannerButton.Add(_bannerRight);
            
            // Shop Now button - centered in banner, contains the subtitle text
            _shopNowContainer = new VisualElement();
            _shopNowContainer.name = "shop-now-container";
            _shopNowContainer.AddToClassList("shop-now-container");
            _shopNowContainer.style.position = Position.Absolute;
            _shopNowContainer.style.left = Length.Percent(50);
            _shopNowContainer.style.translate = new Translate(Length.Percent(-50), 0);
            _shopNowContainer.style.marginLeft = _shopNowXOffset;
            _shopNowContainer.style.bottom = _shopNowY;
            _shopNowContainer.style.height = _shopNowHeight;
            _shopNowContainer.style.paddingLeft = _shopNowPaddingH;
            _shopNowContainer.style.paddingRight = _shopNowPaddingH - 2; // slightly less on right
            _shopNowContainer.style.unityBackgroundImageTintColor = _shopNowBgColor;
            _shopNowContainer.pickingMode = PickingMode.Ignore;
            var btnBgTex = LoadImage("Buttons", "Button_ShopNow_BG");
            if (btnBgTex != null) _shopNowContainer.style.backgroundImage = new StyleBackground(btnBgTex);
            _bannerButton.Add(_shopNowContainer);
            
            // Subtitle text is now inside the shop now button
            _bannerSubtitle = new Label(_bannerSubtitleText);
            _bannerSubtitle.name = "banner-subtitle";
            _bannerSubtitle.AddToClassList("banner-subtitle");
            _bannerSubtitle.style.fontSize = _bannerSubtitleFontSize;
            _bannerSubtitle.style.color = _shopNowTextColor;
            _bannerSubtitle.style.marginTop = _shopNowTextY;
            _bannerSubtitle.style.unityFontStyleAndWeight = _bannerLine2Bold ? FontStyle.Bold : FontStyle.Normal;
            _bannerSubtitle.pickingMode = PickingMode.Ignore;
            if (_titleFont != null)
                _bannerSubtitle.style.unityFontDefinition = FontDefinition.FromFont(_titleFont);
            _shopNowContainer.Add(_bannerSubtitle);
            
            _shopNowIcon = new VisualElement();
            _shopNowIcon.name = "shop-now-icon";
            _shopNowIcon.AddToClassList("shop-now-icon");
            _shopNowIcon.style.width = _shopNowIconSize;
            _shopNowIcon.style.height = _shopNowIconSize;
            _shopNowIcon.style.marginLeft = _shopNowIconMargin;
            _shopNowIcon.style.marginTop = _shopNowIconY;
            _shopNowIcon.pickingMode = PickingMode.Ignore;
            var iconTex = LoadImage("Icons/Misc", "Icon_ExternalLink");
            if (iconTex != null)
            {
                _shopNowIcon.style.backgroundImage = new StyleBackground(iconTex);
                _shopNowIcon.style.unityBackgroundImageTintColor = _shopNowIconColor;
            }
            _shopNowContainer.Add(_shopNowIcon);
            
            // Banner overlay images — sit on top of the banner background, preserving their ratio
            float overlayRatio = 974f / 98f; // natural aspect ratio of overlay images
            float overlayW = _bannerHeight * overlayRatio;
            
            // Right overlay — anchored to right edge
            var overlayRight = new VisualElement();
            overlayRight.name = "banner-overlay-right";
            overlayRight.pickingMode = PickingMode.Ignore;
            overlayRight.style.position = Position.Absolute;
            overlayRight.style.top = 0;
            overlayRight.style.right = 0;
            overlayRight.style.width = overlayW;
            overlayRight.style.height = _bannerHeight;
            overlayRight.style.SetBackgroundStretchToFill();
            var overlayRightTex = LoadImage("Banner", "Banner_Overlay_Right");
            if (overlayRightTex != null) overlayRight.style.backgroundImage = new StyleBackground(overlayRightTex);
            _bannerButton.Add(overlayRight);
            
            // Pre-apply the last-known banner image from disk immediately, before the server
            // verify completes, so a cached banner shows from the first frame instead of popping
            // in after the tool finishes loading. ApplyServerBanner re-applies once verify
            // returns (same image if the version is unchanged, so no visible change).
            PreloadCachedBannerImage();
            
            // Layer the text, shop-now pill, and icon above all banner images and the overlay.
            // BringToFront reorders each to be the last sibling (rendered on top). The pill's
            // subtitle + icon are its children, so they ride along above everything.
            _bannerTextContainer?.BringToFront();
            _shopNowContainer?.BringToFront();
            
            // Build the countdown timer (hidden until a server banner enables it). Positioned
            // where the shop-now pill sits; uses the same styling as the exclusive-deal timer.
            BuildBannerTimer();
        }
        
        // Creates the banner countdown timer (DAYS / HOURS / MINUTES / SECONDS), styled to match
        // the exclusive-deal timer. Hidden by default; ApplyServerBanner shows it (and hides the
        // shop-now pill) when the banner config enables a timer.
        // Applies per-banner timer style overrides (text color, X/Y position, scale) from the admin
        // config. Empty fields fall back to the tool defaults already set in BuildBannerTimer.
        private void ApplyBannerTimerStyle(SyntyStoreService.BannerConfig cfg)
        {
            if (_bannerTimer == null || cfg == null) return;
            float num;
            // Position: X -> marginLeft (centered element), Y -> bottom.
            float x = TryParseInv(cfg.timerX, out num) ? num : _shopNowXOffset;
            float y = TryParseInv(cfg.timerY, out num) ? num : _shopNowY;
            _bannerTimer.style.marginLeft = x;
            _bannerTimer.style.bottom = y;
            // Scale.
            float scale = TryParseInv(cfg.timerScale, out num) ? num : _dealTimerScale;
            _bannerTimer.style.scale = new Scale(new Vector3(scale, scale, 1f));
            // Digit color (the countdown numbers).
            if (!string.IsNullOrEmpty(cfg.timerTextColor) &&
                ColorUtility.TryParseHtmlString(cfg.timerTextColor, out var digitCol))
            {
                if (_bannerTimerDays  != null) _bannerTimerDays.style.color  = digitCol;
                if (_bannerTimerHours != null) _bannerTimerHours.style.color = digitCol;
                if (_bannerTimerMins  != null) _bannerTimerMins.style.color  = digitCol;
                if (_bannerTimerSecs  != null) _bannerTimerSecs.style.color  = digitCol;
            }
            else
            {
                if (_bannerTimerDays  != null) _bannerTimerDays.style.color  = _dealTimerBoxTextColor;
                if (_bannerTimerHours != null) _bannerTimerHours.style.color = _dealTimerBoxTextColor;
                if (_bannerTimerMins  != null) _bannerTimerMins.style.color  = _dealTimerBoxTextColor;
                if (_bannerTimerSecs  != null) _bannerTimerSecs.style.color  = _dealTimerBoxTextColor;
            }
            // Label color (DAYS / HOURS / MINUTES / SECONDS).
            Color labelCol = (!string.IsNullOrEmpty(cfg.timerLabelColor) &&
                ColorUtility.TryParseHtmlString(cfg.timerLabelColor, out var lc)) ? lc : _dealTimerLabelColor;
            _bannerTimer.Query<Label>(className: "banner-timer-unit-label").ForEach(l => l.style.color = labelCol);
            // Box background color (the rounded boxes behind the digits).
            Color boxBg = (!string.IsNullOrEmpty(cfg.timerBoxColor) &&
                ColorUtility.TryParseHtmlString(cfg.timerBoxColor, out var bb)) ? bb : _dealTimerBoxColor;
            if (_bannerTimerDays  != null) _bannerTimerDays.style.backgroundColor  = boxBg;
            if (_bannerTimerHours != null) _bannerTimerHours.style.backgroundColor = boxBg;
            if (_bannerTimerMins  != null) _bannerTimerMins.style.backgroundColor  = boxBg;
            if (_bannerTimerSecs  != null) _bannerTimerSecs.style.backgroundColor  = boxBg;
            // Colon color (the ":" separators).
            Color colonCol = (!string.IsNullOrEmpty(cfg.timerColonColor) &&
                ColorUtility.TryParseHtmlString(cfg.timerColonColor, out var cc)) ? cc : _dealTimerColonColor;
            _bannerTimer.Query<Label>(className: "banner-timer-colon").ForEach(l => l.style.color = colonCol);
        }

        private void BuildBannerTimer()
        {
            if (_bannerButton == null) return;
            _bannerTimer = new VisualElement();
            _bannerTimer.name = "banner-timer";
            _bannerTimer.pickingMode = PickingMode.Ignore;
            _bannerTimer.style.position = Position.Absolute;
            _bannerTimer.style.left = Length.Percent(50);
            _bannerTimer.style.translate = new Translate(Length.Percent(-50), 0);
            _bannerTimer.style.marginLeft = _shopNowXOffset;
            _bannerTimer.style.bottom = _shopNowY;
            _bannerTimer.style.flexDirection = FlexDirection.Row;
            _bannerTimer.style.alignItems = Align.FlexStart;
            _bannerTimer.style.scale = new Scale(new Vector3(_dealTimerScale, _dealTimerScale, 1f));
            _bannerTimer.style.display = DisplayStyle.None;
            
            Label MakeBox()
            {
                var box = new Label("00");
                box.pickingMode = PickingMode.Ignore;
                box.style.width = _dealTimerBoxWidth;
                box.style.height = _dealTimerBoxHeight;
                box.style.backgroundColor = _dealTimerBoxColor;
                box.style.borderTopLeftRadius = _dealTimerBoxRadius;
                box.style.borderTopRightRadius = _dealTimerBoxRadius;
                box.style.borderBottomLeftRadius = _dealTimerBoxRadius;
                box.style.borderBottomRightRadius = _dealTimerBoxRadius;
                box.style.color = _dealTimerBoxTextColor;
                box.style.fontSize = _dealTimerBoxFontSize;
                box.style.unityFontStyleAndWeight = FontStyle.Bold;
                box.style.unityTextAlign = TextAnchor.MiddleCenter;
                if (_newakeFont != null) box.style.unityFontDefinition = FontDefinition.FromFont(_newakeFont);
                return box;
            }
            Label MakeUnitLabel(string text)
            {
                var lbl = new Label(text);
                lbl.pickingMode = PickingMode.Ignore;
                lbl.AddToClassList("banner-timer-unit-label");
                lbl.style.color = _dealTimerLabelColor;
                lbl.style.fontSize = _dealTimerLabelFontSize;
                lbl.style.unityFontStyleAndWeight = FontStyle.Bold;
                lbl.style.unityTextAlign = TextAnchor.MiddleCenter;
                lbl.style.marginTop = _dealTimerLabelMarginTop;
                lbl.style.translate = new Translate(_dealTimerLabelX, _dealTimerLabelY);
                lbl.style.minWidth = _dealTimerBoxWidth;
                if (_newakeFont != null) lbl.style.unityFontDefinition = FontDefinition.FromFont(_newakeFont);
                return lbl;
            }
            Label MakeColon()
            {
                var c = new Label(":");
                c.pickingMode = PickingMode.Ignore;
                c.AddToClassList("banner-timer-colon");
                c.style.color = _dealTimerColonColor;
                c.style.fontSize = _dealTimerColonFontSize;
                c.style.height = _dealTimerBoxHeight;
                c.style.unityFontStyleAndWeight = FontStyle.Bold;
                c.style.unityTextAlign = TextAnchor.MiddleCenter;
                c.style.marginLeft = _dealTimerGap;
                c.style.marginRight = _dealTimerGap;
                c.style.translate = new Translate(0, _dealTimerColonY);
                if (_newakeFont != null) c.style.unityFontDefinition = FontDefinition.FromFont(_newakeFont);
                return c;
            }
            VisualElement MakeUnit(Label box, string labelText)
            {
                var col = new VisualElement();
                col.pickingMode = PickingMode.Ignore;
                col.style.flexDirection = FlexDirection.Column;
                col.style.alignItems = Align.Center;
                col.Add(box);
                col.Add(MakeUnitLabel(labelText));
                return col;
            }
            
            _bannerTimerDays  = MakeBox();
            _bannerTimerHours = MakeBox();
            _bannerTimerMins  = MakeBox();
            _bannerTimerSecs  = MakeBox();
            _bannerTimer.Add(MakeUnit(_bannerTimerDays,  "DAYS"));
            _bannerTimer.Add(MakeColon());
            _bannerTimer.Add(MakeUnit(_bannerTimerHours, "HOURS"));
            _bannerTimer.Add(MakeColon());
            _bannerTimer.Add(MakeUnit(_bannerTimerMins,  "MINUTES"));
            _bannerTimer.Add(MakeColon());
            _bannerTimer.Add(MakeUnit(_bannerTimerSecs,  "SECONDS"));
            _bannerButton.Add(_bannerTimer);
            _bannerTimer.BringToFront();
        }
        
        // Runs the banner countdown. When time runs out, hides the timer and restores the
        // shop-now pill so the banner stays usable.
        private void ScheduleBannerCountdown(System.DateTime endTimeUtc)
        {
            if (_bannerTimer == null) return;
            IVisualElementScheduledItem task = null;
            task = _bannerTimer.schedule.Execute(() =>
            {
                if (_reloadingDomain || _bannerTimer.panel == null) { SafePause(task); return; }
                var remaining = endTimeUtc - System.DateTime.UtcNow;
                if (remaining.TotalSeconds <= 0)
                {
                    if (_bannerTimerDays != null) _bannerTimerDays.text = "00";
                    if (_bannerTimerHours != null) _bannerTimerHours.text = "00";
                    if (_bannerTimerMins != null) _bannerTimerMins.text = "00";
                    if (_bannerTimerSecs != null) _bannerTimerSecs.text = "00";
                    // Time's up: hide the timer, restore the shop-now pill.
                    _bannerTimer.style.display = DisplayStyle.None;
                    if (_shopNowContainer != null) _shopNowContainer.style.display = DisplayStyle.Flex;
                    SafePause(task);
                    return;
                }
                if (_bannerTimerDays != null)  _bannerTimerDays.text  = ((int)remaining.TotalDays).ToString("00");
                if (_bannerTimerHours != null) _bannerTimerHours.text = remaining.Hours.ToString("00");
                if (_bannerTimerMins != null)  _bannerTimerMins.text  = remaining.Minutes.ToString("00");
                if (_bannerTimerSecs != null)  _bannerTimerSecs.text  = remaining.Seconds.ToString("00");
            }).Every(1000);
            TrackScheduledItem(task);
        }
        
        private void AddBackgroundGradient(VisualElement parent)
        {
            _bgGradient = new VisualElement();
            _bgGradient.name = "bg-gradient";
            _bgGradient.pickingMode = PickingMode.Ignore;
            _bgGradient.style.position = Position.Absolute;
            _bgGradient.style.top = 0;
            _bgGradient.style.left = 0;
            _bgGradient.style.right = 0;
            _bgGradient.style.bottom = 0;
            _bgGradient.style.marginLeft = _bgGradientX;
            _bgGradient.style.marginTop = _bgGradientY;
            _bgGradient.style.transformOrigin = new TransformOrigin(Length.Percent(50), Length.Percent(0));
            _bgGradient.style.scale = new Scale(new Vector3(_bgGradientScaleX, _bgGradientScaleY, 1f));
            var gradTex = LoadImage("Background", "Background_Gradient");
            if (gradTex != null)
            {
                _bgGradient.style.backgroundImage = new StyleBackground(gradTex);
                _bgGradient.style.SetBackgroundStretchToFill();
            }
            
            // Set initial state based on Synty Pass
            var initColor = _licenseSyntyPass ? _bgGradientOnColor : _bgGradientOffColor;
            var initOpacity = _licenseSyntyPass ? _bgGradientOnOpacity : _bgGradientOffOpacity;
            _bgGradient.style.unityBackgroundImageTintColor = initColor;
            _bgGradient.style.opacity = initOpacity;
            
            // Setup transitions for smooth state changes
            _bgGradient.style.transitionProperty = new List<StylePropertyName> {
                new StylePropertyName("opacity"),
                new StylePropertyName("-unity-background-image-tint-color"),
                new StylePropertyName("scale")
            };
            _bgGradient.style.transitionDuration = new List<TimeValue> {
                new TimeValue((int)_bgGradientEaseMs, TimeUnit.Millisecond),
                new TimeValue((int)_bgGradientEaseMs, TimeUnit.Millisecond),
                new TimeValue((int)_bgGradientEaseMs, TimeUnit.Millisecond)
            };
            _bgGradient.style.transitionTimingFunction = new List<EasingFunction> {
                new EasingFunction(EasingMode.EaseOut),
                new EasingFunction(EasingMode.EaseOut),
                new EasingFunction(EasingMode.EaseOut)
            };
            
            parent.Add(_bgGradient);
            
            // ── Bottom background gradient ──
            _bottomGradient = new VisualElement();
            _bottomGradient.name = "bottom-gradient";
            _bottomGradient.pickingMode = PickingMode.Ignore;
            _bottomGradient.style.position = Position.Absolute;
            _bottomGradient.style.left = 0;
            _bottomGradient.style.right = 0;
            _bottomGradient.style.bottom = 0;
            _bottomGradient.style.height = Length.Percent(100);
            _bottomGradient.style.marginLeft = _bottomGradientX;
            _bottomGradient.style.marginBottom = _bottomGradientY;
            // Origin at the bottom so scaleY shrinks the band toward the bottom edge. No vertical
            // flip — the gradient's dense end stays at the bottom where the glow should be.
            _bottomGradient.style.transformOrigin = new TransformOrigin(Length.Percent(50), Length.Percent(100));
            _bottomGradient.style.scale = new Scale(new Vector3(_bottomGradientFlipX ? -_bottomGradientScaleX : _bottomGradientScaleX, _bottomGradientFlipY ? -_bottomGradientScaleY : _bottomGradientScaleY, 1f));
            _bottomGradient.style.rotate = new Rotate(new Angle(_bottomGradientRotation, AngleUnit.Degree));
            var botGradTex = LoadImage("Background", "Background_Gradient");
            if (botGradTex != null)
            {
                _bottomGradient.style.backgroundImage = new StyleBackground(botGradTex);
                _bottomGradient.style.SetBackgroundStretchToFill();
            }
            _bottomGradient.style.unityBackgroundImageTintColor = _bottomGradientDownloadColor;
            _bottomGradient.style.opacity = 0f; // hidden until an action is selected
            _bottomGradient.style.transitionProperty = new List<StylePropertyName> {
                new StylePropertyName("opacity"),
                new StylePropertyName("-unity-background-image-tint-color"),
                new StylePropertyName("scale")
            };
            _bottomGradient.style.transitionDuration = new List<TimeValue> {
                new TimeValue((int)_bottomGradientEaseMs, TimeUnit.Millisecond),
                new TimeValue((int)_bottomGradientEaseMs, TimeUnit.Millisecond),
                new TimeValue((int)_bottomGradientEaseMs, TimeUnit.Millisecond)
            };
            parent.Add(_bottomGradient);
            // Apply baked position/scale/rotation immediately so it's correct before any debug edit
            // and before the first action selection drives its color/opacity.
            ApplyBottomGradientLayout();
        }
        
        private void SetBgGradientState(Color color, float opacity)
        {
            if (_bgGradient == null) return;
            _bgGradient.style.unityBackgroundImageTintColor = color;
            _bgGradient.style.opacity = opacity;
        }
        
        private void SetBgGradientImmediate(Color color, float opacity)
        {
            if (_bgGradient == null) return;
            // Temporarily disable transitions for instant update
            _bgGradient.style.transitionDuration = new List<TimeValue> {
                new TimeValue(0, TimeUnit.Millisecond),
                new TimeValue(0, TimeUnit.Millisecond),
                new TimeValue(0, TimeUnit.Millisecond)
            };
            _bgGradient.style.unityBackgroundImageTintColor = color;
            _bgGradient.style.opacity = opacity;
        }
        
        private void RestoreBgGradientTransitions()
        {
            if (_bgGradient == null) return;
            _bgGradient.style.transitionDuration = new List<TimeValue> {
                new TimeValue((int)_bgGradientEaseMs, TimeUnit.Millisecond),
                new TimeValue((int)_bgGradientEaseMs, TimeUnit.Millisecond),
                new TimeValue((int)_bgGradientEaseMs, TimeUnit.Millisecond)
            };
        }
        
        private void TriggerGradient100ScalePop()
        {
            if (_bgGradient == null) return;
            
            // Ease up to the 100% scale Y
            _bgGradient.style.transitionDuration = new List<TimeValue> {
                new TimeValue((int)_bgGradientEaseMs, TimeUnit.Millisecond),
                new TimeValue((int)_bgGradientEaseMs, TimeUnit.Millisecond),
                new TimeValue((int)_bgGradient100PopMs, TimeUnit.Millisecond)
            };
            _bgGradient.style.transitionTimingFunction = new List<EasingFunction> {
                new EasingFunction(EasingMode.EaseOut),
                new EasingFunction(EasingMode.EaseOut),
                new EasingFunction(EasingMode.EaseOut)
            };
            _bgGradient.style.scale = new Scale(new Vector3(_bgGradientScaleX, _bgGradient100ScaleY, 1f));
            
            // Ease back down to normal scale Y
            _bgGradient.schedule.Execute(() => {
                if (_bgGradient == null) return;
                _bgGradient.style.transitionDuration = new List<TimeValue> {
                    new TimeValue((int)_bgGradientEaseMs, TimeUnit.Millisecond),
                    new TimeValue((int)_bgGradientEaseMs, TimeUnit.Millisecond),
                    new TimeValue((int)_bgGradient100ReturnMs, TimeUnit.Millisecond)
                };
                _bgGradient.style.transitionTimingFunction = new List<EasingFunction> {
                    new EasingFunction(EasingMode.EaseOut),
                    new EasingFunction(EasingMode.EaseOut),
                    new EasingFunction(EasingMode.EaseInOut)
                };
                _bgGradient.style.scale = new Scale(new Vector3(_bgGradientScaleX, _bgGradientScaleY, 1f));
            }).StartingIn((long)_bgGradient100PopMs);
        }
        
        private void AddLogo(VisualElement parent)
        {
            // Corner background behind the logo
            var logoBg = new VisualElement();
            _logoBgCorner = logoBg;
            logoBg.name = "logo-bg-corner";
            logoBg.pickingMode = PickingMode.Ignore;
            logoBg.style.position = Position.Absolute;
            logoBg.style.left = 0;
            logoBg.style.top = 0;
            logoBg.style.transformOrigin = new TransformOrigin(0, 0, 0); // pivot top-left
            var logoBgTex = LoadImage("Logo", "LogoBackground_Corner");
            if (logoBgTex != null)
            {
                logoBg.style.backgroundImage = new StyleBackground(logoBgTex);
                logoBg.style.SetBackgroundStretchToFill();
                float bgRatio = (float)logoBgTex.height / logoBgTex.width;
                logoBg.style.width = logoBgTex.width;
                logoBg.style.height = logoBgTex.width * bgRatio;
            }
            logoBg.style.scale = new Scale(new Vector3(_logoBgScale, _logoBgScale, 1f));
            parent.Add(logoBg);
            
            _logo = new VisualElement();
            _logo.name = "logo";
            _logo.AddToClassList("logo");
            _logo.pickingMode = PickingMode.Position;
            _logo.style.width = _logoWidth;
            _logo.style.height = _logoHeight;
            _logo.style.left = _logoX;
            _logo.style.top = _logoY;
            _logo.style.transformOrigin = new TransformOrigin(Length.Percent(50), Length.Percent(50));
            var logoTex = LoadImage("Logo", "Synty_Logo_Large");
            if (logoTex != null) _logo.style.backgroundImage = new StyleBackground(logoTex);
            
            // Transition for smooth scale animation
            _logo.style.transitionProperty = new List<StylePropertyName> { 
                new StylePropertyName("scale")
            };
            _logo.style.transitionDuration = new List<TimeValue> { 
                new TimeValue(100, TimeUnit.Millisecond)
            };
            _logo.style.transitionTimingFunction = new List<EasingFunction> { 
                new EasingFunction(EasingMode.EaseOut)
            };
            
            // Hover pop animation
            _logo.RegisterCallback<MouseEnterEvent>(evt => {
                _logo.style.scale = new Scale(new Vector3(1.05f, 1.05f, 1f));
            });
            _logo.RegisterCallback<MouseLeaveEvent>(evt => {
                _logo.style.scale = new Scale(Vector3.one);
            });
            
            // Click opens Synty Store
            _logo.RegisterCallback<MouseUpEvent>(evt => {
                if (evt.button == 0)
                {
                    Application.OpenURL(SyntyCatalogBridge.STORE_AFFILIATE_URL);
                    evt.StopPropagation();
                }
            });
            
            parent.Add(_logo);
            
            // Passport text logo (separate image, positioned independently of the icon logo).
            var textLogoTex = LoadImage("Logo", "Synty_Importer_TextLogo");
            if (textLogoTex != null)
            {
                _textLogo = new VisualElement();
                _textLogo.name = "text-logo";
                _textLogo.pickingMode = PickingMode.Ignore;
                _textLogo.style.position = Position.Absolute;
                _textLogo.style.backgroundImage = new StyleBackground(textLogoTex);
                _textLogo.style.SetBackgroundScaleToFit();
                _textLogo.style.width = _textLogoWidth;
                _textLogo.style.height = _textLogoHeight;
                _textLogo.style.left = _textLogoX;
                _textLogo.style.top = _textLogoY;
                _textLogo.style.scale = new Scale(new Vector3(_textLogoScale, _textLogoScale, 1f));
                parent.Add(_textLogo);
            }
        }
        
        // Applies shadow scale/offset/opacity live to both header-button shadows.
        private void ApplyButtonShadows()
        {
            float notifBtnSize = _profileBtnSize;
            float notifBtnRight = _profileBtnX + _profileBtnSize + 8f;
            if (_profileBtnShadow != null)
            {
                _profileBtnShadow.style.width = _profileBtnSize;
                _profileBtnShadow.style.height = _profileBtnSize;
                _profileBtnShadow.style.right = _profileBtnX - _btnShadowOffsetX - _profileShadowExtraX;
                _profileBtnShadow.style.top = _profileBtnY + _btnShadowOffsetY;
                _profileBtnShadow.style.scale = new Scale(new Vector3(_btnShadowScale, _btnShadowScale, 1f));
                _profileBtnShadow.style.opacity = _btnShadowOpacity;
            }
            if (_notifBtnShadow != null)
            {
                _notifBtnShadow.style.width = notifBtnSize;
                _notifBtnShadow.style.height = notifBtnSize;
                _notifBtnShadow.style.right = notifBtnRight - _btnShadowOffsetX;
                _notifBtnShadow.style.top = _profileBtnY + _btnShadowOffsetY;
                _notifBtnShadow.style.scale = new Scale(new Vector3(_btnShadowScale, _btnShadowScale, 1f));
                _notifBtnShadow.style.opacity = _btnShadowOpacity;
            }
