        // Creates a black Button_Round shadow sized/positioned to sit under a round header button.
        // Added to parent BEFORE the button so it layers underneath. rightPos/topPos match the
        // button's own right/top; the offsets + scale come from the debug fields.
        private VisualElement CreateButtonShadow(VisualElement parent, float size, float rightPos, float topPos)
        {
            var shadowTex = LoadImage("Buttons", "Button_Round");
            var shadow = new VisualElement();
            shadow.name = "btn-shadow";
            shadow.pickingMode = PickingMode.Ignore;
            shadow.style.position = Position.Absolute;
            shadow.style.width = size;
            shadow.style.height = size;
            shadow.style.right = rightPos - _btnShadowOffsetX;
            shadow.style.top = topPos + _btnShadowOffsetY;
            shadow.style.transformOrigin = new TransformOrigin(Length.Percent(50), Length.Percent(50));
            shadow.style.scale = new Scale(new Vector3(_btnShadowScale, _btnShadowScale, 1f));
            shadow.style.opacity = _btnShadowOpacity;
            if (shadowTex != null)
            {
                shadow.style.backgroundImage = new StyleBackground(shadowTex);
                shadow.style.SetBackgroundScaleToFit();
                shadow.style.unityBackgroundImageTintColor = Color.black;
            }
            else
            {
                // Fallback: a black rounded box if the texture is missing.
                shadow.style.backgroundColor = Color.black;
                shadow.style.borderTopLeftRadius = size / 2;
                shadow.style.borderTopRightRadius = size / 2;
                shadow.style.borderBottomLeftRadius = size / 2;
                shadow.style.borderBottomRightRadius = size / 2;
            }
            parent.Add(shadow);
            return shadow;
        }

