            // Pulse animation
            _notifDotAnimPhase = 0f;
            _notifDotLastTime = EditorApplication.timeSinceStartup;
            EditorApplication.update += UpdateNotifDotPulse;
            
            // Pressed overlay (added before dot so dot renders on top)
            var roundPressedTex = LoadImage("Buttons", "Button_Round_Pressed");
