            notifPressedOverlay.style.right = 0;
            notifPressedOverlay.style.bottom = 0;
            notifPressedOverlay.style.display = DisplayStyle.None;
            notifPressedOverlay.style.unityBackgroundImageTintColor = Color.white;
            notifPressedOverlay.style.borderTopLeftRadius = notifBtnSize / 2;
            notifPressedOverlay.style.borderTopRightRadius = notifBtnSize / 2;
            notifPressedOverlay.style.borderBottomLeftRadius = notifBtnSize / 2;
            notifPressedOverlay.style.borderBottomRightRadius = notifBtnSize / 2;
            if (roundPressedTex != null)
            {
                notifPressedOverlay.style.backgroundImage = new StyleBackground(roundPressedTex);
                notifPressedOverlay.style.SetBackgroundStretchToFill();
            }
            _notificationButton.Add(notifPressedOverlay);
            
            // Dot will be added after button in parent (see below)
            
            // Hover
            _notificationButton.style.transitionProperty = new List<StylePropertyName> { new StylePropertyName("scale") };
            _notificationButton.style.transitionDuration = new List<TimeValue> { new TimeValue(100, TimeUnit.Millisecond) };
            _notificationButton.style.transitionTimingFunction = new List<EasingFunction> { new EasingFunction(EasingMode.EaseOut) };
            
            _notificationButton.RegisterCallback<MouseEnterEvent>(evt => {
                _notificationButton.style.scale = new Scale(new Vector3(_downloadBtnHoverScale, _downloadBtnHoverScale, 1f));
                notifPressedOverlay.style.display = DisplayStyle.Flex;
            });
            _notificationButton.RegisterCallback<MouseLeaveEvent>(evt => {
                _notificationButton.style.scale = new Scale(Vector3.one);
                notifPressedOverlay.style.display = DisplayStyle.None;
            });
            
            _notificationButton.clicked += OnNotificationButtonClicked;
            parent.Add(_notificationButton);
            
            // Add dot after button so it renders on top
            parent.Add(_notificationDot);
        }
        
        private double _notifDotLastTime;
        
        private void UpdateNotifDotPulse()
        {
            if (_reloadingDomain || !this) return;
            if (_notificationDot == null || _notificationDot.style.display == DisplayStyle.None) return;
            double now = EditorApplication.timeSinceStartup;
            float dt = (float)(now - _notifDotLastTime);
            _notifDotLastTime = now;
            _notifDotAnimPhase += dt * 3.14159f;
            if (_notifDotAnimPhase > 6.28318f) _notifDotAnimPhase -= 6.28318f;
            float s = 1f + 0.3f * Mathf.Sin(_notifDotAnimPhase);
            _notificationDot.style.scale = new Scale(new Vector3(s, s, 1f));
        }
        
        private void OnAnnouncementsUpdated()
        {
            if (_notificationDot != null)
                _notificationDot.style.display = SyntyNotificationService.UnseenAnnouncementCount > 0 ? DisplayStyle.Flex : DisplayStyle.None;
        }
        
        private void OnNotificationButtonClicked()
        {
            if (_notificationPopup != null && _notificationPopup.panel != null)
            {
                _notificationPopup.RemoveFromHierarchy();
                _notificationPopup = null;
                return;
            }
            
            // Mark all as seen
            SyntyNotificationService.MarkAnnouncementsSeen();
            SyntyAnalytics.TrackNotificationOpen(SyntyNotificationService.UnseenAnnouncementCount);
            if (_notificationDot != null)
                _notificationDot.style.display = DisplayStyle.None;
            
            // Build popup
            _notificationPopup = new VisualElement();
            _notificationPopup.name = "notification-popup";
            _notificationPopup.style.position = Position.Absolute;
            _notificationPopup.style.right = _profileBtnX + _profileBtnSize + 8f;
            _notificationPopup.style.top = _profileBtnY + _profilePanelOffsetY;
            _notificationPopup.style.width = 280;
            _notificationPopup.style.backgroundColor = _profilePanelBgColor; // match profile menu bg
            _notificationPopup.style.borderTopLeftRadius = 12;
            _notificationPopup.style.borderTopRightRadius = 12;
            _notificationPopup.style.borderBottomLeftRadius = 12;
            _notificationPopup.style.borderBottomRightRadius = 12;
            _notificationPopup.style.borderTopWidth = 1;
            _notificationPopup.style.borderBottomWidth = 1;
            _notificationPopup.style.borderLeftWidth = 1;
            _notificationPopup.style.borderRightWidth = 1;
            _notificationPopup.style.borderTopColor = new Color(1f, 1f, 1f, 0.08f);
            _notificationPopup.style.borderBottomColor = new Color(1f, 1f, 1f, 0.08f);
            _notificationPopup.style.borderLeftColor = new Color(1f, 1f, 1f, 0.08f);
            _notificationPopup.style.borderRightColor = new Color(1f, 1f, 1f, 0.08f);
            _notificationPopup.style.paddingTop = 12;
            _notificationPopup.style.paddingBottom = 12;
            _notificationPopup.style.paddingLeft = 14;
            _notificationPopup.style.paddingRight = 14;
            
            // Title
            var title = new Label("Notifications");
            title.style.color = Color.white;
            title.style.fontSize = 20;
            title.style.unityFontStyleAndWeight = FontStyle.Bold;
            title.style.marginBottom = 8;
            if (_newakeFont != null) title.style.unityFontDefinition = FontDefinition.FromFont(_newakeFont);
            _notificationPopup.Add(title);
            
            var announcements = SyntyNotificationService.Announcements;
            
            if (announcements.Count == 0)
            {
                var empty = new Label("No notifications");
                empty.style.color = new Color(1f, 1f, 1f, 0.3f);
                empty.style.fontSize = 11;
                empty.style.unityTextAlign = TextAnchor.MiddleCenter;
                empty.style.paddingTop = 16;
                empty.style.paddingBottom = 16;
                if (_titleFont != null) empty.style.unityFontDefinition = FontDefinition.FromFont(_titleFont);
                _notificationPopup.Add(empty);
            }
            else
            {
                for (int i = 0; i < announcements.Count; i++)
                {
                    var a = announcements[i];
                    string capturedUrl = a.url;
                    
                    var item = new VisualElement();
                    item.style.paddingTop = 6;
                    item.style.paddingBottom = 6;
                    item.style.flexDirection = FlexDirection.Row;
                    item.style.alignItems = Align.FlexStart;
                    if (i < announcements.Count - 1)
                    {
                        item.style.borderBottomWidth = 1;
                        item.style.borderBottomColor = new Color(1f, 1f, 1f, 0.05f);
                    }
                    
                    // Clickable if URL exists
                    var capturedAnnId = a.id;
                    bool hasUrl = !string.IsNullOrEmpty(capturedUrl);
                    if (hasUrl)
                    {
                        // Track hover for cursor
                        bool[] isItemHovered = { false };
                        var cursorOverlay = new IMGUIContainer(() => {
                            if (isItemHovered[0])
                                EditorGUIUtility.AddCursorRect(new Rect(0, 0, item.resolvedStyle.width, item.resolvedStyle.height), MouseCursor.Link);
                        });
                        cursorOverlay.pickingMode = PickingMode.Ignore;
                        cursorOverlay.style.position = Position.Absolute;
                        cursorOverlay.style.top = 0;
                        cursorOverlay.style.left = 0;
                        cursorOverlay.style.right = 0;
                        cursorOverlay.style.bottom = 0;
                        item.Add(cursorOverlay);
                        
                        item.RegisterCallback<MouseEnterEvent>(evt => {
                            item.style.backgroundColor = new Color(1f, 1f, 1f, 0.04f);
                            isItemHovered[0] = true;
                        });
                        item.RegisterCallback<MouseLeaveEvent>(evt => {
                            item.style.backgroundColor = Color.clear;
                            isItemHovered[0] = false;
                        });
                        item.RegisterCallback<MouseDownEvent>(evt => {
                            if (!string.IsNullOrEmpty(capturedUrl))
                            {
                                SyntyAnalytics.TrackNotificationClick(capturedAnnId, capturedUrl);
                                Application.OpenURL(capturedUrl);
                            }
                        });
                    }
                    
                    var msgContainer = new VisualElement();
                    msgContainer.style.flexGrow = 1;
                    msgContainer.pickingMode = PickingMode.Ignore;
                    
                    var msg = new Label(a.message);
                    msg.style.color = new Color(1f, 1f, 1f, 0.75f);
                    msg.style.fontSize = 14;
                    msg.style.whiteSpace = WhiteSpace.Normal;
                    msg.pickingMode = PickingMode.Ignore;
                    if (_titleFont != null) msg.style.unityFontDefinition = FontDefinition.FromFont(_titleFont);
                    msgContainer.Add(msg);
                    
                    if (!string.IsNullOrEmpty(a.date))
                    {
                        string dateStr = a.date;
                        try
                        {
                            var dt = System.DateTime.Parse(dateStr, null, System.Globalization.DateTimeStyles.RoundtripKind);
                            dateStr = dt.ToString("MMM d, yyyy");
                        }
                        catch { }
                        
                        var dateLabel = new Label(dateStr);
                        dateLabel.style.color = new Color(1f, 1f, 1f, 0.25f);
                        dateLabel.style.fontSize = 11;
                        dateLabel.style.marginTop = 2;
                        dateLabel.pickingMode = PickingMode.Ignore;
                        if (_titleFont != null) dateLabel.style.unityFontDefinition = FontDefinition.FromFont(_titleFont);
                        msgContainer.Add(dateLabel);
                    }
                    
                    item.Add(msgContainer);
                    
                    // Link arrow indicator
                    if (hasUrl)
                    {
                        var linkIcon = new VisualElement();
                        var linkTex = LoadImage("Icons/Misc", "Icon_ExternalLink");
                        if (linkTex == null) linkTex = LoadImage("Filter", "Icon_ExternalLink");
                        if (linkTex != null) linkIcon.style.backgroundImage = new StyleBackground(linkTex);
                        linkIcon.style.width = 16;
                        linkIcon.style.height = 16;
                        linkIcon.style.SetBackgroundScaleToFit();
                        linkIcon.style.unityBackgroundImageTintColor = Color.white;
                        linkIcon.style.marginLeft = 6;
                        linkIcon.style.alignSelf = Align.Center;
                        linkIcon.pickingMode = PickingMode.Ignore;
                        item.Add(linkIcon);
                    }
                    
                    _notificationPopup.Add(item);
                }
            }
            
            _mainFrame.Add(_notificationPopup);
            _notificationButton.BringToFront();
            _notificationDot.BringToFront();
            
            // Click outside to close
            _mainFrame.RegisterCallback<PointerDownEvent>(OnNotificationOutsideClick, TrickleDown.TrickleDown);
        }
        
        private void OnNotificationOutsideClick(PointerDownEvent evt)
        {
            if (_notificationPopup == null) return;
            
            var target = evt.target as VisualElement;
            while (target != null)
            {
                if (target == _notificationPopup || target == _notificationButton) return;
                target = target.parent;
            }
            
            _notificationPopup.RemoveFromHierarchy();
            _notificationPopup = null;
            _mainFrame.UnregisterCallback<PointerDownEvent>(OnNotificationOutsideClick, TrickleDown.TrickleDown);
        }
        
