        private void ToggleProfilePicker()
        {
            // Toggle picker visibility inside the profile panel
            if (_profilePickerPanel != null)
            {
                bool isVisible = _profilePickerPanel.style.display == DisplayStyle.Flex;
                _profilePickerPanel.style.display = isVisible ? DisplayStyle.None : DisplayStyle.Flex;
                return;
            }
            
            if (_profilePanel == null) return;
            
            _profilePickerPanel = new VisualElement();
            _profilePickerPanel.name = "profile-picker-section";
            _profilePickerPanel.style.marginBottom = 8;
            _profilePickerPanel.style.paddingTop = 4;
            _profilePickerPanel.style.paddingBottom = 4;
            _profilePickerPanel.pickingMode = PickingMode.Position;
            
            var title = new Label("Profile Picture");
            title.style.color = Color.white;
            title.style.fontSize = 11;
            title.style.unityFontStyleAndWeight = FontStyle.Bold;
            title.style.marginBottom = 6;
            title.style.unityTextAlign = TextAnchor.MiddleCenter;
            if (_titleFont != null) title.style.unityFontDefinition = FontDefinition.FromFont(_titleFont);
            _profilePickerPanel.Add(title);
            
            var grid = new VisualElement();
            grid.style.flexDirection = FlexDirection.Row;
            grid.style.flexWrap = Wrap.Wrap;
            grid.style.justifyContent = Justify.FlexStart;
            _profilePickerPanel.Add(grid);
            
            BuildProfileGrid(grid);
            
            // Insert after the top row (index 1)
            if (_profilePanel.childCount > 1)
                _profilePanel.Insert(1, _profilePickerPanel);
            else
                _profilePanel.Add(_profilePickerPanel);
        }
        
        private void BuildProfileGrid(VisualElement grid)
        {
            grid.Clear();
            
            string profileFolder = $"{_imagesPath}/Icons/Profile";
            if (!Directory.Exists(profileFolder)) return;
            
            var pngFiles = Directory.GetFiles(profileFolder, "*.png")
                .Select(f => Path.GetFileNameWithoutExtension(f))
                .OrderBy(f => f)
                .ToList();
            
            float thumbSize = 36;
            float thumbMargin = 3;
            
            foreach (var imgName in pngFiles)
            {
                var tex = LoadImage("Icons/Profile", imgName);
                if (tex == null) continue;
                
                var thumb = new Button();
                thumb.style.width = thumbSize;
                thumb.style.height = thumbSize;
                thumb.style.marginRight = thumbMargin;
                thumb.style.marginBottom = thumbMargin;
                thumb.style.backgroundImage = new StyleBackground(tex);
                thumb.style.SetBackgroundScaleToFit();
                thumb.style.borderTopLeftRadius = thumbSize / 2;
                thumb.style.borderTopRightRadius = thumbSize / 2;
                thumb.style.borderBottomLeftRadius = thumbSize / 2;
                thumb.style.borderBottomRightRadius = thumbSize / 2;
                thumb.style.borderTopWidth = imgName == _selectedProfileImage ? 2 : 0;
                thumb.style.borderBottomWidth = imgName == _selectedProfileImage ? 2 : 0;
                thumb.style.borderLeftWidth = imgName == _selectedProfileImage ? 2 : 0;
                thumb.style.borderRightWidth = imgName == _selectedProfileImage ? 2 : 0;
                thumb.style.borderTopColor = _accentColor;
                thumb.style.borderBottomColor = _accentColor;
                thumb.style.borderLeftColor = _accentColor;
                thumb.style.borderRightColor = _accentColor;
                thumb.style.backgroundColor = Color.clear;
                thumb.style.paddingTop = 0;
                thumb.style.paddingBottom = 0;
                thumb.style.paddingLeft = 0;
                thumb.style.paddingRight = 0;
                
                string capturedName = imgName;
                thumb.clicked += () => SelectProfileImage(capturedName);
                grid.Add(thumb);
            }
            
            // Add custom image button
            var addBtn = new Button();
            addBtn.style.width = thumbSize;
            addBtn.style.height = thumbSize;
            addBtn.style.marginRight = thumbMargin;
            addBtn.style.marginBottom = thumbMargin;
            addBtn.style.backgroundColor = new Color(0.2f, 0.18f, 0.28f, 1f);
            addBtn.style.borderTopLeftRadius = thumbSize / 2;
            addBtn.style.borderTopRightRadius = thumbSize / 2;
            addBtn.style.borderBottomLeftRadius = thumbSize / 2;
            addBtn.style.borderBottomRightRadius = thumbSize / 2;
            addBtn.style.borderTopWidth = 1;
            addBtn.style.borderBottomWidth = 1;
            addBtn.style.borderLeftWidth = 1;
            addBtn.style.borderRightWidth = 1;
            addBtn.style.borderTopColor = new Color(1f, 1f, 1f, 0.2f);
            addBtn.style.borderBottomColor = new Color(1f, 1f, 1f, 0.2f);
            addBtn.style.borderLeftColor = new Color(1f, 1f, 1f, 0.2f);
            addBtn.style.borderRightColor = new Color(1f, 1f, 1f, 0.2f);
            addBtn.style.alignItems = Align.Center;
            addBtn.style.justifyContent = Justify.Center;
            addBtn.style.paddingTop = 0;
            addBtn.style.paddingBottom = 0;
            addBtn.style.paddingLeft = 0;
            addBtn.style.paddingRight = 0;
            
            var addLabel = new Label("+");
            addLabel.pickingMode = PickingMode.Ignore;
            addLabel.style.color = new Color(1f, 1f, 1f, 0.6f);
            addLabel.style.fontSize = 18;
            addLabel.style.unityTextAlign = TextAnchor.MiddleCenter;
            addLabel.style.marginTop = -2;
            addBtn.Add(addLabel);
            
            string folderPath = profileFolder;
            addBtn.clicked += () => AddCustomProfileImage(folderPath);
            grid.Add(addBtn);
        }
        
        private void SelectProfileImage(string imageName)
        {
            _selectedProfileImage = imageName;
            EditorPrefs.SetString(PREFS_PROFILE_IMAGE, imageName);
            
            // Update profile button texture
            var tex = LoadImage("Icons/Profile", imageName);
            if (tex != null && _profileButton != null)
                _profileButton.style.backgroundImage = new StyleBackground(tex);
            
            // Update panel profile image
            if (_profilePanel != null)
            {
                var panelImg = _profilePanel.Q<VisualElement>("panel-profile-img");
                if (panelImg != null && tex != null)
                    panelImg.style.backgroundImage = new StyleBackground(tex);
            }
            
            // Rebuild grid to update selection highlight
            if (_profilePickerPanel != null)
            {
                var grid = _profilePickerPanel.Q<VisualElement>(className: null);
                // Find the grid (second child after title)
                if (_profilePickerPanel.childCount > 1)
                {
                    var gridEl = _profilePickerPanel[1];
                    BuildProfileGrid(gridEl);
                }
            }
        }
        
        private void AddCustomProfileImage(string profileFolder)
        {
            string path = EditorUtility.OpenFilePanel("Select Profile Picture", "", "png,jpg,jpeg");
            if (string.IsNullOrEmpty(path)) return;
            
            try
            {
                // Load the source image
                byte[] fileData = File.ReadAllBytes(path);
                var srcTex = new Texture2D(2, 2);
                srcTex.LoadImage(fileData);
                
                // Make it square (crop to center)
                int size = Mathf.Min(srcTex.width, srcTex.height);
                int xOffset = (srcTex.width - size) / 2;
                int yOffset = (srcTex.height - size) / 2;
                
                var squareTex = new Texture2D(size, size, TextureFormat.RGBA32, false);
                squareTex.SetPixels(srcTex.GetPixels(xOffset, yOffset, size, size));
                squareTex.Apply();
                
                // Scale down if too large
                if (size > 256)
                {
                    var scaledTex = new Texture2D(256, 256, TextureFormat.RGBA32, false);
                    var rt = RenderTexture.GetTemporary(256, 256);
                    Graphics.Blit(squareTex, rt);
                    RenderTexture.active = rt;
                    scaledTex.ReadPixels(new Rect(0, 0, 256, 256), 0, 0);
                    scaledTex.Apply();
                    RenderTexture.active = null;
                    RenderTexture.ReleaseTemporary(rt);
                    Object.DestroyImmediate(squareTex);
                    squareTex = scaledTex;
                }
                
                // Generate unique filename
                string baseName = "Custom_" + Path.GetFileNameWithoutExtension(path).Replace(" ", "_");
                string destPath = Path.Combine(profileFolder, baseName + ".png");
                int counter = 1;
                while (File.Exists(destPath))
                {
                    destPath = Path.Combine(profileFolder, baseName + "_" + counter + ".png");
                    counter++;
                }
                
                // Save as PNG
                byte[] pngData = squareTex.EncodeToPNG();
                File.WriteAllBytes(destPath, pngData);
                
                Object.DestroyImmediate(srcTex);
                Object.DestroyImmediate(squareTex);
                
                // Refresh asset database so Unity sees the new file
                AssetDatabase.Refresh();
                
                // Clear image cache for this file
                string finalName = Path.GetFileNameWithoutExtension(destPath);
                string cacheKey = $"Icons/Profile/{finalName}";
                if (_imageCache.ContainsKey(cacheKey))
                    _imageCache.Remove(cacheKey);
                
                // Select the new image (this rebuilds the grid)
                SelectProfileImage(finalName);
            }
            catch (System.Exception)
            {
                // Debug.LogError($"[Synty] Failed to add custom profile image: {e.Message}");
            }
        }
        
        private void OnProfileButtonClicked()
        {
            _profilePanelVisible = !_profilePanelVisible;
            if (_profilePanel != null)
            {
                _profilePanel.style.display = _profilePanelVisible ? DisplayStyle.Flex : DisplayStyle.None;
                if (_profilePanelVisible)
                {
                    // Order matters: whatever is brought to front LAST draws on top. Bring the
                    // button forward first, then the panel, so the open panel renders ABOVE
                    // the profile button rather than the button poking through it.
                    _profileButton.BringToFront();
                    _profilePanel.BringToFront();
                }
            }
            if (_changeProfileBtn != null)
                _changeProfileBtn.style.display = _profilePanelVisible ? DisplayStyle.Flex : DisplayStyle.None;
            
            // Hide picker when panel closes
            if (!_profilePanelVisible && _profilePickerPanel != null)
            {
                _profilePickerPanel.style.display = DisplayStyle.None;
            }
        }
        
        private void OnDebugOptionsButtonClicked()
        {
            _optionsPanelVisible = !_optionsPanelVisible;
            
            if (_optionsPanelVisible)
            {
                _optionsPanel.style.display = DisplayStyle.Flex;
                _verticalDivider.style.display = DisplayStyle.Flex;
                var pos = position;
                pos.width = WIDTH_NO_OPTIONS + _optionsPanelWidth + 2;
                position = pos;
                minSize = new Vector2(WIDTH_NO_OPTIONS + _optionsPanelWidth + 2, _minHeight);
            }
            else
            {
                _optionsPanel.style.display = DisplayStyle.None;
                _verticalDivider.style.display = DisplayStyle.None;
                minSize = new Vector2(_minWidthNoOptions, _minHeight);
                var pos = position;
                pos.width = WIDTH_NO_OPTIONS;
                position = pos;
            }
        }
        
        private void BuildProfilePanel(VisualElement parent)
        {
            _profilePanel = new VisualElement();
            _profilePanel.name = "profile-panel";
            _profilePanel.style.position = Position.Absolute;
            // Position panel so the profile image inside aligns with the main profile button
            float accountBtnHeight = 32f;
            float verticalCenter = (accountBtnHeight - _profileBtnSize) / 2f;
            _profilePanel.style.top    = _profileBtnY - _profilePanelPadding - verticalCenter + _profilePanelOffsetY;
            _profilePanel.style.right  = _profileBtnX - _profilePanelPadding + _profilePanelOffsetX;
            _profilePanel.style.width  = _profilePanelWidth;
            _profilePanel.style.backgroundColor = _profilePanelBgColor;
            _profilePanel.style.borderTopLeftRadius    = _profilePanelRadius;
            _profilePanel.style.borderTopRightRadius   = _profilePanelRadius;
            _profilePanel.style.borderBottomLeftRadius = _profilePanelRadius;
            _profilePanel.style.borderBottomRightRadius= _profilePanelRadius;
            _profilePanel.style.paddingTop    = _profilePanelPadding;
            _profilePanel.style.paddingBottom = _profilePanelPadding;
            _profilePanel.style.paddingLeft   = _profilePanelPadding;
            _profilePanel.style.paddingRight  = _profilePanelPadding;
            _profilePanel.style.flexDirection = FlexDirection.Column;
            _profilePanel.style.display = DisplayStyle.None;
            _profilePanel.pickingMode = PickingMode.Position;
            
            // Close panel when clicking outside
            parent.RegisterCallback<MouseDownEvent>(evt =>
            {
                if (_profilePanelVisible && _profilePanel != null)
                {
                    var localPos = _profilePanel.WorldToLocal(evt.mousePosition);
                    if (!new Rect(0, 0, _profilePanel.resolvedStyle.width, _profilePanel.resolvedStyle.height).Contains(localPos))
                    {
                        _profilePanelVisible = false;
                        _profilePanel.style.display = DisplayStyle.None;
                        if (_changeProfileBtn != null) _changeProfileBtn.style.display = DisplayStyle.None;
                        if (_profilePickerPanel != null) _profilePickerPanel.style.display = DisplayStyle.None;
                    }
                }
            });
            
            // Top row: account button + profile image
            var topRow = new VisualElement();
            topRow.style.flexDirection = FlexDirection.Row;
            topRow.style.alignItems = Align.Center;
            topRow.style.marginBottom = 8;
            _profilePanel.Add(topRow);
            
            // Account button — left side. Shows "Account" on the top line with the logged-in
            // customer's email underneath at a smaller, dimmer size. We build two stacked
            // labels inside the button instead of setting button.text so the two lines can
            // have different font sizes / colors. flexDirection=Column stacks them; the
            // outer button keeps all its existing styling and click behaviour.
            var accountBtn = new Button();
            _profileAccountBtn = accountBtn;
            accountBtn.text = "";
            accountBtn.style.flexDirection = FlexDirection.Row;
            accountBtn.style.justifyContent = Justify.Center;
            accountBtn.style.alignItems = Align.Center;
            accountBtn.style.height = 32;
            accountBtn.style.flexGrow = 1;
            accountBtn.style.marginRight = _profileBtnSize + 8;
            accountBtn.style.paddingTop = 4;
            accountBtn.style.paddingBottom = 4;
            accountBtn.style.overflow = Overflow.Hidden;
            
            var accountTitleLbl = new Label("Account");
            accountTitleLbl.pickingMode = PickingMode.Ignore;
            accountTitleLbl.style.unityTextAlign = TextAnchor.MiddleCenter;
            accountTitleLbl.style.marginTop = 0;
            accountTitleLbl.style.marginBottom = 0;
            accountTitleLbl.style.paddingTop = 0;
            accountTitleLbl.style.paddingBottom = 0;
            // Offset the title left a touch so it stays visually centered despite the icon
            // sitting on the right edge.
            accountTitleLbl.style.marginRight = 18;
            accountBtn.Add(accountTitleLbl);
            
            // Product page icon, right-aligned. Absolutely positioned at the right edge so it
            // doesn't shift the centered title; the title's right margin above balances it.
            var accountProductIcon = new VisualElement();
            accountProductIcon.name = "account-product-icon";
            accountProductIcon.pickingMode = PickingMode.Ignore;
            var accountProductTex = LoadImage("Assets", "Icon_ProductPage");
            if (accountProductTex != null)
                accountProductIcon.style.backgroundImage = accountProductTex;
            accountProductIcon.style.SetBackgroundScaleToFit();
            accountProductIcon.style.position = Position.Absolute;
            accountProductIcon.style.right = 10;
            accountProductIcon.style.width = 14;
            accountProductIcon.style.height = 14;
            accountProductIcon.style.unityBackgroundImageTintColor = _profileAccountTextColor;
            accountBtn.Add(accountProductIcon);
            
            // Email line — uses the live SyntyStoreService email. Now placed ABOVE the
            // account button (added to the panel before topRow) and stretched to fill the
            // panel width, rather than inside the button.
            string loggedEmail = Synty.Tools.SyntyStoreService.Instance?.CustomerEmail ?? "";
            var accountEmailLbl = new Label(string.IsNullOrEmpty(loggedEmail) ? "" : loggedEmail);
            _profileAccountEmailLbl = accountEmailLbl;
            accountEmailLbl.pickingMode = PickingMode.Ignore;
            accountEmailLbl.style.unityTextAlign = TextAnchor.MiddleLeft;
            accountEmailLbl.style.fontSize = _profileEmailFontSize;
            accountEmailLbl.style.whiteSpace = WhiteSpace.NoWrap;
            accountEmailLbl.style.overflow = Overflow.Hidden;
            accountEmailLbl.style.textOverflow = TextOverflow.Ellipsis;
            accountEmailLbl.style.flexGrow = 1;
            accountEmailLbl.style.width = Length.Percent(100);
            accountEmailLbl.style.marginTop = 4;
            accountEmailLbl.style.marginBottom = 4;
            accountEmailLbl.style.paddingTop = 0;
            accountEmailLbl.style.paddingBottom = 0;
            accountEmailLbl.style.opacity = 0.75f;
            // Place the email directly UNDER the account button: topRow (which holds the
            // account + profile buttons) is the first child of the panel, so inserting the
            // email at the index right after topRow puts it on its own line beneath the row,
            // spanning the panel width.
            int topRowIdx = _profilePanel.IndexOf(topRow);
            _profilePanel.Insert(topRowIdx < 0 ? 0 : topRowIdx + 1, accountEmailLbl);
            
            accountBtn.style.backgroundColor = _profileAccountBtnColor;
            accountBtn.style.color = _profileAccountTextColor;
            accountBtn.style.borderTopLeftRadius = 6;
            accountBtn.style.borderTopRightRadius = 6;
            accountBtn.style.borderBottomLeftRadius = 6;
            accountBtn.style.borderBottomRightRadius = 6;
            accountBtn.style.borderTopWidth = 0;
            accountBtn.style.borderBottomWidth = 0;
            accountBtn.style.borderLeftWidth = 0;
            accountBtn.style.borderRightWidth = 0;
            accountBtn.style.marginBottom = 0;
            accountBtn.style.transitionProperty = new List<StylePropertyName> { 
                new StylePropertyName("scale"),
                new StylePropertyName("opacity"),
                new StylePropertyName("border-top-width"),
                new StylePropertyName("border-bottom-width"),
                new StylePropertyName("border-left-width"),
                new StylePropertyName("border-right-width")
            };
            accountBtn.style.transitionDuration = new List<TimeValue> { 
                new TimeValue(120, TimeUnit.Millisecond),
                new TimeValue(120, TimeUnit.Millisecond),
                new TimeValue(120, TimeUnit.Millisecond),
                new TimeValue(120, TimeUnit.Millisecond),
                new TimeValue(120, TimeUnit.Millisecond),
                new TimeValue(120, TimeUnit.Millisecond)
            };
            accountBtn.style.transitionTimingFunction = new List<EasingFunction> { 
                new EasingFunction(EasingMode.EaseOut),
                new EasingFunction(EasingMode.EaseOut),
                new EasingFunction(EasingMode.EaseOut),
                new EasingFunction(EasingMode.EaseOut),
                new EasingFunction(EasingMode.EaseOut),
                new EasingFunction(EasingMode.EaseOut)
            };
            accountBtn.style.borderTopColor = Color.white;
            accountBtn.style.borderBottomColor = Color.white;
            accountBtn.style.borderLeftColor = Color.white;
            accountBtn.style.borderRightColor = Color.white;
            accountBtn.style.borderTopWidth = 0;
            accountBtn.style.borderBottomWidth = 0;
            accountBtn.style.borderLeftWidth = 0;
            accountBtn.style.borderRightWidth = 0;
            accountBtn.RegisterCallback<MouseEnterEvent>(evt => {
                accountBtn.style.scale = new Scale(new Vector3(1.04f, 1.04f, 1f));
                accountBtn.style.borderTopWidth = 2;
                accountBtn.style.borderBottomWidth = 2;
                accountBtn.style.borderLeftWidth = 2;
                accountBtn.style.borderRightWidth = 2;
            });
            accountBtn.RegisterCallback<MouseLeaveEvent>(evt => {
                accountBtn.style.scale = new Scale(Vector3.one);
                accountBtn.style.borderTopWidth = 0;
                accountBtn.style.borderBottomWidth = 0;
                accountBtn.style.borderLeftWidth = 0;
                accountBtn.style.borderRightWidth = 0;
            });
            accountBtn.clicked += () => OpenAccountLoginUrl();
            topRow.Add(accountBtn);
            
            // Profile image in panel — right side, absolutely positioned so account hover doesn't affect it
            var panelProfileImg = new VisualElement();
            panelProfileImg.name = "panel-profile-img";
            panelProfileImg.style.position = Position.Absolute;
            panelProfileImg.style.right = 0;
            panelProfileImg.style.top = (32f - _profileBtnSize) / 2f;
            panelProfileImg.style.width = _profileBtnSize;
            panelProfileImg.style.height = _profileBtnSize;
            panelProfileImg.style.borderTopLeftRadius = _profileBtnSize / 2;
