            panelProfileImg.style.borderBottomLeftRadius = _profileBtnSize / 2;
            panelProfileImg.style.borderBottomRightRadius = _profileBtnSize / 2;
            panelProfileImg.style.flexShrink = 0;
            panelProfileImg.pickingMode = PickingMode.Position;
            panelProfileImg.RegisterCallback<MouseDownEvent>(evt => {
