                // Title gets the configured font size + bold; email line a bit smaller
                // (75%) so the hierarchy is clear. Style both directly since the button now
                // contains two stacked labels, not a single Q<Label>().
                if (accountTitleLbl != null)
                {
                    accountTitleLbl.style.fontSize = _profileAccountFontSize;
                    accountTitleLbl.style.unityFontStyleAndWeight = _profileAccountBold ? FontStyle.Bold : FontStyle.Normal;
                    accountTitleLbl.style.color = _profileAccountTextColor;
                }
                if (accountEmailLbl != null)
                {
                    accountEmailLbl.style.fontSize = _profileEmailFontSize;
                    accountEmailLbl.style.unityFontStyleAndWeight = FontStyle.Normal;
                    accountEmailLbl.style.color = _profileAccountTextColor;
                }
                accountBtn.style.fontSize = _profileAccountFontSize;
                accountBtn.style.unityFontStyleAndWeight = _profileAccountBold ? FontStyle.Bold : FontStyle.Normal;
