            // Notifications section title
            var notifLabel = new Label("Notifications");
            _profileNotifLabel = notifLabel;
            notifLabel.style.fontSize = _profileLabelFontSize;
            notifLabel.style.color = _profileLabelColor;
            notifLabel.style.unityFontStyleAndWeight = FontStyle.Bold;
            notifLabel.style.marginTop = 4;
            notifLabel.style.marginBottom = 6;
            _profilePanel.Add(notifLabel);
            
            // Helper to build each toggle row. Persists state to EditorPrefs and notifies via callback.
            float trackW = 40f, trackH = 22f, knobSize = 16f, knobPad = 3f;
            Color trackOnColor  = new Color(0.255f, 0.255f, 0.388f, 1f); // #414163
            Color trackOffColor = new Color(0.3f, 0.3f, 0.35f, 1f);
            
            VisualElement AddNotifToggle(string labelText, string prefKey, bool defaultOn, System.Action<bool> onChange = null)
            {
                var row = new VisualElement();
                row.style.flexDirection = FlexDirection.Row;
                row.style.alignItems = Align.Center;
                row.style.justifyContent = Justify.SpaceBetween;
                row.style.paddingTop = 3;
                row.style.paddingBottom = 3;
                row.style.marginBottom = 2;
                row.style.paddingLeft = 4;
                _profilePanel.Add(row);
                
                var lbl = new Label(labelText);
                lbl.style.fontSize = _profileLabelFontSize;
                lbl.style.color = _profileLabelColor;
                row.Add(lbl);
                
                // Load persisted state from EditorPrefs
                bool isOn = EditorPrefs.GetBool(prefKey, defaultOn);
                
                var track = new VisualElement();
                track.style.width  = trackW;
                track.style.height = trackH;
                track.style.borderTopLeftRadius    = trackH * 0.5f;
                track.style.borderTopRightRadius   = trackH * 0.5f;
                track.style.borderBottomLeftRadius = trackH * 0.5f;
                track.style.borderBottomRightRadius= trackH * 0.5f;
                track.style.backgroundColor = isOn ? trackOnColor : trackOffColor;
                track.style.transitionProperty = new List<StylePropertyName> { new StylePropertyName("background-color") };
                track.style.transitionDuration = new List<TimeValue> { new TimeValue(150, TimeUnit.Millisecond) };
                track.style.transitionTimingFunction = new List<EasingFunction> { new EasingFunction(EasingMode.EaseInOut) };
                track.pickingMode = PickingMode.Position;
                
                var knob = new VisualElement();
                knob.style.position = Position.Absolute;
                knob.style.width  = knobSize;
                knob.style.height = knobSize;
                knob.style.borderTopLeftRadius    = knobSize * 0.5f;
                knob.style.borderTopRightRadius   = knobSize * 0.5f;
                knob.style.borderBottomLeftRadius = knobSize * 0.5f;
                knob.style.borderBottomRightRadius= knobSize * 0.5f;
                knob.style.backgroundColor = Color.white;
                knob.style.top  = knobPad;
                knob.style.left = isOn ? trackW - knobSize - knobPad : knobPad;
                knob.style.transitionProperty = new List<StylePropertyName> { new StylePropertyName("left") };
                knob.style.transitionDuration = new List<TimeValue> { new TimeValue(150, TimeUnit.Millisecond) };
                knob.style.transitionTimingFunction = new List<EasingFunction> { new EasingFunction(EasingMode.EaseInOut) };
                knob.pickingMode = PickingMode.Ignore;
                track.Add(knob);
                
                track.RegisterCallback<MouseDownEvent>(_ =>
                {
                    isOn = !isOn;
                    track.style.backgroundColor = isOn ? trackOnColor : trackOffColor;
                    knob.style.left = isOn ? trackW - knobSize - knobPad : knobPad;
                    EditorPrefs.SetBool(prefKey, isOn);
                    onChange?.Invoke(isOn);
                });
                row.Add(track);
                return row;
            }
            
            AddNotifToggle("Sales",    SyntyNotificationService.PREFS_NOTIF_SALES,    true);
            AddNotifToggle("Releases", SyntyNotificationService.PREFS_NOTIF_RELEASES, true);
            AddNotifToggle("Updates",  SyntyNotificationService.PREFS_NOTIF_UPDATES,  true);
            
            // Analytics — separate section under notifications, with its own toggle and a Delete button.
            var analyticsLabel = new Label("Analytics");
            analyticsLabel.style.fontSize = _profileLabelFontSize;
            analyticsLabel.style.color = _profileLabelColor;
            analyticsLabel.style.unityFontStyleAndWeight = FontStyle.Bold;
            analyticsLabel.style.marginTop = 12;
            analyticsLabel.style.marginBottom = 6;
            _profilePanel.Add(analyticsLabel);
            
            var openDownloadsBtn = new Button(() => {
                try
                {
                    string folder = SyntyDownloadManager.DownloadCacheFolder;
                    // Make sure it exists so the OS file browser has something to open.
                    if (!System.IO.Directory.Exists(folder))
                        System.IO.Directory.CreateDirectory(folder);
                    // EditorUtility.RevealInFinder is cross-platform (Explorer on Windows,
                    // Finder on Mac, the default file manager on Linux). Pass a trailing
                    // separator so it opens the folder itself rather than selecting it.
                    EditorUtility.RevealInFinder(folder + System.IO.Path.DirectorySeparatorChar);
                }
                catch { }
            });
            openDownloadsBtn.text = "Open Downloads Folder";
            openDownloadsBtn.style.marginTop = 6;
            openDownloadsBtn.style.marginLeft = 4;
            openDownloadsBtn.style.marginRight = 4;
            openDownloadsBtn.style.height = 26;
            openDownloadsBtn.style.fontSize = _profileLabelFontSize;
            openDownloadsBtn.style.backgroundColor = new Color(0.255f, 0.255f, 0.388f, 1f); // #414163
            openDownloadsBtn.style.color = Color.white;
            openDownloadsBtn.style.borderTopLeftRadius    = 6;
            openDownloadsBtn.style.borderTopRightRadius   = 6;
            openDownloadsBtn.style.borderBottomLeftRadius = 6;
            openDownloadsBtn.style.borderBottomRightRadius= 6;
            openDownloadsBtn.style.borderLeftWidth   = 0;
            openDownloadsBtn.style.borderRightWidth  = 0;
            openDownloadsBtn.style.borderTopWidth    = 0;
            openDownloadsBtn.style.borderBottomWidth = 0;
            var openDlBase  = new Color(0.255f, 0.255f, 0.388f, 1f);  // #414163
            var openDlHover = new Color(0.337f, 0.337f, 0.486f, 1f);  // lighter #56567C
            openDownloadsBtn.style.transitionProperty = new List<StylePropertyName> {
                new StylePropertyName("background-color"), new StylePropertyName("scale")
            };
            openDownloadsBtn.style.transitionDuration = new List<TimeValue> {
                new TimeValue(110, TimeUnit.Millisecond), new TimeValue(110, TimeUnit.Millisecond)
            };
            openDownloadsBtn.style.transitionTimingFunction = new List<EasingFunction> {
                new EasingFunction(EasingMode.EaseOut), new EasingFunction(EasingMode.EaseOut)
            };
            openDownloadsBtn.RegisterCallback<MouseEnterEvent>(_ => {
                openDownloadsBtn.style.backgroundColor = openDlHover;
                openDownloadsBtn.style.scale = new Scale(new Vector3(1.02f, 1.02f, 1f));
            });
            openDownloadsBtn.RegisterCallback<MouseLeaveEvent>(_ => {
                openDownloadsBtn.style.backgroundColor = openDlBase;
                openDownloadsBtn.style.scale = new Scale(new Vector3(1f, 1f, 1f));
            });
            // (added below under its own "Asset Downloads" title, not here under Analytics)
            
            var deleteAnalyticsBtn = new Button(() => { });
            bool optedOutNow = SyntyAnalytics.AccountOptedOut || !EditorPrefs.GetBool(SyntyAnalytics.PREFS_ANALYTICS_ENABLED, true);
            deleteAnalyticsBtn.text = optedOutNow ? "Turn Analytics Back On" : "Delete My Data & Opt Out";
            deleteAnalyticsBtn.style.marginTop = 6;
            deleteAnalyticsBtn.style.marginLeft = 4;
            deleteAnalyticsBtn.style.marginRight = 4;
            deleteAnalyticsBtn.style.height = 26;
            deleteAnalyticsBtn.style.fontSize = _profileLabelFontSize;
            deleteAnalyticsBtn.style.backgroundColor = new Color(0.255f, 0.255f, 0.388f, 1f); // #414163
            deleteAnalyticsBtn.style.color = Color.white;
            deleteAnalyticsBtn.style.borderTopLeftRadius    = 6;
            deleteAnalyticsBtn.style.borderTopRightRadius   = 6;
            deleteAnalyticsBtn.style.borderBottomLeftRadius = 6;
            deleteAnalyticsBtn.style.borderBottomRightRadius= 6;
            deleteAnalyticsBtn.style.borderLeftWidth   = 0;
            deleteAnalyticsBtn.style.borderRightWidth  = 0;
            deleteAnalyticsBtn.style.borderTopWidth    = 0;
            deleteAnalyticsBtn.style.borderBottomWidth = 0;
            // Hover visuals: lighten the background and nudge a subtle scale, matching the
            // interactive feel of the other profile buttons. Base is #414163.
            var delAnalyticsBase = new Color(0.255f, 0.255f, 0.388f, 1f);   // #414163
            var delAnalyticsHover = new Color(0.337f, 0.337f, 0.486f, 1f);  // lighter #56567C
            deleteAnalyticsBtn.style.transitionProperty = new List<StylePropertyName> {
                new StylePropertyName("background-color"), new StylePropertyName("scale")
            };
            deleteAnalyticsBtn.style.transitionDuration = new List<TimeValue> {
                new TimeValue(110, TimeUnit.Millisecond), new TimeValue(110, TimeUnit.Millisecond)
            };
            deleteAnalyticsBtn.style.transitionTimingFunction = new List<EasingFunction> {
                new EasingFunction(EasingMode.EaseOut), new EasingFunction(EasingMode.EaseOut)
            };
            deleteAnalyticsBtn.RegisterCallback<MouseEnterEvent>(_ => {
                deleteAnalyticsBtn.style.backgroundColor = delAnalyticsHover;
                deleteAnalyticsBtn.style.scale = new Scale(new Vector3(1.02f, 1.02f, 1f));
            });
            deleteAnalyticsBtn.RegisterCallback<MouseLeaveEvent>(_ => {
                deleteAnalyticsBtn.style.backgroundColor = delAnalyticsBase;
                deleteAnalyticsBtn.style.scale = new Scale(new Vector3(1f, 1f, 1f));
            });
            // Clicking removes the whole Analytics section (header, Share Usage toggle, and this
            // button) from the profile menu.
            deleteAnalyticsBtn.clicked += () => {
                if (SyntyAnalytics.AccountOptedOut || !EditorPrefs.GetBool(SyntyAnalytics.PREFS_ANALYTICS_ENABLED, true))
                {
                    // ── Opt back IN ── re-enable future tracking for this account.
                    deleteAnalyticsBtn.SetEnabled(false);
                    deleteAnalyticsBtn.text = "Updating...";
                    string hash = SyntyAnalytics.EmailHash;
                    string json = "{\"emailHash\":\"" + hash + "\"}";
                    var req = new UnityEngine.Networking.UnityWebRequest(
                        "https://synty-downloads.syntystore.workers.dev/analytics/optin", "POST");
                    req.uploadHandler = new UnityEngine.Networking.UploadHandlerRaw(
                        System.Text.Encoding.UTF8.GetBytes(json));
                    req.downloadHandler = new UnityEngine.Networking.DownloadHandlerBuffer();
                    req.SetRequestHeader("Content-Type", "application/json");
                    var op = req.SendWebRequest();
                    op.completed += _ =>
                    {
                        bool ok = req.result == UnityEngine.Networking.UnityWebRequest.Result.Success;
                        try { req.Dispose(); } catch { }
                        deleteAnalyticsBtn.SetEnabled(true);
                        if (ok)
                        {
                            SyntyAnalytics.AccountOptedOut = false;
                            EditorPrefs.SetBool(SyntyAnalytics.PREFS_ANALYTICS_ENABLED, true);
                            deleteAnalyticsBtn.text = "Delete My Data & Opt Out";
                            EditorUtility.DisplayDialog("Analytics On",
                                "Analytics are back on for your account.", "OK");
                        }
                        else
                        {
                            deleteAnalyticsBtn.text = "Turn Analytics Back On";
                            EditorUtility.DisplayDialog("Update Failed",
                                "Could not update your preference. Please try again.", "OK");
                        }
                    };
                    return;
                }

                // ── Opt OUT + delete ── erases this account's data and records the opt-out.
                bool confirmed = EditorUtility.DisplayDialog(
                    "Delete My Data & Opt Out",
                    "This permanently deletes all Synty Importer usage analytics linked to your Synty account from Synty Importer's servers, and stops future collection for your account on every install. This cannot be undone.\n\nContinue?",
                    "Delete & Opt Out", "Cancel");
                if (!confirmed) return;
                deleteAnalyticsBtn.SetEnabled(false);
                deleteAnalyticsBtn.text = "Deleting...";
                string installId = SyntyAnalytics.InstallId;
                string emailHash = SyntyAnalytics.EmailHash;
                string sessionTok = EditorPrefs.GetString("SyntyStore_SessionToken", "");
                string body = "{\"session_token\":\"" + sessionTok + "\",\"installId\":\"" + installId + "\",\"emailHash\":\"" + emailHash + "\"}";
                var dreq = new UnityEngine.Networking.UnityWebRequest(
                    "https://synty-downloads.syntystore.workers.dev/analytics/delete", "POST");
                dreq.uploadHandler = new UnityEngine.Networking.UploadHandlerRaw(
                    System.Text.Encoding.UTF8.GetBytes(body));
                dreq.downloadHandler = new UnityEngine.Networking.DownloadHandlerBuffer();
                dreq.SetRequestHeader("Content-Type", "application/json");
                var dop = dreq.SendWebRequest();
                dop.completed += _ =>
                {
                    bool ok = dreq.result == UnityEngine.Networking.UnityWebRequest.Result.Success;
                    long httpCode = dreq.responseCode;
                    string respText = dreq.downloadHandler != null ? dreq.downloadHandler.text : "";
                    string netErr = dreq.error;
                    try { dreq.Dispose(); } catch { }
                    deleteAnalyticsBtn.SetEnabled(true);
                    // A 2xx with success:true is a real success; some setups return 200 with an error body.
                    if (ok && !string.IsNullOrEmpty(respText) && respText.Contains("\"success\":true"))
                        ok = true;
                    else if (ok && string.IsNullOrEmpty(respText))
                        ok = true; // success result, empty body — treat as ok
                    else if (ok && respText.Contains("\"error\""))
                        ok = false; // 200 but error body
                    if (!ok)
                        Synty.Tools.SyntyLog.Error($"[Analytics] Delete failed. http={httpCode} netErr={netErr} body={respText}");
                    if (ok)
                    {
                        SyntyAnalytics.RotateInstallId();
                        SyntyAnalytics.AccountOptedOut = !string.IsNullOrEmpty(emailHash);
                        // Persist the opt-out locally too, so it survives an editor restart even before
                        // the account opt-out has been re-checked from the server (which needs login).
                        EditorPrefs.SetBool(SyntyAnalytics.PREFS_ANALYTICS_ENABLED, false);
                        EditorUtility.DisplayDialog("Data Deleted",
                            string.IsNullOrEmpty(emailHash)
                                ? "Your analytics data has been deleted."
                                : "Your analytics data has been deleted and your account is opted out of future collection.",
                            "OK");
                        // Flip to the opt-in affordance instead of removing the section.
                        deleteAnalyticsBtn.text = "Turn Analytics Back On";
                    }
                    else
                    {
                        deleteAnalyticsBtn.text = "Delete My Data & Opt Out";
                        EditorUtility.DisplayDialog("Delete Failed",
                            "Could not delete analytics data. Please check your connection and try again.", "OK");
                    }
                };
            };
            _profilePanel.Add(deleteAnalyticsBtn);

            // Debug Logging — available to everyone so a customer can enable it (e.g. to capture logs
            // for support). Off by default, so the console stays quiet unless they turn it on.
            {
                var debugLabel = new Label("Advanced");
                debugLabel.style.fontSize = _profileLabelFontSize;
                debugLabel.style.color = _profileLabelColor;
                debugLabel.style.unityFontStyleAndWeight = FontStyle.Bold;
                debugLabel.style.marginTop = 12;
                debugLabel.style.marginBottom = 6;
                _profilePanel.Add(debugLabel);

                // Reuse the same pill switch as the Notifications toggles.
                AddNotifToggle("Debug Logging", PREF_DEBUG_LOGGING, false);
