            var assetDownloadsLabel = new Label("Asset Downloads");
            assetDownloadsLabel.style.fontSize = _profileLabelFontSize;
            assetDownloadsLabel.style.color = _profileLabelColor;
            assetDownloadsLabel.style.unityFontStyleAndWeight = FontStyle.Bold;
            assetDownloadsLabel.style.marginTop = 12;
            assetDownloadsLabel.style.marginBottom = 6;
            _profilePanel.Add(assetDownloadsLabel);
            _profilePanel.Add(openDownloadsBtn);
            
            // Toolbar Button position section — only on Unity versions where the toolbar button
            // actually works. Unity 6.3+ rewrote the main toolbar so a custom button can't be shown
            // reliably there; we hide this control on those versions rather than offer a setting for
            // a feature that won't take effect.
            Label toolbarLabel = null;
#if !UNITY_6000_3_OR_NEWER
            int analyticsIdx = _profilePanel.IndexOf(analyticsLabel);
            if (analyticsIdx < 0) analyticsIdx = _profilePanel.childCount;
            toolbarLabel = new Label("Toolbar Button");
            toolbarLabel.style.fontSize = _profileLabelFontSize;
            toolbarLabel.style.color = _profileLabelColor;
            toolbarLabel.style.unityFontStyleAndWeight = FontStyle.Bold;
            toolbarLabel.style.marginTop = 12;
            toolbarLabel.style.marginBottom = 6;
            _profilePanel.Insert(analyticsIdx, toolbarLabel);
            
            var positionOptions = new List<string> { "Left Aligned", "Center", "Right Aligned", "Off" };
            int currentPos = SyntyToolbarButton.ToolbarPosition;
            
            var toolbarDropdown = new PopupField<string>(
                positionOptions, 
                currentPos < positionOptions.Count ? currentPos : 1
            );
            toolbarDropdown.style.height = 28;
            toolbarDropdown.style.marginBottom = 4;
            toolbarDropdown.style.marginLeft = 4;
            toolbarDropdown.style.marginRight = 4;
            // Background of the dropdown's inner input box -> #414163. The visible box is the
            // child "unity-base-popup-field__input"; style it once geometry is ready so the
            // element exists, and also set it immediately in case it is already built.
            var toolbarDropColor = new Color(0.255f, 0.255f, 0.388f, 1f); // #414163
            void StyleToolbarDropdownBg()
            {
                var inputVe = toolbarDropdown.Q<VisualElement>(className: "unity-base-popup-field__input");
                if (inputVe != null)
                {
                    inputVe.style.backgroundColor = toolbarDropColor;
                    inputVe.style.borderTopLeftRadius = 6;
                    inputVe.style.borderTopRightRadius = 6;
                    inputVe.style.borderBottomLeftRadius = 6;
                    inputVe.style.borderBottomRightRadius = 6;
                }
            }
            toolbarDropdown.RegisterCallback<GeometryChangedEvent>(_ => StyleToolbarDropdownBg());
            StyleToolbarDropdownBg();
            toolbarDropdown.RegisterValueChangedCallback(evt => {
                int idx = positionOptions.IndexOf(evt.newValue);
                if (idx >= 0)
                {
                    SyntyToolbarButton.SetToolbarPosition(idx);
                }
            });
            // Place the dropdown immediately after the toolbar label (which sits just before
            // the Analytics label). Re-resolve the analytics index in case anything shifted.
            int dropIdx = _profilePanel.IndexOf(analyticsLabel);
            if (dropIdx < 0) dropIdx = _profilePanel.childCount;
            _profilePanel.Insert(dropIdx, toolbarDropdown);
#endif
            
            // ── Currency selector ──
            var currencyLabel = new Label("Currency");
            currencyLabel.style.fontSize = _profileLabelFontSize;
            currencyLabel.style.color = _profileLabelColor;
            currencyLabel.style.unityFontStyleAndWeight = FontStyle.Bold;
            currencyLabel.style.marginTop = 12;
            currencyLabel.style.marginBottom = 6;
            int curLabelIdx = _profilePanel.IndexOf(analyticsLabel);
            if (curLabelIdx < 0) curLabelIdx = _profilePanel.childCount;
            _profilePanel.Insert(curLabelIdx, currencyLabel);
            
            const string AUTO_CURRENCY_LABEL = "Auto (by location)";
            var currencyOptions = new List<string> { AUTO_CURRENCY_LABEL };
            for (int ci = 0; ci < SyntyCurrency.Supported.Length; ci++)
                currencyOptions.Add(SyntyCurrency.Supported[ci].label);
            // Show "Auto" unless the user has explicitly picked a currency.
            int curSelected = 0;
            if (SyntyCurrency.IsManuallySet)
            {
                for (int ci = 0; ci < SyntyCurrency.Supported.Length; ci++)
                    if (SyntyCurrency.Supported[ci].code == SyntyCurrency.Current) { curSelected = ci + 1; break; }
            }
            var currencyDropdown = new PopupField<string>(currencyOptions, curSelected);
            currencyDropdown.style.height = 28;
            currencyDropdown.style.marginBottom = 4;
            currencyDropdown.style.marginLeft = 4;
            currencyDropdown.style.marginRight = 4;
            void StyleCurrencyDropdownBg()
            {
                var inputVe = currencyDropdown.Q<VisualElement>(className: "unity-base-popup-field__input");
                if (inputVe != null)
                {
                    inputVe.style.backgroundColor = new Color(0.255f, 0.255f, 0.388f, 1f); // #414163
                    inputVe.style.borderTopLeftRadius = 6;
                    inputVe.style.borderTopRightRadius = 6;
                    inputVe.style.borderBottomLeftRadius = 6;
                    inputVe.style.borderBottomRightRadius = 6;
                }
            }
            currencyDropdown.RegisterCallback<GeometryChangedEvent>(_ => StyleCurrencyDropdownBg());
            StyleCurrencyDropdownBg();
            currencyDropdown.RegisterValueChangedCallback(evt => {
                int idx = currencyOptions.IndexOf(evt.newValue);
                if (idx <= 0)
                {
                    SyntyCurrency.SetAuto(); // "Auto (by location)" — clear manual flag and re-detect
                }
                else
                {
                    int sIdx = idx - 1; // offset for the Auto option at index 0
                    if (sIdx >= 0 && sIdx < SyntyCurrency.Supported.Length)
                        SyntyCurrency.SetCurrencyManual(SyntyCurrency.Supported[sIdx].code);
