            // Logout button
            var logoutBtn = new Button();
            _profileLogoutBtn = logoutBtn;
            logoutBtn.text = "Logout";
            logoutBtn.style.backgroundColor = _logoutBtnColor;
            logoutBtn.style.color = _logoutTextColor;
