            logoutBtn.style.borderRightColor = Color.white;
            logoutBtn.style.borderTopWidth = 0;
            logoutBtn.style.borderBottomWidth = 0;
            logoutBtn.style.borderLeftWidth = 0;
            logoutBtn.style.borderRightWidth = 0;
            logoutBtn.style.transitionProperty = new List<StylePropertyName> { 
                new StylePropertyName("scale"),
                new StylePropertyName("border-top-width"),
                new StylePropertyName("border-bottom-width"),
                new StylePropertyName("border-left-width"),
                new StylePropertyName("border-right-width")
            };
            logoutBtn.style.transitionDuration = new List<TimeValue> { 
                new TimeValue(120, TimeUnit.Millisecond),
                new TimeValue(120, TimeUnit.Millisecond),
                new TimeValue(120, TimeUnit.Millisecond),
                new TimeValue(120, TimeUnit.Millisecond),
                new TimeValue(120, TimeUnit.Millisecond)
            };
            logoutBtn.style.transitionTimingFunction = new List<EasingFunction> { 
                new EasingFunction(EasingMode.EaseOut),
                new EasingFunction(EasingMode.EaseOut),
                new EasingFunction(EasingMode.EaseOut),
                new EasingFunction(EasingMode.EaseOut),
                new EasingFunction(EasingMode.EaseOut)
            };
            logoutBtn.RegisterCallback<MouseEnterEvent>(evt => {
                logoutBtn.style.scale = new Scale(new Vector3(1.04f, 1.04f, 1f));
                logoutBtn.style.borderTopWidth = 2;
                logoutBtn.style.borderBottomWidth = 2;
                logoutBtn.style.borderLeftWidth = 2;
                logoutBtn.style.borderRightWidth = 2;
            });
            logoutBtn.RegisterCallback<MouseLeaveEvent>(evt => {
                logoutBtn.style.scale = new Scale(Vector3.one);
                logoutBtn.style.borderTopWidth = 0;
                logoutBtn.style.borderBottomWidth = 0;
                logoutBtn.style.borderLeftWidth = 0;
                logoutBtn.style.borderRightWidth = 0;
            });
            logoutBtn.clicked += () =>
            {
                _profilePanelVisible = false;
                _profilePanel.style.display = DisplayStyle.None;
                if (_changeProfileBtn != null) _changeProfileBtn.style.display = DisplayStyle.None;
                if (_profilePickerPanel != null) _profilePickerPanel.style.display = DisplayStyle.None;
                
                // Clear deal state + login state via the centralized helper
                OnLogoutInitiated();
                
                // Return to login screen
                var r = rootVisualElement;
                r.Clear();
                if (_styleSheet != null) r.styleSheets.Add(_styleSheet);
                ShowLoginScreen(r);
                
            };
            _profilePanel.Add(logoutBtn);
            logoutBtn.RegisterCallback<AttachToPanelEvent>(_ =>
            {
                var lbl = logoutBtn.Q<Label>();
                if (lbl != null) { lbl.style.fontSize = _logoutFontSize; lbl.style.unityFontStyleAndWeight = _logoutBold ? FontStyle.Bold : FontStyle.Normal; }
                logoutBtn.style.fontSize = _logoutFontSize;
                logoutBtn.style.unityFontStyleAndWeight = _logoutBold ? FontStyle.Bold : FontStyle.Normal;
            });
            
            // ── Reorder profile sections ──
            // The panel is built in a scattered order (mix of Add/Insert); arrange the sections as:
            // Account, Currency, Asset Downloads, Toolbar, Notifications, Analytics, Logout. Each
            // section begins at its header element (Account = everything before the first header).
            // We group the flat child list by these anchors and re-append the groups in the target
            // order (Add() moves an element that's already a child).
            {
                var kids = new List<VisualElement>();
                foreach (var c in _profilePanel.Children()) kids.Add(c);
                var anchors = new List<VisualElement> { notifLabel, analyticsLabel, toolbarLabel, assetDownloadsLabel, currencyLabel, logoutBtn };
                anchors.RemoveAll(a => a == null || kids.IndexOf(a) < 0);
                anchors.Sort((a, b) => kids.IndexOf(a).CompareTo(kids.IndexOf(b)));
                if (anchors.Count > 0)
                {
                    var ordered = new List<VisualElement>();
                    int firstIdx = kids.IndexOf(anchors[0]);
                    for (int i = 0; i < firstIdx; i++) ordered.Add(kids[i]); // Account section
                    System.Func<VisualElement, List<VisualElement>> section = (anchor) =>
                    {
                        var outList = new List<VisualElement>();
                        int s = kids.IndexOf(anchor);
                        if (s < 0) return outList;
                        int ai = anchors.IndexOf(anchor);
                        int e = (ai + 1 < anchors.Count) ? kids.IndexOf(anchors[ai + 1]) : kids.Count;
                        for (int i = s; i < e; i++) outList.Add(kids[i]);
                        return outList;
                    };
                    foreach (var a in new VisualElement[] { currencyLabel, assetDownloadsLabel, toolbarLabel, notifLabel, analyticsLabel, logoutBtn })
                        ordered.AddRange(section(a));
                    foreach (var c in kids) if (!ordered.Contains(c)) ordered.Add(c); // safety
                    foreach (var el in ordered) _profilePanel.Add(el); // Add moves existing children
                }
            }

            parent.Add(_profilePanel);
        }
        
        // URL the banner opens when clicked. Set from the server banner config if provided,
        // otherwise the banner falls back to the general store link.
        private string _bannerLinkUrl = null;
        
        private void OnBannerClicked()
        {
            if (!string.IsNullOrEmpty(_bannerLinkUrl))
            {
                Application.OpenURL(AppendUtm(_bannerLinkUrl, "banner_link"));
                return;
            }
            Application.OpenURL(SyntyCatalogBridge.STORE_AFFILIATE_URL);
        }
        
        // Opens syntystore.com signed in as the current Passport user. Hits the worker's
        // /account-login-url endpoint to get a Shopify Multipass URL — Multipass replaces
        // whatever account (or none) is in the browser with the email Passport is logged
        // in as, so the Account button always lands on the same customer. Falls back to
        // a normal /account redirect if the worker can't generate a multipass token (e.g.
        // MULTIPASS_SECRET isn't configured, or the store isn't on Shopify Plus).
        private void OpenAccountLoginUrl()
        {
            string email = Synty.Tools.SyntyStoreService.Instance?.CustomerEmail ?? "";
            if (string.IsNullOrEmpty(email))
            {
                Application.OpenURL(AppendUtm("https://syntystore.com/account/login", "store_link"));
                return;
            }
            // Fire-and-forget async request — the user already clicked, we just open the
            // returned URL when it arrives. If anything errors, fall through to the bare
            // /account page (where they can sign in manually).
            var req = new UnityEngine.Networking.UnityWebRequest(
                "https://synty-downloads.syntystore.workers.dev/account-login-url", "POST");
            string bodyJson = $"{{\"email\":\"{email.Replace("\"", "\\\"")}\"}}";
            byte[] bodyBytes = System.Text.Encoding.UTF8.GetBytes(bodyJson);
            req.uploadHandler = new UnityEngine.Networking.UploadHandlerRaw(bodyBytes);
            req.downloadHandler = new UnityEngine.Networking.DownloadHandlerBuffer();
            req.SetRequestHeader("Content-Type", "application/json");
            var op = req.SendWebRequest();
            op.completed += _ =>
            {
                string targetUrl = "https://syntystore.com/account/login";
                try
                {
                    if (req.result == UnityEngine.Networking.UnityWebRequest.Result.Success)
                    {
                        // Minimal JSON parse — we just need the "url" string. JsonUtility
                        // would need a wrapper class; a regex is shorter and harmless here
                        // since the field's a known shape and we URL-encode-decode nothing.
                        var text = req.downloadHandler.text;
                        var m = System.Text.RegularExpressions.Regex.Match(text, "\"url\"\\s*:\\s*\"([^\"]+)\"");
                        if (m.Success) targetUrl = m.Groups[1].Value;
                    }
                    else
                    {
                        // UnityEngine.Debug.LogWarning($"[OpenAccountLoginUrl] worker request failed: {req.error}");
                    }
                }
                finally
                {
                    req.Dispose();
                    Application.OpenURL(AppendUtm(targetUrl, "store_link"));
                }
            };
        }
        
        // Auto-fits a Label inside its parent's width by shrinking the font size when the
        // measured text would otherwise overflow. The original (max) font size is remembered
        // in userData so the label can grow back when shorter text is assigned later. Used
        // by the multi-select bars (INSTALL / UNINSTALL / ADD TO CART / UPDATE) where the
        // subtitle varies in length and could otherwise exceed the button's painted area.
        // Runs on a light scheduled poll (not a geometry callback) so font writes never feed
        // back into the layout pass that triggered them - which is what caused Unity's
        // recursive-layout warning.
        private static void RegisterTextAutoFit(Label label, float minFontSize = 8f, float horizontalPaddingPx = 12f)
        {
            if (label == null) return;
            label.style.whiteSpace = WhiteSpace.NoWrap;
            
            // Poll-based fit instead of reacting to GeometryChangedEvent. Writing fontSize
            // inside a geometry callback re-triggers layout and Unity reports recursive
            // layout. A light scheduled task runs outside the layout pass, so the font
            // write never feeds back into the same cycle. It only does work when the parent
            // width or the text actually changed, so it is effectively idle at rest.
            float lastWidth = -1f;
            string lastText = null;
            IVisualElementScheduledItem fitTask = null;
            fitTask = label.schedule.Execute(() =>
            {
                if (_reloadingDomain || label.panel == null) { SafePause(fitTask); return; }
                var parent = label.parent;
                if (parent == null) return;
                float parentW = parent.resolvedStyle.width;
                if (parentW <= 0f || float.IsNaN(parentW)) return;
                
                // Skip if nothing relevant changed since the last fit.
                if (Mathf.Abs(parentW - lastWidth) < 0.5f && label.text == lastText) return;
                lastWidth = parentW;
                lastText = label.text;
                
                float maxFont;
                if (label.userData is float storedMax) maxFont = storedMax;
                else
                {
                    maxFont = label.resolvedStyle.fontSize;
                    if (maxFont <= 0f || float.IsNaN(maxFont)) return;
                    label.userData = maxFont;
                }
                
                float currentSize = label.resolvedStyle.fontSize;
                if (currentSize <= 0f || float.IsNaN(currentSize)) return;
                var measured = label.MeasureTextSize(label.text, 0, VisualElement.MeasureMode.Undefined, 0, VisualElement.MeasureMode.Undefined);
                float measuredAtMax = measured.x * (maxFont / currentSize);
                float available = Mathf.Max(1f, parentW - horizontalPaddingPx);
                float targetSize = measuredAtMax > available
                    ? Mathf.Max(minFontSize, maxFont * (available * 0.97f) / measuredAtMax)
                    : maxFont;
                
                if (Mathf.Abs(targetSize - currentSize) > 0.5f)
                    label.style.fontSize = targetSize;
            }).Every(100); // check ~10x/sec; cheap and never recurses into layout
            TrackScheduledItem(fitTask);
        }
        
        // Same idea as RegisterTextAutoFit, but for a container that holds multiple Label
        // children in a horizontal row — measures the combined width and scales every
        // child's font size uniformly so the whole row fits. Used by the cart bar's price
        // container ("prefix" + "$dollars" + "cents") since each child gets independent
        // layout, so per-label auto-fit alone doesn't constrain the row total.
        private static void RegisterContainerAutoFit(VisualElement container, float minFontSize = 8f, float horizontalPaddingPx = 12f)
        {
            if (container == null) return;
            
            // Same poll-based approach as RegisterTextAutoFit: never write fontSize from a
            // geometry callback (that recurses into layout). A light scheduled task fits the
            // row outside the layout pass and only acts when the width or label set changed.
            float lastWidth = -1f;
            string lastSig = null;
            IVisualElementScheduledItem rowFitTask = null;
            rowFitTask = container.schedule.Execute(() =>
            {
                if (_reloadingDomain || container.panel == null) { SafePause(rowFitTask); return; }
                float containerW = container.resolvedStyle.width;
                if (containerW <= 0f || float.IsNaN(containerW)) return;
                
                var labels = container.Query<Label>().ToList();
                if (labels.Count == 0) return;
                
                // Signature of the current label texts, so we re-fit when the price changes.
                string sig = string.Empty;
                foreach (var l in labels) sig += l.text + "|";
                if (Mathf.Abs(containerW - lastWidth) < 0.5f && sig == lastSig) return;
                lastWidth = containerW;
                lastSig = sig;
                
                foreach (var lbl in labels)
                {
                    if (lbl.userData is float) continue;
                    var sz = lbl.resolvedStyle.fontSize;
                    if (sz > 0f && !float.IsNaN(sz)) lbl.userData = sz;
                    lbl.style.whiteSpace = WhiteSpace.NoWrap;
                }
                
                float totalAtMax = 0f;
                bool haveMax = true;
                foreach (var lbl in labels)
                {
                    if (!(lbl.userData is float mx)) { haveMax = false; break; }
                    float cur = lbl.resolvedStyle.fontSize;
                    if (cur <= 0f || float.IsNaN(cur)) { haveMax = false; break; }
                    var m = lbl.MeasureTextSize(lbl.text, 0, VisualElement.MeasureMode.Undefined, 0, VisualElement.MeasureMode.Undefined);
                    totalAtMax += m.x * (mx / cur);
                }
                if (!haveMax) return;
                
                float available = Mathf.Max(1f, containerW - horizontalPaddingPx);
                float ratio = totalAtMax > available ? (available * 0.97f) / totalAtMax : 1f;
                
                foreach (var lbl in labels)
                {
                    if (!(lbl.userData is float mx)) continue;
                    float target = Mathf.Max(minFontSize, mx * ratio);
                    float cur = lbl.resolvedStyle.fontSize;
                    if (Mathf.Abs(target - cur) > 0.5f)
                        lbl.style.fontSize = target;
                }
            }).Every(100);
            TrackScheduledItem(rowFitTask);
        }
    }
}
